const e=[{id:"n5-ha",level:5,title:"は — das Themen-Partikel",intro:'Das erste und wichtigste Partikel im Japanischen: は (gesprochen "wa").',text:'Die Struktur „A は B です" bedeutet wörtlich „Was A angeht, es ist B." は markiert das Gesprächsthema.',tip:'Häufiger Fehler: は wird als "ha" geschrieben, aber als "wa" ausgesprochen — nur als Partikel!',ex:[["私は学生です。","わたしはがくせいです。","Ich bin Student(in)."],["これは本です。","これはほんです。","Das ist ein Buch."]],q:[{q:"私は学生です。 — Was markiert は hier?",o:["Das Gesprächsthema","Das direkte Objekt","Eine Frage"],c:0},{q:"Wie spricht man は als Partikel aus?",o:["ha","wa","ba"],c:1},{q:"Vervollständige: これ ___ 本です。",o:["は","を","か"],c:0}]},{id:"n5-ga",level:5,title:"が — Subjekt-Partikel",intro:"が markiert das grammatische Subjekt — anders als は lenkt es den Fokus direkt auf das Wort davor, nicht auf das große Ganze.",text:'は kündigt das Gesprächsthema an ("was X angeht..."), が hebt genau hervor, WER oder WAS etwas tut oder existiert. Besonders wichtig bei あります/います (es gibt/existiert) und bei Vorlieben mit 好き.',tip:"Faustregel für den Anfang: bei neuer, noch nicht erwähnter Information oft が, bei einem bereits bekannten Thema oft は. 猫がいます (Es gibt eine Katze — neue Info) vs. 猫は元気です (Die [besagte] Katze geht es gut — schon bekanntes Thema).",ex:[["猫がいます。","ねこがいます。","Es gibt eine Katze. / Da ist eine Katze."],["田中さんが来ました。","たなかさんがきました。","Herr Tanaka ist gekommen."]],q:[{q:"猫がいます。 — Was markiert が hier?",o:["Das grammatische Subjekt","Das direkte Objekt","Eine Frage"],c:0},{q:"Wofür wird が typischerweise bei あります/います gebraucht?",o:["Um anzugeben, was existiert","Um eine Verneinung zu bilden","Um die Vergangenheit zu markieren"],c:0},{q:"Vervollständige: 田中さん ___ 来ました。",o:["が","を","か"],c:0}]},{id:"n5-ka",level:5,title:"か — Fragepartikel",intro:"Aus jeder Aussage wird mit か am Satzende ganz einfach eine Frage.",text:"Die Wortstellung ändert sich nicht — man hängt nur か an. Kein Fragezeichen nötig.",tip:"In lockerer Sprache lässt man か manchmal weg und hebt nur die Stimme am Satzende.",ex:[["あなたは学生ですか。","あなたはがくせいですか。","Bist du Student(in)?"],["これは本ですか。","これはほんですか。","Ist das ein Buch?"]],q:[{q:"Wofür steht か am Satzende?",o:["Frage","Verneinung","Vergangenheit"],c:0},{q:"Braucht man im Japanischen ein Fragezeichen bei か?",o:["Ja, immer","Nein, nicht nötig","Nur schriftlich"],c:1},{q:"Vervollständige: あなたは学生です ___。",o:["か","は","を"],c:0}]},{id:"n5-fragewoerter",level:5,title:"疑問詞 — Fragewörter",intro:'Mit か wird aus einer Aussage eine Ja/Nein-Frage — für offene Fragen ("wo", "wann", "wer" ...) gibt es eigene Fragewörter, die einfach an die Stelle des gesuchten Elements treten.',text:"Die Wortstellung bleibt gleich, nur das gesuchte Wort wird durch das Fragewort ersetzt, und か kommt trotzdem ans Ende: 何 (was), どこ (wo), いつ (wann), だれ (wer), どうして (warum), いくつ (wie viele/wie alt), いくら (wie viel kostet es). Beispiel: これは何ですか。 (Was ist das?) — 何 steht genau dort, wo im Antwortsatz die gesuchte Information stehen würde.",tip:"だれ und 何 klingen in schnellen Sätzen manchmal ähnlich — bei Unsicherheit hilft der Kontext: だれ fragt immer nach Personen, 何 nach Dingen.",ex:[["これは何ですか。","これはなんですか。","Was ist das?"],["トイレはどこですか。","といれはどこですか。","Wo ist die Toilette?"]],q:[{q:"Welches Fragewort fragt nach einer Person?",o:["だれ","どこ","いつ"],c:0},{q:"これは何ですか。 — Wonach wird hier gefragt?",o:["Was etwas ist","Wo etwas ist","Wann etwas passiert"],c:0},{q:"Bleibt か bei einer Frage mit Fragewort trotzdem am Satzende?",o:["Ja","Nein","Nur manchmal"],c:0}]},{id:"n5-wo",level:5,title:"を — Objekt-Partikel",intro:"を markiert das direkte Objekt eines Satzes.",text:'Struktur: „Objekt + を + Verb". Es wird wie "o" ausgesprochen.',tip:"を wird ausschließlich als Partikel verwendet, niemals in normalen Wörtern.",ex:[["水を飲みます。","みずをのみます。","Ich trinke Wasser."],["本を読みます。","ほんをよみます。","Ich lese ein Buch."]],q:[{q:"Was markiert を?",o:["Das direkte Objekt","Das Thema","Besitz"],c:0},{q:"Wie spricht man を aus?",o:["wo","o","vo"],c:1},{q:"Vervollständige: 水 ___ 飲みます。",o:["を","は","の"],c:0}]},{id:"n5-ni",level:5,title:"に — Zeitpunkt & Ziel",intro:"に markiert einen festen Zeitpunkt oder den Ort, an dem sich etwas befindet bzw. wohin sich etwas bewegt.",text:"Zwei Hauptfunktionen: 1) Zeitpunkt — 三時に会います (Wir treffen uns um drei Uhr). 2) Ziel einer Bewegung oder Ort einer Existenz — 学校に行きます (Ich gehe zur Schule), 部屋にいます (Ich bin im Zimmer).",tip:"Bei Uhrzeiten und Daten braucht man に fast immer — bei Wörtern wie 今日 (heute) oder 明日 (morgen) dagegen meist nicht.",ex:[["三時に会いましょう。","さんじにあいましょう。","Lass uns um drei Uhr treffen."],["学校に行きます。","がっこうにいきます。","Ich gehe zur Schule."]],q:[{q:"Welche zwei Hauptfunktionen hat に?",o:["Zeitpunkt und Bewegungsziel/Ort","Verneinung und Frage","Vergangenheit und Zukunft"],c:0},{q:"三時に会いましょう。 — Was markiert に hier?",o:["Den Zeitpunkt","Das Objekt","Den Grund"],c:0},{q:"Vervollständige: 学校 ___ 行きます。",o:["に","は","が"],c:0}]},{id:"n5-de",level:5,title:"で — Ort der Handlung & Mittel",intro:"で markiert den Ort, an dem eine Handlung stattfindet, oder das Mittel/Werkzeug, mit dem etwas getan wird — nicht zu verwechseln mit に!",text:"Der Unterschied zu に: に steht bei Existenz/Ziel (jemand/etwas IST irgendwo oder geht IRGENDWOHIN), で steht dort, wo etwas GETAN wird. 図書館で勉強します (Ich lerne IN der Bibliothek — Handlung). Zusätzlich markiert で auch das Mittel: バスで行きます (Ich fahre MIT dem Bus).",tip:"Merkhilfe: に = wo etwas IST, で = wo etwas PASSIERT/GEMACHT wird.",ex:[["図書館で勉強します。","としょかんでべんきょうします。","Ich lerne in der Bibliothek."],["バスで行きます。","ばすでいきます。","Ich fahre mit dem Bus."]],q:[{q:"Was markiert で im Unterschied zu に?",o:["Den Ort, wo eine Handlung stattfindet","Den Ort, wo etwas existiert","Die Vergangenheit"],c:0},{q:"バスで行きます。 — Was markiert で hier?",o:["Das Mittel/Verkehrsmittel","Das Ziel","Den Grund"],c:0},{q:"Vervollständige: 図書館 ___ 勉強します。",o:["で","に","を"],c:0}]},{id:"n5-he",level:5,title:"へ — Richtungspartikel",intro:'へ (in dieser Funktion "e" statt "he" ausgesprochen) markiert die Richtung einer Bewegung — oft austauschbar mit に, aber mit leicht anderem Fokus.',text:"Während に das konkrete Ziel betont (genau dorthin), betont へ eher die Richtung/den Weg (in diese Richtung). Im Alltag oft synonym: 日本へ行きます = 日本に行きます (Ich gehe nach Japan).",tip:'Achtung bei der Aussprache: へ wird als Partikel "e" gesprochen, nicht "he" — genau wie は als Partikel "wa" statt "ha" klingt.',ex:[["日本へ行きます。","にほんへいきます。","Ich gehe nach Japan."],["どちらへ行きますか。","どちらへいきますか。","Wohin gehen Sie? (höflich)"]],q:[{q:"Wie spricht man へ als Partikel aus?",o:["e","he","ye"],c:0},{q:"Was betont へ im Vergleich zu に?",o:["Die Richtung/den Weg","Den genauen Zeitpunkt","Das direkte Objekt"],c:0},{q:"Vervollständige: 日本 ___ 行きます。",o:["へ","を","が"],c:0}]},{id:"n5-mo",level:5,title:"も — auch",intro:"も ersetzt は oder を, wenn eine Aussage ebenfalls zutrifft.",text:'„私は学生です。田中さんも学生です。" = „Ich bin Student. Herr Tanaka ist auch Student."',tip:"も kann は, が und を ersetzen — es wird aber nie mit ihnen kombiniert.",ex:[["私も学生です。","わたしもがくせいです。","Ich bin auch Student(in)."],["お茶も飲みます。","おちゃものみます。","Ich trinke auch Tee."]],q:[{q:"Was bedeutet も ungefähr?",o:["auch","nicht","sehr"],c:0},{q:"田中さんも学生です。 bedeutet:",o:["Auch Tanaka ist Student","Nur Tanaka ist Student","Tanaka ist kein Student"],c:0},{q:"Vervollständige: お茶 ___ 飲みます。 (auch trinke ich Tee)",o:["も","は","を"],c:0}]},{id:"n5-no",level:5,title:"の — Possessiv-Partikel",intro:'の verbindet zwei Nomen, ähnlich einem Genitiv im Deutschen ("von").',text:'Struktur: „Besitzer + の + Sache". Die Reihenfolge ist wichtig — anders als im Deutschen steht der Besitzer zuerst.',tip:'の kann Ketten bilden: 日本語の先生の本 = „das Buch des Japanischlehrers".',ex:[["私の名前は田中です。","わたしのなまえはたなかです。","Mein Name ist Tanaka."],["これは友達の本です。","これはともだちのほんです。","Das ist das Buch meines Freundes."]],q:[{q:"の entspricht im Deutschen ungefähr:",o:["von / Genitiv","und","aber"],c:0},{q:"Richtige Reihenfolge:",o:["Besitzer + の + Sache","Sache + の + Besitzer"],c:0},{q:"Vervollständige: 私 ___ 名前は田中です。",o:["の","は","を"],c:0}]},{id:"n5-i",level:5,title:"い-Adjektive & な-Adjektive",intro:"Japanische Adjektive gibt es in zwei Familien, die sich völlig unterschiedlich konjugieren — welche Familie ein Adjektiv gehört, erkennt man meist an der Endung.",text:"い-Adjektive enden in der Grundform auf -i (大きい, おいしい) und werden direkt konjugiert: Vergangenheit 大きかった, Verneinung 大きくない. な-Adjektive (z. B. 元気, 静か) brauchen vor einem Nomen ein angehängtes な (元気な人), verhalten sich sonst aber eher wie Nomen: Vergangenheit 元気でした, Verneinung 元気じゃない.",tip:"Achtung, klassische Ausnahme: 綺麗 (schön) und 有名 (berühmt) sehen aus wie い-Adjektive, sind aber な-Adjektive — genau wie bei den Verbgruppen gibt es hier ein paar Wörter, die man einzeln mitlernen muss.",ex:[["この店はおいしいです。","このみせはおいしいです。","Dieses Restaurant ist lecker. (い-Adjektiv)"],["彼は元気な人です。","かれはげんきなひとです。","Er ist ein munterer Mensch. (な-Adjektiv vor Nomen)"]],q:[{q:"Wie wird die Vergangenheit von 大きい (groß) gebildet?",o:["大きかった","大きいでした","大きくました"],c:0},{q:"Was braucht ein な-Adjektiv direkt vor einem Nomen?",o:["Ein angehängtes な","Ein angehängtes い","Gar nichts"],c:0},{q:"綺麗 (schön) gehört zu welcher Adjektiv-Familie — trotz der い-ähnlichen Optik?",o:["な-Adjektiv","い-Adjektiv"],c:0}]},{id:"n5-zaehleinheitswoerter",level:5,title:"助数詞 — Zähleinheitswörter",intro:'Im Japanischen bekommt praktisch jede Art von Ding ihr eigenes Zählwort — man zählt nie einfach nur „eins, zwei, drei", sondern immer „ein Stück", „zwei Personen", „drei flache Dinge" usw.',text:"Die wichtigsten Zähleinheiten für den Einstieg: つ (allgemein für Gegenstände, 1-10 unregelmäßig: ひとつ, ふたつ, みっつ...), 人 (にん, für Personen: ひとり, ふたり, dann さんにん, よにん...), 枚 (まい, für flache Dinge wie Papier oder T-Shirts), 本 (ほん, für lange, dünne Dinge wie Flaschen oder Stifte), 匹 (ひき, für kleine Tiere). Struktur: Menge + Zähleinheit steht meist direkt hinter dem Satzobjekt, ohne weiteres Partikel dazwischen: りんごを三つ買います (Ich kaufe drei Äpfel).",tip:"Bei manchen Zählern (v. a. 本, 匹) ändert sich der Anlaut je nach Zahl aus reinen Lautgründen (一本 = いっぽん, 二本 = にほん, 三本 = さんぼん) — das wirkt am Anfang chaotisch, festigt sich aber mit Übung von allein.",ex:[["りんごを三つ買います。","りんごをみっつかいます。","Ich kaufe drei Äpfel."],["学生が二人います。","がくせいがふたりいます。","Es gibt zwei Studenten."]],q:[{q:"Welches Zählwort passt zu Personen?",o:["人 (にん)","枚 (まい)","匹 (ひき)"],c:0},{q:'Wie heißt „eine Person" auf Japanisch (unregelmäßig)?',o:["ひとり","いちにん","わんにん"],c:0},{q:"Welches Zählwort passt zu flachen Dingen wie Papier?",o:["枚","本","つ"],c:0}]},{id:"n5-hikaku",level:5,title:"比較 — Vergleiche ziehen",intro:'Um zwei Dinge zu vergleichen oder das Beste einer Gruppe hervorzuheben, braucht man im Japanischen keine eigene Steigerungsform wie im Deutschen ("groß" → "größer") — stattdessen helfen ein paar feste Wörter.',text:'Für „mehr als" steht より hinter dem Vergleichspunkt: これはそれより大きいです (Das ist größer als das). Für „nicht so ... wie" steht ほど mit Verneinung: これはそれほど大きくないです (Das ist nicht so groß wie das). Für den Superlativ steht 一番 (ichiban, „Nummer eins") vor dem Adjektiv: これが一番大きいです (Das ist am größten).',tip:"Das Adjektiv selbst verändert sich beim Vergleichen NICHT — anders als im Deutschen bleibt 大きい immer 大きい, nur より/ほど/一番 drumherum erledigen die eigentliche Vergleichsarbeit.",ex:[["これはそれより大きいです。","これはそれよりおおきいです。","Das ist größer als das."],["これが一番大きいです。","これがいちばんおおきいです。","Das ist am größten."]],q:[{q:'Welches Wort bedeutet „mehr als" beim Vergleich?',o:["より","ほど","一番"],c:0},{q:'Wie bildet man den Superlativ ("am ...sten")?',o:["一番 vor dem Adjektiv","より hinter dem Adjektiv","Das Adjektiv verdoppeln"],c:0},{q:'Verändert sich das japanische Adjektiv selbst beim Vergleichen (wie im Deutschen "groß"→"größer")?',o:["Nein, es bleibt gleich","Ja, es bekommt eine eigene Endung","Nur bei な-Adjektiven"],c:0}]},{id:"n4-mashita-masendeshita",level:5,title:"〜ました / 〜ませんでした — Vergangenheit",intro:"Nachdem du mit です/ます Sätze in der Gegenwart bilden kannst, ist die Vergangenheitsform der nächste Schritt.",text:'Aus ます wird ました für „hat getan", aus ます wird ませんでした für „hat nicht getan". Bei です wird daraus でした / じゃなかったです.',tip:"Die Verneinung in der Vergangenheit hängt am Verb selbst — nicht extra mit einem eigenen Wort wie im Deutschen.",ex:[["昨日、映画を見ました。","きのう、えいがをみました。","Gestern habe ich einen Film gesehen."],["朝ご飯を食べませんでした。","あさごはんをたべませんでした。","Ich habe nicht gefrühstückt."]],q:[{q:"Wie bildet man die Vergangenheit von 食べます?",o:["食べました","食べます","食べません"],c:0},{q:"Wie verneint man die Vergangenheit von 見ます?",o:["見ませんでした","見ました","見ません"],c:0},{q:"Vervollständige: 昨日、勉強___。 (habe gelernt)",o:["しました","します","しません"],c:0}]},{id:"n4-verbgruppen",level:4,title:"Verbgruppen — Godan, Ichidan, unregelmäßig",intro:"Japanische Verben lassen sich in drei Gruppen einteilen — welche Gruppe ein Verb hat, entscheidet, wie es konjugiert wird (z. B. für die て-Form).",text:"Ichidan-Verben (Gruppe 2) enden in der Wörterbuchform auf -iru/-eru und verlieren beim Konjugieren einfach das る (食べる → 食べ). Godan-Verben (Gruppe 1) enden auf verschiedene -u-Laute, wobei sich die letzte Silbe je nach Form ändert (飲む → 飲み). Unregelmäßige Verben (Gruppe 3) gibt es nur zwei: する (tun) und 来る (kommen) — sie folgen keinem festen Muster und werden einzeln gelernt.",tip:'Nicht jedes Verb auf -eru/-iru ist automatisch Ichidan — Ausnahmen wie 帰る (kaeru, "nach Hause gehen") sehen aus wie Ichidan, sind aber Godan. Solche Ausnahmen am besten einzeln mitlernen.',ex:[["食べる → 食べます","たべる → たべます","essen (Ichidan) → höfliche Form"],["飲む → 飲みます","のむ → のみます","trinken (Godan) → höfliche Form"]],q:[{q:"Wie viele Verbgruppen gibt es im Japanischen?",o:["Drei","Zwei","Vier"],c:0},{q:'Welche Verben gehören zur "unregelmäßigen" Gruppe?',o:["する und 来る","Alle Verben auf -eru","Alle Verben auf -u"],c:0},{q:"食べる gehört zu welcher Gruppe?",o:["Ichidan (Gruppe 2)","Godan (Gruppe 1)","Unregelmäßig (Gruppe 3)"],c:0}]},{id:"n4-te",level:4,title:"て-Form — Handlungen verbinden",intro:"Die て-Form ist eine der wichtigsten Verbformen im Japanischen — sie verbindet Handlungen und ist Grundlage vieler weiterer Formen.",text:'Statt „und" zwischen zwei Sätzen zu wiederholen, hängst du Verben in der て-Form aneinander: 朝起きて、朝ご飯を食べます = „Ich stehe auf und esse Frühstück."',tip:"Die Bildung der て-Form hängt von der Verbgruppe ab — am besten von Anfang an mit jedem neuen Verb mitlernen.",ex:[["朝起きて、顔を洗います。","あさおきて、かおをあらいます。","Ich stehe auf und wasche mein Gesicht."],["駅に行って、電車に乗ります。","えきにいって、でんしゃにのります。","Ich gehe zum Bahnhof und steige in den Zug."]],q:[{q:"Wofür wird die て-Form vor allem genutzt?",o:["Um Handlungen zu verbinden","Um die Vergangenheit zu bilden","Um Fragen zu stellen"],c:0},{q:"朝起きて、朝ご飯を食べます。 bedeutet:",o:["Ich stehe auf und esse Frühstück","Ich esse und stehe dann auf","Ich stehe nicht auf"],c:0},{q:"Die て-Form ist außerdem Grundlage für:",o:["Weitere wichtige Verbformen","Nur Höflichkeitsformen","Nur die Vergangenheit"],c:0}]},{id:"n4-tekudasai",level:5,title:"〜てください — Bitten aussprechen",intro:"Mit der て-Form plus ください formulierst du höfliche Bitten und Aufforderungen.",text:'„Verb-て + ください" entspricht etwa „Bitte tu...". 待ってください = „Bitte warte."',tip:"Ohne ください wirkt die reine て-Form eher wie eine lockere Aufforderung unter Freunden.",ex:[["ちょっと待ってください。","ちょっとまってください。","Bitte warte kurz."],["ここに名前を書いてください。","ここになまえをかいてください。","Bitte schreib hier deinen Namen."]],q:[{q:"Was bedeutet 待ってください?",o:["Bitte warte","Warte nicht","Ich warte"],c:0},{q:"Welche Form steht vor ください?",o:["Die て-Form des Verbs","Die Wörterbuchform","Die ました-Form"],c:0},{q:"Vervollständige höflich: ここに書い___ください。",o:["て","た","ます"],c:0}]},{id:"n4-temoiidesu-tehaikemasen",level:5,title:"〜てもいいです / 〜てはいけません — Erlaubnis & Verbot",intro:"Mit diesen beiden Ausdrücken sagst du, was erlaubt und was verboten ist.",text:'„Verb-て + もいいです" = „Man darf...". „Verb-て + はいけません" = „Man darf nicht...".',tip:'Wörtlich heißt てもいいです etwa „auch wenn ..., ist es gut" — daraus wird im Deutschen einfach „darf".',ex:[["ここで写真を撮ってもいいです。","ここでしゃしんをとってもいいです。","Hier darf man fotografieren."],["ここでたばこを吸ってはいけません。","ここでたばこをすってはいけません。","Hier darf man nicht rauchen."]],q:[{q:"Was bedeutet 〜てもいいです?",o:["Man darf...","Man darf nicht...","Man muss..."],c:0},{q:"Was bedeutet 〜てはいけません?",o:["Man darf nicht...","Man darf...","Man kann..."],c:0},{q:"ここで写真を撮ってもいいです。 bedeutet:",o:["Hier darf man fotografieren","Hier darf man nicht fotografieren","Hier muss man fotografieren"],c:0}]},{id:"n4-kotogadekimasu",level:4,title:"〜ことができます — Fähigkeit & Können",intro:"Um auszudrücken, dass man etwas kann, nutzt man diese Konstruktion mit der Wörterbuchform des Verbs.",text:'„Verb (Wörterbuchform) + ことができます" = „kann ... tun". 日本語を話すことができます = „Ich kann Japanisch sprechen."',tip:'こと verwandelt das Verb quasi in ein Nomen ("das Sprechen") — できます bedeutet dann „ist möglich".',ex:[["日本語を話すことができます。","にほんごをはなすことができます。","Ich kann Japanisch sprechen."],["漢字を読むことができません。","かんじをよむことができません。","Ich kann keine Kanji lesen."]],q:[{q:"Welche Verbform steht vor ことができます?",o:["Die Wörterbuchform","Die て-Form","Die ました-Form"],c:0},{q:"日本語を話すことができます。 bedeutet:",o:["Ich kann Japanisch sprechen","Ich spreche gerade Japanisch","Ich lerne Japanisch"],c:0},{q:"Was bedeutet 〜ことができません?",o:["kann nicht","kann","muss"],c:0}]},{id:"n4-kanou-kei",level:4,title:"可能形 — Potentialform (können)",intro:"Neben ことができます gibt es eine kürzere, im Alltag viel häufigere Art zu sagen, dass man etwas kann: die Potentialform — direkt am Verb selbst gebildet.",text:"Bei Ichidan-Verben ersetzt man das abschließende る durch られる: 食べる → 食べられる (essen können). Bei Godan-Verben wird die letzte Silbe von der u-Reihe in die e-Reihe verschoben und ein る angehängt: 飲む → 飲める (trinken können), 話す → 話せる (sprechen können). Die unregelmäßigen Verben haben eigene Formen: する → できる, 来る → 来られる. Das Objekt bekommt bei der Potentialform meist が statt を: 日本語が話せます (statt 日本語を話す).",tip:'できる (die Potentialform von する) ist eines der meistgenutzten Wörter im Alltag — es steht auch eigenständig für „möglich sein/machbar sein", nicht nur als Verbform.',ex:[["日本語が話せます。","にほんごがはなせます。","Ich kann Japanisch sprechen."],["漢字が読めますか。","かんじがよめますか。","Kannst du Kanji lesen?"]],q:[{q:"Wie wird die Potentialform von 飲む (trinken) gebildet?",o:["飲める","飲みられる","飲むる"],c:0},{q:"Was ist die Potentialform von する (tun)?",o:["できる","される","しられる"],c:0},{q:"Welches Partikel steht bei der Potentialform typischerweise vor dem Objekt, statt を?",o:["が","に","で"],c:0}]},{id:"n4-ukemi-kei",level:4,title:"受身形 — Passiv",intro:'Die Passivform beschreibt, dass jemand/etwas eine Handlung ERFÄHRT, statt sie selbst auszuführen — oft mit einer Nebenbedeutung von „unangenehm betroffen sein".',text:'Bildung bei Godan-Verben: letzte Silbe in die a-Reihe verschieben + れる (書く → 書かれる, „geschrieben werden"). Bei Ichidan-Verben: る → られる (見る → 見られる, „gesehen werden") — sieht identisch aus wie die Potentialform, der Unterschied ergibt sich nur aus dem Kontext! Unregelmäßige Verben: する → される, 来る → 来られる. Der Handelnde wird oft mit に markiert: 先生に褒められました (Ich wurde vom Lehrer gelobt).',tip:'Besonderheit im Japanischen: Das „Leidens-Passiv" (迷惑の受身) drückt aus, dass einem durch die Handlung eines anderen etwas Unangenehmes widerfahren ist — sogar bei Verben, die im Deutschen gar kein Passiv bilden können: 雨に降られました (wörtlich „vom Regen beregnet worden" = „Der Regen hat mich überrascht/erwischt").',ex:[["先生に褒められました。","せんせいにほめられました。","Ich wurde vom Lehrer gelobt."],["雨に降られました。","あめにふられました。","Ich wurde vom Regen überrascht."]],q:[{q:"Welches Partikel markiert typischerweise den Handelnden im Passivsatz?",o:["に","を","が"],c:0},{q:"Wie sieht die Ichidan-Passivform im Vergleich zur Potentialform aus?",o:["Identisch — nur der Kontext unterscheidet","Komplett anders","Nur bei unregelmäßigen Verben gleich"],c:0},{q:'Was drückt das „Leidens-Passiv" zusätzlich aus?',o:["Dass einem durch die Handlung etwas Unangenehmes widerfahren ist","Dass die Handlung freiwillig geschah","Dass die Handlung in der Zukunft liegt"],c:0}]},{id:"n4-taidesu",level:5,title:"〜たいです — Wünsche ausdrücken",intro:"Mit たい drückst du aus, was du gerne tun möchtest.",text:'„Verb-Stamm (ます-Form ohne ます) + たいです" = „möchte ... tun". 食べたいです = „Ich möchte essen."',tip:"たい verhält sich wie ein i-Adjektiv — Vergangenheit und Verneinung werden entsprechend gebildet (たかったです, たくないです).",ex:[["寿司が食べたいです。","すしがたべたいです。","Ich möchte Sushi essen."],["日本に行きたいです。","にほんにいきたいです。","Ich möchte nach Japan gehen."]],q:[{q:"Was bedeutet 食べたいです?",o:["Ich möchte essen","Ich esse","Ich habe gegessen"],c:0},{q:"Wie verhält sich たい grammatisch?",o:["Wie ein i-Adjektiv","Wie ein Nomen","Wie ein Partikel"],c:0},{q:"日本に行きたいです。 bedeutet:",o:["Ich möchte nach Japan gehen","Ich bin in Japan","Ich komme aus Japan"],c:0}]},{id:"n4-ageru-kureru-morau",level:4,title:"あげる・くれる・もらう — Geben & Nehmen",intro:'Bei "geben" und "bekommen" unterscheidet das Japanische nicht nur zwischen Geben und Nehmen, sondern auch danach, WER im Verhältnis zum Sprecher etwas gibt oder bekommt — eine Perspektive, die es im Deutschen so nicht gibt.',text:"あげる: ich (oder jemand aus meiner Gruppe) gibt jemand anderem etwas — nie umgekehrt zu mir selbst: 私は田中さんに本をあげました (Ich habe Tanaka ein Buch gegeben). くれる: jemand gibt MIR (oder meiner Gruppe) etwas — die Blickrichtung geht zum Sprecher hin: 田中さんは私に本をくれました (Tanaka hat mir ein Buch gegeben). もらう: ich bekomme/empfange etwas von jemandem, der Geber wird mit に oder から markiert: 私は田中さんに本をもらいました (Ich habe von Tanaka ein Buch bekommen).",tip:'Merkhilfe: くれる ist quasi "geben, Blickrichtung zu MIR" — deshalb kann man くれる niemals benutzen, wenn man selbst der Geber ist. Das ist der häufigste Anfängerfehler bei diesem Thema.',ex:[["田中さんは私に本をくれました。","たなかさんはわたしにほんをくれました。","Tanaka hat mir ein Buch gegeben."],["私は田中さんに花をあげました。","わたしはたなかさんにはなをあげました。","Ich habe Tanaka Blumen gegeben."]],q:[{q:"Welches Verb benutzt man, wenn jemand MIR etwas gibt?",o:["くれる","あげる","もらう"],c:0},{q:"Kann man くれる benutzen, wenn man selbst der Geber ist?",o:["Nein, niemals","Ja, immer","Nur bei Familie"],c:0},{q:"Welches Partikel markiert bei もらう den Geber?",o:["に (oder から)","を","が"],c:0}]},{id:"n4-ikou-kei",level:4,title:'意向形 — Volitionalform ("lass uns...")',intro:"Mit der Volitionalform schlägst du vor, gemeinsam etwas zu tun, oder drückst deine eigene Absicht aus — im Alltag meist als höfliches ましょう bekannt.",text:'Höfliche Form: Verb-Stamm + ましょう (行きましょう = „Lass uns gehen"). Als Frage wird daraus eine höfliche Einladung: 一緒に行きましょうか (Sollen wir zusammen gehen?). Die informelle Volitionalform (よう-Form) wird bei Godan-Verben über die o-Reihe + う gebildet (行く → 行こう), bei Ichidan-Verben über る → よう (食べる → 食べよう) — sie klingt unter Freunden natürlicher als ましょう.',tip:"ましょう wirkt nicht nur als Vorschlag, sondern manchmal auch wie eine sanfte Aufforderung (etwa von Lehrern zu Schülern) — Kontext und Tonfall entscheiden, ob es als Einladung oder Anweisung ankommt.",ex:[["一緒に行きましょう。","いっしょにいきましょう。","Lass uns zusammen gehen."],["もう帰ろう。","もうかえろう。","Lass uns jetzt nach Hause gehen. (informell)"]],q:[{q:"Wie bildet man die höfliche Volitionalform?",o:["Verb-Stamm + ましょう","Verb-Stamm + たい","Wörterbuchform + か"],c:0},{q:"Wie lautet die informelle Volitionalform von 行く?",o:["行こう","行きよう","行くよう"],c:0},{q:"一緒に行きましょうか。 bedeutet:",o:["Sollen wir zusammen gehen?","Ich gehe alleine","Wohin gehst du?"],c:0}]},{id:"n4-nagara",level:4,title:"〜ながら — Gleichzeitigkeit",intro:"Mit ながら verbindest du zwei Handlungen, die gleichzeitig stattfinden.",text:'„Verb-Stamm + ながら" = „während man ... tut". 音楽を聞きながら勉強します = „Ich lerne, während ich Musik höre."',tip:"Die Haupthandlung steht am Satzende — ながら hängt an der Nebenhandlung.",ex:[["音楽を聞きながら勉強します。","おんがくをききながらべんきょうします。","Ich lerne, während ich Musik höre."],["歩きながら話しましょう。","あるきながらはなしましょう。","Lass uns reden, während wir gehen."]],q:[{q:"Was verbindet ながら?",o:["Zwei gleichzeitige Handlungen","Zwei aufeinanderfolgende Handlungen","Ursache und Wirkung"],c:0},{q:"音楽を聞きながら勉強します。 bedeutet:",o:["Ich lerne, während ich Musik höre","Ich höre Musik, nachdem ich gelernt habe","Ich lerne oder höre Musik"],c:0},{q:"Wo steht die Haupthandlung im ながら-Satz?",o:["Am Satzende","Am Satzanfang","Direkt nach ながら"],c:0}]},{id:"n4-toki",level:4,title:'〜とき — Zeitpunkt & „wenn"',intro:'とき bedeutet wörtlich „Zeitpunkt" und wird genutzt, um zu sagen, wann etwas passiert.',text:'„Satz + とき" = „wenn/als...". 日本に行くとき、パスポートが要ります = „Wenn man nach Japan geht, braucht man einen Pass."',tip:'Ob vor とき die Wörterbuchform oder die Vergangenheitsform steht, ändert die Bedeutung leicht — Wörterbuchform meist für „bevor/während", Vergangenheitsform für „nachdem".',ex:[["日本に行くとき、パスポートが要ります。","にほんにいくとき、ぱすぽーとがいります。","Wenn man nach Japan geht, braucht man einen Pass."],["子供のとき、よく公園で遊びました。","こどものとき、よくこうえんであそびました。","Als Kind habe ich oft im Park gespielt."]],q:[{q:"Was bedeutet とき wörtlich?",o:["Zeitpunkt","Ort","Grund"],c:0},{q:"子供のとき、よく公園で遊びました。 bedeutet:",o:["Als Kind habe ich oft im Park gespielt","Ich spiele oft mit Kindern","Kinder spielen oft im Park"],c:0},{q:"日本に行くとき、パスポートが要ります。 sagt aus:",o:["Für die Reise nach Japan braucht man einen Pass","Man braucht nie einen Pass","Nur Kinder brauchen einen Pass"],c:0}]},{id:"n4-jouken-kei",level:4,title:"条件形 — と・ば・たら (Konditionalformen)",intro:'Für „wenn/falls" gibt es im Japanischen gleich drei gebräuchliche Formen — と, ば und たら —, die sich in Nuancen unterscheiden, aber am Anfang oft austauschbar wirken.',text:'と: für Naturgesetze, automatische Abläufe, feste Mechanismen — „wenn X, dann folgt IMMER Y": 春になると、桜が咲きます (Wenn der Frühling kommt, blühen die Kirschblüten). ば: betont die Bedingung selbst, oft bei allgemeinen Wahrheiten oder Ratschlägen (Verb: u → e + ば, z. B. 行く → 行けば; い-Adjektiv: い → ければ): 安ければ、買います (Wenn es billig ist, kaufe ich es). たら: die alltäglichste, flexibelste Form für konkrete Einzelfälle, gebildet aus der Vergangenheitsform + ら: 雨が降ったら、家にいます (Falls es regnet, bleibe ich zu Hause).',tip:"Faustregel für den Alltag: Bist du unsicher, welche Form richtig ist, nimm たら — sie ist die vielseitigste und wird von Muttersprachlern am häufigsten benutzt, auch wenn と oder ば in manchen Fällen eleganter klingen.",ex:[["雨が降ったら、家にいます。","あめがふったら、いえにいます。","Falls es regnet, bleibe ich zu Hause."],["春になると、桜が咲きます。","はるになると、さくらがさきます。","Wenn der Frühling kommt, blühen die Kirschblüten."]],q:[{q:"Welche Form wird am häufigsten für konkrete Einzelfälle im Alltag verwendet?",o:["たら","と","ば"],c:0},{q:"春になると、桜が咲きます。 — Welche Form wird hier verwendet, und warum?",o:["と, weil es ein fester, automatischer Ablauf ist","ば, weil es ein Ratschlag ist","たら, weil es ein einmaliges Ereignis ist"],c:0},{q:"Wie wird たら grundsätzlich gebildet?",o:["Vergangenheitsform + ら","Wörterbuchform + ば","Stamm + と"],c:0}]},{id:"n4-kara-node",level:5,title:"〜から / ので — Begründung",intro:"Beide Partikel geben einen Grund an — から klingt direkter, ので etwas höflicher/sachlicher.",text:'„Grund + から/ので、+ Folge" = „Weil..., ...". 忙しいから、行けません = „Weil ich beschäftigt bin, kann ich nicht gehen."',tip:"ので wirkt oft höflicher und wird häufig in formelleren Situationen bevorzugt.",ex:[["忙しいから、行けません。","いそがしいから、いけません。","Weil ich beschäftigt bin, kann ich nicht gehen."],["雨ですので、傘を持って行きます。","あめですので、かさをもっていきます。","Da es regnet, nehme ich einen Schirm mit."]],q:[{q:"Was drücken から und ので aus?",o:["Einen Grund","Eine Zeitangabe","Einen Ort"],c:0},{q:"Welches der beiden wirkt tendenziell höflicher?",o:["ので","から","Beide gleich"],c:0},{q:"忙しいから、行けません。 bedeutet:",o:["Weil ich beschäftigt bin, kann ich nicht gehen","Ich bin nicht beschäftigt","Ich gehe, weil ich Zeit habe"],c:0}]},{id:"n4-deshiyou",level:4,title:"〜でしょう — Vermutung",intro:'でしょう drückt eine Vermutung oder Wahrscheinlichkeit aus, ähnlich „wohl" oder „wahrscheinlich" im Deutschen.',text:'„Satz + でしょう" = „ist wohl/wahrscheinlich...". 明日は雨でしょう = „Morgen wird es wohl regnen."',tip:'Mit steigender Betonung am Ende wird でしょう auch genutzt, um höflich nach Zustimmung zu fragen, ähnlich „nicht wahr?".',ex:[["明日は雨でしょう。","あしたはあめでしょう。","Morgen wird es wohl regnen."],["田中さんはもう帰ったでしょう。","たなかさんはもうかえったでしょう。","Herr Tanaka ist wohl schon nach Hause gegangen."]],q:[{q:"Was drückt でしょう aus?",o:["Eine Vermutung","Eine Vergangenheit","Ein Verbot"],c:0},{q:"明日は雨でしょう。 bedeutet:",o:["Morgen wird es wohl regnen","Morgen regnet es sicher nicht","Gestern hat es geregnet"],c:0},{q:"でしょう kann mit steigender Betonung auch bedeuten:",o:['„Nicht wahr?" — eine Bestätigung erfragen',"Einen Befehl","Eine Entschuldigung"],c:0}]},{id:"n4-relativsaetze",level:4,title:"連体修飾 — Relativsätze",intro:'Um ein Nomen näher zu beschreiben, stellt man im Japanischen einfach einen ganzen Satz (in der einfachen Form) direkt VOR das Nomen — ganz ohne Relativpronomen wie "der/die/das".',text:'Beispiel: 昨日買った本 (das Buch, das ich gestern gekauft habe) — wörtlich "gestern-gekauftes Buch". Der Verb-Teil steht in der einfachen (Wörterbuch-)Form, nicht in der höflichen ます-Form, auch in ansonsten höflichen Sätzen.',tip:'Die Reihenfolge ist umgekehrt zum Deutschen: Der ganze Nebensatz kommt VOR dem Nomen, nicht danach. „Der Mann, der dort steht" wird zu „dort-stehender Mann" (あそこに立っている人).',ex:[["昨日買った本は面白いです。","きのうかったほんはおもしろいです。","Das Buch, das ich gestern gekauft habe, ist interessant."],["あそこに立っている人は先生です。","あそこにたっているひとはせんせいです。","Der Mann, der dort steht, ist der Lehrer."]],q:[{q:"Wo steht der beschreibende Verb-Teil im Vergleich zum Nomen?",o:["Direkt davor","Direkt danach","Am Satzende"],c:0},{q:"In welcher Form steht das Verb im Relativsatz?",o:["Einfache/Wörterbuchform","Immer ます-Form","Te-Form"],c:0},{q:"昨日買った本 bedeutet wörtlich:",o:["gestern-gekauftes Buch","das Buch von gestern (kein Kauf-Bezug)","das teure Buch"],c:0}]},{id:"n4-nakerebanarimasen",level:4,title:"〜なければなりません — Notwendigkeit",intro:'Um "müssen" auszudrücken, verneint man das Verb erst und hängt dann なければなりません an — wörtlich "wenn nicht ..., geht es nicht".',text:"Bildung: Verneinte Form (ない-Form) minus い, plus ければなりません: 行かない → 行かなければなりません (ich muss gehen). Im Alltag oft verkürzt zu 〜なきゃ (umgangssprachlich).",tip:"Diese doppelte Verneinung wirkt für Deutschsprachige zunächst unnötig kompliziert — mit Übung wird die Struktur aber schnell automatisch.",ex:[["明日行かなければなりません。","あしたいかなければなりません。","Ich muss morgen gehen."],["薬を飲まなければなりません。","くすりをのまなければなりません。","Ich muss Medikamente nehmen."]],q:[{q:"Wie wird なければなりません gebildet?",o:["Aus der verneinten (ない) Form","Aus der て-Form","Aus der Wörterbuchform direkt"],c:0},{q:"Was bedeutet なければなりません wörtlich?",o:["Wenn nicht ..., geht es nicht","Ich möchte nicht","Es ist verboten"],c:0},{q:"Wie lautet die umgangssprachliche Kurzform?",o:["〜なきゃ","〜なくて","〜ながら"],c:0}]},{id:"n4-soudesu",level:4,title:"そうです — Hörensagen & Anschein",intro:'そうです hat zwei völlig unterschiedliche Bedeutungen, je nachdem woran es angehängt wird: "ich habe gehört, dass..." oder "es sieht so aus, als ob...".',text:"Hörensagen (aus einer Quelle): Wörterbuchform/Vergangenheit + そうです — 雨が降るそうです (Ich habe gehört, es soll regnen). Anschein (eigene Beobachtung): Verb-Stamm oder Adjektiv-Stamm + そうです — 美味しそうです (Das sieht lecker aus).",tip:"Merkhilfe: Volle Satzform + そうです = Hörensagen (von anderen gehört). Verkürzter Stamm + そうです = eigener optischer Eindruck.",ex:[["雨が降るそうです。","あめがふるそうです。","Ich habe gehört, es soll regnen."],["このケーキは美味しそうです。","このけーきはおいしそうです。","Dieser Kuchen sieht lecker aus."]],q:[{q:"Volle Verbform + そうです drückt aus:",o:["Hörensagen (von jemandem gehört)","Eigenen optischen Eindruck","Eine Frage"],c:0},{q:"Verkürzter Stamm + そうです (z. B. 美味しそう) drückt aus:",o:["Wie etwas aussieht/wirkt","Eine feste Tatsache","Vergangenheit"],c:0},{q:"美味しそうです bedeutet:",o:["Das sieht lecker aus","Das war lecker","Ich habe gehört, es sei lecker"],c:0}]},{id:"n4-katagaiidesu",level:4,title:"〜方がいいです — Ratschläge geben",intro:'Mit 方がいいです gibst du einen Rat: "es wäre besser, ... zu tun" — bei Verneinung entsprechend "besser NICHT tun".',text:"Bildung: Vergangenheitsform (た-Form) + 方がいいです für positive Ratschläge: 行った方がいいです (Du solltest lieber gehen). Für negative Ratschläge: ない-Form + 方がいいです: 行かない方がいいです (Du solltest lieber nicht gehen).",tip:"Auch wenn grammatisch die Vergangenheitsform steht, geht es inhaltlich nicht um die Vergangenheit — das wirkt für Anfänger oft verwirrend, ist aber einfach die feste Konstruktion.",ex:[["早く寝た方がいいです。","はやくねたほうがいいです。","Du solltest lieber früh schlafen gehen."],["お酒を飲まない方がいいです。","おさけをのまないほうがいいです。","Du solltest lieber keinen Alkohol trinken."]],q:[{q:"Wie wird ein positiver Ratschlag mit 方がいいです gebildet?",o:["Vergangenheitsform (た-Form) + 方がいいです","Wörterbuchform + 方がいいです","ます-Form + 方がいいです"],c:0},{q:"Wie wird ein negativer Ratschlag gebildet?",o:["ない-Form + 方がいいです","た-Form + 方がいいです","て-Form + 方がいいです"],c:0},{q:"早く寝た方がいいです。 bedeutet:",o:["Du solltest lieber früh schlafen gehen","Du bist früh eingeschlafen","Schlaf niemals früh"],c:0}]},{id:"n4-kedo-noni",level:4,title:"けど・のに — Gegensatz ausdrücken",intro:'Neben から/ので für Gründe gibt es けど (umgangssprachlich für "aber/obwohl") und のに (drückt zusätzlich eine Portion Überraschung oder Enttäuschung aus).',text:'けど hängt einfach an einen ganzen Satz und bedeutet "aber/obwohl", eher neutral: 高いけど、買います (Es ist teuer, aber ich kaufe es). のに drückt denselben Gegensatz aus, transportiert aber zusätzlich Verwunderung oder Frustration: 勉強したのに、失敗しました (Obwohl ich gelernt habe, bin ich durchgefallen — mit spürbarer Enttäuschung).',tip:"だけど/だけれど sind etwas formellere/schriftsprachlichere Varianten von けど — alle bedeuten im Kern dasselbe.",ex:[["高いけど、買います。","たかいけど、かいます。","Es ist teuer, aber ich kaufe es."],["勉強したのに、失敗しました。","べんきょうしたのに、しっぱいしました。","Obwohl ich gelernt habe, bin ich durchgefallen."]],q:[{q:"Was transportiert のに zusätzlich zum reinen Gegensatz?",o:["Überraschung oder Enttäuschung","Eine Frage","Eine Bitte"],c:0},{q:"高いけど、買います。 bedeutet:",o:["Es ist teuer, aber ich kaufe es","Weil es teuer ist, kaufe ich es nicht","Es ist nicht teuer"],c:0},{q:"Welches Wort ist eine formellere Variante von けど?",o:["だけれど","のに","から"],c:0}]},{id:"n4-shieki-kei",level:4,title:"使役形 — Kausativ (lassen/veranlassen)",intro:'Die Kausativform drückt aus, dass jemand eine andere Person etwas TUN LÄSST oder dazu VERANLASST — je nach Kontext auch als Erlaubnis ("lassen") oder Zwang ("zwingen") verstanden.',text:'Bildung bei Godan-Verben: letzte Silbe in die a-Reihe + せる (書く → 書かせる, "schreiben lassen"). Bei Ichidan-Verben: る → させる (食べる → 食べさせる, "essen lassen"). Unregelmäßig: する → させる, 来る → 来させる. Wer die Handlung tatsächlich ausführt, wird meist mit に markiert: 先生は学生に本を読ませました (Der Lehrer ließ die Schüler das Buch lesen).',tip:'Ob させる als "erlauben" oder "zwingen" verstanden wird, hängt vom Kontext ab — anders als im Deutschen gibt es keine grammatische Unterscheidung zwischen beidem.',ex:[["先生は学生に本を読ませました。","せんせいはがくせいにほんをよませました。","Der Lehrer ließ die Schüler das Buch lesen."],["子供に野菜を食べさせます。","こどもにやさいをたべさせます。","Ich lasse das Kind Gemüse essen."]],q:[{q:"Was drückt die Kausativform aus?",o:["Jemanden etwas tun lassen/veranlassen","Eine Bitte","Die Vergangenheit"],c:0},{q:"Wie wird die Kausativform von 食べる gebildet?",o:["食べさせる","食べられる","食べれる"],c:0},{q:"Welches Partikel markiert meist die Person, die die Handlung ausführt?",o:["に","を","が"],c:0}]},{id:"n4-temiru",level:4,title:"〜てみる — etwas ausprobieren",intro:'Mit てみる drückst du aus, dass du etwas einmal probierst oder ausprobierst — wörtlich "tun und sehen".',text:'Bildung: て-Form + みる. 食べてみます (Ich probiere es zu essen). Das みる kommt vom Verb 見る (sehen), wird hier aber rein grammatisch als "ausprobieren" verstanden, nicht wörtlich als "sehen".',tip:"Sehr nützlich für Empfehlungen: このお寿司を食べてみてください (Probieren Sie doch mal dieses Sushi).",ex:[["このお寿司を食べてみてください。","このおすしをたべてみてください。","Probieren Sie doch mal dieses Sushi."],["新しい店に行ってみました。","あたらしいみせにいってみました。","Ich habe das neue Geschäft mal ausprobiert."]],q:[{q:"Wie wird てみる gebildet?",o:["て-Form + みる","Wörterbuchform + みる","ない-Form + みる"],c:0},{q:"Was bedeutet てみる ungefähr?",o:["Etwas ausprobieren","Etwas beenden","Etwas bereuen"],c:0},{q:"食べてみます bedeutet:",o:["Ich probiere es zu essen","Ich habe schon gegessen","Ich esse nie"],c:0}]},{id:"n4-teoku",level:4,title:"〜ておく — im Voraus erledigen",intro:"Mit ておく drückst du aus, dass du etwas jetzt schon erledigst, damit es später bereit/praktisch ist — eine vorbereitende Handlung.",text:"Bildung: て-Form + おく. 予約しておきます (Ich reserviere schon mal im Voraus). Im Alltag oft zu とく verkürzt (umgangssprachlich): 買っとく statt 買っておく.",tip:'Die Grundbedeutung von おく ist "hinlegen/platzieren" — die Handlung wird bildlich "für später hingelegt/bereitgestellt".',ex:[["チケットを予約しておきます。","ちけっとをよやくしておきます。","Ich reserviere die Tickets schon im Voraus."],["冷蔵庫に入れておいてください。","れいぞうこにいれておいてください。","Bitte leg es schon mal in den Kühlschrank."]],q:[{q:"Wie wird ておく gebildet?",o:["て-Form + おく","た-Form + おく","ます-Form + おく"],c:0},{q:"Was drückt ておく aus?",o:["Eine vorbereitende Handlung für später","Bedauern","Eine Vermutung"],c:0},{q:"Wie lautet die umgangssprachliche Kurzform?",o:["〜とく","〜とる","〜どく"],c:0}]},{id:"n4-teshimau",level:4,title:"〜てしまう — vollständig/versehentlich tun",intro:"てしまう betont, dass eine Handlung vollständig abgeschlossen ist — oft mit einer Nebenbedeutung von Bedauern, wenn etwas ungewollt oder versehentlich passiert ist.",text:'Bildung: て-Form + しまう. 忘れてしまいました (Ich habe es leider vergessen). Ohne Bedauern-Kontext kann てしまう auch einfach "komplett fertig machen" bedeuten: 宿題をやってしまいました (Ich habe die Hausaufgabe ganz fertig gemacht).',tip:"Umgangssprachlich oft zu ちゃう/じゃう verkürzt: 忘れちゃった statt 忘れてしまった.",ex:[["財布を忘れてしまいました。","さいふをわすれてしまいました。","Ich habe leider mein Portemonnaie vergessen."],["宿題をやってしまいました。","しゅくだいをやってしまいました。","Ich habe die Hausaufgabe komplett fertig gemacht."]],q:[{q:"Welche Nebenbedeutung transportiert てしまう oft?",o:["Bedauern über etwas Versehentliches","Eine Bitte","Eine Vermutung"],c:0},{q:"Wie wird てしまう umgangssprachlich verkürzt?",o:["〜ちゃう","〜とく","〜なきゃ"],c:0},{q:"財布を忘れてしまいました。 bedeutet:",o:["Ich habe leider mein Portemonnaie vergessen","Ich habe mein Portemonnaie gefunden","Ich brauche kein Portemonnaie"],c:0}]},{id:"n4-takotogaaru",level:4,title:"〜たことがある — Erfahrung ausdrücken",intro:"Mit たことがある sagst du, dass du etwas schon (mindestens) einmal in deinem Leben getan/erlebt hast — Erfahrung, nicht ein konkretes einzelnes Ereignis.",text:"Bildung: Vergangenheitsform (た-Form) + ことがある. 日本に行ったことがあります (Ich bin schon einmal in Japan gewesen). Verneint: 〜たことがありません (noch nie getan haben).",tip:"Unterschied zur einfachen Vergangenheit: 日本に行きました (ich bin [an einem bestimmten Zeitpunkt] gefahren) vs. 日本に行ったことがあります (ich habe die Erfahrung, schon mal dort gewesen zu sein — ohne konkreten Zeitbezug).",ex:[["日本に行ったことがあります。","にほんにいったことがあります。","Ich bin schon einmal in Japan gewesen."],["寿司を食べたことがありません。","すしをたべたことがありません。","Ich habe noch nie Sushi gegessen."]],q:[{q:"Was drückt たことがある aus?",o:["Erfahrung, etwas schon einmal getan zu haben","Eine geplante Zukunft","Eine Vermutung"],c:0},{q:"Wie wird たことがある gebildet?",o:["Vergangenheitsform (た-Form) + ことがある","Wörterbuchform + ことがある","ます-Form + ことがある"],c:0},{q:"寿司を食べたことがありません。 bedeutet:",o:["Ich habe noch nie Sushi gegessen","Ich esse gerade Sushi","Ich mag kein Sushi"],c:0}]},{id:"n4-youninaru",level:4,title:"〜ようになる — eine Veränderung erreichen",intro:"Mit ようになる drückst du aus, dass sich ein Zustand im Laufe der Zeit verändert hat — oft für neu erworbene Fähigkeiten oder Gewohnheiten.",text:"Bildung: Wörterbuchform des Verbs (oft Potentialform) + ようになる. 漢字が読めるようになりました (Ich kann jetzt Kanji lesen — konnte ich vorher nicht). Betont die VERÄNDERUNG selbst, nicht nur den aktuellen Zustand.",tip:"ようになる wird sehr oft mit der Potentialform kombiniert, z. B. 泳げるようになりました (Ich kann jetzt schwimmen — konnte es vorher nicht).",ex:[["漢字が読めるようになりました。","かんじがよめるようになりました。","Ich kann jetzt Kanji lesen (konnte ich vorher nicht)."],["毎日運動するようになりました。","まいにちうんどうするようになりました。","Ich bin dazu übergegangen, jeden Tag Sport zu machen."]],q:[{q:"Was betont ようになる besonders?",o:["Eine Veränderung im Zeitverlauf","Eine einmalige Handlung","Eine Verneinung"],c:0},{q:"Mit welcher Form wird ようになる oft kombiniert?",o:["Potentialform","Kausativform","Passivform"],c:0},{q:"漢字が読めるようになりました。 bedeutet:",o:["Ich kann jetzt Kanji lesen (vorher nicht)","Ich habe Kanji nie gelernt","Ich lese gerade Kanji"],c:0}]},{id:"n4-sugiru",level:4,title:"〜すぎる — zu viel / übermäßig",intro:'すぎる hängt an Verben oder Adjektive und drückt aus, dass etwas ein übertriebenes/zu hohes Maß erreicht — "zu ...".',text:'Bildung bei Adjektiven: Stamm + すぎる (高い → 高すぎる, "zu teuer"). Bei Verben: Stamm (ます-Form ohne ます) + すぎる: 食べる → 食べすぎる ("zu viel essen"). Wird oft in der Vergangenheit verwendet, um ein bereits eingetretenes Übermaß zu beschreiben.',tip:"食べ過ぎた (zu viel gegessen) ist einer der alltäglichsten Sätze nach einem großen Essen — die Konstruktion ist extrem gebräuchlich.",ex:[["このコーヒーは熱すぎます。","このこーひーはあつすぎます。","Dieser Kaffee ist zu heiß."],["昨日食べ過ぎました。","きのうたべすぎました。","Gestern habe ich zu viel gegessen."]],q:[{q:"Wie wird すぎる bei Adjektiven gebildet?",o:["Adjektiv-Stamm + すぎる","Ganzes Adjektiv + すぎる","ない-Form + すぎる"],c:0},{q:"食べ過ぎました bedeutet:",o:["Ich habe zu viel gegessen","Ich habe nichts gegessen","Ich esse gerade"],c:0},{q:"高すぎます bedeutet:",o:["Es ist zu teuer","Es ist billig","Es ist nicht teuer genug"],c:0}]},{id:"n4-keigo",level:4,title:"敬語 — Grundlagen der Höflichkeitssprache",intro:"Keigo ist ein System von drei Sprachebenen, das ausdrückt, wie man sich selbst und andere je nach sozialer Situation respektvoll positioniert — weit über die normale です/ます-Höflichkeit hinaus.",text:'Es gibt drei Hauptebenen: 尊敬語 (sonkeigo, erhöhende Sprache für die Handlungen des Gegenübers, z. B. 召し上がる statt 食べる für "essen"), 謙譲語 (kenjougo, bescheidene Sprache für die eigenen Handlungen, z. B. いただく statt 食べる), und 丁寧語 (teineigo, die einfache Höflichkeitsebene mit です/ます, die im ganzen Lernpfad schon durchgehend verwendet wird).',tip:"Als Faustregel für den Anfang: 尊敬語 hebt die andere Person hoch, 謙譲語 senkt die eigene Position ab — beide Richtungen erzeugen denselben Effekt von Respekt.",ex:[["先生が召し上がります。","せんせいがめしあがります。","Der Lehrer isst (erhöhende Form)."],["私がいただきます。","わたしがいただきます。","Ich esse (bescheidene Form)."]],q:[{q:"Wie viele Hauptebenen hat Keigo?",o:["Drei","Zwei","Fünf"],c:0},{q:"Was macht 尊敬語?",o:["Erhöht die Handlungen des Gegenübers","Senkt die eigene Position ab","Ist nur für Fragen gedacht"],c:0},{q:"Was macht 謙譲語?",o:["Senkt die eigenen Handlungen bescheiden ab","Erhöht die eigene Position","Wird nur schriftlich verwendet"],c:0}]},{id:"n4-teageru-tekureru-temorau",level:4,title:"てあげる・てくれる・てもらう — Handlungen als Gefallen",intro:"Genau wie あげる/くれる/もらう bei Gegenständen die Blickrichtung des Gebens anzeigen, funktionieren てあげる/てくれる/てもらう für HANDLUNGEN, die als Gefallen für jemanden getan werden.",text:"てあげる: ich tue etwas FÜR jemand anderen — 手伝ってあげます (Ich helfe dir als Gefallen). てくれる: jemand tut etwas FÜR MICH — 手伝ってくれます (Er/sie hilft mir). てもらう: ich LASSE MIR von jemandem einen Gefallen tun — 手伝ってもらいます (Ich lasse mir helfen).",tip:'てあげる kann gegenüber ranghöheren Personen unhöflich wirken, da es impliziert, man tue ihnen einen Gefallen "von oben herab" — bei Vorgesetzten besser die Handlung neutral formulieren.',ex:[["友達を手伝ってあげました。","ともだちをてつだってあげました。","Ich habe meinem Freund geholfen (als Gefallen)."],["母が手伝ってくれました。","ははがてつだってくれました。","Meine Mutter hat mir geholfen."]],q:[{q:"Was drückt てくれる aus?",o:["Jemand tut etwas für MICH","Ich tue etwas für jemanden","Eine Vermutung"],c:0},{q:"Warum kann てあげる gegenüber Vorgesetzten unhöflich wirken?",o:['Es klingt wie ein Gefallen "von oben herab"',"Es ist grammatisch falsch","Es existiert in dieser Form nicht"],c:0},{q:"手伝ってもらいます bedeutet:",o:["Ich lasse mir helfen / bekomme Hilfe","Ich helfe jemandem","Ich brauche keine Hilfe"],c:0}]},{id:"n4-yasui-nikui",level:4,title:"〜やすい・〜にくい — leicht/schwer zu tun",intro:"Mit やすい und にくい drückst du aus, wie leicht oder schwer sich etwas tun lässt — angehängt direkt an den Verb-Stamm.",text:'Bildung: Verb-Stamm (ます-Form ohne ます) + やすい ("leicht zu tun") oder にくい ("schwer zu tun"). 読みやすい本 (ein leicht zu lesendes Buch), 読みにくい字 (schwer zu lesende Schrift).',tip:"Beide werden wie normale い-Adjektive weiter konjugiert: 読みやすかったです (war leicht zu lesen), 読みにくくないです (ist nicht schwer zu lesen).",ex:[["この本は読みやすいです。","このほんはよみやすいです。","Dieses Buch ist leicht zu lesen."],["彼の字は読みにくいです。","かれのじはよみにくいです。","Seine Handschrift ist schwer zu lesen."]],q:[{q:"Wie wird やすい/にくい gebildet?",o:["Verb-Stamm + やすい/にくい","Wörterbuchform + やすい/にくい","て-Form + やすい/にくい"],c:0},{q:"Was bedeutet 読みやすい?",o:["Leicht zu lesen","Schwer zu lesen","Ich lese gerade"],c:0},{q:"Wie werden やすい/にくい weiter konjugiert?",o:["Wie normale い-Adjektive","Wie な-Adjektive","Sie können nicht konjugiert werden"],c:0}]},{id:"n4-mama",level:4,title:"〜まま — Zustand unverändert lassen",intro:'まま drückt aus, dass ein Zustand unverändert bleibt, während etwas anderes passiert — "so wie es ist" oder "ohne dass sich etwas ändert".',text:"Bildung: Vergangenheitsform (た-Form) eines Verbs + まま, oder Nomen + の + まま. 靴を履いたまま入りました (Ich bin mit Schuhen an hineingegangen). 電気をつけたまま寝ました (Ich habe mit brennendem Licht geschlafen).",tip:"まま betont oft, dass etwas eigentlich hätte geändert werden sollen (Schuhe ausziehen, Licht ausschalten), es aber nicht wurde — ein leichter Unterton von Nachlässigkeit schwingt oft mit.",ex:[["靴を履いたまま入りました。","くつをはいたままはいりました。","Ich bin mit Schuhen an hineingegangen."],["電気をつけたまま寝ました。","でんきをつけたままねました。","Ich bin mit brennendem Licht eingeschlafen."]],q:[{q:"Was drückt まま aus?",o:["Ein unveränderter Zustand während etwas anderes passiert","Eine Vermutung","Eine Frage"],c:0},{q:"Wie wird まま bei Verben gebildet?",o:["た-Form + まま","Wörterbuchform + まま","ない-Form + まま"],c:0},{q:"靴を履いたまま入りました。 bedeutet:",o:["Ich bin mit Schuhen an hineingegangen","Ich habe die Schuhe ausgezogen","Ich kaufe neue Schuhe"],c:0}]},{id:"n4-toshite",level:4,title:"〜として — als / in der Rolle von",intro:'として drückt eine Rolle, Funktion oder Eigenschaft aus, in der jemand oder etwas auftritt — vergleichbar mit "als" im Deutschen.',text:"Bildung: Nomen + として. 先生として働いています (Ich arbeite als Lehrer). 友達としてアドバイスします (Ich gebe dir als Freund einen Rat) — betont dabei die konkrete Rolle/Funktion.",tip:"Nicht zu verwechseln mit の (Besitz) — として bezeichnet eine FUNKTION, keinen Besitz oder eine feste Eigenschaft.",ex:[["彼は医者として働いています。","かれはいしゃとしてはたらいています。","Er arbeitet als Arzt."],["友達としてアドバイスします。","ともだちとしてあどばいすします。","Ich gebe dir als Freund einen Rat."]],q:[{q:"Was drückt として aus?",o:["Eine Rolle oder Funktion","Besitz","Die Vergangenheit"],c:0},{q:"彼は医者として働いています。 bedeutet:",o:["Er arbeitet als Arzt","Er besucht einen Arzt","Er wird bald Arzt"],c:0},{q:"Womit wird として oft verwechselt, obwohl es etwas anderes bedeutet?",o:["の (Besitz)","から (Grund)","けど (Gegensatz)"],c:0}]},{id:"n4-nioite",level:3,title:"〜において — in / bei (formell)",intro:"において ist eine formelle, meist schriftliche Variante von で oder に, um einen Ort, Bereich oder Kontext anzugeben — häufig in offiziellen Ankündigungen oder Aufsätzen.",text:"Bildung: Nomen + において. 会議は本社において行われます (Die Besprechung findet in der Zentrale statt) — im Alltag würde man hier einfach で verwenden, において klingt deutlich formeller/schriftsprachlicher.",tip:"In der gesprochenen Alltagssprache wirkt において fast immer zu steif — es lohnt sich, den Unterschied zu erkennen, aber im lockeren Gespräch bei で/に zu bleiben.",ex:[["会議は本社において行われます。","かいぎはほんしゃにおいておこなわれます。","Die Besprechung findet in der Zentrale statt."],["現代社会において重要です。","げんだいしゃかいにおいてじゅうようです。","In der modernen Gesellschaft ist das wichtig."]],q:[{q:"Wofür ist において eine formellere Alternative?",o:["で/に","から","けど"],c:0},{q:"Wo begegnet einem において typischerweise?",o:["In offiziellen Ankündigungen/Aufsätzen","Nur in SMS an Freunde","Nur bei Zahlen"],c:0},{q:"Ist において für lockere Alltagsgespräche geeignet?",o:["Eher nicht, wirkt zu förmlich","Ja, ist die Standardform","Nur bei Fragen"],c:0}]},{id:"n4-bakari",level:4,title:"〜ばかり — nur / gerade erst",intro:'ばかり hat zwei Hauptbedeutungen: "nur/ausschließlich" bei Nomen, und "gerade erst getan" bei der Vergangenheitsform von Verben.',text:'Bei Nomen: 彼はゲームばかりしています (Er macht nur/ständig Videospiele). Bei Verben: た-Form + ばかり = "gerade erst getan": 今、着いたばかりです (Ich bin gerade erst angekommen).',tip:'Bei der "gerade erst"-Bedeutung schwingt oft eine Nuance von "es fühlt sich noch ganz frisch an" mit — nicht nur eine reine Zeitangabe.',ex:[["彼はゲームばかりしています。","かれはげーむばかりしています。","Er macht nur Videospiele."],["今、着いたばかりです。","いま、ついたばかりです。","Ich bin gerade erst angekommen."]],q:[{q:"Was bedeutet ばかり bei Nomen?",o:["nur/ausschließlich","vielleicht","niemals"],c:0},{q:'Wie wird "gerade erst getan" ausgedrückt?',o:["た-Form + ばかり","て-Form + ばかり","Wörterbuchform + ばかり"],c:0},{q:"今、着いたばかりです。 bedeutet:",o:["Ich bin gerade erst angekommen","Ich komme morgen an","Ich bin nie angekommen"],c:0}]},{id:"n4-nimokakawarazu",level:3,title:"〜にもかかわらず — trotz / obwohl",intro:'にもかかわらず drückt einen starken Gegensatz aus — "trotz X" oder "obwohl X" — und wirkt formeller als けど/のに.',text:"Bildung: Nomen/Satz (einfache Form) + にもかかわらず. 雨にもかかわらず、行きました (Trotz des Regens bin ich gegangen). Wird oft in Berichten, Nachrichten oder formellen Texten verwendet.",tip:'にもかかわらず betont die Unerwartetheit stärker als のに — es klingt fast wie "und das, obwohl eigentlich..." mit leichtem Erstaunen.',ex:[["雨にもかかわらず、行きました。","あめにもかかわらず、いきました。","Trotz des Regens bin ich gegangen."],["忙しいにもかかわらず、手伝ってくれました。","いそがしいにもかかわらず、てつだってくれました。","Obwohl er beschäftigt war, hat er mir geholfen."]],q:[{q:"Was drückt にもかかわらず aus?",o:["Einen starken Gegensatz (trotz/obwohl)","Einen Grund","Eine Vermutung"],c:0},{q:"Wie wirkt にもかかわらず im Vergleich zu のに?",o:["Formeller","Umgangssprachlicher","Bedeutet das Gegenteil"],c:0},{q:"雨にもかかわらず、行きました。 bedeutet:",o:["Trotz des Regens bin ich gegangen","Wegen des Regens bin ich nicht gegangen","Es regnet nicht"],c:0}]},{id:"n4-bekida",level:3,title:"〜べきだ — man sollte",intro:'べきだ drückt eine moralische oder allgemein anerkannte Pflicht/Empfehlung aus — stärker als 方がいいです, eher in Richtung "das ist die richtige Sache zu tun".',text:"Bildung: Wörterbuchform des Verbs + べきだ. 約束を守るべきです (Man sollte Versprechen halten). Bei する wird oft die Kurzform すべき verwendet statt するべき.",tip:"べきだ klingt bestimmter/moralischer als 方がいいです — für einen lockeren Ratschlag bleibt man eher bei 方がいいです, für eine klare Pflicht/Norm nimmt man べきだ.",ex:[["約束を守るべきです。","やくそくをまもるべきです。","Man sollte Versprechen halten."],["もっと勉強すべきです。","もっとべんきょうすべきです。","Du solltest mehr lernen."]],q:[{q:"Wie stark ist べきだ im Vergleich zu 方がいいです?",o:["Stärker/moralischer","Schwächer","Bedeutet dasselbe ohne Unterschied"],c:0},{q:"Wie wird べきだ gebildet?",o:["Wörterbuchform + べきだ","た-Form + べきだ","ない-Form + べきだ"],c:0},{q:"Welche Kurzform gibt es bei する?",o:["すべき","するべき (nur diese Form)","しべき"],c:0}]},{id:"n4-wakeda",level:3,title:"〜わけだ — das erklärt es / kein Wunder",intro:'わけだ zieht eine logische Schlussfolgerung aus etwas zuvor Gesagtem — "das erklärt, warum..." oder "kein Wunder, dass...".',text:"Bildung: Satz (einfache Form) + わけだ. 三年間日本に住んでいた。だから日本語が上手なわけだ (Er hat drei Jahre in Japan gelebt. Kein Wunder, dass er gut Japanisch spricht).",tip:"わけだ setzt voraus, dass der Zuhörer bereits eine Information hat, aus der jetzt eine logische Konsequenz gezogen wird — es erklärt einen Zusammenhang, statt einfach eine neue Tatsache zu nennen.",ex:[["三年間住んでいた。だから上手なわけだ。","さんねんかんすんでいた。だからじょうずなわけだ。","Er hat drei Jahre dort gelebt. Kein Wunder, dass er gut ist."],["道理で分からないわけだ。","どうりでわからないわけだ。","Kein Wunder, dass ich es nicht verstehe."]],q:[{q:"Was macht わけだ?",o:["Zieht eine logische Schlussfolgerung","Stellt eine Frage","Drückt eine Bitte aus"],c:0},{q:"Was setzt わけだ beim Zuhörer voraus?",o:["Eine bereits bekannte Information, aus der eine Konsequenz folgt","Nichts, es ist eine reine Neuigkeit","Eine Entschuldigung"],c:0},{q:"道理で分からないわけだ。 bedeutet ungefähr:",o:["Kein Wunder, dass ich es nicht verstehe","Ich verstehe alles","Bitte erkläre es mir"],c:0}]},{id:"n4-youto-u",level:4,title:"〜ようと思う — vorhaben / die Absicht haben",intro:'Mit der Volitionalform (よう) + と思う drückst du eine konkrete eigene Absicht aus — "ich habe vor, zu..." oder "ich denke, ich werde...".',text:"Bildung: Volitionalform + と思う. 来年日本に行こうと思います (Ich habe vor, nächstes Jahr nach Japan zu gehen). Unterschied zu たいです (Wunsch): ようと思う klingt nach einer konkreteren, aktiveren Entscheidung, nicht nur einem Wunsch.",tip:"思っています (statt 思います) wird oft für einen bereits länger gehegten Plan verwendet, während 思います eher eine spontane, gerade gefasste Absicht ausdrückt.",ex:[["来年日本に行こうと思います。","らいねんにほんにいこうとおもいます。","Ich habe vor, nächstes Jahr nach Japan zu gehen."],["もっと運動しようと思っています。","もっとうんどうしようとおもっています。","Ich habe vor, mehr Sport zu treiben."]],q:[{q:"Wie wird ようと思う gebildet?",o:["Volitionalform + と思う","Wörterbuchform + と思う","ない-Form + と思う"],c:0},{q:"Was ist der Unterschied zu たいです?",o:["ようと思う klingt nach einer konkreteren Entscheidung","Es gibt keinen Unterschied","たいです ist förmlicher"],c:0},{q:"Wofür wird oft 思っています statt 思います verwendet?",o:["Einen länger gehegten Plan","Eine spontane Idee","Eine Vergangenheit"],c:0}]},{id:"n4-tsutsu",level:3,title:"〜つつ — während (formell)",intro:"つつ verbindet zwei gleichzeitige Handlungen, ähnlich wie ながら, wirkt aber deutlich formeller/schriftsprachlicher.",text:'Bildung: Verb-Stamm + つつ. 音楽を聞きつつ、勉強します (Ich lerne, während ich Musik höre) — in gesprochener Sprache würde man eher ながら sagen. つつ kann auch "obwohl" bedeuten: 悪いと知りつつ、やってしまった (Ich habe es getan, obwohl ich wusste, dass es falsch ist).',tip:"Im Alltag hört man つつ selten — es lohnt sich vor allem, es beim Lesen zu erkennen, nicht unbedingt aktiv zu verwenden.",ex:[["音楽を聞きつつ、勉強します。","おんがくをききつつ、べんきょうします。","Ich lerne, während ich Musik höre."],["悪いと知りつつ、やってしまった。","わるいとしりつつ、やってしまった。","Ich habe es getan, obwohl ich wusste, dass es falsch ist."]],q:[{q:"Wofür ist つつ eine formellere Alternative?",o:["ながら","けど","から"],c:0},{q:'Welche zusätzliche Bedeutung kann つつ neben "während" haben?',o:["obwohl (Gegensatz)","eine Frage","eine Verneinung"],c:0},{q:"Wird つつ häufig in der gesprochenen Alltagssprache verwendet?",o:["Nein, eher selten/schriftsprachlich","Ja, ständig","Nur bei Kindern"],c:0}]},{id:"n4c-futsuu-kei",level:4,section:"casual",title:"普通形 — Der lockere Sprachstil",intro:'Bisher hast du fast nur den höflichen です/ます-Stil gelernt — den richtigen für Fremde, Kunden, das Büro. Mit Freunden, Familie und in fast jedem Anime/Manga-Dialog wird aber der lockere "普通形" (Plain Form) gesprochen.',text:"Die Wörterbuchform selbst IST schon die lockere Gegenwartsform: 食べます → 食べる, 飲みます → 飲む, 行きます → 行く. Man tauscht also nicht nur die Endung aus, sondern nutzt die Grundform, die du schon aus dem Wörterbuch/den Vokabellisten kennst.",tip:"Höflich und locker zu mischen (z.B. mitten im lockeren Gespräch plötzlich です) wirkt oft unnatürlich steif — Muttersprachler bleiben meist konsequent in einem Register.",ex:[["明日、映画を見る。","あした、えいがをみる。","Morgen schaue ich einen Film. (locker)"],["明日、映画を見ます。","あした、えいがをみます。","Morgen schaue ich einen Film. (höflich)"]],q:[{q:"Welche Form ist die lockere Gegenwartsform von 食べます?",o:["食べる","食べて","食べた"],c:0},{q:"Wann verwendet man typischerweise den 普通形-Stil?",o:["Mit Freunden und Familie","Nur im Büro","Nur beim Schreiben von Briefen"],c:0},{q:"Was wirkt oft unnatürlich?",o:["Höflich und locker im selben Gespräch zu mischen","Immer höflich zu bleiben","Immer locker zu bleiben"],c:0}]},{id:"n4c-da",level:4,section:"casual",title:"だ — Die lockere Kopula",intro:"So wie 見る die lockere Form von 見ます ist, ist だ die lockere Form von です.",text:"学生です → 学生だ (ich bin Student). Bei な-Adjektiven genauso: 元気です → 元気だ. Bei い-Adjektiven fällt です meist ganz weg: 大きいです → 大きい (kein だ nötig!). Wichtig: だ wird direkt VOR einer Frage (か) fast nie verwendet — 学生？ reicht mit fragender Betonung.",tip:"だ am Satzende klingt bei Frauen in der Umgangssprache manchmal recht grob/männlich — in echten Gesprächen lässt man だ am Satzende deshalb oft ganz weg: 学生。statt 学生だ。.",ex:[["私は学生だ。","わたしはがくせいだ。","Ich bin Student. (locker, betont)"],["今日は暇だ。","きょうはひまだ。","Heute habe ich frei. (locker)"]],q:[{q:"Was ist die lockere Form von です?",o:["だ","じゃ","では"],c:0},{q:"Was passiert bei い-Adjektiven im lockeren Stil?",o:["です fällt einfach weg","だ wird angehängt","Nichts ändert sich"],c:0},{q:"Warum lässt man だ am Satzende in echten Gesprächen oft weg?",o:["Es kann grob/männlich klingen","Es ist grammatisch falsch","Es bedeutet dann etwas anderes"],c:0}]},{id:"n4c-verneinung-vergangenheit",level:4,section:"casual",title:"Verneinung & Vergangenheit — lockerer Stil",intro:"Auch Verneinung und Vergangenheit haben eigene lockere Formen, die sich von den ません/ませんでした-Formen unterscheiden.",text:"Verben: 食べません → 食べない, 食べませんでした → 食べなかった. い-Adjektive: 大きくないです → 大きくない, 大きくなかったです → 大きくなかった. な-Adjektive/Nomen: 元気じゃないです → 元気じゃない, 元気じゃなかったです → 元気じゃなかった.",tip:"ない-Form aller Verben verhält sich wie ein い-Adjektiv — deshalb ist die Vergangenheit immer 〜なかった, egal bei welcher Verbgruppe.",ex:[["昨日、勉強しなかった。","きのう、べんきょうしなかった。","Gestern habe ich nicht gelernt."],["あの映画は面白くなかった。","あのえいがはおもしろくなかった。","Der Film war nicht interessant."]],q:[{q:"Was ist die lockere Vergangenheitsform von 食べません?",o:["食べなかった","食べません","食べなくて"],c:0},{q:"Wie verhält sich die ない-Form grammatisch?",o:["Wie ein い-Adjektiv","Wie ein な-Adjektiv","Wie ein Partikel"],c:0},{q:"Wie verneint man 元気だ (locker, Vergangenheit)?",o:["元気じゃなかった","元気じゃないでした","元気なかった"],c:0}]},{id:"n4c-yo-ne-wa",level:4,section:"casual",title:"よ・ね・わ — Satzendpartikel",intro:"Diese kleinen Partikel ans Satzende geben einem Satz emotionale Farbe — dafür gibt es im Deutschen keine direkte Entsprechung, sie fehlen im höflichen Lehrbuch-Japanisch aber fast nie im echten Gespräch.",text:'よ betont eine neue Information für den Zuhörer ("das solltest du wissen!"): 明日は休みだよ (Morgen ist frei, [übrigens]!). ね sucht Zustimmung/Bestätigung, ähnlich "oder?"/"nicht wahr?": いい天気ですね (Schönes Wetter, nicht?). わ (traditionell eher weiblich/sanft) drückt leichte Betonung oder Überraschung aus: すごいわ (Krass, wow).',tip:"よ und ね werden oft kombiniert: 美味しいよね (Ist doch lecker, oder?) — bestätigt UND informiert gleichzeitig.",ex:[["明日は休みだよ。","あしたはやすみだよ。","Morgen ist frei, [das wusstest du nicht, oder]!"],["いい天気ですね。","いいてんきですね。","Schönes Wetter, nicht wahr?"]],q:[{q:"Welches Partikel betont eine für den Zuhörer neue Information?",o:["よ","ね","わ"],c:0},{q:"Welches Partikel sucht eher Zustimmung/Bestätigung?",o:["ね","よ","を"],c:0},{q:"Was bedeutet 美味しいよね ungefähr?",o:["Ist doch lecker, oder?","Ist das lecker?","Es ist nicht lecker."],c:0}]},{id:"n4c-lockere-fragen-ohne-ka",level:4,section:"casual",title:"Lockere Fragen ohne か",intro:"Im höflichen Stil hängt man für Fragen einfach か an — im lockeren Stil lässt man か meistens ganz weg und hebt stattdessen am Satzende die Stimme.",text:'食べる？(mit steigender Betonung) bedeutet "Isst du (das)?" — genau wie 食べますか, nur locker und ohne か. Schriftlich erkennt man das oft am Fragezeichen statt か. Bei だ-Sätzen fällt für die Frage sogar だ selbst weg: 学生？statt 学生だ？.',tip:"か kann im lockeren Stil trotzdem vorkommen, wirkt dann aber oft schroff/direkt, fast wie ein Verhör — besonders unter Freunden eher vermeiden.",ex:[["もう食べた？","もうたべた？","Hast du schon gegessen?"],["元気？","げんき？","Geht’s dir gut?"]],q:[{q:"Wie stellt man im lockeren Stil typischerweise eine Frage?",o:["か weglassen, Stimme am Ende heben","Immer か anhängen","Das Verb verdoppeln"],c:0},{q:"Was passiert bei だ-Sätzen in der lockeren Frage?",o:["だ fällt weg","だ wird zu です","だ bleibt immer stehen"],c:0},{q:"Wie kann か im lockeren Stil wirken?",o:["Schroff/direkt, fast wie ein Verhör","Immer sehr höflich","Bedeutungslos"],c:0}]},{id:"n4c-teru-deshiyo",level:4,section:"casual",title:"てる・でしょ — häufige Verkürzungen",intro:'In schnellem, echtem Gespräch werden manche Endungen regelmäßig verschliffen — wer nur die "sauberen" Lehrbuchformen kennt, tut sich beim Hören oft schwer.',text:"ている (Verlaufsform) wird gesprochen fast immer zu てる verkürzt: 食べている → 食べてる (isst gerade). でしょう wird locker zu でしょ: たぶん来るでしょ (Kommt wohl, oder?). Auch という wird oft zu って verkürzt: 田中さんが来るって (Ich hab gehört, Tanaka kommt).",tip:'Diese Verkürzungen sind KEIN "falsches Japanisch" — sie sind der normale gesprochene Standard. Nur beim formellen Schreiben bleibt man bei den vollen Formen.',ex:[["今、勉強してる。","いま、べんきょうしてる。","Ich lerne gerade."],["雨が降るって。","あめがふるって。","Es soll wohl regnen (hab ich gehört)."]],q:[{q:"Zu was wird ている in schnellem Gespräch oft verkürzt?",o:["てる","てい","ている bleibt immer voll"],c:0},{q:"Wofür steht die Verkürzung って oft?",o:["という (Hörensagen/Zitat)","ではない","ています"],c:0},{q:'Sind diese Verkürzungen "falsches" Japanisch?',o:["Nein, normaler gesprochener Standard","Ja, grammatisch falsch","Nur Kinder benutzen sie"],c:0}]},{id:"n4c-jiyan-daro",level:4,section:"casual",title:"じゃん・だろ — Bestätigung und Vermutung",intro:"Zwei weitere sehr häufige lockere Endungen, die im Lehrbuch-Japanisch praktisch nie auftauchen, in echten Gesprächen aber ständig.",text:'じゃん drückt überraschte Feststellung oder Bestätigung aus, ungefähr "ist doch so, oder": いいじゃん！(Ist doch gut/cool!). だろ ist die lockere, meist männlich wirkende Kurzform von でしょう — eine Vermutung oder rhetorische Bestätigung: そうだろ？(Ist doch so, oder?).',tip:"じゃん stammt ursprünglich aus westkantōischen Mundarten (Raum Kanagawa, Yamanashi, Shizuoka), ist aber längst im ganz normalen lockeren Standardjapanisch angekommen — überall zu hören, nicht nur in einer Region.",ex:[["すごいじゃん！","すごいじゃん！","Krass, oder!/Ist doch stark!"],["お前もそう思うだろ？","おまえもそうおもうだろ？","Du denkst doch auch so, oder?"]],q:[{q:"Was drückt じゃん ungefähr aus?",o:['Überraschte Feststellung/Bestätigung ("ist doch so")',"Eine höfliche Frage","Eine Verneinung"],c:0},{q:"だろ ist die lockere Kurzform von welchem Wort?",o:["でしょう","ではない","でした"],c:0},{q:"Woher stammt じゃん ursprünglich?",o:["Aus einem regionalen Dialekt, heute überall verbreitet","Nur aus dem Kansai-Dialekt, sonst nirgends verwendet","Es ist ein ganz neues Internet-Wort"],c:0}]},{id:"n4c-chou-mechiya",level:4,section:"casual",title:"超・めっちゃ — lockere Verstärkungswörter",intro:'Für "sehr"/"total" gibt es im lockeren Stil viel farbigere Alternativen zu とても, die im Alltag (und in Anime/Manga) ständig zu hören sind.',text:'超 (ちょう, wörtlich "super/ultra") und めっちゃ (ursprünglich Kansai-Dialekt, heute landesweit) bedeuten beide umgangssprachlich "sehr/total": 超楽しい！(Total lustig!), めっちゃ美味しい (Voll lecker). Beide klingen deutlich lebendiger und jugendlicher als das neutrale とても.',tip:"とても bleibt die sichere, neutrale Wahl für höfliche und schriftliche Kontexte — 超/めっちゃ gehören ausschließlich in den lockeren, mündlichen Stil unter Freunden.",ex:[["このゲーム、超面白い！","このゲーム、ちょうおもしろい！","Dieses Spiel ist total interessant!"],["めっちゃ疲れた。","めっちゃつかれた。","Bin voll müde/total erschöpft."]],q:[{q:"Was bedeuten 超 und めっちゃ umgangssprachlich?",o:["Sehr/total (Verstärkung)","Überhaupt nicht","Vielleicht"],c:0},{q:"Wo sollte man 超/めっちゃ vermeiden?",o:["In höflichen/schriftlichen Kontexten","Beim Sprechen mit Freunden","In Anime-Dialogen"],c:0},{q:"Woher stammt めっちゃ ursprünglich?",o:["Kansai-Dialekt, heute landesweit gebräuchlich","Es ist reine Erfindung des Internets","Aus dem Englischen entlehnt"],c:0}]},{id:"n5-desu-deshita",level:5,title:"です・でした — die höfliche Kopula",intro:'です verbindet zwei Nomen höflich: „A ist B."',text:"です steht am Satzende und macht die Aussage höflich. Vergangenheit: でした. Verneinung: じゃありません (locker じゃないです), verneinte Vergangenheit: じゃありませんでした. です selbst wird nicht flektiert wie ein Verb — die Formen sind feste Bausteine.",tip:"In sehr formellem Kontext ist ではありません die Schriftform von じゃありません.",ex:[["田中さんは先生です。","たなかさんはせんせいです。","Herr/Frau Tanaka ist Lehrer(in)."],["きのうは休みでした。","きのうはやすみでした。","Gestern war frei."],["これは私のかばんじゃありません。","これはわたしのかばんじゃありません。","Das ist nicht meine Tasche."]],q:[{q:"Wie lautet die höfliche Vergangenheit von です?",o:["でした","です","だった"],c:0},{q:'„Es ist nicht ein Buch." höflich:',o:["本じゃありません","本くない","本ないです"],c:0},{q:"です macht einen Satz vor allem …",o:["höflich","zur Frage","zur Vergangenheit"],c:0}]},{id:"n5-kore-sore-are-dore",level:5,title:"これ・それ・あれ・どれ — das hier, das da",intro:'Vier Wörter für „dieses Ding" — je nach Entfernung zum Sprecher und Hörer.',text:'これ ist beim Sprecher, それ beim Hörer, あれ von beiden entfernt, どれ ist die Frage „welches?". Sie stehen allein als Nomen: これは何ですか。 Für „dieses + Nomen" braucht man die の-Reihe (nächste Lektion).',tip:"それ benutzt man auch für etwas, das der Gesprächspartner gerade gesagt hat.",ex:[["これは何ですか。","これはなんですか。","Was ist das (hier)?"],["それは私のです。","それはわたしのです。","Das (bei dir) gehört mir."],["どれがいいですか。","どれがいいですか。","Welches ist gut / hätten Sie gern?"]],q:[{q:"Etwas liegt direkt bei dir, weit weg vom Hörer. Du sagst:",o:["これ","それ","あれ"],c:0},{q:'„Welches?" heißt …',o:["どれ","あれ","これ"],c:0},{q:"それ zeigt auf etwas …",o:["beim Hörer","beim Sprecher","weit von beiden"],c:0}]},{id:"n5-kono-sono-ano-dono",level:5,title:"この・その・あの・どの — dieses + Nomen",intro:"Vor einem Nomen wird aus これ → この usw.",text:'この本 „dieses Buch", その車 „das Auto (bei dir)", あの人 „jene Person (dort)", どの „welches + Nomen". Diese Wörter stehen nie allein — es muss ein Nomen folgen.',tip:"Verwechslungsgefahr: これ steht allein, この braucht ein Nomen dahinter.",ex:[["この本はおもしろいです。","このほんはおもしろいです。","Dieses Buch ist interessant."],["あの人はだれですか。","あのひとはだれですか。","Wer ist die Person dort?"],["どの電車ですか。","どのでんしゃですか。","Welcher Zug ist es?"]],q:[{q:'„Dieses Buch" heißt …',o:["この本","これ本","ここ本"],c:0},{q:"あの人 zeigt auf jemanden …",o:["weit von Sprecher und Hörer","beim Sprecher","beim Hörer"],c:0},{q:"Welcher Satz ist falsch?",o:["これ本は高いです","この本は高いです","その車は赤いです"],c:0}]},{id:"n5-koko-soko-asoko-doko",level:5,title:"ここ・そこ・あそこ・どこ — hier, dort, wo",intro:"Die Ortsversion der こそあど-Wörter.",text:'ここ „hier (beim Sprecher)", そこ „dort (beim Hörer)", あそこ „dort drüben", どこ „wo?". Höfliche Variante für Richtung/Ort: こちら・そちら・あちら・どちら. Mit です: トイレはどこですか。',tip:'どちら heißt auch höflich „welcher von zweien" und „woher/wohin".',ex:[["駅はどこですか。","えきはどこですか。","Wo ist der Bahnhof?"],["トイレはあそこです。","トイレはあそこです。","Die Toilette ist dort drüben."],["ここで待ってください。","ここでまってください。","Bitte warten Sie hier."]],q:[{q:'„Wo?" heißt …',o:["どこ","どれ","どの"],c:0},{q:"Ein Ort direkt beim Sprecher:",o:["ここ","そこ","あそこ"],c:0},{q:'Höflich für „hier/diese Richtung":',o:["こちら","これ","この"],c:0}]},{id:"n5-arimasu-imasu",level:5,title:"あります・います — es gibt / sich befinden",intro:"Zwei Verben für Existenz: います für Belebtes, あります für alles andere.",text:'Struktur: 〈Ort〉に〈Ding〉があります／います. Menschen und Tiere → います, Gegenstände und Pflanzen → あります. Verneinung: ありません／いません. Für „X hat Y" nutzt man dasselbe Muster: 私には車があります。',tip:"あります benutzt man auch für Termine und Veranstaltungen: 明日、試験があります。",ex:[["机の上に本があります。","つくえのうえにほんがあります。","Auf dem Tisch ist ein Buch."],["公園に子どもがいます。","こうえんにこどもがいます。","Im Park sind Kinder."],["時間がありません。","じかんがありません。","Ich habe keine Zeit."]],q:[{q:'Welches Verb für „Im Zimmer ist eine Katze"?',o:["います","あります","です"],c:0},{q:'„Es gibt keinen Stuhl." heißt …',o:["いすがありません","いすがいません","いすじゃありません"],c:0},{q:"Das Muster ist …",o:["Ort に Ding が あります","Ding を Ort に あります","Ort が Ding に います"],c:0}]},{id:"n5-ichino",level:5,title:"位置の言葉 — 上・下・中・前・後ろ・隣",intro:"Positionsnomen sagen, wo etwas relativ zu etwas anderem liegt.",text:'Muster: 〈A〉の〈Position〉に … — z. B. 机の上 „auf dem Tisch", いすの下 „unter dem Stuhl", 箱の中 „im Karton", 駅の前 „vor dem Bahnhof", 家の後ろ „hinter dem Haus", 銀行の隣 „neben der Bank", A と B の間 „zwischen A und B".',tip:'そば und 近く heißen beide „in der Nähe"; 隣 meint direkt daneben (gleiche Art von Ding).',ex:[["かばんはテーブルの下にあります。","かばんはテーブルのしたにあります。","Die Tasche ist unter dem Tisch."],["コンビニは駅の前にあります。","コンビニはえきのまえにあります。","Der Konbini ist vor dem Bahnhof."],["銀行と郵便局の間です。","ぎんこうとゆうびんきょくのあいだです。","Es ist zwischen Bank und Post."]],q:[{q:'„auf dem Tisch" heißt …',o:["机の上","机の下","机の中"],c:0},{q:'„zwischen A und B" heißt …',o:["A と B の間","A の B 間","A も B も間"],c:0},{q:"隣 bedeutet …",o:["direkt daneben","gegenüber","weit weg"],c:0}]},{id:"n5-teimasu",level:5,title:"〜ています — gerade dabei / Zustand",intro:"て-Form + いる drückt eine laufende Handlung oder einen andauernden Zustand aus.",text:'Verlauf: 今、ごはんを食べています „ich esse gerade". Zustand nach einer Veränderung: 結婚しています „ich bin verheiratet", 田中さんを知っています „ich kenne Herrn Tanaka". Gewohnheit: 毎日、日本語を勉強しています.',tip:"Bei 知る heißt die Verneinung 知りません (nicht 知っていません).",ex:[["今、テレビを見ています。","いま、テレビをみています。","Ich sehe gerade fern."],["姉は東京に住んでいます。","あねはとうきょうにすんでいます。","Meine ältere Schwester wohnt in Tōkyō."],["田中さんはめがねをかけています。","たなかさんはめがねをかけています。","Herr Tanaka trägt eine Brille."]],q:[{q:'„Ich wohne in Ōsaka." heißt …',o:["大阪に住んでいます","大阪に住みます","大阪に住んでした"],c:0},{q:"〜ています kann ausdrücken:",o:["laufende Handlung UND Dauerzustand","nur Zukunft","nur Vergangenheit"],c:0},{q:"Die Verneinung von 知っています ist meist …",o:["知りません","知っていません","知りましょう"],c:0}]},{id:"n5-mou-mada",level:5,title:"もう・まだ — schon und noch (nicht)",intro:'もう + Vergangenheit = „schon", まだ + Verneinung = „noch nicht".',text:'もう食べました „ich habe schon gegessen"; noch nicht: まだ食べていません (nicht まだ食べませんでした). まだ allein = „noch": まだ 学生です „ich bin noch Student". もう + Verneinung = „nicht mehr": もう ありません.',tip:"Auf もう〜ましたか antwortet man verneinend mit いいえ、まだです。",ex:[["もう宿題をしました。","もうしゅくだいをしました。","Ich habe die Hausaufgaben schon gemacht."],["ばんごはんはまだ食べていません。","ばんごはんはまだたべていません。","Ich habe noch nicht zu Abend gegessen."],["お金はもうありません。","おかねはもうありません。","Ich habe kein Geld mehr."]],q:[{q:'„Noch nicht gegessen" heißt korrekt …',o:["まだ食べていません","まだ食べませんでした","もう食べません"],c:0},{q:"もう + Vergangenheit heißt …",o:["schon","noch nicht","nie"],c:0},{q:'Antwort auf „もう終わりましたか。" (nein):',o:["いいえ、まだです","はい、まだです","いいえ、もうです"],c:0}]},{id:"n5-ga-hoshii",level:5,title:"〜が ほしい — ich hätte gern (Dinge)",intro:"ほしい ist ein い-Adjektiv und drückt den Wunsch nach einem Gegenstand aus.",text:'Muster: 〈Ding〉が ほしいです „ich will/hätte gern …". Verneinung: ほしくないです. Für Wünsche nach Handlungen nimmt man 〜たい (eigene Lektion). Über Dritte spricht man mit ほしがっています.',tip:"Wie bei 好き steht das Objekt des Wunsches mit が, nicht mit を.",ex:[["新しいパソコンがほしいです。","あたらしいパソコンがほしいです。","Ich hätte gern einen neuen Computer."],["今は何もほしくないです。","いまはなにもほしくないです。","Ich will gerade nichts."],["子どもは犬をほしがっています。","こどもはいぬをほしがっています。","Das Kind wünscht sich einen Hund."]],q:[{q:"Welche Partikel vor ほしい?",o:["が","を","に"],c:0},{q:'„Ich will nichts." heißt …',o:["何もほしくないです","何もほしいです","何がほしいです"],c:0},{q:"Für den Wunsch nach einer Handlung nimmt man …",o:["〜たい","ほしい","です"],c:0}]},{id:"n5-ga-sukiki-kirai-jouzu-heta",level:5,title:"〜が 好き・きらい・上手・下手",intro:"Vorlieben und Fähigkeiten stehen mit が, obwohl es im Deutschen ein Objekt ist.",text:'私はコーヒーが好きです „ich mag Kaffee". Ebenso きらい „nicht mögen", 上手 „gut können", 下手 „schlecht können", 得意／苦手. Alles な-Adjektive → Vergangenheit 好きでした, Verneinung 好きじゃないです.',tip:"Über die eigenen Fähigkeiten sagt man aus Bescheidenheit selten 上手; eher 好き oder できます.",ex:[["私は魚が好きです。","わたしはさかながすきです。","Ich mag Fisch."],["弟はサッカーが上手です。","おとうとはサッカーがじょうずです。","Mein kleiner Bruder ist gut im Fußball."],["納豆はあまり好きじゃないです。","なっとうはあまりすきじゃないです。","Nattō mag ich nicht so."]],q:[{q:"Welche Partikel bei 好き?",o:["が","を","は"],c:0},{q:"好き ist ein …",o:["な-Adjektiv","い-Adjektiv","Verb"],c:0},{q:'„nicht besonders gern" nutzt oft …',o:["あまり … じゃない","とても … です","もう … ました"],c:0}]},{id:"n5-kute-de",level:5,title:"〜くて・〜で — Adjektive verbinden",intro:"Zwei Eigenschaften in einem Satz: い-Adjektiv → くて, な-Adjektiv/Nomen → で.",text:'このへやは広くて明るいです „dieses Zimmer ist groß und hell". きれいで静かな町 „eine schöne, ruhige Stadt". Die Verbindung ist wertneutral; für echten Gegensatz nimmt man が/けど.',tip:"いい wird unregelmäßig zu よくて.",ex:[["この店は安くておいしいです。","このみせはやすくておいしいです。","Dieser Laden ist günstig und lecker."],["彼は親切で真面目です。","かれはしんせつでまじめです。","Er ist freundlich und gewissenhaft."],["天気がよくて気持ちがいいです。","てんきがよくてきもちがいいです。","Das Wetter ist schön und es fühlt sich gut an."]],q:[{q:'„groß und neu" (大きい + 新しい):',o:["大きくて新しい","大きいで新しい","大きくと新しい"],c:0},{q:"な-Adjektiv 静か verbindet mit …",o:["で","くて","て"],c:0},{q:"いい wird zu …",o:["よくて","いくて","いいで"],c:0}]},{id:"n5-kunaru-ninaru",level:5,title:"〜くなる・〜になる — es wird …",intro:"Zustandsänderung: い-Adjektiv → く + なる, な-Adjektiv/Nomen → に + なる.",text:'寒くなりました „es ist kalt geworden". 元気になる „gesund werden". 先生になりたい „Lehrer werden wollen". Für „etwas verändern" (transitiv) nimmt man する: 部屋をきれいにする.',tip:"いい → よくなる (unregelmäßig).",ex:[["もう暗くなりました。","もうくらくなりました。","Es ist schon dunkel geworden."],["日本語が少し上手になりました。","にほんごがすこしじょうずになりました。","Mein Japanisch ist etwas besser geworden."],["将来、医者になりたいです。","しょうらい、いしゃになりたいです。","Ich möchte später Arzt werden."]],q:[{q:'„warm werden" (あたたかい):',o:["あたたかくなる","あたたかいになる","あたたかになる"],c:0},{q:'„Lehrer werden":',o:["先生になる","先生くなる","先生をなる"],c:0},{q:"いい wird zu …",o:["よくなる","いくなる","いいなる"],c:0}]},{id:"n5-ku-ni",level:5,title:"〜く・〜に — Adjektiv als Adverb",intro:"Aus Eigenschaftswörtern werden Umstandswörter: い → く, な → に.",text:'早く起きる „früh aufstehen", 静かに話す „leise sprechen", きれいに書く „schön schreiben". Das Adverb steht direkt vor dem Verb.',tip:"Viele feste Wendungen: よろしくお願いします enthält das Adverb よろしく (von よろしい „angemessen, gut“).",ex:[["もっとゆっくり話してください。","もっとゆっくりはなしてください。","Bitte sprechen Sie langsamer."],["字をていねいに書きます。","じをていねいにかきます。","Ich schreibe die Zeichen sorgfältig."],["朝は早く起きます。","あさははやくおきます。","Morgens stehe ich früh auf."]],q:[{q:'„schnell laufen" (はやい + 走る):',o:["はやく走る","はやい走る","はやに走る"],c:0},{q:"な-Adjektiv 静か als Adverb:",o:["静かに","静かく","静かで"],c:0},{q:"Das Adverb steht …",o:["vor dem Verb","am Satzanfang immer","nach dem Verb"],c:0}]},{id:"n5-masenka-mashiyou",level:5,title:"〜ませんか・〜ましょう — einladen und vorschlagen",intro:"〜ませんか lädt höflich ein, 〜ましょう schlägt gemeinsames Handeln vor.",text:'一緒に行きませんか „wollen wir nicht zusammen gehen?" — freundliche Einladung. 行きましょう „lass uns gehen" — Vorschlag/Zustimmung. 〜ましょうか bietet Hilfe an: 持ちましょうか „soll ich (es) tragen?".',tip:"〜ませんか ist einladender/weicher als 〜ましょう, weil es dem Gegenüber die Wahl lässt.",ex:[["今度、映画を見に行きませんか。","こんど、えいがをみにいきませんか。","Wollen wir nicht demnächst ins Kino gehen?"],["ここで少し休みましょう。","ここですこしやすみましょう。","Lass uns hier kurz Pause machen."],["荷物を持ちましょうか。","にもつをもちましょうか。","Soll ich das Gepäck tragen?"]],q:[{q:"Eine höfliche Einladung endet auf …",o:["〜ませんか","〜ました","〜ましたか"],c:0},{q:'„Lass uns essen" heißt …',o:["食べましょう","食べませんか","食べます"],c:0},{q:"〜ましょうか nutzt man, um …",o:["Hilfe anzubieten","zu verneinen","nach dem Preis zu fragen"],c:0}]},{id:"n5-masu",level:5,title:"ます-Stamm + に 行く — hingehen, um zu …",intro:"Zweck einer Bewegung: Verb-Stamm (ます weg) + に + 行く／来る／帰る.",text:'映画を見に行きます „ich gehe einen Film sehen". Bei する-Nomen entfällt する: 買い物に行く, 勉強に来る. Auch Nomen direkt möglich: 昼ごはんに行く.',tip:"に markiert hier den Zweck, nicht den Ort — der Ort steht mit へ／に davor: 日本へ 遊びに行く.",ex:[["図書館へ本を借りに行きます。","としょかんへほんをかりにいきます。","Ich gehe in die Bibliothek, um ein Buch zu leihen."],["友だちが遊びに来ました。","ともだちがあそびにきました。","Ein Freund ist zu Besuch gekommen."],["スーパーへ買い物に行きます。","スーパーへかいものにいきます。","Ich gehe zum Supermarkt einkaufen."]],q:[{q:'„essen gehen" (食べる):',o:["食べに行く","食べるに行く","食べてに行く"],c:0},{q:"Bei 買い物する wird daraus …",o:["買い物に行く","買い物するに行く","買い物をに行く"],c:0},{q:"に markiert hier …",o:["den Zweck","den Ort","die Zeit"],c:0}]},{id:"n5-kara-made",level:5,title:"〜から・〜まで — von … bis",intro:'から „von/ab", まで „bis" — für Zeit und Ort.',text:'9時から5時まで働きます „ich arbeite von 9 bis 5". 東京から大阪まで „von Tōkyō nach Ōsaka". Jede Angabe kann auch allein stehen: 3時から „ab 3 Uhr". から heißt außerdem „weil" (eigene Lektion).',tip:'まで betont die Grenze; für Richtung „nach" ohne Grenze nimmt man へ／に.',ex:[["銀行は9時から3時までです。","ぎんこうはくじからさんじまでです。","Die Bank hat von 9 bis 15 Uhr geöffnet."],["駅から家まで歩きます。","えきからいえまであるきます。","Ich gehe vom Bahnhof bis nach Hause zu Fuß."],["夏休みは来週からです。","なつやすみはらいしゅうからです。","Die Sommerferien sind ab nächster Woche."]],q:[{q:'„von Montag bis Freitag":',o:["月曜日から金曜日まで","月曜日まで金曜日から","月曜日も金曜日も"],c:0},{q:"まで bedeutet …",o:["bis","von","weil"],c:0},{q:'から kann außer „von" auch heißen:',o:["weil","aber","oder"],c:0}]},{id:"n5-dake-shikanai",level:5,title:"〜だけ・〜しか〜ない — nur",intro:'Zwei Wege für „nur": だけ neutral, しか + Verneinung mit Ton „nur so wenig".',text:'水だけ飲みます „ich trinke nur Wasser". 水しか飲みません „ich trinke nichts als Wasser" (betont die Knappheit). しか ersetzt が und を (nach anderen Partikeln steht es dahinter: ここでしか) und verlangt immer eine verneinte Form.',tip:"だけ kann nach Partikeln stehen (ここでだけ); しか ersetzt が und を (水しか飲まない), steht aber nach anderen Partikeln (ここでしか).",ex:[["ひらがなだけ書けます。","ひらがなだけかけます。","Ich kann nur Hiragana schreiben."],["500円しかありません。","ごひゃくえんしかありません。","Ich habe nur 500 Yen."],["日曜日だけ休みです。","にちようびだけやすみです。","Nur am Sonntag ist frei."]],q:[{q:"しか verlangt …",o:["eine verneinte Form","です","eine Frage"],c:0},{q:'„Ich habe nur 100 Yen." (knapp):',o:["100円しかありません","100円だけあります","100円もあります"],c:0},{q:'Neutral „nur Wasser":',o:["水だけ","水しか","水こそ"],c:0}]},{id:"n5-goro-gurai",level:5,title:"〜ごろ・〜ぐらい — ungefähr",intro:"ごろ für einen ungefähren Zeitpunkt, ぐらい (くらい) für eine ungefähre Menge/Dauer.",text:'3時ごろ 会いましょう „treffen wir uns gegen 3". 1時間ぐらい かかります „es dauert etwa eine Stunde". ぐらい steht auch bei Anzahl: 10人ぐらい.',tip:"Bei einer Uhrzeit als Zeitpunkt → ごろ; bei einer Zeitspanne → ぐらい.",ex:[["明日の朝8時ごろ 出ます。","あしたのあさはちじごろでます。","Morgen früh gegen 8 Uhr gehe ich los."],["駅まで20分ぐらいです。","えきまでにじゅっぷんぐらいです。","Bis zum Bahnhof sind es etwa 20 Minuten."],["パーティーに30人ぐらい来ました。","パーティーにさんじゅうにんぐらいきました。","Zur Party kamen etwa 30 Leute."]],q:[{q:'„gegen 5 Uhr":',o:["5時ごろ","5時ぐらい","5時まで"],c:0},{q:'„etwa drei Stunden":',o:["3時間ぐらい","3時間ごろ","3時間だけ"],c:0},{q:"ごろ nutzt man für …",o:["einen Zeitpunkt","eine Menge","einen Ort"],c:0}]},{id:"n5-naidekudasai",level:5,title:"〜ないでください — bitte nicht …",intro:"Höfliche Bitte, etwas zu unterlassen: ない-Form + でください.",text:'ここで写真を撮らないでください „bitte machen Sie hier keine Fotos". Gegenstück zu 〜てください. Freundlicher/weicher wird es mit 〜ないでくださいね.',tip:"Die ない-Form bildet man wie die Verneinung im Plain-Stil: 行く → 行かない → 行かないでください.",ex:[["ここに車を止めないでください。","ここにくるまをとめないでください。","Bitte parken Sie hier nicht."],["授業中は話さないでください。","じゅぎょうちゅうははなさないでください。","Bitte sprechen Sie während des Unterrichts nicht."],["心配しないでくださいね。","しんぱいしないでくださいね。","Machen Sie sich bitte keine Sorgen."]],q:[{q:'„Bitte nicht rauchen." (たばこを吸う):',o:["たばこを吸わないでください","たばこを吸ってください","たばこを吸いないでください"],c:0},{q:"〜ないでください ist das Gegenstück zu …",o:["〜てください","〜ましょう","〜たいです"],c:0},{q:"Basis ist die …",o:["ない-Form","ます-Form","た-Form"],c:0}]},{id:"n5-tekara",level:5,title:"〜てから — nachdem / erst … dann",intro:'て-Form + から heißt „nachdem …" und betont die Reihenfolge.',text:'手を洗ってから食べます „erst Hände waschen, dann essen". Anders als das bloße て-Verbinden liegt hier Nachdruck auf „zuerst das, dann das". Nur ein から dieser Art pro Satz ist üblich.',tip:'Nicht verwechseln mit から „weil" — das steht nach einer vollständigen Satzform, nicht nach der て-Form.',ex:[["宿題をしてから遊びます。","しゅくだいをしてからあそびます。","Nachdem ich Hausaufgaben gemacht habe, spiele ich."],["よく考えてから返事します。","よくかんがえてからへんじします。","Ich antworte, nachdem ich gut nachgedacht habe."],["日本に来てから3年になります。","にほんにきてからさんねんになります。","Es sind drei Jahre, seit ich nach Japan gekommen bin."]],q:[{q:'„Nachdem ich gegessen habe, gehe ich." (食べる):',o:["食べてから行きます","食べるから行きます","食べたから行きます"],c:0},{q:"〜てから betont …",o:["die Reihenfolge","den Grund","den Ort"],c:0},{q:'から „weil" steht nach …',o:["einer vollständigen Verbform","der て-Form","einem Nomen ohne です"],c:0}]},{id:"n5-maeni-atode",level:5,title:"〜前に・〜あとで — vor / nach",intro:'Zeitliche Abfolge mit Nomen und Verben: 前に „vor", あとで „nach".',text:'Verb (Wörterbuchform) + 前に: 寝る前に歯を磨きます „vor dem Schlafen Zähne putzen". Verb (た-Form) + あとで: 食べたあとで „nach dem Essen". Nomen + の: 仕事の前に, 授業のあとで.',tip:"Vor 前に steht immer die Wörterbuchform — auch wenn der Satz in der Vergangenheit liegt.",ex:[["出かける前に窓を閉めます。","でかけるまえにまどをしめます。","Bevor ich rausgehe, schließe ich das Fenster."],["ごはんを食べたあとで、散歩しました。","ごはんをたべたあとで、さんぽしました。","Nach dem Essen habe ich einen Spaziergang gemacht."],["会議の前に資料を読みます。","かいぎのまえにしりょうをよみます。","Vor der Besprechung lese ich die Unterlagen."]],q:[{q:"Vor 前に steht die …",o:["Wörterbuchform","た-Form","ない-Form"],c:0},{q:'„nach dem Aufstehen" (起きる):',o:["起きたあとで","起きるあとで","起きてあとで"],c:0},{q:'„vor der Arbeit":',o:["仕事の前に","仕事前に","仕事をあとで"],c:0}]},{id:"n5-toki",level:5,title:"〜とき — wenn / als",intro:'とき („Zeit") verbindet zwei Situationen: „wenn/als X, dann Y".',text:'子どものとき „als ich Kind war", 日本に行くとき „wenn ich nach Japan fahre" (vor der Reise), 日本に行ったとき „als ich in Japan war" (dort angekommen). Die Zeitform vor とき entscheidet über den Bezug. Nomen + の + とき, な-Adjektiv + な + とき.',tip:"Wörterbuchform vor とき = die Handlung ist noch nicht abgeschlossen; た-Form = abgeschlossen.",ex:[["ひまなとき、音楽を聞きます。","ひまなとき、おんがくをききます。","Wenn ich frei habe, höre ich Musik."],["国を出るとき、空港で写真を撮りました。","くにをでるとき、くうこうでしゃしんをとりました。","Als ich mein Land verließ, machte ich am Flughafen Fotos."],["若いとき、よく旅行しました。","わかいとき、よくりょこうしました。","Als ich jung war, bin ich viel gereist."]],q:[{q:'„als ich klein war":',o:["子どものとき","子どもとき","子どもだとき"],c:0},{q:'„日本に行った とき" heißt: das Foto entstand …',o:["in Japan","vor der Abreise","nie"],c:0},{q:"な-Adjektiv 元気 + とき:",o:["元気なとき","元気とき","元気でとき"],c:0}]},{id:"n5-taritarisuru",level:5,title:"〜たり〜たりする — mal dies, mal das",intro:"た-Form + り zählt beispielhaft einige Tätigkeiten auf (nicht vollständig, keine feste Reihenfolge).",text:'日曜日は、本を読んだり、音楽を聞いたりします „sonntags lese ich, höre Musik und so". Am Ende steht meist する in der passenden Zeitform. Auch für Gegensätze: 行ったり来たり „hin und her".',tip:'Anders als die て-Reihung sagt 〜たり〜たり: „unter anderem", nicht „alles nacheinander".',ex:[["休みの日は、掃除をしたり、買い物をしたりします。","やすみのひは、そうじをしたり、かいものをしたりします。","An freien Tagen putze ich, gehe einkaufen und so weiter."],["ゆうべは、歌ったり踊ったりしました。","ゆうべは、うたったりおどったりしました。","Gestern Abend haben wir gesungen, getanzt und so."],["エレベーターが上がったり下がったりしています。","エレベーターがあがったりさがったりしています。","Der Aufzug fährt hoch und runter."]],q:[{q:"Basis für 〜たり ist die …",o:["た-Form","ます-Form","Wörterbuchform"],c:0},{q:"Am Satzende steht meist …",o:["する (passend flektiert)","です","ください"],c:0},{q:"〜たり〜たり bedeutet …",o:["beispielhafte Aufzählung","strikte Reihenfolge","Verbot"],c:0}]},{id:"n5-tsumoridesu",level:5,title:"〜つもりです — ich habe vor …",intro:"Wörterbuchform + つもりです drückt eine feste Absicht aus.",text:'夏休みに国へ帰るつもりです „ich habe vor, in den Sommerferien nach Hause zu fahren". Verneinte Absicht: 行かないつもりです „ich habe vor, nicht zu gehen". Schwächer als ein Plan, stärker als ein Wunsch.',tip:"つもり ist ein Nomen — deshalb steht davor die Verbform wie vor einem Nomen (Wörterbuchform / ない-Form).",ex:[["週末は家でゆっくりするつもりです。","しゅうまつはいえでゆっくりするつもりです。","Am Wochenende habe ich vor, zu Hause zu entspannen."],["今日はお酒を飲まないつもりです。","きょうはおさけをのまないつもりです。","Heute habe ich vor, keinen Alkohol zu trinken."],["来年、日本語能力試験を受けるつもりです。","らいねん、にほんごのうりょくしけんをうけるつもりです。","Nächstes Jahr habe ich vor, den JLPT abzulegen."]],q:[{q:"Vor つもり steht die …",o:["Wörterbuchform oder ない-Form","ます-Form","て-Form"],c:0},{q:'„Ich habe vor, nicht zu gehen.":',o:["行かないつもりです","行くつもりじゃないです","行かないでつもりです"],c:0},{q:"つもり ist grammatisch ein …",o:["Nomen","Verb","い-Adjektiv"],c:0}]},{id:"n5-ka-mo-dareka-daremo",level:5,title:"何か・何も・だれか・だれも — Fragewort + か / も",intro:'Fragewort + か = „irgend-", Fragewort + も + Verneinung = „kein-".',text:'何か食べましたか „hast du etwas gegessen?"; 何も食べませんでした „ich habe nichts gegessen". Ebenso だれか／だれも, どこか／どこも, いつか. Bei も steht das Verb immer verneint.',tip:"Nach 何か/だれか lässt man は/が/を oft weg; を kann aber bleiben: 何かを買う.",ex:[["冷蔵庫に何かありますか。","れいぞうこになにかありますか。","Ist irgendetwas im Kühlschrank?"],["今日はどこも行きませんでした。","きょうはどこもいきませんでした。","Heute bin ich nirgendwo hingegangen."],["部屋にはだれもいません。","へやにはだれもいません。","Im Zimmer ist niemand."]],q:[{q:'„etwas trinken":',o:["何か飲む","何も飲む","何を飲まない"],c:0},{q:'„niemand ist da":',o:["だれもいません","だれかいます","だれもいます"],c:0},{q:"Nach 〜も steht das Verb …",o:["verneint","in der Vergangenheit","als Frage"],c:0}]},{id:"n5-ndesu",level:5,title:"〜んです — Erklärung und Nachfrage",intro:"んです (formell のです) verknüpft eine Aussage mit dem Kontext: Grund, Erklärung, Interesse.",text:'どうしたんですか „was ist denn los?"; 頭が痛いんです „mir tut nämlich der Kopf weh". Nomen/な-Adjektiv + なんです. In der Frage klingt es anteilnehmend, in der Antwort erklärend. Ohne んです wirkt dieselbe Aussage nüchtern-sachlich.',tip:"Nicht in jedem Satz — んです passt, wenn ein Bezug zur Situation da ist, nicht bei reiner Faktenauskunft.",ex:[["遅れてすみません。電車が止まったんです。","おくれてすみません。でんしゃがとまったんです。","Entschuldigung für die Verspätung — der Zug stand nämlich still."],["その服、すてきですね。どこで買ったんですか。","そのふく、すてきですね。どこでかったんですか。","Das Kleid ist schön. Wo hast du es denn gekauft?"],["明日は行けないんです。用事があるんです。","あしたはいけないんです。ようじがあるんです。","Morgen kann ich nicht — ich habe nämlich etwas vor."]],q:[{q:"Nomen 学生 + んです wird zu …",o:["学生なんです","学生んです","学生だんです"],c:0},{q:"んです in einer Frage klingt …",o:["anteilnehmend/neugierig","befehlend","unhöflich"],c:0},{q:"Die formelle Schriftform ist …",o:["のです","んだ","です"],c:0}]},{id:"n5-ga-2",level:5,title:'〜が、… — zwei Sätze mit „aber" / Überleitung',intro:'Das Satz-が verbindet zwei Aussagen: entweder als Gegensatz „aber" oder als weiche Überleitung.',text:'すみませんが、駅はどこですか „Entschuldigung, aber wo ist der Bahnhof?" — hier nur Überleitung, kein echter Gegensatz. 高いですが、おいしいです „es ist teuer, aber lecker". が steht am Ende des ersten Teilsatzes.',tip:"In höflicher Rede leitet 〜が oft eine Bitte oder Frage ein und macht sie weicher.",ex:[["もしもし、田中ですが、山田さんはいますか。","もしもし、たなかですが、やまださんはいますか。","Hallo, hier ist Tanaka — ist Herr Yamada da?"],["この部屋は狭いですが、明るいです。","このへやはせまいですが、あかるいです。","Dieses Zimmer ist eng, aber hell."],["見に行きましたが、休みでした。","みにいきましたが、やすみでした。","Ich bin hingegangen, aber es hatte geschlossen."]],q:[{q:"が steht …",o:["am Ende des ersten Teilsatzes","am Satzanfang","nach dem Verb des zweiten Teils"],c:0},{q:'„…ですが、…" kann außer „aber" auch sein:',o:["eine weiche Überleitung","eine Verneinung","ein Befehl"],c:0},{q:'„teuer, aber gut":',o:["高いですが、いいです","高いでも、いいです","高いだが、いいです"],c:0}]},{id:"n5-ne-yo",level:5,title:"〜ね・〜よ — Zustimmung suchen, Neues betonen",intro:"Satzend-Partikeln: ね sucht Zustimmung/teilt ein Gefühl, よ betont eine Information für den Hörer.",text:'いい天気ですね „schönes Wetter, nicht?" — gemeinsames Empfinden. この電車は東京に行きますよ „dieser Zug fährt nach Tōkyō" (Info, die du vielleicht nicht hast). Beides höflich mit です/ます kombinierbar.',tip:"Zu viel よ kann belehrend klingen; ね wirkt fast immer freundlich-verbindend.",ex:[["この店、おいしいですね。","このみせ、おいしいですね。","Dieser Laden ist lecker, findest du nicht?"],["あ、かぎが落ちましたよ。","あ、かぎがおちましたよ。","Oh, Ihnen ist der Schlüssel runtergefallen."],["明日は休みですよね。","あしたはやすみですよね。","Morgen ist frei, oder?"]],q:[{q:"ね nutzt man, um …",o:["Zustimmung zu suchen","zu befehlen","zu verneinen"],c:0},{q:"よ betont …",o:["eine Information für den Hörer","eine Frage","die Vergangenheit"],c:0},{q:"よね fragt nach …",o:["Bestätigung","dem Preis","der Uhrzeit"],c:0}]},{id:"n5-deshiyou",level:5,title:"〜でしょう？ — nicht wahr? (Vermutung/Rückfrage)",intro:"でしょう äußert eine Annahme; mit steigender Betonung sucht es Zustimmung.",text:'明日は雨でしょう „morgen wird es wohl regnen" (Vermutung). Mit Fragezeichen/steigend: 大変でしょう？ „das ist bestimmt anstrengend, oder?". Höflicher und vorsichtiger als だ／です.',tip:'Fallend gesprochen = Vermutung; steigend gesprochen = Rückfrage/„oder?".',ex:[["あの人は先生でしょう。","あのひとはせんせいでしょう。","Die Person ist wohl Lehrer(in)."],["疲れたでしょう。少し休んでください。","つかれたでしょう。すこしやすんでください。","Du bist sicher müde. Ruh dich kurz aus."],["週末は混むでしょう。","しゅうまつはこむでしょう。","Am Wochenende wird es wohl voll."]],q:[{q:"でしょう (fallend) drückt aus:",o:["eine Vermutung","einen Befehl","eine Verneinung"],c:0},{q:"でしょう？ (steigend) bedeutet …",o:["…, oder? / nicht wahr?","…, weil","…, aber"],c:0},{q:"Im Vergleich zu です ist でしょう …",o:["vorsichtiger","unhöflicher","genau gleich"],c:0}]},{id:"n5-ya-nado",level:5,title:"〜や〜・〜など — und (unter anderem)",intro:'や verbindet Nomen als unvollständige Aufzählung; など schließt sie mit „usw." ab.',text:'かばんの中に、本やノートやペンなどがあります „in der Tasche sind Bücher, Hefte, Stifte und so". Anders als と (vollständige Liste) sagt や: „zum Beispiel diese". など ist optional, aber häufig.',tip:'と = „genau A und B"; や = „A, B und noch anderes".',ex:[["朝はパンやたまごを食べます。","あさはパンやたまごをたべます。","Morgens esse ich Brot, Eier und so."],["京都や奈良などへ行きました。","きょうとやならなどへいきました。","Ich bin nach Kyōto, Nara und anderswohin gefahren."],["ノートやペンなどを買いました。","ノートやペンなどをかいました。","Ich habe Hefte, Stifte und so gekauft."]],q:[{q:"や sagt: die Liste ist …",o:["unvollständig / beispielhaft","vollständig","verneint"],c:0},{q:'„genau A und B" nimmt …',o:["と","や","も"],c:0},{q:"など bedeutet …",o:["usw.","nur","nicht"],c:0}]},{id:"n5-mo-2",level:5,title:"〜も — sogar / so viel wie",intro:"Nach einer Mengen- oder Zahlangabe betont も, dass die Menge groß/überraschend ist.",text:'3時間も待ちました „ich habe ganze drei Stunden gewartet". Mit Verneinung: 1円もありません „ich habe keinen einzigen Yen". Grundbedeutung „auch" bleibt: 私も学生です.',tip:'Nach einer kleinen Zahl + も + Verneinung = „nicht einmal …".',ex:[["パーティーに100人も来ました。","パーティーにひゃくにんもきました。","Zur Party kamen ganze 100 Leute."],["きのうは10時間も寝ました。","きのうはじゅうじかんもねました。","Gestern habe ich ganze 10 Stunden geschlafen."],["一度も日本に行ったことがありません。","いちどもにほんにいったことがありません。","Ich war noch kein einziges Mal in Japan."]],q:[{q:'„ganze fünf Stück":',o:["5つも","5つだけ","5つしか"],c:0},{q:'„nicht einen einzigen":',o:["1つもない","1つもある","1つだけ"],c:0},{q:"Die Grundbedeutung von も ist …",o:["auch","nur","aber"],c:0}]},{id:"n5-noga-sukiki-noga-jouzu",level:5,title:"〜のが好き・〜のが上手 — Tätigkeiten mögen/können",intro:"Um ein Verb zum Nomen zu machen, hängt man の an die Wörterbuchform.",text:'写真を撮るのが好きです „ich fotografiere gern". 歌うのが上手です „gut singen können". 日本語を話すのは難しいです „Japanisch sprechen ist schwer". Nach の folgt が／は wie bei einem Nomen.',tip:'Statt の geht oft auch こと; bei „mögen/können/hören/sehen" ist の üblicher.',ex:[["料理を作るのが好きです。","りょうりをつくるのがすきです。","Ich koche gern."],["朝早く起きるのはつらいです。","あさはやくおきるのはつらいです。","Früh aufstehen ist hart."],["弟は絵をかくのが上手です。","おとうとはえをかくのがじょうずです。","Mein kleiner Bruder kann gut zeichnen."]],q:[{q:'Aus 読む „lesen" wird das Nomen …',o:["読むの","読みの","読んで"],c:0},{q:'„Schwimmen ist Spaß." (泳ぐ):',o:["泳ぐのは楽しいです","泳ぐは楽しいです","泳いでのは楽しいです"],c:0},{q:"Nach の folgt …",o:["が / は wie bei einem Nomen","immer を","immer に"],c:0}]},{id:"n4-tara",level:4,title:"〜たら — als sich herausstellte / nachdem",intro:'たら bildet nicht nur „wenn", sondern erzählt auch eine überraschende Entdeckung.',text:'Vergangenheitsform + ら: 家に帰ったら、誰もいなかった „als ich nach Hause kam, war niemand da". Der zweite Satzteil ist etwas, das der Sprecher nicht steuern konnte — oft eine Überraschung. Für reine Bedingungen siehe die Konditional-Lektion.',tip:"Wenn der zweite Teil eine bewusste Handlung ist, steht er meist nicht in der Vergangenheit; bei einer Entdeckung schon.",ex:[["窓を開けたら、雪が降っていた。","まどをあけたら、ゆきがふっていた。","Als ich das Fenster öffnete, schneite es."],["薬を飲んだら、楽になりました。","くすりをのんだら、らくになりました。","Nachdem ich die Medizin genommen hatte, ging es mir besser."],["駅に着いたら、電話してください。","えきについたら、でんわしてください。","Ruf an, wenn du am Bahnhof angekommen bist."]],q:[{q:"部屋に＿＿、鍵が落ちていた。",o:["入ったら","入るので","入れば","入るなら"],c:0},{q:"たら + Entdeckung: der zweite Teil beschreibt …",o:["etwas Unerwartetes/Ungesteuertes","einen Befehl","eine Frage"],c:0},{q:'„Als ich aufwachte, war es schon Mittag." — 起きたら、もう＿＿。',o:["昼だった","昼だろう","昼らしい","昼になれ"],c:0}]},{id:"n4-shi",level:4,title:"〜し — Gründe aufzählen",intro:'し reiht mehrere Gründe oder Eigenschaften auf: „…, und außerdem …".',text:'Plain-Form + し: この店は安いし、おいしいし、近い „dieser Laden ist günstig, lecker und außerdem nah". Oft bleibt der letzte Grund unausgesprochen — し deutet an, dass es noch mehr gibt. Häufig als Begründung am Satzende: 今日は行かない。疲れたし。',tip:'Anders als て verbindet し bewusst „Argumente" — es klingt, als zähle man Pluspunkte oder Ausreden auf.',ex:[["お金もないし、時間もないし、旅行は無理です。","おかねもないし、じかんもないし、りょこうはむりです。","Ich habe kein Geld und keine Zeit — Reisen geht nicht."],["彼は親切だし、頭もいいし、人気があります。","かれはしんせつだし、あたまもいいし、にんきがあります。","Er ist freundlich und klug, deshalb ist er beliebt."],["もう遅いし、そろそろ帰ります。","もうおそいし、そろそろかえります。","Es ist schon spät, ich gehe langsam."]],q:[{q:"雨も降っている＿＿、今日は家にいよう。",o:["し","ながら","まま","ように"],c:0},{q:"し reiht vor allem … auf",o:["Gründe / Pluspunkte","Zeitpunkte","Orte"],c:0},{q:"Vor し steht die …",o:["Plain-Form","ます-Form","て-Form"],c:0}]},{id:"n4-tameni",level:4,title:"〜ために — Zweck und Ursache",intro:'ために hat zwei Bedeutungen: „um zu / für" (Zweck) und „wegen" (Ursache).',text:'Zweck: 日本語を勉強するために、日本へ来ました „ich kam nach Japan, um Japanisch zu lernen" — beide Teile haben denselben, steuerbaren Handelnden. Nomen + の + ために: 家族のために働く. Ursache: 台風のために、電車が止まった „wegen des Taifuns hielt der Zug".',tip:"Für einen Zweck, den man nicht direkt steuert (können/nicht), nimmt man 〜ように statt ために.",ex:[["健康のために、毎朝走っています。","けんこうのために、まいあさはしっています。","Für die Gesundheit laufe ich jeden Morgen."],["試験に合格するために、一生懸命勉強した。","しけんにごうかくするために、いっしょうけんめいべんきょうした。","Ich habe hart gelernt, um die Prüfung zu bestehen."],["事故のために、道が混んでいます。","じこのために、みちがこんでいます。","Wegen eines Unfalls ist die Straße verstopft."]],q:[{q:"将来の＿＿、お金を貯めています。",o:["ために","ように","そうに","ながら"],c:0},{q:"Welcher Zweck nimmt lieber 〜ように statt ために?",o:["ein nicht steuerbarer (können, verstehen)","ein bewusst geplanter","kein Unterschied"],c:0},{q:"大雪＿＿ために、学校が休みになった。",o:["の","を","に","で"],c:0}]},{id:"n4-youni",level:4,title:"〜ように — damit / so dass",intro:'ように drückt ein Ziel aus, das man nicht direkt „macht": können, nicht tun, werden.',text:'Vor ように steht meist ein Potenzial-Verb, ein Verneinungs-Verb oder ein Zustandsverb: 後ろの人にも聞こえるように、大きい声で話します „ich spreche laut, damit auch die Leute hinten es hören". Verwandt: 〜ようにする (sich bemühen), 〜ようになる (eine Veränderung erreichen).',tip:"ために = ich tue A, um B zu tun (gleicher Wille); ように = ich tue A, damit B (Zustand/Fähigkeit) eintritt.",ex:[["忘れないように、メモしておきます。","わすれないように、メモしておきます。","Damit ich es nicht vergesse, mache ich mir eine Notiz."],["子どもでも読めるように、ふりがなをつけた。","こどもでもよめるように、ふりがなをつけた。","Ich habe Furigana ergänzt, damit auch Kinder lesen können."],["風邪をひかないように、気をつけてください。","かぜをひかないように、きをつけてください。","Pass auf, dass du dich nicht erkältest."]],q:[{q:"遅れない＿＿、早めに家を出た。",o:["ように","ために","そうに","みたいに"],c:0},{q:"Vor ように steht typischerweise …",o:["Potenzial-/Verneinungs-Verb","ます-Form","Nomen ohne の"],c:0},{q:'„damit alle es verstehen":',o:["みんながわかるように","みんながわかるために","みんながわかるそう"],c:0}]},{id:"n4-younisuru-kotonisuru",level:4,title:"〜ようにする・〜ことにする — sich vornehmen",intro:"Zwei Wege, einen Vorsatz auszudrücken: ようにする = allgemeine Gewohnheit anstreben, ことにする = eine konkrete Entscheidung.",text:'毎日野菜を食べるようにしています „ich versuche, jeden Tag Gemüse zu essen" (Bemühen, Tendenz). 来月から日本語を習うことにしました „ich habe beschlossen, ab nächsten Monat Japanisch zu lernen" (klarer Entschluss). Verneint: 〜ないようにする / 〜ないことにする.',tip:"ことにする = *ich* entscheide; ことになる = es *ergibt sich* / wird entschieden (nächste Lektion).",ex:[["エレベーターを使わないようにしています。","エレベーターをつかわないようにしています。","Ich versuche, den Aufzug nicht zu benutzen."],["たばこをやめることにしました。","たばこをやめることにしました。","Ich habe beschlossen, mit dem Rauchen aufzuhören."],["毎朝六時に起きるようにしている。","まいあさろくじにおきるようにしている。","Ich versuche, jeden Morgen um 6 aufzustehen."]],q:[{q:"甘い物を食べない＿＿しています。",o:["ように","ことに","ために","そうに"],c:0},{q:"Ein einmaliger, klarer Entschluss:",o:["〜ことにする","〜ようにする","〜ようになる"],c:0},{q:'„Ich bemühe mich, mehr zu schlafen." nutzt …',o:["よく寝るようにする","よく寝ることにする","よく寝るようになる"],c:0}]},{id:"n4-kotoninaru",level:4,title:"〜ことになる — es ist beschlossen / es ergibt sich",intro:"ことになる sagt: die Sache wurde (von außen / durch Umstände) so entschieden.",text:'来月、大阪へ転勤することになりました „es wurde entschieden, dass ich nächsten Monat nach Ōsaka versetzt werde" — oft eine höfliche Art, eigene Neuigkeiten zu verkünden, ohne sich in den Vordergrund zu stellen. Auch für logische Schlüsse: 1ドル150円なら、これは3000円ということになる.',tip:"Selbst wenn man selbst entschieden hat, klingt ことになる bescheidener als ことにする.",ex:[["来年、結婚することになりました。","らいねん、けっこんすることになりました。","Nächstes Jahr werde ich heiraten (so wurde es entschieden)."],["会議は金曜日に行うことになった。","かいぎはきんようびにおこなうことになった。","Die Besprechung findet nun am Freitag statt."],["規則で、ここでは写真が撮れないことになっている。","きそくで、ここではしゃしんがとれないことになっている。","Laut Vorschrift darf man hier keine Fotos machen."]],q:[{q:"４月から東京の支社で働く＿＿なりました。",o:["ことに","ように","そうに","ために"],c:0},{q:"ことになる klingt im Vergleich zu ことにする …",o:["bescheidener / weniger ich-betont","aggressiver","gleich"],c:0},{q:"〜ことになっている bedeutet oft …",o:["es ist Regel / feststehend","es ist gerade passiert","es könnte sein"],c:0}]},{id:"n4-mitai",level:4,title:"〜みたい — wie / sieht aus wie",intro:"みたい drückt Ähnlichkeit und Vermutung aus, in lockerer Sprache.",text:'Nomen + みたい: 子どもみたいに笑う „lacht wie ein Kind". Verb/Adjektiv Plain + みたい: 雨が降ったみたいだ „es scheint geregnet zu haben". Vor einem Nomen: 夢みたいな話. Die höfliche/schriftliche Entsprechung ist ようだ.',tip:"みたい ist umgangssprachlich; in Aufsätzen und formellen Texten nimmt man ようだ.",ex:[["彼はまだ来ていないみたいです。","かれはまだきていないみたいです。","Er scheint noch nicht da zu sein."],["この部屋、氷みたいに寒いね。","このへや、こおりみたいにさむいね。","Dieses Zimmer ist kalt wie Eis."],["誰かがドアをノックしたみたい。","だれかがドアをノックしたみたい。","Es scheint, jemand hat an die Tür geklopft."]],q:[{q:"外は寒い＿＿。みんなコートを着ている。",o:["みたいだ","そうにない","ばかりだ","わけだ"],c:0},{q:"Die formelle/schriftliche Variante von みたい ist …",o:["ようだ","らしい","そうだ(伝聞)"],c:0},{q:'„wie ein Traum" (vor Nomen):',o:["夢みたいな","夢みたいの","夢みたいに"],c:0}]},{id:"n4-rashii",level:4,title:"〜らしい — anscheinend / typisch",intro:'らしい hat zwei Seiten: „anscheinend" (aus glaubwürdiger Quelle) und „typisch für".',text:'Vermutung aus Information: 天気予報によると、明日は雨らしい „laut Vorhersage regnet es morgen wohl". Typisch: 今日は春らしい天気ですね „heute ist richtig frühlingshaftes Wetter". Anders als そうだ(伝聞) mischt sich bei らしい eigene Einschätzung mit ein.',tip:'そうだ(伝聞) = reine Weitergabe; らしい = Weitergabe + „ich halte es für plausibel".',ex:[["田中さんは会社を辞めたらしい。","たなかさんはかいしゃをやめたらしい。","Herr Tanaka hat anscheinend gekündigt."],["彼女は本当に学生らしい学生だ。","かのじょはほんとうにがくせいらしいがくせいだ。",'Sie ist eine richtig „studentische" Studentin.'],["この辺りは昔、海だったらしいです。","このあたりはむかし、うみだったらしいです。","Diese Gegend war früher wohl Meer."]],q:[{q:"ニュースによると、事故があった＿＿。",o:["らしい","つもりだ","ところだ","ばかりだ"],c:0},{q:"「男らしい」 bedeutet …",o:["männlich / typisch Mann","anscheinend ein Mann","kein Mann"],c:0},{q:"Im Unterschied zu そうだ(伝聞) schwingt bei らしい … mit",o:["eigene Einschätzung","nichts anderes","ein Befehl"],c:0}]},{id:"n4-sou",level:4,title:"〜そう — sieht (gleich) so aus (様態)",intro:'Verb-Stamm / Adjektiv-Stamm + そう beschreibt einen unmittelbaren Eindruck: „sieht aus, als ob".',text:'このケーキ、おいしそう „dieser Kuchen sieht lecker aus". 雨が降りそうだ „es sieht nach Regen aus / wird gleich regnen". いい → よさそう, ない → なさそう (unregelmäßig). Nicht verwechseln mit 〜そうだ(伝聞) „man sagt", das an die Plain-Form andockt.',tip:"Faustregel: 降りそう (Stamm) = mein Eindruck; 降るそうだ (Plain) = ich habe gehört.",ex:[["彼は疲れていそうだった。","かれはつかれていそうだった。","Er sah müde aus."],["棚から本が落ちそうです。","たなからほんがおちそうです。","Das Buch droht aus dem Regal zu fallen."],["この問題は難しそうですね。","このもんだいはむずかしそうですね。","Diese Aufgabe sieht schwer aus."]],q:[{q:"空が暗い。雨が＿＿だ。",o:["降りそう","降るそう","降ったら","降るらしく"],c:0},{q:"いい wird im 様態-そう zu …",o:["よさそう","いそう","いいそう"],c:0},{q:"「難しそうだ」 (Stamm) drückt aus:",o:["mein Eindruck beim Hinsehen","ich habe es gehört","es ist sicher so"],c:0}]},{id:"n4-garu-tagaru",level:4,title:"〜がる・〜たがる — Gefühle Dritter",intro:"Über die Gefühle und Wünsche anderer spricht man nicht direkt mit 〜たい / 〜ほしい, sondern mit がる.",text:'い-Adjektiv-Stamm + がる: 弟は暗い所を怖がる „mein Bruder fürchtet sich vor dunklen Orten". Wunsch: 〜たい → 〜たがる: 子どもが外へ行きたがっている „das Kind will nach draußen". Meist im Verlauf 〜たがっている, weil es beobachtetes Verhalten ist.',tip:"Für die eigenen Gefühle bleibt es bei 怖い / 〜たい — がる nur bei der 3. Person.",ex:[["みんなが新しいゲームを欲しがっている。","みんながあたらしいゲームをほしがっている。","Alle wollen das neue Spiel haben."],["妹は寒がって、上着を取りに行った。","いもうとはさむがって、うわぎをとりにいった。","Meine Schwester fror und holte ihre Jacke."],["彼は本当のことを言いたがらない。","かれはほんとうのことをいいたがらない。","Er will die Wahrheit nicht sagen."]],q:[{q:"妹はいつも私のかばんを使い＿＿。",o:["たがる","たい","たそう","てほしい"],c:0},{q:"がる benutzt man für …",o:["die Gefühle einer dritten Person","die eigenen Gefühle","Fragen"],c:0},{q:"「怖い」 → 3. Person:",o:["怖がる","怖いがる","怖たがる"],c:0}]},{id:"n4-shieki-ukemi-kei",level:4,title:"使役受身形 — Kausativ-Passiv (〜させられる)",intro:'Diese Form sagt: „ich wurde gezwungen / musste (ungern) etwas tun".',text:'Godan: 飲む → 飲まされる, 待つ → 待たされる. Ichidan: 食べる → 食べさせられる. する → させられる, 来る → 来させられる. 子どものとき、毎日ピアノを練習させられた „als Kind musste ich jeden Tag Klavier üben (gezwungen)". Es schwingt Widerwille mit.',tip:"Reihenfolge der Bausteine: Kausativ (させる) + Passiv (られる) → させられる.",ex:[["部長にお酒を飲まされました。","ぶちょうにおさけをのまされました。","Der Abteilungsleiter hat mich zum Trinken gezwungen."],["一時間も待たされて、疲れた。","いちじかんもまたされて、つかれた。","Ich wurde eine ganze Stunde warten gelassen und bin müde."],["子どもの時、嫌いな野菜を食べさせられた。","こどものとき、きらいなやさいをたべさせられた。","Als Kind musste ich ungeliebtes Gemüse essen."]],q:[{q:"先生に廊下に＿＿。（立つ）",o:["立たされた","立たれた","立たせた","立った"],c:0},{q:"させられる drückt vor allem aus:",o:["gezwungen werden / ungern müssen","freiwillig tun","jemandem erlauben"],c:0},{q:"Die Bausteine sind …",o:["Kausativ + Passiv","Passiv + Potenzial","Volitional + Passiv"],c:0}]},{id:"n4-hazuda",level:4,title:"〜はずだ — es müsste (eigentlich) so sein",intro:'はず drückt eine begründete Erwartung aus: „logisch betrachtet ist es so".',text:'Plain-Form + はずだ: 彼はもう着いているはずだ „er müsste schon angekommen sein" (weil der Zug pünktlich war). Wenn die Erwartung nicht eintritt: 〜はずがない „das kann nicht sein" oder 〜はずだったのに „eigentlich hätte …, aber". Nomen + の + はず, な-Adjektiv + な + はず.',tip:"はず = ich schließe es aus Fakten; かもしれない = bloße Möglichkeit; に違いない = fast sicher.",ex:[["鍵はかばんの中にあるはずです。","かぎはかばんのなかにあるはずです。","Der Schlüssel müsste in der Tasche sein."],["彼女がそんなことを言うはずがない。","かのじょがそんなことをいうはずがない。","Sie würde so etwas nie sagen."],["今日は休みのはずだったのに、呼び出された。","きょうはやすみのはずだったのに、よびだされた。","Eigentlich hätte ich heute frei, aber ich wurde gerufen."]],q:[{q:"説明書を読んだから、使い方はわかる＿＿だ。",o:["はず","よう","そう","つもり"],c:0},{q:"「そんなはずがない」 bedeutet …",o:["das kann unmöglich sein","das ist sicher so","vielleicht"],c:0},{q:"はず beruht auf …",o:["einer Schlussfolgerung aus Fakten","reinem Bauchgefühl","Hörensagen"],c:0}]},{id:"n4-kamoshirenai",level:4,title:"〜かもしれない — es könnte sein",intro:'かもしれない drückt eine echte Möglichkeit aus — mehr als „vielleicht", weniger als „wahrscheinlich".',text:"Plain-Form + かもしれない: 今日は雨が降るかもしれない. Locker: 〜かも. Höflich: 〜かもしれません. Nomen/な-Adjektiv ohne だ: 彼は病気かもしれない. Grobe Wahrscheinlichkeit: かもしれない < でしょう / だろう < に違いない.",tip:'かもしれない sagt nichts über „eher ja" oder „eher nein" — beide Möglichkeiten stehen offen.',ex:[["彼はもう帰ったかもしれません。","かれはもうかえったかもしれません。","Er ist vielleicht schon gegangen."],["この道は間違っているかもしれない。","このみちはまちがっているかもしれない。","Dieser Weg könnte falsch sein."],["約束を忘れているかも。","やくそくをわすれているかも。","Vielleicht hat er das Versprechen vergessen."]],q:[{q:"空が曇ってきた。夕方、雪になる＿＿。",o:["かもしれない","に違いない","はずがない","わけだ"],c:0},{q:"Reihenfolge nach Sicherheit (schwach → stark):",o:["かもしれない → だろう → に違いない","に違いない → だろう → かもしれない","alle gleich"],c:0},{q:"「彼は学生＿＿かもしれない」",o:["—（nichts）","だ","です","である"],c:0}]},{id:"n4-toiu",level:4,title:"〜という — namens / dass (Zitat & Benennung)",intro:"という verbindet einen Inhalt oder Namen mit einem Nomen.",text:'Benennung: 田中という人から電話がありました „ein Herr namens Tanaka hat angerufen". Inhalt: 彼が結婚するという話を聞いた „ich hörte, dass er heiratet". Frage-Inhalt: どうすればいいかという問題. Locker wird という oft zu って: 明日休みだって.',tip:"Nach einem Zitat-Verb (言う・聞く・思う) steht das schlichte と; という bindet den Inhalt an ein Nomen.",ex:[["「さくら」という喫茶店を知っていますか。","「さくら」というきっさてんをしっていますか。",'Kennst du das Café namens „Sakura"?'],["彼は来られないという連絡がありました。","かれはこられないというれんらくがありました。","Es kam die Nachricht, dass er nicht kommen kann."],["日本語は難しいというイメージがある。","にほんごはむずかしいというイメージがある。","Japanisch hat den Ruf, schwer zu sein."]],q:[{q:"田中さん＿＿方が受付で待っています。",o:["という","といって","とは","とか"],c:0},{q:"Die lockere Kurzform von 〜という ist oft …",o:["〜って","〜のに","〜だけ"],c:0},{q:"「彼が犯人だ＿＿うわさが広がった」",o:["という","そうな","らしい","みたいな"],c:0}]},{id:"n4-tokoro",level:4,title:"〜ところ — gerade dabei / gerade getan",intro:"ところ markiert die Phase einer Handlung: davor, mitten drin, gerade danach.",text:'Wörterbuchform + ところ: これから出かけるところです „ich bin gerade im Begriff zu gehen". 〜ているところ: 今、食べているところです „ich esse gerade". た-Form + ところ: たった今、着いたところです „ich bin eben angekommen".',tip:"ところ als Phasen-Wort steht am Satzende mit です/だ und meint Zeit, nicht Ort.",ex:[["ちょうど今、家を出るところです。","ちょうどいま、いえをでるところです。","Ich gehe gerade jetzt aus dem Haus."],["レポートを書いているところなので、後で電話します。","レポートをかいているところなので、あとででんわします。","Ich schreibe gerade den Bericht, ich rufe später an."],["さっき駅に着いたところだ。","さっきえきについたところだ。","Ich bin eben am Bahnhof angekommen."]],q:[{q:"今、資料を準備している＿＿です。",o:["ところ","ばかり","つもり","よう"],c:0},{q:"「食べるところ」 heißt: die Handlung …",o:["steht unmittelbar bevor","ist gerade beendet","läuft gerade"],c:0},{q:"「たった今 終わった＿＿だ」",o:["ところ","こと","もの","つもり"],c:0}]},{id:"n4-tabakari",level:4,title:"〜たばかり — gerade erst getan",intro:"た-Form + ばかり betont, dass seit einer Handlung nur wenig Zeit vergangen ist — gefühlt.",text:'日本に来たばかりで、まだ何もわかりません „ich bin gerade erst nach Japan gekommen und verstehe noch nichts". Anders als 〜たところ (objektiv „soeben") ist ばかり eine gefühlte Frische — auch Monate später möglich: 去年買ったばかりのパソコン.',tip:'たところ = objektiv gerade eben; たばかり = subjektiv „noch ganz frisch".',ex:[["この電車は発車したばかりです。","このでんしゃははっしゃしたばかりです。","Dieser Zug ist gerade erst abgefahren."],["習ったばかりの漢字をもう忘れた。","ならったばかりのかんじをもうわすれた。","Das eben gelernte Kanji habe ich schon wieder vergessen."],["引っ越したばかりなので、片づいていません。","ひっこしたばかりなので、かたづいていません。","Ich bin gerade erst umgezogen, es ist noch nicht aufgeräumt."]],q:[{q:"さっき昼ご飯を食べた＿＿なのに、もうお腹がすいた。",o:["ばかり","うち","まま","あいだ"],c:0},{q:"Unterschied zu 〜たところ: たばかり betont …",o:["die gefühlte Frische","den exakten Zeitpunkt","den Ort"],c:0},{q:"「買ったばかり＿＿くつ」",o:["の","な","に","と"],c:0}]},{id:"n4-meru-waru-keru-su",level:4,title:"複合動詞 — 〜始める・〜終わる・〜続ける・〜出す",intro:"An den Verb-Stamm angehängte Hilfsverben zeigen den Verlauf einer Handlung.",text:'〜始める „anfangen zu": 雨が降り始めた. 〜終わる „fertig sein mit": 本を読み終わった. 〜続ける „weiter…": 三時間歩き続けた. 〜出す „plötzlich los… ": 赤ちゃんが泣き出した (unkontrolliert, abrupt — anders als 始める).',tip:'〜出す betont das Plötzliche/Unerwartete, 〜始める das schlichte „ab jetzt".',ex:[["駅に着いたとき、電車が動き出した。","えきについたとき、でんしゃがうごきだした。","Als ich am Bahnhof ankam, setzte sich der Zug in Bewegung."],["彼は黙って食べ続けた。","かれはだまってたべつづけた。","Er aß schweigend weiter."],["宿題をやり終わったら、遊んでいいよ。","しゅくだいをやりおわったら、あそんでいいよ。","Wenn du die Hausaufgaben fertig hast, darfst du spielen."]],q:[{q:"空が急に暗くなって、雨が降り＿＿。",o:["出した","終わった","続けた","始まった"],c:0},{q:"「読み終わる」 heißt …",o:["mit dem Lesen fertig sein","zu lesen beginnen","weiterlesen"],c:0},{q:"〜出す betont gegenüber 〜始める das …",o:["Plötzliche/Abrupte","Langsame","Höfliche"],c:0}]},{id:"n4-okagede-seide",level:4,title:"〜おかげで・〜せいで — dank / wegen",intro:"Beide nennen eine Ursache — おかげで für ein gutes Ergebnis, せいで für ein schlechtes.",text:'先生のおかげで、試験に合格できました „dank des Lehrers habe ich bestanden". 事故のせいで、遅刻した „wegen des Unfalls kam ich zu spät". Neutral bleibt ため oder から. Nomen + の, Verb + Plain.',tip:'せいで schiebt Schuld zu; おかげで dankt. Ironisch geht auch „おかげで" für Negatives: „na super, dank dir …".',ex:[["薬のおかげで、熱が下がりました。","くすりのおかげで、ねつがさがりました。","Dank der Medizin ist das Fieber gesunken."],["寝坊したせいで、バスに乗り遅れた。","ねぼうしたせいで、バスにのりおくれた。","Weil ich verschlafen habe, habe ich den Bus verpasst."],["君のおかげで助かったよ。","きみのおかげでたすかったよ。","Dank dir bin ich gerettet."]],q:[{q:"大雨の＿＿、試合が中止になった。",o:["せいで","おかげで","ように","ために"],c:0},{q:"Ein gutes Ergebnis + Ursache:",o:["〜おかげで","〜せいで","〜くせに"],c:0},{q:"「あなたのせいだ」 heißt …",o:["du bist schuld","danke dir","egal"],c:0}]},{id:"n4-temo-demo",level:4,title:"〜ても・〜でも — selbst wenn",intro:'て-Form + も heißt „auch wenn / selbst wenn" — die Bedingung ändert nichts am Ergebnis.',text:'雨が降っても、行きます „selbst wenn es regnet, gehe ich". な-Adjektiv/Nomen + でも: 便利でも、高すぎる. Mit Fragewort: 何を言っても „egal was man sagt", いくら〜ても „egal wie sehr".',tip:'たら/ば/と = „wenn, dann"; ても = „auch wenn, trotzdem nicht anders".',ex:[["高くても、これが欲しいです。","たかくても、これがほしいです。","Auch wenn es teuer ist, das will ich."],["いくら考えても、答えが出ない。","いくらかんがえても、こたえがでない。","Egal wie sehr ich nachdenke, ich finde keine Antwort."],["日曜日でも、その店は開いています。","にちようびでも、そのみせはあいています。","Sogar sonntags hat der Laden geöffnet."]],q:[{q:"どんなに忙しく＿＿、朝ごはんは食べる。",o:["ても","たら","ば","なら"],c:0},{q:'Nomen 学生 + „selbst wenn":',o:["学生でも","学生ても","学生なら"],c:0},{q:"「何を食べても太らない」 — 何を … drückt aus:",o:["egal was","nichts","etwas Bestimmtes"],c:0}]},{id:"n4-bahodo",level:4,title:"〜ば〜ほど — je … desto",intro:"Die Kombination aus ば-Form und Wörterbuchform + ほど drückt eine sich steigernde Abhängigkeit aus.",text:'練習すればするほど、上手になる „je mehr man übt, desto besser wird man". い-Adjektiv: 安ければ安いほど. な-Adjektiv/Nomen: 便利なら便利なほど / 便利であればあるほど. Oft reicht auch nur 〜ほど: 考えるほどわからなくなる.',tip:"Beide Verben sind dasselbe Wort — einmal in der ば-Form, einmal als Wörterbuchform.",ex:[["日本語は勉強すればするほど面白くなる。","にほんごはべんきょうすればするほどおもしろくなる。","Je mehr man Japanisch lernt, desto interessanter wird es."],["給料は高ければ高いほどいい。","きゅうりょうはたかければたかいほどいい。","Je höher das Gehalt, desto besser."],["彼のことを知れば知るほど好きになった。","かれのことをしればしるほどすきになった。","Je mehr ich ihn kennenlernte, desto lieber mochte ich ihn."]],q:[{q:"値段は安ければ＿＿ほど売れる。",o:["安い","安く","安さ","安いの"],c:0},{q:"Die beiden Verben in 〜ば〜ほど sind …",o:["dasselbe Verb in zwei Formen","zwei verschiedene Verben","immer する"],c:0},{q:'„je ruhiger, desto besser" (静か):',o:["静かなら静かなほど","静かければ静かいほど","静かでば静かほど"],c:0}]},{id:"n4-naide-zuni",level:4,title:"〜ないで・〜ずに — ohne zu tun",intro:"ない-Form + で (oder Schriftform 〜ずに) beschreibt eine Handlung, die *nicht* begleitet.",text:'朝ごはんを食べないで、学校へ行った „ich ging zur Schule, ohne zu frühstücken". Schriftlich/formell: 〜ずに (朝ごはんを食べずに). する wird unregelmäßig zu せずに. Anders als 〜なくて (Grund) beschreibt 〜ないで die Art und Weise.',tip:'なくて = „weil nicht" (Grund); ないで / ずに = „ohne dass" (Begleitumstand) und in Bitten (〜ないでください).',ex:[["電気を消さないで寝てしまった。","でんきをけさないでねてしまった。","Ich bin eingeschlafen, ohne das Licht auszumachen."],["辞書を使わずに、この文を訳してください。","じしょをつかわずに、このぶんをやくしてください。","Übersetzen Sie diesen Satz bitte ohne Wörterbuch."],["何も言わずに、彼は部屋を出て行った。","なにもいわずに、かれはへやをでていった。","Ohne ein Wort verließ er das Zimmer."]],q:[{q:"傘を持た＿＿出かけて、雨に降られた。",o:["ないで","なくて","なければ","ないと"],c:0},{q:"Die formelle Schriftform von 〜ないで ist …",o:["〜ずに","〜なくて","〜ないと"],c:0},{q:'する → „ohne zu tun":',o:["せずに","しずに","さずに"],c:0}]},{id:"n4-nakutemoii",level:4,title:"〜なくてもいい — muss man nicht",intro:'ない-Form ohne das letzte い + くてもいい heißt „es ist nicht nötig, zu …".',text:'明日は来なくてもいいです „du musst morgen nicht kommen". Gegenstück zu 〜なければならない „muss". Locker: 〜なくてもいい → 〜なくていい. Nomen/な-Adjektiv: 新しくなくてもいい / きれいじゃなくてもいい.',tip:'なくてもいい (nicht nötig) vs. 〜てはいけない (verboten) — beides „nicht", aber ganz verschieden.',ex:[["心配しなくてもいいですよ。","しんぱいしなくてもいいですよ。","Du musst dir keine Sorgen machen."],["靴を脱がなくてもいいです。","くつをぬがなくてもいいです。","Sie müssen die Schuhe nicht ausziehen."],["全部食べなくてもいいよ。","ぜんぶたべなくてもいいよ。","Du musst nicht alles aufessen."]],q:[{q:"予約は＿＿もいいです。当日でも入れます。",o:["しなくて","しないで","しなければ","しては"],c:0},{q:"Das Gegenteil (Pflicht) ist …",o:["〜なければならない","〜てもいい","〜たがる"],c:0},{q:"「新しく＿＿もいい」",o:["なくて","ないで","なければ","ずに"],c:0}]},{id:"n4-tehoshii",level:4,title:"〜てほしい — ich möchte, dass jemand …",intro:"て-Form + ほしい drückt einen Wunsch an eine *andere* Person aus.",text:'手伝ってほしいんですが „ich hätte gern, dass du mir hilfst". Die Person, an die sich der Wunsch richtet, steht mit に: 先生に説明してほしい. Verneinung: 〜ないでほしい „ich möchte, dass du das nicht tust". Für den eigenen Wunsch nach einer Handlung nimmt man 〜たい.',tip:"〜たい = ich will selbst …; 〜てほしい = ich will, dass ein anderer …",ex:[["もっと早く言ってほしかった。","もっとはやくいってほしかった。","Ich hätte gewollt, dass du es früher sagst."],["ここでたばこを吸わないでほしい。","ここでたばこをすわないでほしい。","Ich möchte, dass hier nicht geraucht wird."],["子どもには元気に育ってほしい。","こどもにはげんきにそだってほしい。","Ich wünsche mir, dass das Kind gesund aufwächst."]],q:[{q:"君に本当のことを話し＿＿。",o:["てほしい","たい","たがる","てみたい"],c:0},{q:"Die angesprochene Person steht mit …",o:["に","を","が","へ"],c:0},{q:'„Ich möchte, dass du nicht gehst.":',o:["行かないでほしい","行きたくない","行くほしくない"],c:0}]},{id:"n4-sonkei",level:4,title:"尊敬語 — respektvolle Sprache über andere",intro:"Um die Handlungen höhergestellter Personen zu ehren, hebt man das Verb an.",text:'Muster: お + ます-Stamm + になる — 社長はもうお帰りになりました „der Chef ist schon gegangen". Passiv-Form als leichte Höflichkeit: 先生が来られる. Sonderverben: いる/行く/来る → いらっしゃる, 言う → おっしゃる, 見る → ご覧になる, する → なさる, 食べる/飲む → 召し上がる.',tip:"Sonkeigo hebt den *anderen*; die eigenen Handlungen senkt man mit Kenjōgo (nächste Lektion).",ex:[["先生は何時にいらっしゃいますか。","せんせいはなんじにいらっしゃいますか。","Wann kommen Sie, Herr Lehrer?"],["お客様がお待ちになっています。","おきゃくさまがおまちになっています。","Der Kunde wartet."],["部長はもう資料をご覧になりました。","ぶちょうはもうしりょうをごらんになりました。","Der Abteilungsleiter hat die Unterlagen bereits gesehen."]],q:[{q:"社長は明日大阪へ＿＿。（行く・尊敬）",o:["いらっしゃいます","まいります","行かせます","おります"],c:0},{q:"Das Sonkeigo-Grundmuster ist …",o:["お + ます-Stamm + になる","お + ます-Stamm + する","〜させていただく"],c:0},{q:"「食べる」 als Sonkeigo:",o:["召し上がる","いただく","お食べする"],c:0}]},{id:"n4-kenjou",level:4,title:"謙譲語 — bescheidene Sprache über sich selbst",intro:"Kenjōgo senkt die eigenen Handlungen, um den Gegenüber zu ehren.",text:'Muster: お + ます-Stamm + する — 私がご案内します „ich führe Sie". Sonderverben: 行く/来る → まいる, いる → おる, 言う → 申す/申し上げる, する → いたす, 見る → 拝見する, 聞く/訪ねる → 伺う, 食べる/飲む/もらう → いただく, あげる → 差し上げる.',tip:"Faustregel: Handelt der andere → Sonkeigo. Handle ich (für den anderen) → Kenjōgo.",ex:[["田中と申します。よろしくお願いします。","たなかともうします。よろしくおねがいします。","Mein Name ist Tanaka. Sehr erfreut."],["明日、そちらへ伺います。","あした、そちらへうかがいます。","Morgen komme ich zu Ihnen."],["お荷物をお持ちします。","おにもつをおもちします。","Ich trage Ihr Gepäck."]],q:[{q:"資料は私が＿＿。（見る・謙譲）",o:["拝見します","ご覧になります","見られます","お見になります"],c:0},{q:"Das Kenjōgo-Grundmuster ist …",o:["お + ます-Stamm + する","お + ます-Stamm + になる","〜れる/られる"],c:0},{q:"「行く」 als Kenjōgo:",o:["まいる","いらっしゃる","おいでになる"],c:0}]},{id:"n4-sa-mi",level:4,title:"〜さ・〜み — aus Adjektiv wird Nomen",intro:"い-Adjektive lassen sich zu Nomen machen: mit さ (objektiv, messbar) oder み (gefühlt).",text:'高い → 高さ „die Höhe" (Messwert), 高み „eine Anhöhe" (Ort/Gefühl). 重い → 重さ. な-Adjektive: 便利 → 便利さ. さ passt zu Zahlen und Vergleichen, み zu wenigen festen Wörtern: 深み, 楽しみ, 悲しみ, 弱み, 強み.',tip:"Im Zweifel さ — es funktioniert bei fast allen Adjektiven; み nur bei einer festen Liste.",ex:[["この山の高さは3000メートルです。","このやまのたかさはさんぜんメートルです。","Dieser Berg ist 3000 Meter hoch."],["彼の話には深みがある。","かれのはなしにはふかみがある。","Seine Worte haben Tiefe."],["旅行を楽しみにしています。","りょこうをたのしみにしています。","Ich freue mich auf die Reise."]],q:[{q:"荷物の＿＿を量ってください。（重い → Nomen）",o:["重さ","重み","重く","重いこと"],c:0},{q:"Für einen Messwert / eine Zahl nimmt man …",o:["〜さ","〜み","beide gleich oft"],c:0},{q:"「楽しい」 → festes み-Nomen:",o:["楽しみ","楽しさ nur","楽しいこと"],c:0}]},{id:"n4-tearu",level:4,title:"〜てある — hergerichteter Zustand",intro:"て-Form (transitives Verb) + ある beschreibt einen Zustand, den jemand absichtlich hergestellt hat.",text:'ドアが開けてあります „die Tür ist (bewusst) geöffnet". Man sieht das Ergebnis einer Handlung, deren Zweck noch besteht — jemand hat es vorbereitet. Vergleich: 窓が開いている (〜ている, intransitiv) = Zustand ohne Absicht; 窓が開けてある (〜てある, transitiv) = jemand hat es geöffnet und so gelassen.',tip:"Bei 〜てある wird das Objekt mit が markiert, nicht mit を: ビールが冷やしてある.",ex:[["壁に地図がはってあります。","かべにちずがはってあります。","An der Wand hängt (aufgehängt) eine Karte."],["予約はもうしてあるから、大丈夫です。","よやくはもうしてあるから、だいじょうぶです。","Die Reservierung ist schon gemacht, alles gut."],["冷蔵庫にケーキが買ってある。","れいぞうこにケーキがかってある。","Im Kühlschrank ist (gekauft und bereitgelegt) ein Kuchen."]],q:[{q:"テーブルの上に手紙が置い＿＿。",o:["てある","ている","ておく","ておる"],c:0},{q:"Bei 〜てある steht das Objekt mit …",o:["が","を","に","へ"],c:0},{q:"「窓が開けてある」 heißt: …",o:["jemand hat es absichtlich geöffnet gelassen","es ging von allein auf","es wird gerade geöffnet"],c:0}]},{id:"n4-meiwakuno-ukemi",level:4,title:'迷惑の受身 — das „leidende" Passiv',intro:"Japanisch nutzt das Passiv auch, wenn einen etwas *stört* — selbst bei Verben ohne echtes Objekt.",text:'雨に降られて、ぬれてしまった „ich wurde vom Regen überrascht und wurde nass". 隣の人にたばこを吸われて、気分が悪い „der Nachbar hat (mir zum Ärger) geraucht". Der Betroffene steht mit は/が, der Verursacher mit に. Es gibt kein deutsches Passiv-Äquivalent — sinngemäß „mir wurde … angetan".',tip:"Erkennungszeichen: Passiv + negatives Gefühl + oft ein Verb, das sonst kein Passiv bildet (降る, 泣く, 来る).",ex:[["電車で足を踏まれた。","でんしゃであしをふまれた。","Im Zug ist mir jemand auf den Fuß getreten."],["子どもに泣かれて、夜眠れなかった。","こどもになかれて、よるねむれなかった。","Das Kind hat geweint, und ich konnte nachts nicht schlafen."],["友だちに来られて、勉強できなかった。","ともだちにこられて、べんきょうできなかった。","Ein Freund kam (ungelegen), und ich konnte nicht lernen."]],q:[{q:"夜中に赤ちゃんに＿＿、寝られなかった。",o:["泣かれて","泣いて","泣かせて","泣くと"],c:0},{q:"Der Verursacher im Leid-Passiv steht mit …",o:["に","を","が","から"],c:0},{q:"Das Leid-Passiv drückt meist … aus",o:["eine Störung / einen Nachteil für den Sprecher","einen Vorteil","eine Bitte"],c:0}]},{id:"n4-tekuru-teiku",level:4,title:"〜てくる・〜ていく — Richtung und Verlauf",intro:"くる und いく an der て-Form zeigen Bewegung *zum Sprecher hin* bzw. *weg* — räumlich oder zeitlich.",text:'Räumlich: 走ってくる „hergelaufen kommen", 持っていく „mitnehmen (weg)". Zeitlich: だんだん暖かくなってきた „es ist allmählich wärmer geworden (bis jetzt)"; これから寒くなっていく „es wird von jetzt an kälter werden". Auch „anfangen zu": 雨が降ってきた.',tip:"てきた blickt aus der Gegenwart zurück; ていく blickt in die Zukunft.",ex:[["最近、日本語が分かるようになってきた。","さいきん、にほんごがわかるようになってきた。","In letzter Zeit verstehe ich allmählich mehr Japanisch."],["お弁当を作って持っていきます。","おべんとうをつくってもっていきます。","Ich mache eine Bentō und nehme sie mit."],["これから人口は減っていくだろう。","これからじんこうはへっていくだろう。","Die Bevölkerung wird von jetzt an wohl abnehmen."]],q:[{q:"空が急に暗くなって、雨が降っ＿＿。",o:["てきた","ていった","てある","ておいた"],c:0},{q:'„von jetzt an immer mehr …" nutzt …',o:["〜ていく","〜てくる","〜てある"],c:0},{q:"傘を持っ＿＿方がいいよ、雨だから。",o:["ていった","てきた","てあった","ておいた"],c:0}]},{id:"n4-tokorodata",level:4,title:"〜ところだった — es wäre fast passiert",intro:'Wörterbuchform + ところだった sagt: „beinahe wäre …, aber zum Glück nicht".',text:'あぶない！車にひかれるところだった „Vorsicht! Fast wäre ich vom Auto überfahren worden". Oft mit もう少しで oder あやうく davor. Es ist *nicht* passiert — daher die Erleichterung (oder das Bedauern: 言うところだった „fast hätte ich es verraten").',tip:'Unterschied zu 〜そうだった: ところだった betont „um ein Haar", oft mit konkretem Auslöser.',ex:[["もう少しで電車に乗り遅れるところだった。","もうすこしででんしゃにのりおくれるところだった。","Fast hätte ich den Zug verpasst."],["危うく約束を忘れるところだった。","あやうくやくそくをわすれるところだった。","Um ein Haar hätte ich den Termin vergessen."],["あなたが教えてくれなかったら、間違えるところでした。","あなたがおしえてくれなかったら、まちがえるところでした。","Wenn du es mir nicht gesagt hättest, hätte ich mich fast geirrt."]],q:[{q:"ブレーキが遅かったら、ぶつかる＿＿。",o:["ところだった","ことになった","わけだった","ばかりだった"],c:0},{q:"〜ところだった sagt über das Ereignis: es …",o:["ist gerade NICHT passiert","ist gerade passiert","passiert regelmäßig"],c:0},{q:"Häufig davor steht …",o:["もう少しで / あやうく","もう / まだ","たった今"],c:0}]},{id:"n4-kuseni",level:3,title:"〜くせに — obwohl (mit Vorwurf)",intro:'くせに heißt „obwohl", aber immer mit Kritik, Verachtung oder Enttäuschung.',text:'知っているくせに、教えてくれない „obwohl er es weiß, sagt er es nicht (gemein)". Subjekt beider Teile ist dieselbe Person. Neutral wäre のに — くせに fügt „und das finde ich daneben" hinzu. Nicht in höflichen/formellen Kontexten verwenden.',tip:"のに = sachlicher Gegensatz; くせに = Gegensatz + Missbilligung.",ex:[["子どものくせに、大人みたいなことを言う。","こどものくせに、おとなみたいなことをいう。","Obwohl er ein Kind ist, redet er wie ein Erwachsener."],["お金があるくせに、いつもおごらない。","おかねがあるくせに、いつもおごらない。","Obwohl er Geld hat, gibt er nie einen aus."],["本当は行きたいくせに、行かないと言っている。","ほんとうはいきたいくせに、いかないといっている。","Obwohl er eigentlich hin will, sagt er, er gehe nicht."]],q:[{q:"自分は何もしない＿＿、人には文句ばかり言う。",o:["くせに","ために","ように","あいだ"],c:0},{q:"くせに unterscheidet sich von のに durch …",o:["einen Ton von Vorwurf/Missbilligung","mehr Höflichkeit","nichts"],c:0},{q:"くせに ist geeignet für …",o:["lockere, kritische Rede","formelle E-Mails","Prüfungsaufsätze"],c:0}]},{id:"n4-poi",level:4,title:"〜っぽい — -haft / neigt zu",intro:'Nomen/Verb-Stamm/Adjektiv-Stamm + っぽい bildet ein い-Adjektiv „wirkt wie / neigt zu".',text:'子どもっぽい „kindisch", 忘れっぽい „vergesslich", 水っぽい „wässrig", 怒りっぽい „jähzornig". Locker gefärbt, oft leicht negativ. Beugt sich wie ein normales い-Adjektiv: 白っぽかった.',tip:"っぽい (Neigung/Anschein) ist nicht dasselbe wie らしい (typisch, wie es sein soll): 男らしい ≠ 男っぽい.",ex:[["この味、ちょっと水っぽいね。","このあじ、ちょっとみずっぽいね。","Der Geschmack ist etwas wässrig."],["彼は飽きっぽくて、何も続かない。","かれはあきっぽくて、なにもつづかない。","Er wird schnell überdrüssig, nichts hält lange."],["最近、忘れっぽくなった。","さいきん、わすれっぽくなった。","In letzter Zeit bin ich vergesslicher geworden."]],q:[{q:"あの人はすぐ怒る。本当に怒り＿＿人だ。",o:["っぽい","らしい","がち","ぎみ"],c:0},{q:"「子どもっぽい」 heißt …",o:["kindisch (Verhalten wie ein Kind)","typisch für ein Kind (positiv)","kein Kind"],c:0},{q:"っぽい beugt sich wie …",o:["ein い-Adjektiv","ein Verb","ein Nomen"],c:0}]},{id:"n4-gachi",level:3,title:"〜がち — neigt dazu (meist unerwünscht)",intro:'ます-Stamm oder Nomen + がち heißt „neigt dazu / passiert häufig" — fast immer negativ.',text:'冬は風邪をひきがちだ „im Winter neigt man dazu, sich zu erkälten". 病気がちの子ども „ein kränkliches Kind". Anders als よく (schlicht „oft") schwingt bei がち mit: „und das ist ein Problem".',tip:"がち (Tendenz, negativ) vs. っぽい (Wesenszug/Anschein): 遅れがち = kommt oft zu spät; 怒りっぽい = ist jähzornig.",ex:[["忙しいと、朝ごはんを抜きがちになる。","いそがしいと、あさごはんをぬきがちになる。","Wenn man beschäftigt ist, lässt man das Frühstück oft ausfallen."],["曇りがちの天気が続いています。","くもりがちのてんきがつづいています。","Es bleibt überwiegend bewölktes Wetter."],["一人暮らしだと、栄養が偏りがちだ。","ひとりぐらしだと、えいようがかたよりがちだ。","Wenn man allein lebt, wird die Ernährung leicht einseitig."]],q:[{q:"ストレスがたまると、食べ過ぎ＿＿だ。",o:["がち","っぽい","ぎみ","げ"],c:0},{q:"がち hat fast immer … Färbung",o:["negative","positive","neutrale"],c:0},{q:"Vor がち steht …",o:["ます-Stamm oder Nomen","die て-Form","die ない-Form"],c:0}]},{id:"n4-gimi",level:3,title:"〜気味 — ein leichter Anflug von",intro:'ます-Stamm oder Nomen + 気味（ぎみ）heißt „ein bisschen / leicht angehaucht von".',text:'風邪気味なので、今日は早く帰ります „ich bin leicht erkältet, deshalb gehe ich heute früh". 疲れ気味, 太り気味, 緊張気味. Es beschreibt einen schwachen, beginnenden Zustand — nicht voll ausgeprägt.',tip:'がち = „passiert oft"; 気味 = „ist gerade ein wenig so". 遅れがち (chronisch zu spät) ≠ 遅れ気味 (heute etwas spät dran).',ex:[["最近ちょっと疲れ気味です。","さいきんちょっとつかれぎみです。","In letzter Zeit bin ich etwas erschöpft."],["今月は少し食べ過ぎ気味だ。","こんげつはすこしたべすぎぎみだ。","Diesen Monat habe ich etwas zu viel gegessen."],["寝不足気味で、頭が痛い。","ねぶそくぎみで、あたまがいたい。","Ich habe etwas zu wenig geschlafen und Kopfschmerzen."]],q:[{q:"のどが痛い。少し風邪＿＿かもしれない。",o:["気味","がち","っぽい","だらけ"],c:0},{q:"気味 beschreibt einen Zustand, der …",o:["schwach / beginnend ist","voll ausgeprägt ist","chronisch ist"],c:0},{q:"Vor 気味 steht …",o:["ます-Stamm oder Nomen","ein ganzer Satz","die た-Form"],c:0}]},{id:"n4-wakeganai-wakedehanai",level:3,title:"〜わけがない・〜わけではない",intro:'Zwei „わけ"-Ausdrücke, die man leicht verwechselt: „unmöglich" vs. „nicht unbedingt".',text:'〜わけがない = „es kann gar nicht sein": 彼が知らないわけがない „er kann es unmöglich nicht wissen". 〜わけではない = „das heißt nicht, dass …": 嫌いなわけではないが、あまり食べない „ich mag es nicht direkt nicht, esse es aber selten" — eine Teilverneinung.',tip:"わけがない = starke Verneinung der Möglichkeit; わけではない = weiche Einschränkung.",ex:[["あの真面目な人が嘘をつくわけがない。","あのまじめなひとがうそをつくわけがない。","So ein ernsthafter Mensch lügt garantiert nicht."],["お金があるからといって、幸せなわけではない。","おかねがあるからといって、しあわせなわけではない。","Nur weil man Geld hat, heißt das nicht, dass man glücklich ist."],["全部が難しいわけではない。簡単な問題もある。","ぜんぶがむずかしいわけではない。かんたんなもんだいもある。","Nicht alles ist schwer — es gibt auch leichte Aufgaben."]],q:[{q:"毎日練習しているのだから、上手にならない＿＿。",o:["わけがない","わけではない","わけにはいかない","ことはない"],c:0},{q:'„Das heißt nicht unbedingt, dass …":',o:["〜わけではない","〜わけがない","〜に違いない"],c:0},{q:"「知らないわけがない」 bedeutet: er …",o:["weiß es ganz sicher","weiß es sicher nicht","weiß es vielleicht"],c:0}]},{id:"n4-wakenihaikanai",level:3,title:"〜わけにはいかない — das geht (aus Prinzip) nicht",intro:"わけにはいかない sagt: aus sozialen, moralischen oder praktischen Gründen ist etwas nicht machbar — obwohl es theoretisch ginge.",text:'明日は試験だから、遊ぶわけにはいかない „morgen ist Prüfung, da kann ich nicht (einfach) feiern". Verneint: 〜ないわけにはいかない = „ich komme nicht umhin, zu …": 招待されたから、行かないわけにはいかない.',tip:'できない = körperlich/technisch unmöglich; わけにはいかない = „es verbietet sich" trotz Möglichkeit.',ex:[["約束したから、行かないわけにはいかない。","やくそくしたから、いかないわけにはいかない。","Ich habe es versprochen, also komme ich nicht drumherum zu gehen."],["仕事中だから、お酒を飲むわけにはいかない。","しごとちゅうだから、おさけをのむわけにはいかない。","Ich bin bei der Arbeit, da kann ich keinen Alkohol trinken."],["みんなが待っているので、休むわけにはいかない。","みんながまっているので、やすむわけにはいかない。","Alle warten, da kann ich nicht Pause machen."]],q:[{q:"大事な会議なので、遅刻する＿＿。",o:["わけにはいかない","わけがない","わけではない","ことはない"],c:0},{q:"「行かないわけにはいかない」 heißt …",o:["ich muss (komme nicht drumherum) gehen","ich darf nicht gehen","ich kann nicht gehen"],c:0},{q:"わけにはいかない unterscheidet sich von できない, weil …",o:["es theoretisch möglich, aber sozial/moralisch ausgeschlossen ist","es technisch unmöglich ist","kein Unterschied"],c:0}]},{id:"n4-youtosuru",level:4,title:"〜ようとする — versuchen zu / im Begriff sein",intro:'Volitionalform + とする heißt „einen Anlauf nehmen zu" oder „gerade dabei sein, zu …".',text:'出かけようとしたとき、電話が鳴った „gerade als ich gehen wollte, klingelte das Telefon". 何度も立ち上がろうとしたが、できなかった „ich versuchte mehrmals aufzustehen, schaffte es aber nicht". Verneint: 〜ようとしない = „macht keine Anstalten zu": 子どもが薬を飲もうとしない.',tip:"てみる = einfach mal ausprobieren; ようとする = sich anstrengen / im Ansatz sein (oft mit Hindernis).",ex:[["ドアを開けようとしたが、鍵がかかっていた。","ドアをあけようとしたが、かぎがかかっていた。","Ich wollte die Tür öffnen, aber sie war abgeschlossen."],["彼は失敗を認めようとしない。","かれはしっぱいをみとめようとしない。","Er macht keine Anstalten, seinen Fehler zuzugeben."],["寝ようとしたとき、地震が来た。","ねようとしたとき、じしんがきた。","Gerade als ich schlafen wollte, kam ein Erdbeben."]],q:[{q:"赤ちゃんが歩＿＿としている。",o:["こう","く","いて","ける"],c:0},{q:"「食べようとしない」 heißt: die Person …",o:["macht keine Anstalten zu essen","isst gerade","kann nicht essen"],c:0},{q:"〜ようとする betont gegenüber 〜てみる …",o:["Anstrengung / einen Ansatz (oft mit Hindernis)","ein lockeres Ausprobieren","eine Bitte"],c:0}]},{id:"n4-kiru-kirenai",level:4,title:"〜きる・〜きれない — vollständig / nicht zu schaffen",intro:'ます-Stamm + きる heißt „bis zum Ende / ganz und gar"; die Potentialverneinung きれない heißt „nicht ganz schaffen".',text:'長い小説を一日で読みきった „ich habe den langen Roman an einem Tag durchgelesen". 多すぎて食べきれない „es ist zu viel, ich schaffe es nicht aufzuessen". Auch „völlig": 疲れきる „total erschöpft sein", 困りきる.',tip:"きる = restlos abschließen; きれない = die Menge/Aufgabe übersteigt das Machbare.",ex:[["マラソンを最後まで走りきった。","マラソンをさいごまではしりきった。","Ich bin den Marathon bis zum Ende durchgelaufen."],["質問が多すぎて、答えきれなかった。","しつもんがおおすぎて、こたえきれなかった。","Es waren zu viele Fragen, ich konnte nicht alle beantworten."],["彼は疲れきった顔をしていた。","かれはつかれきったかおをしていた。","Er hatte ein völlig erschöpftes Gesicht."]],q:[{q:"この量は一人では食べ＿＿よ。",o:["きれない","きらない","きれる","きった"],c:0},{q:"「読みきる」 heißt …",o:["ganz zu Ende lesen","anfangen zu lesen","überfliegen"],c:0},{q:"疲れきる bedeutet …",o:["völlig erschöpft sein","ein bisschen müde sein","sich ausruhen"],c:0}]},{id:"n4-tabini",level:4,title:"〜たびに — jedes Mal, wenn",intro:'Wörterbuchform oder Nomen + の + たびに heißt „immer wenn / bei jeder Gelegenheit von".',text:'この写真を見るたびに、旅行を思い出す „jedes Mal, wenn ich dieses Foto sehe, erinnere ich mich an die Reise". 試験のたびに緊張する „bei jeder Prüfung bin ich nervös". Betont die Regelmäßigkeit der Kopplung zweier Ereignisse.',tip:"いつも〜と / 〜ごとに sind ähnlich; たびに klingt etwas gehobener und betont die Wiederholung.",ex:[["彼に会うたびに、元気をもらう。","かれにあうたびに、げんきをもらう。","Jedes Mal, wenn ich ihn treffe, gibt er mir Kraft."],["引っ越しのたびに、荷物が増える。","ひっこしのたびに、にもつがふえる。","Bei jedem Umzug wird das Gepäck mehr."],["この曲を聞くたびに、学生時代を思い出す。","このきょくをきくたびに、がくせいじだいをおもいだす。","Immer wenn ich dieses Lied höre, denke ich an meine Studienzeit."]],q:[{q:"母は電話する＿＿、「ちゃんと食べてる？」と聞く。",o:["たびに","ところに","ばかりに","ように"],c:0},{q:"Nomen vor たびに braucht …",o:["の","を","に","と"],c:0},{q:"たびに betont …",o:["die regelmäßige Kopplung zweier Ereignisse","einen einmaligen Zeitpunkt","einen Ort"],c:0}]},{id:"n4-madeni",level:4,title:"〜までに — bis spätestens (Frist)",intro:'までに markiert eine Frist: „bis zu diesem Zeitpunkt muss etwas geschehen sein".',text:'5時までにレポートを出してください „reichen Sie den Bericht bis spätestens 17 Uhr ein". Unterschied zu まで (ohne に) = „bis andauernd": 5時まで働く „bis 17 Uhr (durchgehend) arbeiten". までに geht mit punktuellen Handlungen (出す, 終わる, 帰る), まで mit andauernden (待つ, 寝る, いる).',tip:"Merksatz: までに + einmalige Handlung; まで + fortlaufende Handlung.",ex:[["来週の月曜日までに返事をください。","らいしゅうのげつようびまでにへんじをください。","Bitte antworten Sie bis spätestens nächsten Montag."],["夜12時までにはうちに帰りたい。","よるじゅうにじまでにはうちにかえりたい。","Ich möchte bis spätestens Mitternacht zu Hause sein."],["試験が始まるまでに、席に着いてください。","しけんがはじまるまでに、せきについてください。","Nehmen Sie bis zum Prüfungsbeginn Ihren Platz ein."]],q:[{q:"金曜日＿＿、この仕事を終わらせなければならない。",o:["までに","まで","から","ごろ"],c:0},{q:"「5時まで待つ」 vs 「5時までに来る」 — までに geht mit …",o:["einer einmaligen Handlung","einer andauernden Handlung","beidem gleich"],c:0},{q:'„bis 22 Uhr (durchgehend) lernen":',o:["10時まで勉強する","10時までに勉強する","10時ごろ勉強する"],c:0}]},{id:"n4-koso",level:3,title:"〜こそ — gerade / genau das",intro:'こそ hebt ein Wort besonders hervor: „gerade dieses / genau jetzt".',text:'今度こそ成功したい „diesmal will ich es (ganz bestimmt) schaffen". こちらこそ、よろしくお願いします „ganz meinerseits". 君こそ、よくやったよ „gerade du hast das gut gemacht". Nach から wird こそ zu からこそ = „gerade weil".',tip:"こそ verschiebt die Betonung, ändert die Satzstruktur aber nicht — es ersetzt oder ergänzt は/が.",ex:[["今日こそ早く寝よう。","きょうこそはやくねよう。","Heute gehe ich (ganz bestimmt) früh schlafen."],["あなたの助けがあったからこそ、できたんです。","あなたのたすけがあったからこそ、できたんです。","Gerade weil ich deine Hilfe hatte, habe ich es geschafft."],["「ありがとう」「いいえ、こちらこそ」","「ありがとう」「いいえ、こちらこそ」",'„Danke." — „Nein, ganz meinerseits."']],q:[{q:"一度失敗した。だから、次＿＿がんばる。",o:["こそ","さえ","しか","だけ"],c:0},{q:"「からこそ」 bedeutet …",o:["gerade weil","obwohl","falls"],c:0},{q:"こそ … die Satzstruktur",o:["ändert sie nicht (nur Betonung)","macht den Satz zur Frage","verneint den Satz"],c:0}]},{id:"n4-sae-saeba",level:3,title:"〜さえ・〜さえ〜ば — sogar / wenn nur",intro:'さえ betont ein extremes Beispiel („sogar"); さえ〜ば nennt eine einzige ausreichende Bedingung.',text:'Sogar: 忙しくて、食事をする時間さえない „ich bin so beschäftigt, dass ich nicht mal Zeit zum Essen habe". 子どもでさえ知っている „sogar Kinder wissen das". Nur-wenn: お金さえあれば、何でも買える „wenn ich nur Geld hätte, könnte ich alles kaufen"; 練習しさえすれば、上手になる.',tip:"さえ hebt das Unerwartete hervor; さえ〜ば reduziert alles auf *eine* Bedingung.",ex:[["疲れて、立っていることさえできなかった。","つかれて、たっていることさえできなかった。","Ich war so müde, dass ich nicht einmal stehen konnte."],["天気さえよければ、山がきれいに見える。","てんきさえよければ、やまがきれいにみえる。","Wenn nur das Wetter gut ist, sieht man die Berge schön."],["薬を飲みさえすれば、すぐ治りますよ。","くすりをのみさえすれば、すぐなおりますよ。","Wenn du nur die Medizin nimmst, wird es schnell besser."]],q:[{q:"ひらがな＿＿読めない子どもが多い。",o:["さえ","こそ","ばかり","だけ"],c:0},{q:"「お金さえあれば」 heißt …",o:["wenn nur Geld da wäre (eine einzige Bedingung)","obwohl Geld da ist","weil Geld da ist"],c:0},{q:"「〜しさえすれば」 baut auf … auf",o:["ます-Stamm + さえ + すれば","て-Form + さえ","ない-Form + さえ"],c:0}]},{id:"n4-dakedenaku-bakaridenaku",level:4,title:"〜だけでなく・〜ばかりでなく — nicht nur …, sondern auch",intro:'Beide Ausdrücke erweitern eine Aussage: „nicht bloß A, sondern auch B".',text:'彼は英語だけでなく、中国語も話せる „er spricht nicht nur Englisch, sondern auch Chinesisch". Formeller: 〜ばかりでなく / 〜のみならず. Der zweite Teil trägt oft も oder まで: 大人ばかりでなく子どもまで楽しめる.',tip:"だけでなく ist neutral und alltagstauglich; ばかりでなく / のみならず klingen schriftlicher.",ex:[["この町は自然が豊かなだけでなく、交通も便利だ。","このまちはしぜんがゆたかなだけでなく、こうつうもべんりだ。","Diese Stadt hat nicht nur viel Natur, sondern auch guten Verkehr."],["値段が高いばかりでなく、味もよくない。","ねだんがたかいばかりでなく、あじもよくない。","Es ist nicht nur teuer, sondern schmeckt auch nicht gut."],["子どもだけでなく、大人にも人気がある。","こどもだけでなく、おとなにもにんきがある。","Es ist nicht nur bei Kindern, sondern auch bei Erwachsenen beliebt."]],q:[{q:"彼は仕事ができる＿＿、性格もいい。",o:["だけでなく","までもなく","ものの","どころか"],c:0},{q:"Der zweite Teil trägt häufig …",o:["も oder まで","は","を"],c:0},{q:"Schriftlicher/formeller klingt …",o:["〜ばかりでなく","〜だけでなく","kein Unterschied"],c:0}]},{id:"n4-nitote",level:4,title:"〜にとって — für / aus der Sicht von",intro:"Nomen + にとって nennt den Standpunkt, von dem aus etwas bewertet wird.",text:'私にとって、家族が一番大切です „für mich ist die Familie das Wichtigste". 学生にとって、この本は難しすぎる. Danach folgt meist eine Bewertung (大切, 難しい, 必要, いい). Nicht verwechseln mit に (Empfänger) oder のために (Zweck).',tip:'にとって = „aus Sicht von X betrachtet"; のために = „zum Nutzen/Zweck von X".',ex:[["子どもにとって、遊びは勉強と同じくらい大切だ。","こどもにとって、あそびはべんきょうとおなじくらいたいせつだ。","Für Kinder ist Spielen genauso wichtig wie Lernen."],["外国人にとって、日本の敬語は難しい。","がいこくじんにとって、にほんのけいごはむずかしい。","Für Ausländer ist die japanische Höflichkeitssprache schwer."],["この経験は私にとって大きな意味があった。","このけいけんはわたしにとっておおきないみがあった。","Diese Erfahrung hatte für mich große Bedeutung."]],q:[{q:"私＿＿、日本語を学ぶことは夢の実現です。",o:["にとって","について","に対して","によって"],c:0},{q:"Nach にとって folgt meist …",o:["eine Bewertung (大切/難しい …)","ein Befehl","eine Frage"],c:0},{q:"にとって unterscheidet sich von のために durch …",o:["Standpunkt statt Zweck","nichts","mehr Höflichkeit"],c:0}]},{id:"n4-nitsuite-ni-shite",level:4,title:"〜について・〜に関して — über / bezüglich",intro:"Beide markieren das Thema, um das es geht.",text:'日本の歴史について本を書いた „ich habe ein Buch über die japanische Geschichte geschrieben". 〜に関して ist die formellere Variante (Anträge, Berichte). Vor einem Nomen: 〜についての / 〜に関する: 環境に関する問題.',tip:"について = alltagstauglich; に関して / に関する = förmlicher Schriftstil.",ex:[["その事件について、詳しく説明してください。","そのじけんについて、くわしくせつめいしてください。","Bitte erklären Sie den Vorfall genauer."],["料金に関するお問い合わせは、こちらへ。","りょうきんにかんするおといあわせは、こちらへ。","Anfragen zu den Gebühren bitte hierher."],["将来の計画について話し合った。","しょうらいのけいかくについてはなしあった。","Wir haben über die Zukunftspläne gesprochen."]],q:[{q:"新しい規則＿＿、質問があります。",o:["について","にとって","によって","に対して"],c:0},{q:"Vor einem Nomen wird 〜について zu …",o:["〜についての","〜についてな","〜についてと"],c:0},{q:"Formeller / schriftlicher ist …",o:["〜に関して","〜について","kein Unterschied"],c:0}]},{id:"n4-niyote",level:4,title:"〜によって — durch / je nach / abhängig von",intro:"によって hat mehrere Bedeutungen: Urheber im Passiv, Mittel, und Variation.",text:'Urheber: この絵はピカソによって描かれた „dieses Bild wurde von Picasso gemalt". Mittel/Grund: 話し合いによって問題を解決する. Variation: 人によって考え方が違う „je nach Person denkt man anders". Vor Nomen: 〜による: 地震による被害.',tip:"Im Passiv steht der Schöpfer/Autor mit によって (nicht mit に), besonders bei Werken und Erfindungen.",ex:[["電話は1876年にベルによって発明された。","でんわはせんはっぴゃくななじゅうろくねんにベルによってはつめいされた。","Das Telefon wurde 1876 von Bell erfunden."],["季節によって、景色が大きく変わる。","きせつによって、けしきがおおきくかわる。","Je nach Jahreszeit ändert sich die Landschaft stark."],["台風による被害が広がっている。","たいふうによるひがいがひろがっている。","Die Schäden durch den Taifun weiten sich aus."]],q:[{q:"この小説は有名な作家＿＿書かれた。",o:["によって","について","にとって","に対して"],c:0},{q:"「人によって違う」 heißt …",o:["es hängt von der Person ab","wegen der Person","für die Person"],c:0},{q:"Vor einem Nomen wird によって zu …",o:["による","によっての","によると nur"],c:0}]},{id:"n4-ni-shite",level:4,title:"〜に対して — gegenüber / im Gegensatz zu",intro:"に対して nennt das Ziel einer Haltung/Handlung oder stellt zwei Dinge gegenüber.",text:'Ziel: 目上の人に対して、丁寧な言葉を使う „gegenüber Höhergestellten benutzt man höfliche Sprache". Gegensatz: 兄は静かなのに対して、弟はよくしゃべる „während der ältere Bruder still ist, redet der jüngere viel". Vor Nomen: 〜に対する: 客に対する態度.',tip:"について = Thema; に対して = Adressat einer Einstellung / oder Kontrast zweier Seiten.",ex:[["先生の質問に対して、はっきり答えた。","せんせいのしつもんにたいして、はっきりこたえた。","Auf die Frage des Lehrers antwortete ich klar."],["去年の夏は暑かったのに対して、今年は涼しい。","きょねんのなつはあつかったのにたいして、ことしはすずしい。","Während letzter Sommer heiß war, ist es dieses Jahr kühl."],["彼の失礼な態度に対して、みんな怒っている。","かれのしつれいなたいどにたいして、みんなおこっている。","Über sein unhöfliches Verhalten sind alle verärgert."]],q:[{q:"子ども＿＿、そんな厳しい言い方はよくない。",o:["に対して","について","によって","にとって"],c:0},{q:"「AのB に対して、C」 kann ausdrücken …",o:["einen Kontrast zwischen A und C","einen Grund","eine Frist"],c:0},{q:"Vor einem Nomen wird に対して zu …",o:["に対する","に対しての nur","に対したり"],c:0}]},{id:"n4-monoda",level:3,title:"〜ものだ — allgemeine Wahrheit / früher immer",intro:'ものだ verallgemeinert: „so ist das nun mal" — oder erinnert an Gewohnheiten der Vergangenheit.',text:'Allgemeingültig: 年を取ると、昔のことを思い出すものだ „wenn man älter wird, erinnert man sich eben an früher". Nostalgie (た-Form + ものだ): 子どもの頃、よくこの川で泳いだものだ „als Kind bin ich oft in diesem Fluss geschwommen". Als milder Ratschlag: 先生には敬語を使うものだ.',tip:"ものだ (Norm/Nostalgie) ≠ 〜ものだから (Grund) ≠ 〜もの／もん (kindliche Begründung).",ex:[["困ったときは、お互いに助け合うものだ。","こまったときは、おたがいにたすけあうものだ。","In schweren Zeiten hilft man einander eben."],["学生の頃は、夜遅くまで友だちと話したものだ。","がくせいのころは、よるおそくまでともだちとはなしたものだ。","Als Student habe ich oft bis spät mit Freunden geredet."],["時間はあっという間に過ぎるものですね。","じかんはあっというまにすぎるものですね。","Die Zeit vergeht eben wie im Flug."]],q:[{q:"人の悪口は言わない＿＿だ。",o:["もの","ところ","よう","ため"],c:0},{q:"た-Form + ものだ drückt oft … aus",o:["Nostalgie / frühere Gewohnheit","eine Frist","eine Bitte"],c:0},{q:"「〜ものだ」 verallgemeinert zu …",o:["einer Norm / allgemeinen Wahrheit","einer einmaligen Tatsache","einer Vermutung"],c:0}]},{id:"n4-kotoda-kotohanai",level:4,title:"〜ことだ・〜ことはない — Rat und Beruhigung",intro:'Zwei „こと"-Ausdrücke für Ratschläge: 〜ことだ „du solltest", 〜ことはない „du musst nicht".',text:'合格したいなら、毎日勉強することだ „wenn du bestehen willst, solltest du täglich lernen" — ein direkter, oft belehrender Rat. 心配することはない „es gibt keinen Grund, sich Sorgen zu machen" — beruhigend, „das brauchst du nicht".',tip:"ことだ ist bestimmt/belehrend; unter Gleichgestellten lieber 〜方がいい. ことはない tröstet.",ex:[["風邪のときは、ゆっくり休むことだ。","かぜのときは、ゆっくりやすむことだ。","Bei einer Erkältung solltest du dich gut ausruhen."],["まだ時間がある。慌てることはないよ。","まだじかんがある。あわてることはないよ。","Es ist noch Zeit. Du musst dich nicht hetzen."],["分からないことがあれば、遠慮なく聞くことだ。","わからないことがあれば、えんりょなくきくことだ。","Wenn etwas unklar ist, solltest du ruhig fragen."]],q:[{q:"上手になりたければ、毎日練習する＿＿。",o:["ことだ","ことになる","ばかりだ","ところだ"],c:0},{q:"「泣くことはない」 bedeutet …",o:["du musst nicht weinen (kein Grund dazu)","du sollst weinen","du kannst nicht weinen"],c:0},{q:"〜ことだ als Rat klingt …",o:["bestimmt / belehrend","sehr vorsichtig","fragend"],c:0}]},{id:"n4-verbpaare-transitiv-intransitiv",level:4,title:"自動詞・他動詞 — Verbpaare (transitiv / intransitiv)",intro:"Viele japanische Verben kommen als Paar: eines mit を (jemand tut es), eines mit が (es passiert von selbst).",text:"Beispiele: 開ける / 開く, 閉める / 閉まる, つける / つく, 消す / 消える, 出す / 出る, 入れる / 入る, 決める / 決まる, 始める / 始まる, 落とす / 落ちる, 壊す / 壊れる. Das transitive Verb (他動詞) braucht ein Objekt mit を: ドアを開ける. Das intransitive (自動詞) beschreibt das Geschehen selbst, das Subjekt steht mit が: ドアが開く. Für einen bewusst hergestellten Zustand: 〜てある (他動詞) vs. 〜ている (自動詞).",tip:"Faustregel, keine Garantie: endet das Paarglied auf -eru und das andere auf -aru/-u, ist das -aru/-u-Glied oft intransitiv (閉まる, 始まる).",ex:[["子どもが窓を開けました。","こどもがまどをあけました。","Das Kind hat das Fenster geöffnet. (他動詞, を)"],["風で窓が開きました。","かぜでまどがあきました。","Durch den Wind ging das Fenster auf. (自動詞, が)"],["電気を消してから、部屋を出ます。","でんきをけしてから、へやをでます。","Ich mache das Licht aus und verlasse dann das Zimmer."]],q:[{q:"弟がコップ＿＿割りました。",o:["を","が","に","で"],c:0},{q:"地震でお皿＿＿割れました。",o:["が","を","は","へ"],c:0},{q:"Welches ist transitiv (他動詞)?",o:["始める","始まる","出る","入る"],c:0},{q:"「エアコンがついている」 — welches Verb?",o:["自動詞 (つく)","他動詞 (つける)","Passiv","Kausativ"],c:0}]},{id:"n4-zutsu",level:4,title:"〜ずつ — je / jeweils / nach und nach",intro:"Zahl + Zähler + ずつ verteilt eine Menge gleichmäßig oder schrittweise.",text:'一人に二枚ずつ配ります „ich teile jedem zwei Blatt aus". 少しずつ覚える „nach und nach lernen". ずつ steht direkt hinter der Mengenangabe und bleibt unverändert. Häufig mit 少し, ちょっと, 一つ, 一日.',tip:'「一つずつ」 = „eins nach dem anderen"; ohne ずつ (「一つ」) fehlt die Verteilungs-Nuance.',ex:[["みんなに一つずつあげてください。","みんなにひとつずつあげてください。","Gib bitte jedem eins."],["毎日少しずつ日本語が上手になります。","まいにちすこしずつにほんごがじょうずになります。","Tag für Tag wird mein Japanisch ein bisschen besser."],["三人ずつのグループに分かれました。","さんにんずつのグループにわかれました。","Wir haben uns in Gruppen zu je drei aufgeteilt."]],q:[{q:"ノートを一人に三冊＿＿渡した。",o:["ずつ","だけ","しか","ごろ"],c:0},{q:'„nach und nach besser werden" — 少し＿＿よくなる。',o:["ずつ","ずつに","ずつも","ずつの"],c:0},{q:"ずつ steht …",o:["direkt hinter der Mengenangabe","am Satzanfang","hinter dem Verb","vor der Zahl"],c:0}]},{id:"n4-bayokata-tarayokata",level:4,title:"〜ばよかった・〜たらよかった — hätte ich doch …",intro:"Konditionalform + よかった drückt Bedauern über etwas Getanes oder Unterlassenes aus.",text:'もっと早く家を出ればよかった „ich hätte früher losgehen sollen". 傘を持ってくればよかった „hätte ich doch einen Schirm mitgenommen". Verneint: 〜なければよかった „hätte ich das bloß nicht getan". Umgangssprachlich oft 〜たらよかった. Häufig mit のに am Ende für stärkeres Bedauern: 予約すればよかったのに.',tip:'Für Rat an andere („du hättest … sollen") passt eher 〜ばよかったのに; für eigenes Bedauern reicht 〜ばよかった.',ex:[["あの店で買っておけばよかった。","あのみせでかっておけばよかった。","Ich hätte im Laden doch kaufen sollen."],["そんなこと、言わなければよかった。","そんなこと、いわなければよかった。","Das hätte ich bloß nicht sagen sollen."],["もっと勉強すればよかったと思っています。","もっとべんきょうすればよかったとおもっています。","Ich denke, ich hätte mehr lernen sollen."]],q:[{q:"道が込んでいる。もっと早く出＿＿よかった。",o:["れば","ると","るなら","ずに"],c:0},{q:'„Hätte ich das bloß nicht gegessen." — 食べ＿＿よかった。',o:["なければ","れば","たら","ないと"],c:0},{q:"〜ばよかった drückt aus …",o:["Bedauern","einen Befehl","eine Vermutung über die Zukunft","Erlaubnis"],c:0}]},{id:"n4-noni",level:4,title:"〜のに — wozu man etwas benutzt (Zweck)",intro:"Wörterbuchform + のに + 使う / いる / 便利だ / 時間がかかる nennt den Zweck einer Sache oder Handlung.",text:'このはさみは紙を切るのに使います „diese Schere benutzt man zum Schneiden von Papier". 駅まで行くのに三十分かかる „bis zum Bahnhof braucht man 30 Minuten". Diese のに ist NICHT das gegensätzliche „obwohl" — es folgt immer ein Ausdruck von Nutzen, Bedarf, Aufwand oder Eignung.',tip:"Nach Nomen steht stattdessen に: 料理に使う. のに braucht ein vorangehendes Verb.",ex:[["この道具は瓶を開けるのに便利です。","このどうぐはびんをあけるのにべんりです。","Dieses Werkzeug ist praktisch, um Flaschen zu öffnen."],["引っ越しの準備をするのに一週間かかった。","ひっこしのじゅんびをするのにいっしゅうかんかかった。","Die Vorbereitung des Umzugs hat eine Woche gedauert."],["子どもが漢字を覚えるのに、この本が役に立ちます。","こどもがかんじをおぼえるのに、このほんがやくにたちます。","Damit Kinder Kanji lernen, ist dieses Buch nützlich."]],q:[{q:"このアプリは単語を覚える＿＿便利だ。",o:["のに","ので","のは","のが"],c:0},{q:"空港まで行く＿＿一時間かかる。",o:["のに","のに対して","から","けど"],c:0},{q:'Nach einem Nomen wie „料理" steht statt のに …',o:["に","のに","には","にのに"],c:0}]},{id:"n3-monodakara",level:3,title:'〜ものだから — Rechtfertigung („weil eben …")',intro:"Erklärt entschuldigend, warum etwas passiert ist — der Grund liegt außerhalb der eigenen Kontrolle.",text:'Nach Verb/い-Adj in Plainform, な-Adj + な, Nomen + な: 〜ものだから / 〜もので. „道が込んでいたものだから、遅れてしまった." Der Sprecher betont, dass ihn keine Schuld trifft. Umgangssprachlich auch 〜もんだから.',tip:"Nur für den Grund von etwas bereits Geschehenem. Für Bitten/Aufforderungen passt 〜ので.",ex:[["子どもが熱を出したものですから、早退させてもらいました。","こどもがねつをだしたものですから、そうたいさせてもらいました。","Weil mein Kind Fieber bekommen hat, durfte ich früher gehen."],["あまりに眠かったものだから、会議中に寝てしまった。","あまりにねむかったものだから、かいぎちゅうにねてしまった。","Ich war so müde, dass ich in der Sitzung eingeschlafen bin."],["慣れないものでうまくできませんでした。","なれないものでうまくできませんでした。","Weil ich es nicht gewohnt bin, hat es nicht gut geklappt."]],q:[{q:"バスが来なかった＿＿、歩いて来ました。",o:["ものだから","ものなら","ものの","ことか"],c:0},{q:"〜ものだから wird vor allem benutzt für …",o:["eine entschuldigende Begründung","einen Befehl","einen Wunsch","eine Bedingung"],c:0},{q:"な-Adjektiv vor ものだから steht mit …",o:["な","の","だ","nichts"],c:0}]},{id:"n3-dokoroka",level:3,title:'〜どころか — „weit gefehlt, im Gegenteil"',intro:"Weist eine Annahme zurück und stellt das Gegenteil oder etwas Stärkeres dagegen.",text:'Nach Nomen / Verb・い-Adj Plainform / な-Adj (+な). „漢字どころか、ひらがなも読めない." Erwartung: „kann Kanji" → Wirklichkeit: „nicht mal Hiragana". Oft mit 〜も / 〜さえ im zweiten Teil.',tip:"Der zweite Teil geht immer in die *unerwartete* Richtung — meist negativer als gedacht, gelegentlich positiver.",ex:[["彼は謝るどころか、笑っていた。","かれはあやまるどころか、わらっていた。","Statt sich zu entschuldigen, lachte er sogar."],["疲れが取れるどころか、旅行でもっと疲れた。","つかれがとれるどころか、りょこうでもっとつかれた。","Statt mich zu erholen, war ich nach der Reise noch erschöpfter."],["貯金どころか、借金がある。","ちょきんどころか、しゃっきんがある。","Von Ersparnissen keine Rede — ich habe Schulden."]],q:[{q:"手伝ってくれる＿＿、じゃまばかりしている。",o:["どころか","だけあって","かわりに","うえに"],c:0},{q:"「安いどころか高かった」 heißt: …",o:["es war nicht billig, sondern teuer","es war sehr billig","es war weder billig noch teuer","der Preis war unbekannt"],c:0},{q:"Im zweiten Satzteil steht oft …",o:["〜も / 〜さえ","ただ","たぶん","もし"],c:0}]},{id:"n3-bakarika-bakaridenaku",level:3,title:'〜ばかりか・〜ばかりでなく — „nicht nur …, sondern auch"',intro:"Fügt eine zweite, oft stärkere Aussage hinzu.",text:'Nach Nomen / Plainform: 〜ばかりか / 〜ばかりでなく … （も）. „雨ばかりか、風も強くなってきた." Schriftsprachlicher als 〜だけでなく. Im zweiten Teil häufig 〜も, 〜まで, 〜さえ.',tip:"Kein Imperativ/Bitte im zweiten Teil. Dafür nimmt man 〜だけでなく.",ex:[["彼女は英語ばかりか、フランス語も話せる。","かのじょはえいごばかりか、フランスごもはなせる。","Sie spricht nicht nur Englisch, sondern auch Französisch."],["料金が高いばかりでなく、サービスも悪い。","りょうきんがたかいばかりでなく、サービスもわるい。","Nicht nur der Preis ist hoch, auch der Service ist schlecht."],["彼は約束を忘れたばかりか、謝りもしなかった。","かれはやくそくをわすれたばかりか、あやまりもしなかった。","Er hat die Verabredung nicht nur vergessen, er hat sich nicht einmal entschuldigt."]],q:[{q:"この店は品数が多い＿＿、値段も安い。",o:["ばかりでなく","かぎり","とたん","だらけ"],c:0},{q:"〜ばかりか ist gegenüber 〜だけでなく eher …",o:["schriftsprachlich","umgangssprachlich","unhöflich","veraltet"],c:0},{q:"Nicht möglich nach 〜ばかりか:",o:["ein Befehl","ein Nomen","ein Adjektiv","ein Verb"],c:0}]},{id:"n3-amari",level:3,title:'〜あまり（に）— „vor lauter …, so sehr, dass"',intro:"Ein zu starkes Gefühl oder Ausmaß führt zu einer (meist negativen) Folge.",text:'Nach Nomen + の / Verb・い-Adj Plainform / な-Adj + な: 〜あまり(に). „緊張のあまり、声が出なかった." Auch 〜あまりの＋Nomen＋に: „あまりの寒さに震えた."',tip:"Beschreibt einen einmaligen Zustand, keine Gewohnheit. Der Auslöser ist ein Übermaß.",ex:[["驚きのあまり、言葉を失った。","おどろきのあまり、ことばをうしなった。","Vor Schreck verschlug es mir die Sprache."],["働きすぎたあまり、体を壊してしまった。","はたらきすぎたあまり、からだをこわしてしまった。","Weil ich zu viel gearbeitet habe, wurde ich krank."],["あまりのうれしさに、涙が出た。","あまりのうれしさに、なみだがでた。","Vor lauter Freude kamen mir die Tränen."]],q:[{q:"心配した＿＿、一晩中眠れなかった。",o:["あまり","うちに","とおり","ものの"],c:0},{q:"「あまりの暑さに」— was folgt sinngemäß?",o:["eine Folge dieser großen Hitze","ein Wunsch nach Hitze","eine Frage zur Hitze","ein Vergleich"],c:0},{q:"な-Adjektiv vor あまり steht mit …",o:["な","の","だ","に"],c:0}]},{id:"n3-ueni",level:3,title:'〜うえに — „obendrein, zusätzlich"',intro:"Legt eine gleichartige zweite Eigenschaft/Handlung oben drauf (beide positiv oder beide negativ).",text:'Nach Plainform, な-Adj + な, Nomen + の: 〜上（うえ）に. „この部屋は狭い上に、暗い." Die beiden Teile ziehen in dieselbe Richtung.',tip:'Nicht mischen: nicht „gut, obendrein schlecht". Für Gegensätze nimmt man 〜のに / 〜わりに.',ex:[["彼は頭がいい上に、努力家だ。","かれはあたまがいいうえに、どりょくかだ。","Er ist klug und obendrein fleißig."],["道に迷った上に、雨まで降ってきた。","みちにまよったうえに、あめまでふってきた。","Ich habe mich verlaufen und obendrein fing es an zu regnen."],["このアパートは駅から近い上に、家賃も安い。","このアパートはえきからちかいうえに、やちんもやすい。","Diese Wohnung ist nah am Bahnhof und zudem günstig."]],q:[{q:"風が強い＿＿、気温も下がってきた。",o:["上に","ながら","ものの","かぎり"],c:0},{q:"Die beiden Teile von 〜上に …",o:["weisen in dieselbe Richtung","widersprechen sich","sind zeitlich versetzt","sind Ursache und Wirkung"],c:0},{q:"Nomen vor 上に steht mit …",o:["の","な","だ","に"],c:0}]},{id:"n3-ha-da-nun-einmal-wenn-schon",level:3,title:'〜以上（は）— „da nun einmal …, wenn schon"',intro:"Aus einer feststehenden Tatsache folgt eine selbstverständliche Konsequenz oder Entschlossenheit.",text:'Nach Verb Plainform / Nomen + である: 〜以上（は）. „引き受けた以上は、最後までやる." Der zweite Teil enthält oft 〜べきだ, 〜なければならない, 〜つもりだ, 〜はずだ.',tip:"Ähnlich 〜からには (etwas entschlossener) und 〜上は (schriftlicher).",ex:[["約束した以上、守らなければならない。","やくそくしたいじょう、まもらなければならない。","Da ich es versprochen habe, muss ich es halten."],["学生である以上、勉強が本分だ。","がくせいであるいじょう、べんきょうがほんぶんだ。","Solange man Student ist, ist Lernen die Hauptaufgabe."],["試合に出る以上は、勝ちたい。","しあいにでるいじょうは、かちたい。","Wenn ich schon am Wettkampf teilnehme, will ich gewinnen."]],q:[{q:"日本で働く＿＿、日本語は必要だ。",o:["以上","うちに","とたん","あまり"],c:0},{q:"Im zweiten Teil steht typischerweise …",o:["〜なければならない / 〜べきだ","eine Frage","eine Vermutung über andere","eine Bitte an sich selbst"],c:0},{q:"Nomen vor 以上 steht mit …",o:["である","の","な","だった"],c:0}]},{id:"n3-ri",level:3,title:'〜限り（は）・〜ない限り — „solange / sofern nicht"',intro:"Nennt die Bedingung, unter der etwas gilt — und die Grenze, an der es endet.",text:'Nach Verb Plainform / い-Adj / な-Adj + な / Nomen + の・である: 〜限り. „体が丈夫な限り、働き続けたい." Verneint: 〜ない限り = „solange nicht / es sei denn". „謝らない限り、許さない."',tip:'Getrennt davon: 〜限り als „so weit / nach bestem …" — 私の知る限り „soweit ich weiß".',ex:[["雨が降らない限り、試合は行われます。","あめがふらないかぎり、しあいはおこなわれます。","Solange es nicht regnet, findet das Spiel statt."],["ここにいる限り、安全だ。","ここにいるかぎり、あんぜんだ。","Solange du hier bist, bist du sicher."],["私の知る限り、彼は正直な人だ。","わたしのしるかぎり、かれはしょうじきなひとだ。","Soweit ich weiß, ist er ein ehrlicher Mensch."]],q:[{q:"許可がない＿＿、中に入れません。",o:["限り","あまり","ものの","うえに"],c:0},{q:"「調べない限り分からない」 heißt: …",o:["ohne nachzuschauen weiß man es nicht","nachschauen hilft nicht","man hat schon nachgeschaut","nachschauen ist verboten"],c:0},{q:"「見た限りでは」 bedeutet …",o:["soweit ich gesehen habe","nur weil ich gesehen habe","obwohl ich gesehen habe","sobald ich gesehen habe"],c:0}]},{id:"n3-karaniha",level:3,title:'〜からには — „wenn schon …, dann auch"',intro:"Aus einem Entschluss/einer Tatsache folgt eine feste Absicht — mit Nachdruck.",text:'Nach Verb Plainform / Nomen + である: 〜からには / 〜からは. „やるからには、完璧にやりたい." Zweiter Teil: 〜べきだ, 〜たい, 〜つもりだ, 〜なければならない.',tip:"Stärker und persönlicher als 〜以上は; drückt Entschlossenheit aus.",ex:[["引き受けたからには、責任を持ってやります。","ひきうけたからには、せきにんをもってやります。","Wenn ich es schon übernommen habe, mache ich es verantwortungsvoll."],["日本へ来たからには、富士山に登りたい。","にほんへきたからには、ふじさんにのぼりたい。","Wenn ich schon in Japan bin, will ich auf den Fuji steigen."],["プロであるからには、言い訳は許されない。","プロであるからには、いいわけはゆるされない。","Als Profi sind Ausreden nicht erlaubt."]],q:[{q:"試験を受ける＿＿、合格を目指す。",o:["からには","あまり","うちに","ながら"],c:0},{q:"〜からには vs. 〜以上は — 〜からには klingt …",o:["entschlossener / persönlicher","schriftlicher","höflicher","zweifelnder"],c:0},{q:"Passt NICHT nach 〜からには:",o:["eine sachliche Frage","〜たい","〜べきだ","〜つもりだ"],c:0}]},{id:"n3-kotonaku",level:3,title:'〜ことなく — „ohne (auch nur) zu …"',intro:"Etwas geschieht, ohne dass eine andere Handlung dazwischentritt. Schriftsprachlich.",text:'Nach Verb Wörterbuchform: 〜ことなく. „彼は一度も休むことなく、働き続けた." Entspricht 〜ないで / 〜ずに, klingt aber gehobener und betont die Durchgängigkeit.',tip:"Meist mit Verben der Fortdauer (〜続ける) oder mit 一度も / 最後まで.",ex:[["彼女は立ち止まることなく、ゴールまで走った。","かのじょはたちどまることなく、ゴールまではしった。","Sie lief ohne anzuhalten bis ins Ziel."],["問題は解決されることなく、時間だけが過ぎた。","もんだいはかいけつされることなく、じかんだけがすぎた。","Das Problem wurde nicht gelöst, es verging nur die Zeit."],["彼は誰にも相談することなく、会社を辞めた。","かれはだれにもそうだんすることなく、かいしゃをやめた。","Ohne mit jemandem zu sprechen, kündigte er."]],q:[{q:"祖父は生涯、故郷を離れる＿＿暮らした。",o:["ことなく","ものの","うえに","あまり"],c:0},{q:"〜ことなく entspricht am ehesten …",o:["〜ずに","〜ながら","〜たまま","〜たとたん"],c:0},{q:"〜ことなく ist im Ton …",o:["schriftsprachlich","salopp","kindlich","dialektal"],c:0}]},{id:"n3-zaruwo-nai",level:3,title:'〜ざるを得ない — „nicht umhinkönnen, gezwungen sein zu"',intro:"Man muss etwas tun, auch wenn man nicht will — durch die Umstände erzwungen.",text:'Verb ない-Form ohne ない + ざるを得ない. „台風だから、中止せざるを得ない." Ausnahme する → せざるを得ない. Gehoben; umgangssprachlich eher 〜しかない / 〜なければならない.',tip:'Drückt Widerwillen aus: „bleibt mir nichts anderes übrig". Nicht für freie Entscheidungen.',ex:[["証拠がある以上、認めざるを得ない。","しょうこがあるいじょう、みとめざるをえない。","Da es Beweise gibt, muss ich es wohl zugeben."],["終電がなくなったので、タクシーで帰らざるを得なかった。","しゅうでんがなくなったので、タクシーでかえらざるをえなかった。","Weil der letzte Zug weg war, musste ich mit dem Taxi heim."],["上司の命令なら、従わざるを得ない。","じょうしのめいれいなら、したがわざるをえない。","Wenn es der Befehl des Chefs ist, muss man gehorchen."]],q:[{q:"予算がないので、計画を変更せ＿＿。",o:["ざるを得ない","ないことはない","るべきだ","ずにすむ"],c:0},{q:"〜ざるを得ない drückt aus …",o:["erzwungenes Handeln gegen den Willen","freie Wahl","eine Erlaubnis","eine Vermutung"],c:0},{q:"する wird zu …",o:["せざるを得ない","しざるを得ない","するざるを得ない","さざるを得ない"],c:0}]},{id:"n3-sobald",level:3,title:'〜次第 — „sobald" und „je nach"',intro:"Zwei Bedeutungen: (1) sobald etwas fertig ist, (2) etwas hängt von etwas ab.",text:'(1) Verb ます-Stamm + 次第: „着き次第、連絡します." — sofort danach, meist mit Zukunft. (2) Nomen + 次第だ / Nomen + 次第で: „結果は努力次第だ." — es kommt darauf an.',tip:"Bedeutung (1) nur mit Willens-/Ereignisverben, kein 〜た, kein Vergangenheitsbezug.",ex:[["詳しいことが分かり次第、お知らせします。","くわしいことがわかりしだい、おしらせします。","Sobald Näheres bekannt ist, gebe ich Bescheid."],["行くかどうかは天気次第だ。","いくかどうかはてんきしだいだ。","Ob wir gehen, hängt vom Wetter ab."],["やり方次第で、結果は大きく変わる。","やりかたしだいで、けっかはおおきくかわる。","Je nach Vorgehen ändert sich das Ergebnis stark."]],q:[{q:"準備ができ＿＿、始めましょう。",o:["次第","あまり","うえに","ものの"],c:0},{q:"「値段は品質次第だ」 heißt: …",o:["der Preis richtet sich nach der Qualität","der Preis ist fix","die Qualität ist egal","Preis und Qualität sind gleich"],c:0},{q:"「連絡し次第」 — welche Zeitform folgt?",o:["Zukunft (連絡します)","Vergangenheit","Befehl","Verneinung"],c:0}]},{id:"n3-tatotan",level:3,title:'〜たとたん（に）— „kaum … da, im selben Moment"',intro:"Unmittelbar nach einer Handlung passiert überraschend etwas anderes.",text:'Verb + た + とたん（に）. „ドアを開けたとたん、猫が飛び出した." Der zweite Teil ist meist unerwartet, außerhalb der eigenen Kontrolle, und steht in der Vergangenheit.',tip:"Kein Vorsatz/Bitte/Verneinung im zweiten Teil — es ist ein plötzliches Ereignis, kein geplanter Ablauf.",ex:[["立ち上がったとたん、めまいがした。","たちあがったとたん、めまいがした。","Kaum stand ich auf, wurde mir schwindelig."],["彼の顔を見たとたんに、名前を思い出した。","かれのかおをみたとたんに、なまえをおもいだした。","In dem Moment, als ich sein Gesicht sah, fiel mir sein Name ein."],["家を出たとたん、雨が降り出した。","いえをでたとたん、あめがふりだした。","Kaum aus dem Haus, fing es an zu regnen."]],q:[{q:"ベルが鳴っ＿＿、みんな教室を出て行った。",o:["たとたん","たあまり","るからには","るかぎり"],c:0},{q:"Der zweite Teil bei 〜たとたん ist …",o:["ein plötzliches, unerwartetes Ereignis","ein geplanter nächster Schritt","eine Bitte","eine Gewohnheit"],c:0},{q:"Zeitform des zweiten Teils:",o:["Vergangenheit","Zukunft","Befehl","Präsens der Gewohnheit"],c:0}]},{id:"n3-darake",level:3,title:'〜だらけ — „voller, übersät mit"',intro:"Etwas ist im Übermaß mit etwas (meist Unangenehmem) bedeckt oder gefüllt.",text:'Nomen + だらけ. „泥だらけの靴", „間違いだらけのレポート", „借金だらけ". Fast immer negativ konnotiert (Schmutz, Fehler, Blut, Schulden).',tip:"Unterschied zu 〜ばかり (nur/lauter) und 〜まみれ (nur für an der Oberfläche haftende Substanzen wie 血・汗・泥).",ex:[["子どもたちは泥だらけになって遊んでいた。","こどもたちはどろだらけになってあそんでいた。","Die Kinder spielten und waren voller Schlamm."],["この作文は漢字の間違いだらけだ。","このさくぶんはかんじのまちがいだらけだ。","Dieser Aufsatz strotzt vor Kanji-Fehlern."],["部屋はほこりだらけだった。","へやはほこりだらけだった。","Das Zimmer war voller Staub."]],q:[{q:"転んで、手が傷＿＿になった。",o:["だらけ","ばかり","がち","かぎり"],c:0},{q:"〜だらけ ist meist …",o:["negativ konnotiert","positiv","neutral-sachlich","höflich"],c:0},{q:"Was steht vor だらけ?",o:["ein Nomen","ein Verb in ます-Form","ein い-Adjektiv","ein Satz"],c:0}]},{id:"n3-konai",level:3,title:'〜っこない — „auf gar keinen Fall, unmöglich"',intro:"Umgangssprachliche, nachdrückliche Verneinung einer Möglichkeit.",text:'Verb ます-Stamm + っこない. „そんな話、信じられっこない." = 〜はずがない / 〜わけがない, aber salopp und gefühlsbetont. Nur gesprochen / unter Vertrauten.',tip:"Nicht in formellen Situationen. Häufig mit そんな / 絶対.",ex:[["彼に勝てっこないよ。","かれにかてっこないよ。","Gegen ihn kannst du unmöglich gewinnen."],["今から行っても、間に合いっこない。","いまからいっても、まにあいっこない。","Selbst wenn wir jetzt losgehen, schaffen wir es nie."],["一日で覚えられっこない。","いちにちでおぼえられっこない。","An einem Tag kann man das unmöglich lernen."]],q:[{q:"そんな高い物、買え＿＿。",o:["っこない","かねない","がちだ","きれない"],c:0},{q:"〜っこない gehört in welchen Kontext?",o:["lockeres Gespräch","Geschäftsbrief","Vortrag","Prüfungsaufsatz"],c:0},{q:"〜っこない bedeutet dasselbe wie …",o:["〜わけがない","〜かもしれない","〜べきだ","〜がちだ"],c:0}]},{id:"n3-nishiteha",level:3,title:'〜にしては — „für … (Erwartung nicht erfüllt)"',intro:"Etwas weicht von dem ab, was man aufgrund eines Maßstabs erwarten würde.",text:'Nach Nomen / Verb Plainform: 〜にしては. „初めてにしては、上手だ." Maßstab „Anfänger" → Ergebnis besser als erwartet. Der Maßstab muss konkret sein.',tip:"Für allgemeine Erwartungen ohne konkreten Bezug nimmt man 〜わりに(は).",ex:[["冬にしては、暖かい一日だった。","ふゆにしては、あたたかいいちにちだった。","Für den Winter war es ein milder Tag."],["彼は新人にしては、落ち着いている。","かれはしんじんにしては、おちついている。","Für einen Neuling ist er erstaunlich ruhig."],["たくさん食べたにしては、太らないね。","たくさんたべたにしては、ふとらないね。","Für die Menge, die du gegessen hast, nimmst du erstaunlich wenig zu."]],q:[{q:"子どもが描いた＿＿、よくできている。",o:["にしては","だらけ","あまり","からには"],c:0},{q:"〜にしては setzt voraus …",o:["einen konkreten Maßstab","eine Bitte","eine Vermutung","einen Befehl"],c:0},{q:"Ähnlich, aber allgemeiner ist …",o:["〜わりに(は)","〜とたんに","〜ざるを得ない","〜っこない"],c:0}]},{id:"n3-tekaradenaito-tekaradenakereba",level:3,title:'〜てからでないと・〜てからでなければ — „nicht bevor / erst wenn"',intro:"Ohne die erste Handlung ist die zweite nicht möglich.",text:'Verb て-Form + からでないと / からでなければ + Verneinung. „予約してからでないと、入れません." Der Hauptsatz steht verneint (〜ない / 〜られない).',tip:"Betont eine Voraussetzung. Positiver Hauptsatz passt nicht — dann nimmt man 〜てから.",ex:[["説明書を読んでからでないと、使い方が分からない。","せつめいしょをよんでからでないと、つかいかたがわからない。","Ohne die Anleitung zu lesen, verstehe ich die Bedienung nicht."],["許可を取ってからでなければ、撮影できません。","きょかをとってからでなければ、さつえいできません。","Ohne Genehmigung darf man nicht fotografieren."],["よく考えてからでないと、返事できない。","よくかんがえてからでないと、へんじできない。","Bevor ich es nicht gut überlegt habe, kann ich nicht antworten."]],q:[{q:"準備が終わっ＿＿、始められない。",o:["てからでないと","たとたん","たあまり","るからには"],c:0},{q:"Der Hauptsatz bei 〜てからでないと ist …",o:["verneint","ein Befehl","eine Frage","positiv"],c:0},{q:"〜てからでないと betont …",o:["eine notwendige Voraussetzung","einen plötzlichen Wechsel","eine Gewohnheit","einen Gegensatz"],c:0}]},{id:"n3-tetamaranai-teshikataganai",level:3,title:'〜てたまらない・〜てしかたがない — „unerträglich, kann nicht anders"',intro:"Ein Gefühl oder Empfinden ist so stark, dass man es kaum aushält.",text:'Verb て-Form / い-Adj くて / な-Adj で + たまらない / しかたがない / しょうがない. „暑くてたまらない." Meist Gefühle, körperliche Zustände, Wünsche: 眠い, 心配だ, 会いたい, かゆい.',tip:"Nur für die eigene, unmittelbare Empfindung. Für andere: 〜たがっている / 〜ようだ.",ex:[["試験の結果が気になってしかたがない。","しけんのけっかがきになってしかたがない。","Das Prüfungsergebnis lässt mir keine Ruhe."],["国の家族に会いたくてたまらない。","くにのかぞくにあいたくてたまらない。","Ich sehne mich unheimlich danach, meine Familie zu Hause zu sehen."],["さっきから足がかゆくてしょうがない。","さっきからあしがかゆくてしょうがない。","Seit eben juckt mein Bein wie verrückt."]],q:[{q:"一人暮らしを始めたが、寂しく＿＿。",o:["てたまらない","てからでないと","ざるを得ない","にすぎない"],c:0},{q:"〜てたまらない beschreibt …",o:["die eigene starke Empfindung","die Vermutung über andere","eine Bitte","eine Regel"],c:0},{q:"な-Adjektiv vor たまらない steht mit …",o:["で","くて","な","に"],c:0}]},{id:"n3-totomoni",level:3,title:'〜とともに — „zusammen mit / im selben Maße wie"',intro:"Zwei Dinge geschehen gemeinsam oder ändern sich parallel.",text:'Nach Nomen / Verb Wörterbuchform: 〜とともに. Bedeutungen: (1) „gemeinsam mit" 家族とともに暮らす; (2) „während / im Zuge von" 年をとるとともに、記憶力が落ちる. Schriftsprachlich (gesprochen: 〜といっしょに / 〜につれて).',tip:"Für die parallele Veränderung ist 〜につれて austauschbar; 〜とともに klingt formeller.",ex:[["技術の進歩とともに、生活が便利になった。","ぎじゅつのしんぽとともに、せいかつがべんりになった。","Mit dem technischen Fortschritt wurde das Leben bequemer."],["卒業とともに、仲間はそれぞれの道へ進んだ。","そつぎょうとともに、なかまはそれぞれのみちへすすんだ。","Mit dem Abschluss ging jeder seinen eigenen Weg."],["社長は社員とともに問題に取り組んだ。","しゃちょうはしゃいんとともにもんだいにとりくんだ。","Der Chef packte das Problem gemeinsam mit den Mitarbeitern an."]],q:[{q:"年月がたつ＿＿、町の様子も変わっていった。",o:["とともに","にしては","どころか","っこない"],c:0},{q:"〜とともに ist im Ton eher …",o:["schriftsprachlich","salopp","kindlich","dialektal"],c:0},{q:"Für die parallele Änderung austauschbar mit …",o:["〜につれて","〜たとたん","〜ざるを得ない","〜っこない"],c:0}]},{id:"n3-ni-shite-ni-suru",level:3,title:'〜に反して・〜に反する — „entgegen / im Widerspruch zu"',intro:"Etwas verläuft anders als eine Erwartung, Regel oder ein Wunsch.",text:'Nomen + に反して. Typische Bezugswörter: 予想, 期待, 予測, ルール, 意思. „予想に反して、試合はあっさり終わった." Attributiv: 期待に反する結果.',tip:"Nur mit abstrakten Bezugsnomen (Erwartung, Regel …), nicht mit konkreten Dingen.",ex:[["親の期待に反して、彼は音楽の道を選んだ。","おやのきたいにはんして、かれはおんがくのみちをえらんだ。","Entgegen den Erwartungen der Eltern wählte er den Weg der Musik."],["予想に反して、売り上げは大きく伸びた。","よそうにはんして、うりあげはおおきくのびた。","Wider Erwarten stieg der Umsatz stark."],["規則に反する行為は認められない。","きそくにはんするこういはみとめられない。","Regelwidriges Verhalten wird nicht geduldet."]],q:[{q:"天気予報＿＿、午後から晴れた。",o:["に反して","に加えて","につき","にしては"],c:0},{q:"〜に反して steht mit Nomen wie …",o:["予想 / 期待 / 規則","テーブル / いす","今日 / 明日","一つ / 二つ"],c:0},{q:"Die attributive Form lautet …",o:["〜に反する","〜に反して","〜に反した上で","〜に反しながら"],c:0}]},{id:"n3-ni-ete",level:3,title:'〜に加えて — „zusätzlich zu, obendrein"',intro:"Zu einer bestehenden Sache kommt eine weitere gleichartige hinzu.",text:'Nomen + に加えて（は）. „強い風に加えて、雨も降り出した." Schriftsprachlich; gesprochen eher 〜だけでなく / 〜も.',tip:"Beide Teile ziehen in dieselbe Richtung (beide Belastung oder beide Vorteil).",ex:[["家賃に加えて、光熱費もかかる。","やちんにくわえて、こうねつひもかかる。","Zusätzlich zur Miete fallen Nebenkosten an."],["彼は実力に加えて、運もあった。","かれはじつりょくにくわえて、うんもあった。","Zu seinem Können kam auch noch Glück."],["交通費に加えて、宿泊費も会社が出す。","こうつうひにくわえて、しゅくはくひもかいしゃがだす。","Neben den Fahrtkosten übernimmt die Firma auch die Übernachtung."]],q:[{q:"基本給＿＿、毎月手当が支給される。",o:["に加えて","に反して","にしては","どころか"],c:0},{q:"〜に加えて verbindet Teile, die …",o:["gleichgerichtet sind","sich widersprechen","zeitlich weit auseinanderliegen","Ursache und Wirkung sind"],c:0},{q:"Umgangssprachlich sagt man eher …",o:["〜だけでなく〜も","〜たとたん","〜ざるを得ない","〜っこない"],c:0}]},{id:"n3-nisuginai",level:3,title:'〜にすぎない — „nur, nichts weiter als"',intro:"Setzt etwas herab: es ist nicht mehr als das Genannte.",text:'Nach Nomen / Verb Plainform: 〜にすぎない. „これは個人的な意見にすぎない." Oft mit ただ, ほんの, 一部, 言い訳.',tip:'Wertet ab / relativiert. Nicht mit Zahlen für „nur so wenig" — dafür 〜しか〜ない / 〜だけだ.',ex:[["彼はただの知り合いにすぎません。","かれはただのしりあいにすぎません。","Er ist nur ein Bekannter, nicht mehr."],["それは想像にすぎない。証拠はない。","それはそうぞうにすぎない。しょうこはない。","Das ist bloße Vermutung. Es gibt keine Beweise."],["今回の成功は運がよかったにすぎない。","こんかいのせいこうはうんがよかったにすぎない。","Der Erfolg diesmal war nichts als Glück."]],q:[{q:"私は指示に従った＿＿、責任はない。",o:["にすぎない","にちがいない","に反して","に加えて"],c:0},{q:"〜にすぎない drückt aus, dass etwas …",o:["nicht mehr als das Genannte ist","ganz sicher ist","verboten ist","unmöglich ist"],c:0},{q:"Häufig zusammen mit …",o:["ただ / ほんの","きっと","もし","ぜひ"],c:0}]},{id:"n3-nichigainai",level:3,title:'〜にちがいない — „mit Sicherheit, bestimmt"',intro:"Eine sehr sichere Schlussfolgerung aus Anzeichen.",text:'Nach Nomen / な-Adj (Stamm) / Verb・い-Adj Plainform: 〜にちがいない. „電気がついている。中に誰かいるにちがいない." Stärker als 〜だろう / 〜かもしれない, verwandt mit 〜はずだ, das sich aber auf nachprüfbare Gründe stützt.',tip:"Für die eigene feste Überzeugung, nicht für nachprüfbare Fakten. Umgangssprachlich 〜にちがいないよ / 〜に決まっている.",ex:[["あんなに勉強したのだから、合格するにちがいない。","あんなにべんきょうしたのだから、ごうかくするにちがいない。","Nach so viel Lernen wird er bestimmt bestehen."],["道が濡れている。夜のうちに雨が降ったにちがいない。","みちがぬれている。よるのうちにあめがふったにちがいない。","Die Straße ist nass. Es hat sicher nachts geregnet."],["彼女の表情から、悪い知らせにちがいないと思った。","かのじょのひょうじょうから、わるいしらせにちがいないとおもった。","An ihrem Gesicht sah ich: Das musste eine schlechte Nachricht sein."]],q:[{q:"荷物がこんなに重い。本が入っている＿＿。",o:["にちがいない","にすぎない","どころではない","っこない"],c:0},{q:"〜にちがいない ist gegenüber 〜かもしれない …",o:["deutlich sicherer","unsicherer","gleich sicher","höflicher"],c:0},{q:"な-Adjektiv vor にちがいない steht …",o:["im Stamm (ohne な)","mit な","mit だ","mit の"],c:0}]},{id:"n3-nitsuki",level:3,title:'〜につき — „pro / je" und „wegen"',intro:"Zwei Verwendungen: (1) je Einheit, (2) formeller Grund (Aushänge).",text:'(1) Nomen（Menge）+ につき: „一人につき二枚まで." (2) Nomen + につき = „wegen": „工事中につき、通行止め." Bedeutung (2) fast nur auf Schildern/in formellen Mitteilungen.',tip:"Bedeutung (2) ist sehr formell — im Gespräch sagt man ので / から.",ex:[["お子様一人につき、ケーキを一つお選びいただけます。","おこさまひとりにつき、ケーキをひとつおえらびいただけます。","Pro Kind darf ein Kuchen gewählt werden."],["本日は祝日につき、休業いたします。","ほんじつはしゅくじつにつき、きゅうぎょういたします。","Da heute Feiertag ist, bleibt geschlossen."],["一箱につき送料は五百円です。","ひとはこにつきそうりょうはごひゃくえんです。","Pro Karton beträgt das Porto 500 Yen."]],q:[{q:"準備中＿＿、しばらくお待ちください。（掲示）",o:["につき","にしては","に反して","どころか"],c:0},{q:"「一人につき千円」 heißt …",o:["1000 Yen pro Person","insgesamt 1000 Yen","höchstens eine Person","1000 Personen"],c:0},{q:'Die „wegen"-Bedeutung findet man vor allem …',o:["auf Aushängen / in Mitteilungen","im lockeren Gespräch","in Kinderbüchern","in Liedtexten"],c:0}]},{id:"n3-nitsurete-nishitagate",level:3,title:'〜につれて・〜にしたがって — „im Zuge von, je … desto"',intro:"Ändert sich das eine allmählich, ändert sich das andere mit.",text:'Nach Verb Wörterbuchform / Nomen: 〜につれて / 〜にしたがって. „山を登るにつれて、空気が冷たくなった." Beide Seiten beschreiben eine allmähliche, unwillkürliche Veränderung.',tip:'Kein Vorsatz/Bitte im zweiten Teil. 〜にしたがって zusätzlich = „gemäß / nach" (指示にしたがう).',ex:[["時間がたつにつれて、痛みは和らいだ。","じかんがたつにつれて、いたみはやわらいだ。","Mit der Zeit ließ der Schmerz nach."],["都市化が進むにしたがって、農地が減っている。","としかがすすむにしたがって、のうちがへっている。","Mit fortschreitender Urbanisierung schrumpft das Ackerland."],["経験を積むにつれて、仕事が楽になった。","けいけんをつむにつれて、しごとがらくになった。","Mit wachsender Erfahrung wurde die Arbeit leichter."]],q:[{q:"日が暮れる＿＿、気温がぐっと下がった。",o:["につれて","につき","にしては","に加えて"],c:0},{q:"Der zweite Teil bei 〜につれて ist …",o:["eine allmähliche Veränderung","ein Befehl","eine plötzliche Überraschung","eine Bitte"],c:0},{q:"〜にしたがって bedeutet zusätzlich …",o:["gemäß / nach (einer Anweisung)","trotz","anstatt","außer"],c:0}]},{id:"n3-nihokanaranai",level:3,title:'〜にほかならない — „nichts anderes als, gerade das"',intro:"Betont nachdrücklich: die eine Sache ist genau die andere.",text:'Nach Nomen: 〜にほかならない. „成功は努力の結果にほかならない." Schriftsprachlich, oft in Argumentationen/Essays. = ほかの何物でもなく、まさに〜だ.',tip:"Klingt gehoben und bestimmt. Im Alltag: 〜そのものだ / まさに〜だ.",ex:[["この事故は不注意の結果にほかならない。","このじこはふちゅういのけっかにほかならない。","Dieser Unfall ist nichts anderes als die Folge von Unachtsamkeit."],["言葉の乱れは、社会の変化の表れにほかならない。","ことばのみだれは、しゃかいのへんかのあらわれにほかならない。","Der Verfall der Sprache ist nichts als ein Ausdruck des gesellschaftlichen Wandels."],["彼の発言は差別にほかならない。","かれのはつげんはさべつにほかならない。","Seine Äußerung ist nichts anderes als Diskriminierung."]],q:[{q:"これは偶然ではなく、必然＿＿。",o:["にほかならない","にすぎない","に反する","どころではない"],c:0},{q:"〜にほかならない gehört eher in …",o:["Essays / Argumentationen","Kinderreime","Kochrezepte","SMS"],c:0},{q:"Sinngleich ist …",o:["まさに〜だ","たぶん〜だ","もし〜なら","〜かもしれない"],c:0}]},{id:"n3-warini",level:3,title:'〜わりに（は）— „für … verhältnismäßig, gemessen an"',intro:"Das Ergebnis passt nicht zu dem, was man aufgrund einer allgemeinen Größe erwarten würde.",text:'Nach Plainform / な-Adj + な / Nomen + の: 〜わりに(は). „値段のわりに、味は普通だ." Anders als 〜にしては (konkreter Maßstab) ist der Bezug hier allgemeiner.',tip:'Meist leicht wertend („mehr/weniger als gedacht").',ex:[["年齢のわりに、彼は落ち着いている。","ねんれいのわりに、かれはおちついている。","Für sein Alter ist er sehr gefasst."],["たくさん歩いたわりには、疲れていない。","たくさんあるいたわりには、つかれていない。","Für die viele Lauferei bin ich erstaunlich fit."],["このホテルは料金が高いわりに、サービスがよくない。","このホテルはりょうきんがたかいわりに、サービスがよくない。","Für den hohen Preis ist der Service dieses Hotels schwach."]],q:[{q:"勉強時間が短かった＿＿、いい点が取れた。",o:["わりに","につれて","に加えて","とともに"],c:0},{q:"〜わりには im Vergleich zu 〜にしては hat …",o:["einen allgemeineren Bezug","einen konkreteren Bezug","gar keinen Bezug","dieselbe Nuance genau"],c:0},{q:"Nomen vor わりに steht mit …",o:["の","な","だ","に"],c:0}]},{id:"n3-wokomete",level:3,title:'〜をこめて — „mit (einem Gefühl), voller"',intro:"Eine Handlung wird von einem starken Gefühl begleitet.",text:'Nomen（Gefühl）+ をこめて. Typisch: 心, 愛, 感謝, 願い, 怒り. „感謝の気持ちをこめて、手紙を書いた." Attributiv: 心をこめた料理.',tip:"Nur mit Gefühls-/Absichtsnomen. Für neutrale Beigaben nimmt man 〜を入れて.",ex:[["祈りをこめて、鶴を千羽折った。","いのりをこめて、つるをせんばおった。","Voller Gebet faltete ich tausend Kraniche."],["母は愛情をこめて弁当を作ってくれた。","ははあいじょうをこめてべんとうをつくってくれた。","Meine Mutter machte mir das Bentō mit viel Liebe."],["お礼の言葉に感謝をこめた。","おれいのことばにかんしゃをこめた。","In meine Dankesworte legte ich echte Dankbarkeit."]],q:[{q:"心＿＿演奏したので、聴衆に伝わった。",o:["をこめて","につき","に反して","どころか"],c:0},{q:"Vor をこめて steht ein Nomen wie …",o:["心 / 愛 / 感謝","テーブル / 本","三時 / 明日","駅 / 学校"],c:0},{q:"Die attributive Form lautet …",o:["〜をこめた","〜をこめて","〜をこめながら","〜をこめるうちに"],c:0}]},{id:"n3-wotooshite-wotsuujite",level:3,title:'〜をとおして・〜をつうじて — „durch, hindurch, mittels"',intro:"Etwas dient als Mittel/Medium, oder erstreckt sich über einen ganzen Zeitraum.",text:'Nomen + を通（とお）して / を通（つう）じて. (1) Mittel: „友人を通して知り合った." (2) ganzer Zeitraum/Bereich: „一年を通して雨が少ない."',tip:"〜を通じて ist etwas schriftlicher; in Bedeutung (2) beide gleichwertig.",ex:[["旅行を通して、多くのことを学んだ。","りょこうをとおして、おおくのことをまなんだ。","Durch die Reise habe ich viel gelernt."],["この島は一年を通じて暖かい。","このしまはいちねんをつうじてあたたかい。","Diese Insel ist das ganze Jahr über warm."],["代理店を通して契約を結んだ。","だいりてんをとおしてけいやくをむすんだ。","Über eine Agentur wurde der Vertrag geschlossen."]],q:[{q:"テレビ＿＿、世界の出来事を知る。",o:["を通して","につき","に反して","わりに"],c:0},{q:"「一年を通して」 heißt …",o:["das ganze Jahr hindurch","ein Jahr lang gerechnet ab jetzt","einmal im Jahr","im nächsten Jahr"],c:0},{q:"Vor を通して kann stehen …",o:["ein Mittel oder ein Zeitraum","nur ein Gefühl","nur eine Person","nur eine Zahl"],c:0}]},{id:"n3-wohajime",level:3,title:'〜をはじめ（として）— „angefangen mit … (und weitere)"',intro:"Nennt ein besonders typisches/wichtiges Beispiel stellvertretend für eine ganze Gruppe.",text:'Nomen + をはじめ（として）/ をはじめとする + Nomen. „日本語をはじめ、三つの言語が話せる." Danach folgt meist 〜など / weitere Beispiele.',tip:"Das erste Beispiel ist das prominenteste. Attributiv: 校長をはじめとする先生たち.",ex:[["この動物園には、パンダをはじめ珍しい動物が多い。","このどうぶつえんには、パンダをはじめめずらしいどうぶつがおおい。","In diesem Zoo gibt es viele seltene Tiere, allen voran Pandas."],["社長をはじめとして、全社員が式に出席した。","しゃちょうをはじめとして、ぜんしゃいんがしきにしゅっせきした。","Angeführt vom Chef nahmen alle Mitarbeiter an der Feier teil."],["東京をはじめ、多くの都市で人口が増えている。","とうきょうをはじめ、おおくのとしでじんこうがふえている。","Angefangen mit Tōkyō wächst in vielen Städten die Bevölkerung."]],q:[{q:"アジアでは、中国＿＿多くの国が参加した。",o:["をはじめ","につき","に反して","をこめて"],c:0},{q:"Das Nomen vor をはじめ ist …",o:["das prominenteste Beispiel der Gruppe","die Ausnahme","der Grund","der Zeitpunkt"],c:0},{q:"Die attributive Form lautet …",o:["〜をはじめとする","〜をはじめて","〜をはじめながら","〜をはじめるうちに"],c:0}]},{id:"n3-mai-maika",level:3,title:'〜まい・〜まいか — „wohl nicht / bestimmt nicht (tun)"',intro:'Verneinte Vermutung („wohl nicht") oder verneinter Vorsatz („ich werde bestimmt nicht").',text:'Verb Wörterbuchform + まい (五段); ます-Stamm + まい (一段/する→すまい・しまい, 来る→こまい). (1) Vermutung: „もう来るまい." (2) Vorsatz: „二度と行くまい." Frageform 〜まいか = „ob wohl nicht …".',tip:"Gehoben/literarisch. Alltagssprache: (1) 〜ないだろう, (2) 〜ないつもりだ / 二度と〜ない.",ex:[["こんな失敗は二度とするまいと心に誓った。","こんなしっぱいはにどとするまいとこころにちかった。","Ich schwor mir, so einen Fehler nie wieder zu machen."],["彼はもうこの町へは戻るまい。","かれはもうこのまちへはもどるまい。","Er wird wohl nicht mehr in diese Stadt zurückkehren."],["行こうか行くまいか、まだ迷っている。","いこうかいくまいか、まだまよっている。","Ob ich gehen soll oder nicht — ich bin noch unentschlossen."]],q:[{q:"二度とうそはつく＿＿と決めた。",o:["まい","べきだ","つもりだ","ものだ"],c:0},{q:"「もう雨は降るまい」 heißt …",o:["es wird wohl nicht mehr regnen","es regnet sicher","es soll nicht regnen","regnet es?"],c:0},{q:"〜まい gehört zu welchem Register?",o:["gehoben / literarisch","Babysprache","Jugendslang","Dialekt"],c:0}]},{id:"n3-ageku",level:3,title:'〜あげく（に）— „nach langem … schließlich (doch)"',intro:"Nach vielem Mühen/Zögern kommt am Ende ein (meist enttäuschendes) Ergebnis.",text:'Verb + た + あげく（に）/ Nomen + の + あげく. „さんざん迷ったあげく、何も買わなかった." Der erste Teil ist ein langer, mühsamer Prozess, das Ergebnis meist negativ oder unerwartet.',tip:"Ähnlich 〜末（すえ）に, aber 〜あげく klingt negativer. Für ein positives Ergebnis nimmt man 〜末に.",ex:[["長時間話し合ったあげく、結論は出なかった。","ちょうじかんはなしあったあげく、けつろんはでなかった。","Nach langer Diskussion kam am Ende keine Entscheidung heraus."],["あちこち探し回ったあげくに、あきらめた。","あちこちさがしまわったあげくに、あきらめた。","Nach langem Herumsuchen gab ich schließlich auf."],["迷ったあげく、行かないことにした。","まよったあげく、いかないことにした。","Nach langem Zögern beschloss ich, nicht zu gehen."]],q:[{q:"悩んだ＿＿、彼は会社を辞めた。",o:["あげく","うちに","とたん","かぎり"],c:0},{q:"Das Ergebnis nach 〜あげく ist meist …",o:["negativ / enttäuschend","sehr erfreulich","egal","nicht genannt"],c:0},{q:"Vor あげく steht das Verb in der Form …",o:["〜た","〜る","〜ない","〜て"],c:0}]},{id:"n3-kiri",level:3,title:'〜きり — „nur" und „seit … nicht mehr"',intro:"Grenzt streng ein oder markiert den letzten Zeitpunkt vor einer Lücke.",text:'(1) Nomen + きり = „nur": „二人きりで話した." (2) Verb + た + きり = „seit … (nichts mehr)": „朝、家を出たきり、連絡がない." Oft mit 〜ない im Nachsatz.',tip:"Umgangssprachlich auch 〜っきり. Bedeutung (2) impliziert immer eine ausbleibende Fortsetzung.",ex:[["祖母は一度会ったきり、それきりだ。","そぼはいちどあったきり、それきりだ。","Ich habe meine Großmutter nur einmal gesehen, danach nie wieder."],["寝たきりの祖父を家族で看ている。","ねたきりのそふをかぞくでみている。","Wir pflegen den bettlägerigen Großvater in der Familie."],["彼はさっき出かけたきり、まだ戻らない。","かれはさっきでかけたきり、まだもどらない。","Er ist vorhin gegangen und bis jetzt nicht zurück."]],q:[{q:"本を借りた＿＿、返すのを忘れていた。",o:["きり","あげく","うえに","につき"],c:0},{q:"「二人きり」 heißt …",o:["nur zu zweit","zweimal","seit zwei Tagen","beide nicht"],c:0},{q:"Nach 〜たきり folgt oft …",o:["eine Verneinung","ein Befehl","eine Frage","ein Wunsch"],c:0}]},{id:"n3-kurai-hodohanai",level:3,title:'〜くらい／〜ほど〜はない — „nichts ist so … wie" (Superlativ)',intro:"Hebt eine Sache als die äußerste ihrer Art hervor.",text:'Nomen + くらい / ほど + 〜（もの）はない. „故郷の料理くらいおいしいものはない." = „nichts schmeckt so gut wie". Auch 〜ほど〜ものはない.',tip:"Subjektive Wertung. Kein echter Vergleichsmaßstab nötig.",ex:[["家族を失うことほどつらいことはない。","かぞくをうしなうことほどつらいことはない。","Nichts ist so schwer, wie die Familie zu verlieren."],["彼くらい親切な人はいない。","かれくらいしんせつなひとはいない。","Es gibt niemanden, der so freundlich ist wie er."],["試験前の日曜日ほど落ち着かない日はない。","しけんまえのにちようびほどおちつかないひはない。","Kein Tag ist so unruhig wie der Sonntag vor der Prüfung."]],q:[{q:"健康＿＿大切なものはない。",o:["ほど","あげく","きり","につき"],c:0},{q:"Das Muster 〜ほど〜はない bedeutet …",o:["höchster Grad / Superlativ","kein Grad angebbar","ein Gegensatz","eine Bedingung"],c:0},{q:"Die Aussage ist …",o:["subjektiv wertend","streng messbar","eine Frage","ein Befehl"],c:0}]},{id:"n3-ge",level:3,title:'〜げ — „-aussehend, den Anschein von … erweckend"',intro:"Aus dem Aussehen/Verhalten schließt man auf ein Gefühl eines anderen.",text:'い-Adj (ohne い) / な-Adj (Stamm) + げ. „満足げな表情", „不安げに周りを見る", „言いたげな顔". Wirkt wie ein な-Adjektiv (〜げな / 〜げに).',tip:"Nur für sichtbare Anzeichen bei anderen. Nicht für eigene Gefühle. 楽しい→楽しげ, 寂しい→寂しげ.",ex:[["子どもは自慢げに絵を見せた。","こどもはじまんげにえをみせた。","Das Kind zeigte stolz sein Bild."],["彼女は何か言いたげな様子だった。","かのじょはなにかいいたげなようすだった。","Sie sah aus, als wollte sie etwas sagen."],["犬は不安げに主人を見上げた。","いぬはふあんげにしゅじんをみあげた。","Der Hund blickte unruhig zu seinem Herrn auf."]],q:[{q:"彼は自信あり＿＿に答えた。",o:["げ","がち","っぽい","ぎみ"],c:0},{q:"〜げ beschreibt …",o:["sichtbare Anzeichen eines Gefühls bei anderen","die eigene Meinung","eine Vermutung über die Zukunft","einen Grund"],c:0},{q:"「楽しい」 wird zu …",o:["楽しげ","楽しいげ","楽しさげ","楽しくげ"],c:0}]},{id:"n3-kotokara",level:3,title:'〜ことから — „daher / aus dem Umstand, dass"',intro:"Nennt den Anhaltspunkt, aus dem sich etwas ergibt oder benannt wurde.",text:'Nach Plainform / な-Adj + な・である / Nomen + である: 〜ことから. „窓が割れていることから、泥棒が入ったと分かった." Oft zur Herleitung von Schlüssen oder Namen.',tip:"Etwas sachlicher als 〜ので/から; betont den erkennbaren Grund, nicht die eigene Absicht.",ex:[["この地域は桜が多いことから、「桜町」と呼ばれている。","このちいきはさくらがおおいことから、「さくらまち」とよばれている。",'Weil es hier viele Kirschbäume gibt, heißt die Gegend „Sakura-machi".'],["足跡が残っていることから、犯人は男だと考えられる。","あしあとがのこっていることから、はんにんはおとこだとかんがえられる。","An den Fußspuren erkennt man, dass der Täter ein Mann war."],["小さなことから大きな争いに発展した。","ちいさなことからおおきなあらそいにはってんした。","Aus einer Kleinigkeit wurde ein großer Streit."]],q:[{q:"煙が出ている＿＿、火事だと気づいた。",o:["ことから","あげく","きり","ながらも"],c:0},{q:"〜ことから wird oft benutzt, um …",o:["einen Schluss oder eine Benennung herzuleiten","einen Befehl zu geben","einen Wunsch auszudrücken","eine Bedingung zu nennen"],c:0},{q:"な-Adjektiv vor ことから steht mit …",o:["な / である","く","に","nichts"],c:0}]},{id:"n3-kotoni",level:3,title:'〜ことに（は）— „zu meiner Überraschung/Freude/…"',intro:"Stellt die Bewertung des Sprechers voran, bevor der Sachverhalt kommt.",text:'Gefühls-Adjektiv/-Verb + ことに（は）+ Satz. „驚いたことに、彼は全部知っていた." Typisch: 驚いた, 残念な, うれしい, 困った, 幸運な, ありがたい.',tip:"Nur mit Gefühlsausdrücken. Der eigentliche Sachverhalt folgt danach als ganzer Satz.",ex:[["うれしいことに、旧友から連絡が来た。","うれしいことに、きゅうゆうかられんらくがきた。","Zu meiner Freude meldete sich ein alter Freund."],["残念なことに、その店はもう閉まっていた。","ざんねんなことに、そのみせはもうしまっていた。","Leider hatte der Laden schon zu."],["困ったことに、鍵が見つからない。","こまったことに、かぎがみつからない。","Dummerweise finde ich den Schlüssel nicht."]],q:[{q:"＿＿ことに、テストは思ったより簡単だった。",o:["ありがたい","その","この","そんな"],c:0},{q:"〜ことには steht am …",o:["Satzanfang, vor dem eigentlichen Sachverhalt","Satzende","in der Mitte des Nebensatzes","nach dem Verb"],c:0},{q:"Vor ことに passt NICHT …",o:["行く (neutrale Handlung)","驚いた","うれしい","残念な"],c:0}]},{id:"n3-panashi",level:3,title:'〜っぱなし — „gelassen / dauernd (ohne aufzuhören)"',intro:"Ein Zustand bleibt bestehen, weil man vergisst/versäumt, ihn zu beenden — oder etwas hört gar nicht auf.",text:'Verb ます-Stamm + っぱなし. (1) „窓を開けっぱなしにした." (vergessen zu schließen) (2) „朝から立ちっぱなしだ." (die ganze Zeit). Oft leicht vorwurfsvoll.',tip:"Bedeutung (1) meist mit einem transitiven Verb + にする / だ.",ex:[["電気をつけっぱなしで出かけてしまった。","でんきをつけっぱなしででかけてしまった。","Ich bin losgegangen und habe das Licht angelassen."],["一日中パソコンに向かいっぱなしで、目が疲れた。","いちにちじゅうパソコンにむかいっぱなしで、めがつかれた。","Den ganzen Tag am Rechner — die Augen sind müde."],["水を出しっぱなしにしないでください。","みずをだしっぱなしにしないでください。","Bitte lassen Sie das Wasser nicht laufen."]],q:[{q:"ドアを開け＿＿にすると、虫が入る。",o:["っぱなし","がち","かけ","ぎみ"],c:0},{q:"〜っぱなし klingt oft leicht …",o:["vorwurfsvoll","höflich","begeistert","sachlich-neutral"],c:0},{q:"Was steht vor っぱなし?",o:["ein Verb in ます-Form","ein Nomen","ein い-Adjektiv","ein ganzer Satz"],c:0}]},{id:"n3-tebakariiru-tebakari",level:3,title:'〜てばかりいる・〜てばかり — „dauernd nur … tun"',intro:"Kritisiert, dass jemand ständig dasselbe (Unerwünschte) tut und nichts anderes.",text:'Verb て-Form + ばかりいる / ばかりだ. „弟はゲームをしてばかりいる." Meist tadelnd. Vergleiche 〜てばかり (ähnlich) und 〜ばかり + Nomen (nur … ).',tip:"Für positive Dauerhandlungen unüblich. Dann eher 〜てばかり weglassen.",ex:[["泣いてばかりいないで、原因を考えよう。","ないてばかりいないで、げんいんをかんがえよう。","Hör auf, nur zu weinen, und überleg dir die Ursache."],["彼は文句を言ってばかりで、何もしない。","かれはもんくをいってばかりで、なにもしない。","Er meckert nur herum und tut nichts."],["最近、雨が降ってばかりだ。","さいきん、あめがふってばかりだ。","In letzter Zeit regnet es dauernd."]],q:[{q:"スマホを見＿＿いないで、勉強しなさい。",o:["てばかり","たとたん","るきり","たあげく"],c:0},{q:"〜てばかりいる drückt meist … aus.",o:["Kritik / Tadel","Lob","Neutralität","eine Bitte"],c:0},{q:"Was steht vor ばかりいる?",o:["ein Verb in て-Form","ein Nomen","ein Verb in た-Form","ein Adjektiv"],c:0}]},{id:"n3-nagara",level:3,title:'〜ながら（も）— „obwohl, trotz"',intro:"Zwei Gegensätze bestehen gleichzeitig — anders als das gleichlautende 〜ながら für Gleichzeitigkeit.",text:'Verb ます-Stamm / い-Adj / な-Adj (Stamm) / Nomen + ながら（も）. „狭いながらも、居心地のいい部屋だ." „知っていながら、教えてくれなかった."',tip:"Nur die konzessive Bedeutung braucht Kontext, der einen Widerspruch erkennen lässt; oft mit も verstärkt.",ex:[["残念ながら、今回は参加できません。","ざんねんながら、こんかいはさんかできません。","Leider kann ich diesmal nicht teilnehmen."],["彼は若いながらも、しっかりした考えを持っている。","かれはわかいながらも、しっかりしたかんがえをもっている。","Obwohl er jung ist, hat er feste Überzeugungen."],["悪いと知りながら、うそをついてしまった。","わるいとしりながら、うそをついてしまった。","Obwohl ich wusste, dass es falsch war, habe ich gelogen."]],q:[{q:"お金がない＿＿、旅行を続けた。",o:["ながらも","あげく","きり","につれて"],c:0},{q:"「知っていながら」 heißt hier …",o:["obwohl er/ich es wusste","während er/ich es lernt","weil er/ich es weiß","sobald er/ich es weiß"],c:0},{q:"Was steht vor ながらも (Verb)?",o:["der ます-Stamm","die て-Form","die た-Form","die ない-Form"],c:0}]},{id:"n3-niatate-niatari",level:3,title:'〜にあたって・〜にあたり — „anlässlich, bei (einem bedeutsamen Ereignis)"',intro:"Vor / bei einem besonderen Anlass wird etwas getan.",text:'Nomen / Verb Wörterbuchform + にあたって（は）/ にあたり. „開会にあたって、一言ごあいさつ申し上げます." Förmlich; für wichtige, einmalige Anlässe (Beginn, Umzug, Prüfung, Vertrag).',tip:"Nicht für alltägliche Gelegenheiten — dafür 〜とき / 〜際（さい）に.",ex:[["新年を迎えるにあたり、目標を立てた。","しんねんをむかえるにあたり、もくひょうをたてた。","Zum Jahreswechsel habe ich mir Ziele gesetzt."],["契約するにあたっては、内容をよく確認してください。","けいやくするにあたっては、ないようをよくかくにんしてください。","Bei Vertragsabschluss prüfen Sie bitte den Inhalt genau."],["開店にあたって、多くの方の協力を得た。","かいてんにあたって、おおくのかたのきょうりょくをえた。","Zur Eröffnung erhielten wir die Hilfe vieler Menschen."]],q:[{q:"留学する＿＿、両親に相談した。",o:["にあたって","にすぎず","どころか","ながらも"],c:0},{q:"〜にあたって passt zu Anlässen wie …",o:["Beginn / Umzug / Vertrag","Zähneputzen","Bushaltestelle","Mittagessen"],c:0},{q:"Für alltägliche Gelegenheiten nimmt man eher …",o:["〜際に / 〜とき","〜にあたり","〜にあたっては","〜をもって"],c:0}]},{id:"n3-ni-jite",level:3,title:'〜に応じて（〜に応じた）— „je nach, entsprechend"',intro:"Etwas wird an eine variable Größe angepasst.",text:'Nomen + に応じて / に応じた + Nomen. „収入に応じて、税金が決まる." Typische Bezüge: 状況, 能力, 希望, 予算, 場合, 変化.',tip:"Ähnlich 〜によって (je nach), aber 〜に応じて betont die aktive Anpassung an etwas Wechselndes.",ex:[["お客様のご希望に応じて、プランをご用意します。","おきゃくさまのごきぼうにおうじて、プランをごよういします。","Je nach Kundenwunsch stellen wir einen Plan zusammen."],["体力に応じた運動をするといい。","たいりょくにおうじたうんどうをするといい。","Man sollte je nach Kondition trainieren."],["状況に応じて、対応を変える必要がある。","じょうきょうにおうじて、たいおうをかえるひつようがある。","Je nach Lage muss man die Reaktion anpassen."]],q:[{q:"成績＿＿、クラスを分ける。",o:["に応じて","に反して","にあたって","をはじめ"],c:0},{q:"〜に応じて betont …",o:["die Anpassung an etwas Wechselndes","einen Gegensatz","einen Grund","eine Reihenfolge"],c:0},{q:"Die attributive Form lautet …",o:["〜に応じた","〜に応じて","〜に応じつつ","〜に応じるうちに"],c:0}]},{id:"n3-nikaketeha",level:3,title:'〜にかけては — „was … angeht, ist … Spitze"',intro:"In einem bestimmten Bereich ist jemand besonders gut — immer positiv.",text:'Nomen + にかけては + „niemand ist besser / ist top". „記憶力にかけては、彼にかなう者はいない."',tip:"Nur für Können/Stärken, nie für Schwächen. Der Nachsatz ist immer eine Bestleistung.",ex:[["料理の速さにかけては、母が一番だ。","りょうりのはやさにかけては、ははがいちばんだ。","Was Kochgeschwindigkeit angeht, ist meine Mutter unschlagbar."],["数字に強いことにかけては、彼女に任せて大丈夫だ。","すうじにつよいことにかけては、かのじょにまかせてだいじょうぶだ。","Was das Rechnen betrifft, kann man sich ganz auf sie verlassen."],["歌にかけては、クラスで彼の右に出る者はいない。","うたにかけては、クラスでかれのみぎにでるものはいない。","Im Singen macht ihm in der Klasse keiner etwas vor."]],q:[{q:"走る速さ＿＿、彼はチームで一番だ。",o:["にかけては","に反して","にあたって","どころか"],c:0},{q:"Der Nachsatz von 〜にかけては ist immer …",o:["eine Bestleistung / Stärke","eine Schwäche","eine Frage","ein Zweifel"],c:0},{q:"〜にかけては verwendet man für …",o:["Können und Fähigkeiten","Krankheiten","Uhrzeiten","Preise"],c:0}]},{id:"n3-ni-wate-ni-wari",level:3,title:'〜に代わって・〜に代わり — „anstelle von, stellvertretend für"',intro:"Jemand/etwas übernimmt die Rolle eines anderen.",text:'Nomen + に代わって / に代わり. „社長に代わって、部長があいさつした." Auch „an die Stelle von etwas Altem tritt Neues": „馬車に代わって、車が使われるようになった."',tip:'Unterschied zu 〜のかわりに (auch „als Ausgleich / im Tausch"): 〜に代わって betont die Vertretung/Ablösung.',ex:[["入院した父に代わって、私が店を開けた。","にゅういんしたちちにかわって、わたしがみせをあけた。","Anstelle meines Vaters im Krankenhaus habe ich den Laden aufgemacht."],["手紙に代わって、メールが主流になった。","てがみにかわって、メールがしゅりゅうになった。","An die Stelle des Briefs ist die E-Mail getreten."],["司会者に代わり、私が進行を務めます。","しかいしゃにかわり、わたしがしんこうをつとめます。","Anstelle des Moderators führe ich durch das Programm."]],q:[{q:"欠席した委員長＿＿、副委員長が報告した。",o:["に代わって","に応じて","にかけては","ながらも"],c:0},{q:"〜に代わって betont …",o:["Vertretung / Ablösung","einen Gegensatz","einen Zeitpunkt","einen Grund"],c:0},{q:"「馬に代わって車」 heißt …",o:["das Auto ersetzt das Pferd","Auto und Pferd zusammen","ein Auto für ein Pferd tauschen","weder Auto noch Pferd"],c:0}]},{id:"n3-mobamo",level:3,title:'〜も〜ば〜も — „sowohl … als auch / mal … mal" (aufzählend)',intro:"Zählt gleichartige Punkte auf, die zusammen ein Gesamtbild ergeben.",text:'Nomen + も + Verb/Adj ば-Form + Nomen + も …. „彼は歌も歌えば、踊りも踊る." Bei Adjektiven: „給料も安ければ、休みも少ない."',tip:"Bei Eigenschaften ziehen beide Glieder in dieselbe Richtung (beide gut oder beide schlecht); bei Personen oder Fällen können sie auch Gegensätze aufzählen (合格する人もいれば、落ちる人もいる). Reine Aufzählung, keine echte Bedingung.",ex:[["あの店はサービスもよければ、値段も手頃だ。","あのみせはサービスもよければ、ねだんもてごろだ。","Der Laden hat guten Service und ist obendrein preiswert."],["試験には合格する人もいれば、落ちる人もいる。","しけんにはごうかくするひともいれば、おちるひともいる。","Bei der Prüfung gibt es Leute, die bestehen, und solche, die durchfallen."],["この仕事は責任も重ければ、時間も長い。","このしごとはせきにんもおもければ、じかんもながい。","Diese Arbeit ist verantwortungsvoll und zudem zeitraubend."]],q:[{q:"彼女は英語も話せ＿＿、中国語も話せる。",o:["れば","たら","ても","ながら"],c:0},{q:"Bei Eigenschaften einer Sache (サービスもよければ、値段も手頃だ) sind die beiden Glieder von 〜も〜ば〜も …",o:["weisen in dieselbe Richtung","widersprechen sich","sind Ursache und Wirkung","sind zeitlich versetzt"],c:0},{q:"Das Muster ist im Kern eine …",o:["Aufzählung","echte Bedingung","Frage","Vermutung"],c:0}]},{id:"n3-monono",level:3,title:'〜ものの — „obwohl, zwar …, aber"',intro:"Räumt etwas ein, doch die erwartete Folge bleibt aus.",text:'Nach Plainform / い-Adj / な-Adj + な・である / Nomen + である: 〜ものの. „買ったものの、一度も使っていない." Schriftsprachlich; der Widerspruch ist meist eine enttäuschte Erwartung.',tip:"Der zweite Teil ist kein Befehl/Bitte. Umgangssprachlich: 〜けど / 〜のに.",ex:[["返事はしたものの、行くかどうかまだ決めていない。","へんじはしたものの、いくかどうかまだきめていない。","Ich habe zwar geantwortet, aber noch nicht entschieden, ob ich hingehe."],["体にいいとは言うものの、毎日は続けられない。","からだにいいとはいうものの、まいにちはつづけられない。","Es soll ja gesund sein, aber täglich schaffe ich es nicht."],["大学は出たものの、就職先が見つからない。","だいがくはでたものの、しゅうしょくさきがみつからない。","Ich habe zwar die Uni abgeschlossen, finde aber keine Stelle."]],q:[{q:"練習はした＿＿、本番では緊張してしまった。",o:["ものの","ものだから","あげく","にあたって"],c:0},{q:"〜ものの ist im Ton eher …",o:["schriftsprachlich","salopp","kindlich","dialektal"],c:0},{q:"Nicht möglich nach 〜ものの:",o:["ein Befehl","ein Adjektiv","ein Verb","ein Nomen + である"],c:0}]},{id:"n3-osoregaaru",level:3,title:'〜おそれがある — „es besteht die Gefahr, dass"',intro:"Warnt vor einer möglichen negativen Entwicklung.",text:'Verb Wörterbuchform / Nomen + の + おそれがある. „大雨で川が氾濫するおそれがある." Schriftsprachlich, typisch in Nachrichten und Behördentexten. Nur für Unerwünschtes.',tip:"Für positive Möglichkeiten unpassend — dann 〜可能性がある. 〜おそれがある ist immer eine Warnung.",ex:[["台風が上陸するおそれがあります。","たいふうがじょうりくするおそれがあります。","Es besteht die Gefahr, dass der Taifun auf Land trifft."],["この薬は眠気を起こすおそれがある。","このくすりはねむけをおこすおそれがある。","Dieses Medikament kann Müdigkeit verursachen."],["対応が遅れると、被害が広がるおそれがある。","たいおうがおくれると、ひがいがひろがるおそれがある。","Wenn die Reaktion zu spät kommt, droht sich der Schaden auszuweiten."]],q:[{q:"橋が壊れる＿＿があるので、通行止めだ。",o:["おそれ","つもり","ばかり","ところ"],c:0},{q:"〜おそれがある verwendet man für …",o:["drohende negative Folgen","erfreuliche Aussichten","sichere Tatsachen","Bitten"],c:0},{q:"Der Ton von 〜おそれがある ist …",o:["schriftsprachlich / nachrichtlich","salopp","kindlich","dialektal"],c:0}]},{id:"n3-kata",level:3,title:'〜一方（で）— „einerseits … andererseits / während"',intro:"Stellt zwei Seiten desselben Themas oder zwei gegenläufige Entwicklungen nebeneinander.",text:'Plainform + 一方（で）. „都市の人口が増える一方で、地方は減っている." Auch: „仕事に厳しい一方、部下思いだ." (zwei Seiten einer Person).',tip:'Rein aufzählend und kontrastierend, ohne Vorwurf — anders als 〜くせに. Verwechslungsgefahr mit 〜一方だ („nimmt immer weiter zu"), das eine einseitige Steigerung meint.',ex:[["輸出が伸びる一方で、輸入は落ち込んでいる。","ゆしゅつがのびるいっぽうで、ゆにゅうはおちこんでいる。","Während die Exporte wachsen, gehen die Importe zurück."],["彼は無口な一方、いざという時は頼りになる。","かれはむくちないっぽう、いざというときはたよりになる。","Er ist einerseits wortkarg, andererseits in kritischen Momenten verlässlich."],["便利になる一方で、失われるものもある。","べんりになるいっぽうで、うしなわれるものもある。","Es wird bequemer, doch zugleich geht auch etwas verloren."]],q:[{q:"給料は上がらない＿＿、物価は上がり続ける。",o:["一方で","あげく","かぎり","につき"],c:0},{q:"〜一方で verbindet …",o:["zwei gegenläufige Seiten","Ursache und Wirkung","zwei Zeitpunkte","Bedingung und Folge"],c:0},{q:"「〜一方だ」 (ohne で) heißt dagegen …",o:["nimmt einseitig immer weiter zu","einerseits … andererseits","nur ein einziges Mal","genau in dem Moment"],c:0}]},{id:"n3-kanoyouda",level:3,title:'〜かのようだ — „als ob (in Wirklichkeit aber nicht)"',intro:"Vergleicht mit etwas, das faktisch nicht zutrifft — ein bildhafter Als-ob-Vergleich.",text:'Plainform + かのようだ / かのように / かのような. „彼は何も知らなかったかのように話した." Schriftsprachlich; die Realität ist anders als der Vergleich behauptet.',tip:"Umgangssprachlich meist 〜みたいだ / 〜ようだ. 〜かのようだ betont ausdrücklich, dass es nur so wirkt.",ex:[["まるで夢を見ているかのようだった。","まるでゆめをみているかのようだった。","Es war, als würde ich träumen."],["彼女は初めて聞いたかのような顔をした。","かのじょははじめてきいたかのようなかおをした。","Sie machte ein Gesicht, als hörte sie es zum ersten Mal."],["彼は何事もなかったかのように仕事を続けた。","かれはなにごともなかったかのようにしごとをつづけた。","Er arbeitete weiter, als wäre nichts geschehen."]],q:[{q:"氷の上に立っているかの＿＿、足がすくんだ。",o:["ように","せいで","とおりに","うちに"],c:0},{q:"〜かのようだ sagt aus, dass der Vergleich …",o:["in Wirklichkeit nicht zutrifft","sicher zutrifft","eine Frage ist","ein Befehl ist"],c:0},{q:"Der Stil ist eher …",o:["schriftsprachlich","salopp","kindlich","befehlend"],c:0}]},{id:"n3-kurainara",level:3,title:'〜くらいなら — „wenn schon …, dann lieber"',intro:"Von zwei unangenehmen Möglichkeiten wählt man die weniger schlimme.",text:'Verb Wörterbuchform + くらいなら + „(dann lieber) …のほうがましだ / …ほうがいい". „満員電車に乗るくらいなら、歩いて行く."',tip:'Der erste Teil ist die abgelehnte, schlechtere Option. Oft mit ましだ („noch erträglicher") im Nachsatz.',ex:[["途中でやめるくらいなら、最初から始めないほうがいい。","とちゅうでやめるくらいなら、さいしょからはじめないほうがいい。","Wenn man mittendrin aufhört, fängt man besser gar nicht erst an."],["人に頼むくらいなら、自分でやったほうが早い。","ひとにたのむくらいなら、じぶんでやったほうがはやい。","Bevor ich jemanden bitte, mache ich es lieber selbst — das geht schneller."],["謝るくらいなら、初めからしなければいい。","あやまるくらいなら、はじめからしなければいい。","Wenn man sich hinterher entschuldigen muss, lässt man es besser gleich bleiben."]],q:[{q:"行列に並ぶ＿＿、別の店にする。",o:["くらいなら","とたんに","かのように","にあたって"],c:0},{q:"Der Teil vor くらいなら ist …",o:["die abgelehnte, schlechtere Option","die bevorzugte Option","ein Grund","eine Bedingung ohne Wertung"],c:0},{q:"Im Nachsatz steht oft …",o:["〜ほうがましだ / 〜ほうがいい","〜てはいけない","〜たことがある","〜ながら"],c:0}]},{id:"n3-naiuchini",level:3,title:'〜ないうちに — „bevor (etwas Unerwünschtes eintritt), solange noch nicht"',intro:"Man handelt, solange ein Zustand noch andauert und bevor er sich ändert.",text:'Verb ない-Form + うちに. „暗くならないうちに帰ろう." Auch mit い-Adj: „熱いうちに食べてください." (dann ohne ない). Betont: den Moment nutzen, bevor es zu spät ist.',tip:'Unterschied zu 〜前に: 〜ないうちに hat den Beiklang „schnell, solange die Gelegenheit da ist"; 〜前に ist rein zeitlich.',ex:[["雨が降らないうちに洗濯物を取り込んだ。","あめがふらないうちにせんたくものをとりこんだ。","Ich habe die Wäsche hereingeholt, bevor es regnete."],["忘れないうちにメモしておこう。","わすれないうちにメモしておこう。","Ich notiere es mir, bevor ich es vergesse."],["子どもが起きないうちに準備を済ませる。","こどもがおきないうちにじゅんびをすませる。","Ich erledige die Vorbereitungen, solange die Kinder noch schlafen."]],q:[{q:"冷め＿＿うちに、どうぞ召し上がってください。",o:["ない","た","て","る"],c:0},{q:"〜ないうちに betont …",o:["den Moment nutzen, bevor es zu spät ist","einen weit entfernten Zeitpunkt","eine Wiederholung","einen Grund"],c:0},{q:"Mit einem い-Adjektiv wie 熱い sagt man …",o:["熱いうちに","熱くないうちに","熱いないうちに","熱さうちに"],c:0}]},{id:"n3-nioite-niokeru",level:3,title:'〜において・〜における — „in / bei / auf (Ort, Bereich, Zeit — förmlich)"',intro:"Nennt förmlich den Schauplatz oder das Feld eines Geschehens.",text:'Nomen + において（は）(adverbial) / における + Nomen (attributiv). „会議は本館において行われる." „教育における課題を考える." Ersetzt in gehobenem Stil ein einfaches で.',tip:"Rein schriftsprachlich / offiziell. Im Alltag sagt man で.",ex:[["オリンピックは東京において開催された。","オリンピックはとうきょうにおいてかいさいされた。","Die Olympischen Spiele wurden in Tokio ausgetragen."],["現代社会における家族の役割は変わりつつある。","げんだいしゃかいにおけるかぞくのやくわりはかわりつつある。","Die Rolle der Familie in der modernen Gesellschaft wandelt sich."],["この分野において彼は第一人者だ。","このぶんやにおいてかれはだいいちにんしゃだ。","Auf diesem Gebiet ist er führend."]],q:[{q:"研究＿＿倫理はとても重要だ。",o:["における","のうちに","のおそれ","かのよう"],c:0},{q:"Die attributive Form (vor einem Nomen) ist …",o:["〜における","〜において","〜においては","〜において行う"],c:0},{q:"Im Alltag ersetzt man 〜において meist durch …",o:["で","に","を","と"],c:0}]},{id:"n3-nikakawarazu-nimokakawarazu",level:3,title:'〜にかかわらず・〜にもかかわらず — „unabhängig von" und „trotzdem"',intro:"Zwei verwandte Muster: (1) etwas gilt gleichermaßen; (2) etwas geschieht entgegen der Erwartung.",text:'(1) Nomen / 〜か〜ないか + にかかわらず = „ungeachtet": „天候にかかわらず、試合は行う." (2) Plainform / Nomen + にもかかわらず = „obwohl / trotzdem": „努力したにもかかわらず、失敗した."',tip:'にもかかわらず (mit も) ist konzessiv („trotz"); にかかわらず (ohne も) heißt „ganz gleich ob". Nicht verwechseln.',ex:[["年齢や経験にかかわらず、応募できます。","ねんれいやけいけんにかかわらず、おうぼできます。","Unabhängig von Alter und Erfahrung kann man sich bewerben."],["雨にもかかわらず、大勢の人が集まった。","あめにもかかわらず、おおぜいのひとがあつまった。","Trotz des Regens kamen viele Menschen zusammen."],["参加するかしないかにかかわらず、返事はください。","さんかするかしないかにかかわらず、へんじはください。","Ob Sie teilnehmen oder nicht — geben Sie bitte Bescheid."]],q:[{q:"危険だと言われた＿＿、彼は山に登った。",o:["にもかかわらず","にかかわらず","において","かのように"],c:0},{q:'„ganz gleich, ob ja oder nein" heißt …',o:["〜にかかわらず","〜にもかかわらず","〜のうちに","〜くらいなら"],c:0},{q:"〜にもかかわらず ist in der Bedeutung …",o:['konzessiv („trotz")','kausal („weil")','temporal („wenn")','final („um zu")'],c:0}]},{id:"n3-ni-bete-ni-be",level:3,title:'〜に比べて・〜に比べ — „im Vergleich zu, verglichen mit"',intro:"Setzt zwei Größen in Beziehung, um einen Unterschied deutlich zu machen.",text:'Nomen + に比べて（は）/ に比べ. „去年に比べて、今年は雪が多い." Attributiv: „例年に比べた降水量".',tip:"Ähnlich 〜より, aber 〜に比べて eignet sich besser für ganze Zeiträume, Gruppen oder Statistiken.",ex:[["都会に比べて、田舎は家賃が安い。","とかいにくらべて、いなかはやちんがやすい。","Verglichen mit der Stadt ist die Miete auf dem Land billig."],["先月に比べ、売り上げが二割増えた。","せんげつにくらべ、うりあげがにわりふえた。","Gegenüber dem Vormonat stieg der Umsatz um 20 %."],["以前に比べて、体力が落ちた気がする。","いぜんにくらべて、たいりょくがおちたきがする。","Verglichen mit früher fühle ich mich weniger fit."]],q:[{q:"兄＿＿、弟のほうが背が高い。",o:["に比べて","において","にかかわらず","のうちに"],c:0},{q:"〜に比べて eignet sich besonders für …",o:["Zeiträume, Gruppen, Statistiken","einzelne Personen im Gespräch","Befehle","Wünsche"],c:0},{q:"Vor 比べて steht …",o:["ein Nomen + に","ein Verb in て-Form","ein い-Adjektiv","ein ganzer Satz mit と"],c:0}]},{id:"n3-ni-zuite-ni-zuku",level:3,title:'〜に基づいて・〜に基づく — „auf Grundlage von, gestützt auf"',intro:"Etwas wird aus einer festen Quelle (Daten, Regel, Erfahrung) abgeleitet.",text:'Nomen + に基づいて / に基づき (adverbial) / に基づいた・に基づく + Nomen (attributiv). „事実に基づいて報道する." Typische Quellen: データ, 法律, 経験, 契約, アンケート.',tip:'Betont, dass nichts frei erfunden ist. Nicht für lockere Anlässe — dafür 〜をもとに (etwas freier: „ausgehend von").',ex:[["アンケート結果に基づいて、商品を改良した。","アンケートけっかにもとづいて、しょうひんをかいりょうした。","Auf Basis der Umfrageergebnisse wurde das Produkt verbessert."],["この物語は実話に基づいている。","このものがたりはじつわにもとづいている。","Diese Geschichte beruht auf einer wahren Begebenheit."],["規則に基づき、公平に処理します。","きそくにもとづき、こうへいにしょりします。","Wir bearbeiten es regelkonform und fair."]],q:[{q:"専門家の意見＿＿、計画を見直した。",o:["に基づいて","にかかわらず","かのように","くらいなら"],c:0},{q:"〜に基づいて betont, dass die Aussage …",o:["auf einer festen Quelle beruht","frei erfunden ist","unsicher ist","ein Wunsch ist"],c:0},{q:"Die attributive Form ist z. B. …",o:["事実に基づいた話","事実に基づいてに話","事実に基づくて話","事実基づき話"],c:0}]},{id:"n3-ki-ke",level:3,title:'〜向き・〜向け — „geeignet für" und „bestimmt für"',intro:'Zwei ähnliche Suffixe: 〜向き = „passt von der Art her zu", 〜向け = „ist gezielt für … gemacht".',text:'Nomen + 向き（の・に）/ 向け（の・に）. „初心者向きの本" (von Natur aus für Anfänger passend). „子ども向けの番組" (bewusst für Kinder produziert). „輸出向けに生産する".',tip:"〜向き kann auch Richtung/Ausrichtung heißen (南向きの部屋 = nach Süden). 〜向け ist immer die bewusste Zielgruppe.",ex:[["この道具は素人向きではない。","このどうぐはしろうとむきではない。","Dieses Werkzeug ist nichts für Laien."],["海外向けに説明書を英語で作った。","かいがいむけにせつめいしょをえいごでつくった。","Für das Ausland haben wir die Anleitung auf Englisch erstellt."],["南向きの部屋は日当たりがいい。","みなみむきのへやはひあたりがいい。","Ein nach Süden ausgerichtetes Zimmer bekommt viel Sonne."]],q:[{q:"若者＿＿の雑誌がよく売れている。",o:["向け","おそれ","かのよう","うちに"],c:0},{q:'„von Natur aus passend für" heißt …',o:["〜向き","〜向け","〜において","〜に基づく"],c:0},{q:"「南向きの部屋」 bedeutet …",o:["nach Süden ausgerichtetes Zimmer","Zimmer für Südländer","südlich gelegenes Land","Zimmer mit Südwind"],c:0}]},{id:"n3-te",level:3,title:'〜て以来 — „seit(dem) …"',intro:"Ein Ereignis ist der Ausgangspunkt; seither gilt ein dauerhafter Zustand.",text:'Verb て-Form + 以来. „日本に来て以来、毎日日本語を使っている." Auch Nomen + 以来: „卒業以来、会っていない." Der Zeitraum reicht bis in die Gegenwart.',tip:'Für kurze, punktuelle Zeitspannen unüblich (nicht „さっき来て以来"). Es geht um einen langen Bogen bis heute.',ex:[["引っ越して以来、一度も実家に帰っていない。","ひっこしていらい、いちどもじっかにかえっていない。","Seit dem Umzug war ich kein einziges Mal bei meinen Eltern."],["あの事故以来、彼は運転をやめた。","あのじこいらい、かれはうんてんをやめた。","Seit jenem Unfall fährt er nicht mehr Auto."],["入社して以来、遅刻したことがない。","にゅうしゃしていらい、ちこくしたことがない。","Seit meinem Eintritt in die Firma bin ich nie zu spät gekommen."]],q:[{q:"手術をし＿＿以来、走れなくなった。",o:["て","た","る","ない"],c:0},{q:"〜て以来 beschreibt einen Zeitraum, der …",o:["bis in die Gegenwart reicht","nur wenige Minuten dauert","in der Zukunft liegt","sich täglich wiederholt"],c:0},{q:"Mit einem Nomen sagt man …",o:["卒業以来","卒業て以来","卒業に以来","卒業の以来に"],c:0}]},{id:"n3-gatai",level:3,title:'〜がたい — „schwer / kaum möglich zu …"',intro:"Etwas ist gefühlsmäßig oder grundsätzlich schwer zu tun — nicht wegen fehlender Technik.",text:'Verb ます-Stamm + がたい. „信じがたい話", „忘れがたい思い出", „理解しがたい行動". Schriftsprachlich; oft mit 信じる, 理解する, 想像する, 忘れる, 認める.',tip:"Unterschied zu 〜にくい: 〜にくい = praktisch/physisch schwer (歩きにくい靴); 〜がたい = innerlich/prinzipiell schwer (許しがたい).",ex:[["彼の態度は許しがたいものだった。","かれのたいどはゆるしがたいものだった。","Sein Verhalten war kaum zu verzeihen."],["そんな偶然は想像しがたい。","そんなぐうぜんはそうぞうしがたい。","So ein Zufall ist kaum vorstellbar."],["忘れがたい一年になった。","わすれがたいいちねんになった。","Es wurde ein unvergessliches Jahr."]],q:[{q:"その結果は受け入れ＿＿。",o:["がたい","っぽい","ぎみだ","がちだ"],c:0},{q:"Der Unterschied zu 〜にくい: 〜がたい meint …",o:["innerlich / prinzipiell schwer","physisch unhandlich","zeitlich knapp","zu teuer"],c:0},{q:"Vor がたい steht …",o:["der ます-Stamm eines Verbs","ein Nomen","die て-Form","ein い-Adjektiv"],c:0}]},{id:"n3-nuku",level:3,title:'〜ぬく — „bis zum Ende durchhalten, ganz und gar tun"',intro:"Betont, dass eine Handlung trotz Mühe vollständig zu Ende geführt wird.",text:'Verb ます-Stamm + ぬく. „最後まで走りぬいた.", „考えぬいた末の決断だ." Der Prozess ist anstrengend, das Durchhalten die Leistung.',tip:'Nah an 〜きる („vollständig"), aber 〜ぬく hebt das Überwinden von Widerständen hervor. Nicht für Unerwünschtes (nicht „失敗しぬく").',ex:[["苦しかったが、マラソンを走りぬいた。","くるしかったが、マラソンをはしりぬいた。","Es war hart, aber ich habe den Marathon durchgehalten."],["彼女は困難な状況を生きぬいた。","かのじょはこんなんなじょうきょうをいきぬいた。","Sie hat die schwierige Lage durchgestanden."],["考えぬいた結果、留学を決めた。","かんがえぬいたけっか、りゅうがくをきめた。","Nach reiflichem Überlegen entschied ich mich fürs Auslandsstudium."]],q:[{q:"どんなに大変でも、最後までやり＿＿つもりだ。",o:["ぬく","かける","きれない","がたい"],c:0},{q:"〜ぬく hebt hervor, dass man …",o:["Widerstände überwindet und durchhält","kurz etwas anfängt","etwas versehentlich tut","etwas nur beinahe schafft"],c:0},{q:"Nicht möglich ist …",o:["失敗しぬく","守りぬく","戦いぬく","耐えぬく"],c:0}]},{id:"n3-mononara",level:3,title:'〜ものなら — „wenn es (denn) möglich wäre …"',intro:"Drückt einen kaum erfüllbaren Wunsch oder eine gewagte Herausforderung aus.",text:'Verb Potenzialform + ものなら + „(dann) würde ich gern …": „会えるものなら、もう一度会いたい." Als Drohung/Herausforderung mit Befehls-/Volitionalform: „できるものならやってみろ."',tip:'Nicht mit der normalen ば/たら-Bedingung verwechseln — 〜ものなら hat immer den Beiklang „aber es geht wohl kaum".',ex:[["戻れるものなら、あの頃に戻りたい。","もどれるものなら、あのころにもどりたい。","Wenn ich es könnte, würde ich in jene Zeit zurückkehren."],["代わってあげられるものなら、代わってあげたい。","かわってあげられるものなら、かわってあげたい。","Wenn ich könnte, würde ich es für dich übernehmen."],["文句があるなら、言えるものなら言ってみろ。","もんくがあるなら、いえるものならいってみろ。","Wenn du etwas zu meckern hast, dann sag es doch — falls du dich traust."]],q:[{q:"やり直せる＿＿、初めからやり直したい。",o:["ものなら","ものの","ものだから","もので"],c:0},{q:"Vor ものなら (Wunsch) steht das Verb in der …",o:["Potenzialform","た-Form","て-Form","ない-Form"],c:0},{q:"Der Beiklang von 〜ものなら ist …",o:['„aber es geht wohl kaum"','„es ist sicher so"','„es ist verboten"','„es ist Pflicht"'],c:0}]},{id:"n3-tedemo",level:3,title:'〜てでも — „sogar um den Preis von, notfalls unter …"',intro:"Man ist bereit, ein extremes Mittel einzusetzen, um ein Ziel zu erreichen.",text:'Verb て-Form + でも + „(will/muss ich) …": „借金してでも、留学したい." Das Mittel im ersten Teil ist ungewöhnlich hart; der Wille im zweiten Teil ist stark.',tip:"Der Nachsatz ist ein starker Wunsch oder Entschluss (〜たい / 〜つもりだ / 〜なければならない), kein neutraler Bericht.",ex:[["徹夜してでも、締め切りに間に合わせる。","てつやしてでも、しめきりにまにあわせる。","Und wenn ich die Nacht durchmache — ich schaffe die Frist."],["何を犠牲にしてでも、家族を守る。","なにをぎせいにしてでも、かぞくをまもる。","Ich beschütze meine Familie, koste es, was es wolle."],["タクシーを使ってでも、始発に乗りたい。","タクシーをつかってでも、しはつにのりたい。","Zur Not nehme ich ein Taxi — ich will den ersten Zug erwischen."]],q:[{q:"無理をし＿＿、約束は守るつもりだ。",o:["てでも","たきり","たとたん","たあげく"],c:0},{q:"Der Teil vor 〜てでも nennt …",o:["ein hartes, ungewöhnliches Mittel","einen leichten Weg","einen Zeitpunkt","einen Grund zur Absage"],c:0},{q:"Im Nachsatz steht meist …",o:["ein starker Wunsch / Entschluss","eine sachliche Beschreibung","eine Frage","eine Vermutung"],c:0}]},{id:"n3-toshitara-tosureba-tosuruto",level:3,title:'〜としたら・〜とすれば・〜とすると — „angenommen, dass / wenn man annimmt"',intro:"Führt eine hypothetische Annahme ein, aus der der Sprecher etwas folgert.",text:'Plainform + としたら / とすれば / とすると. „明日雨だとしたら、遠足は中止だ." Der Nachsatz ist eine logische Folge der Annahme, oft mit どう / いくら / 何を.',tip:'Nah an 〜なら, aber betont ausdrücklich „mal angenommen". 〜とすれば klingt am sachlichsten, 〜としたら etwas gesprächiger.',ex:[["この話が本当だとしたら、大変なことだ。","このはなしがほんとうだとしたら、たいへんなことだ。","Wenn das stimmen sollte, wäre das eine ernste Sache."],["全部買うとすれば、いくらになりますか。","ぜんぶかうとすれば、いくらになりますか。","Angenommen, ich kaufe alles — wie viel wäre das?"],["彼が来ないとすると、予定を変えるしかない。","かれがこないとすると、よていをかえるしかない。","Sollte er nicht kommen, müssen wir den Plan ändern."]],q:[{q:"今から出発する＿＿、到着は夜になる。",o:["としたら","あげく","かのように","に基づいて"],c:0},{q:"Der Nachsatz von 〜としたら ist …",o:["eine Folgerung aus der Annahme","ein Befehl","ein Gefühlsausdruck ohne Bezug","ein Grund"],c:0},{q:"Am sachlichsten klingt …",o:["〜とすれば","〜としたら","〜としたって","〜とかいって"],c:0}]},{id:"n3-toshitemo",level:3,title:'〜としても — „selbst wenn (angenommen)"',intro:"Auch unter einer angenommenen Bedingung ändert sich das Ergebnis nicht.",text:'Plainform + としても. „たとえ高いとしても、必要なら買う." Oft mit たとえ / 仮に. Hypothetisch — anders als 〜ても, das auch Reales meinen kann.',tip:"Für eine reale, schon eingetretene Einräumung nimmt man 〜ても / 〜のに. 〜としても bleibt im Konjunktiv.",ex:[["失敗するとしても、挑戦する価値はある。","しっぱいするとしても、ちょうせんするかちはある。","Selbst wenn es scheitert — der Versuch lohnt sich."],["仮に彼が正しいとしても、言い方が悪い。","かりにかれがただしいとしても、いいかたがわるい。","Angenommen, er hätte recht — der Ton stimmt trotzdem nicht."],["安いとしても、質が悪ければ意味がない。","やすいとしても、しつがわるければいみがない。","Auch wenn es billig wäre — bei schlechter Qualität bringt es nichts."]],q:[{q:"たとえ雨が降る＿＿、試合は行われる。",o:["としても","としたら","に比べて","において"],c:0},{q:"〜としても ist im Charakter …",o:["hypothetisch / im Konjunktiv","ein Bericht über Reales","eine Frage","ein Wunsch"],c:0},{q:"Oft steht davor ein Signalwort wie …",o:["たとえ / 仮に","もう / まだ","ぜひ / きっと","まるで / いかにも"],c:0}]},{id:"n3-nishironishiro-niseyoniseyo",level:3,title:'〜にしろ〜にしろ・〜にせよ〜にせよ — „ob … oder …, in jedem Fall"',intro:"Zählt Möglichkeiten auf, die alle zum selben Schluss führen.",text:'Nomen / Plainform + にしろ（にせよ）… + にしろ（にせよ）. „行くにしろ行かないにしろ、連絡はして." Auch einzeln: „どちらにせよ、結論は同じだ."',tip:"〜にせよ ist etwas schriftlicher als 〜にしろ. Der Nachsatz gilt für alle genannten Fälle gleichermaßen.",ex:[["賛成にしろ反対にしろ、理由を述べてください。","さんせいにしろはんたいにしろ、りゆうをのべてください。","Ob Sie zustimmen oder ablehnen — nennen Sie bitte einen Grund."],["どちらを選ぶにせよ、後悔はしないだろう。","どちらをえらぶにせよ、こうかいはしないだろう。","Egal, wofür man sich entscheidet — bereuen wird man es wohl nicht."],["冗談にせよ、言っていいことと悪いことがある。","じょうだんにせよ、いっていいこととわるいことがある。","Auch als Scherz gibt es Dinge, die man sagen kann, und solche, die man besser lässt."]],q:[{q:"安い＿＿高い＿＿、品質を確認してから買う。",o:["にしろ / にしろ","として / として","ながら / ながら","たびに / たびに"],c:0},{q:"Der Nachsatz gilt …",o:["für alle genannten Fälle gleich","nur für den ersten Fall","nur für den zweiten Fall","für keinen der Fälle"],c:0},{q:"Etwas schriftlicher ist …",o:["〜にせよ","〜にしろ","〜にしたって","〜だって"],c:0}]},{id:"n3-kotodakara",level:3,title:'〜ことだから — „weil es ja … ist (und man das von ihm/ihr kennt)"',intro:"Aus dem bekannten Wesen einer Person schließt man auf ihr Verhalten.",text:'Nomen (Person) + の + ことだから. „しっかり者の彼女のことだから、準備は完璧だろう." Der Bezug ist fast immer eine Person, deren Eigenart als bekannt vorausgesetzt wird.',tip:"Nicht mit 〜ことから (Herleitung aus einem Umstand) verwechseln. 〜ことだから braucht gemeinsames Vorwissen über die Person.",ex:[["時間に正確な彼のことだから、もう着いているはずだ。","じかんにせいかくなかれのことだから、もうついているはずだ。","So pünktlich, wie er ist, müsste er schon da sein."],["あの子のことだから、きっと迷子になっている。","あのこのことだから、きっとまいごになっている。","So wie die Kleine ist, hat sie sich bestimmt verlaufen."],["約束を守る人のことだから、心配いらない。","やくそくをまもるひとのことだから、しんぱいいらない。","Er hält ja seine Versprechen — kein Grund zur Sorge."]],q:[{q:"慎重な先生＿＿、何度も確認するだろう。",o:["のことだから","のことから","にあたって","に比べて"],c:0},{q:"Der Bezug von 〜ことだから ist meist …",o:["eine Person mit bekannter Eigenart","ein neutraler Umstand","eine Uhrzeit","ein Ort"],c:0},{q:"Man braucht dafür …",o:["gemeinsames Vorwissen über die Person","einen schriftlichen Beleg","eine offizielle Regel","eine Statistik"],c:0}]},{id:"n3-toiumonoda",level:3,title:'〜というものだ — „das ist doch … / das nennt man …"',intro:"Bewertet einen Sachverhalt allgemeingültig — oft mit einem Hauch Kritik oder Belehrung.",text:'Plainform (schlicht, oft Nomen/な-Adj ohne だ) + というものだ. „約束を破るなんて、無責任というものだ." Drückt eine für den Sprecher selbstverständliche Wertung aus.',tip:'Verneint: 〜というものではない / 〜というものでもない = „so einfach ist es nicht". Umgangssprachlich klingt es leicht dozierend.',ex:[["困ったときに助け合うのが友達というものだ。","こまったときにたすけあうのがともだちというものだ。","Sich in der Not zu helfen — das macht Freundschaft aus."],["一度で全部覚えられると思うのは甘いというものだ。","いちどでぜんぶおぼえられるとおもうのはあまいというものだ。","Zu glauben, man lerne alles auf einmal — das ist zu naiv."],["お金があれば幸せだ、というものでもない。","おかねがあればしあわせだ、というものでもない。","Geld allein macht eben doch nicht glücklich."]],q:[{q:"人の失敗を笑うなんて、失礼＿＿。",o:["というものだ","ということだ","というより","というと"],c:0},{q:"〜というものだ drückt aus …",o:["eine allgemeingültige Wertung","eine unsichere Vermutung","eine reine Zeitangabe","eine Bitte"],c:0},{q:"Die verneinte Form 〜というものではない heißt …",o:["so einfach ist es nicht","das ist verboten","das ist Pflicht","das war früher so"],c:0}]},{id:"n3-zunihairarenai-naidehairarenai",level:3,title:'〜ずにはいられない・〜ないではいられない — „nicht anders können, als zu …"',intro:"Ein Gefühl oder Impuls ist so stark, dass man ihm nachgeben muss.",text:'Verb ない-Form (ohne い) + ずにはいられない. „あの映画は何度見ても泣かずにはいられない." する→せずにはいられない. Betont, dass man sich nicht zurückhalten kann.',tip:"〜ないではいられない ist die etwas umgangssprachlichere Variante. Nur für spontane, unwillkürliche Reaktionen.",ex:[["あんな話を聞いたら、怒らずにはいられない。","あんなはなしをきいたら、おこらずにはいられない。","Wenn man so etwas hört, kann man gar nicht anders, als wütend zu werden."],["見事な演奏に、拍手せずにはいられなかった。","みごとなえんそうに、はくしゅせずにはいられなかった。","Bei dem großartigen Spiel musste ich einfach applaudieren."],["困っている人がいたら、手を貸さないではいられない。","こまっているひとがいたら、てをかさないではいられない。","Wenn jemand in Not ist, kann ich nicht anders, als zu helfen."]],q:[{q:"そのニュースには驚か＿＿にはいられなかった。",o:["ず","ない","なく","ぬ"],c:0},{q:"〜ずにはいられない beschreibt …",o:["eine unwillkürliche, nicht zu unterdrückende Reaktion","eine wohlüberlegte Entscheidung","ein Verbot","eine Gewohnheit aus der Kindheit"],c:0},{q:"「する」 wird zu …",o:["せずにはいられない","しずにはいられない","さずにはいられない","しないずにはいられない"],c:0}]},{id:"n3-yorihokanai-yorishikataganai",level:3,title:'〜よりほかない・〜よりしかたがない — „es bleibt nichts anderes übrig, als"',intro:"Es gibt keine Alternative — man muss den einen Weg gehen.",text:'Verb Wörterbuchform + よりほかない / よりしかたがない / ほかない. „終電を逃したから、歩いて帰るよりほかない."',tip:"Nah an 〜しかない, aber 〜よりほかない klingt eine Spur resignierter und förmlicher.",ex:[["機械が壊れたので、手作業でやるよりほかない。","きかいがこわれたので、てさぎょうでやるよりほかない。","Weil die Maschine kaputt ist, bleibt nur Handarbeit."],["本人が話さない以上、待つよりしかたがない。","ほんにんがはなさないいじょう、まつよりしかたがない。","Solange er selbst nichts sagt, kann man nur warten."],["予約が取れなかったら、あきらめるほかない。","よやくがとれなかったら、あきらめるほかない。","Wenn wir keinen Platz bekommen, müssen wir es eben lassen."]],q:[{q:"代わりがいないので、私がやる＿＿。",o:["よりほかない","かのようだ","に基づく","どころだ"],c:0},{q:"Der Ton von 〜よりほかない ist …",o:["resigniert / notgedrungen","begeistert","wütend","neutral-sachlich"],c:0},{q:"Vor よりほかない steht …",o:["ein Verb in Wörterbuchform","ein Nomen","ein Verb in た-Form","ein い-Adjektiv"],c:0}]},{id:"n3-youganai-youmonai",level:3,title:'〜ようがない・〜ようもない — „es gibt keine Möglichkeit zu …"',intro:"Man kann etwas beim besten Willen nicht tun, weil die Mittel fehlen.",text:'Verb ます-Stamm + ようがない / ようもない. „連絡先を知らないので、知らせようがない." Betont: „selbst wenn ich wollte, ginge es nicht".',tip:'Unterschied zu 〜られない: 〜ようがない heißt „es fehlt jede Möglichkeit/Methode", nicht nur „ich schaffe es nicht".',ex:[["原因が分からないので、直しようがない。","げんいんがわからないので、なおしようがない。","Weil die Ursache unklar ist, lässt es sich nicht reparieren."],["もう終わったことだから、今さら言いようがない。","もうおわったことだから、いまさらいいようがない。","Es ist vorbei — jetzt lässt sich dazu nichts mehr sagen."],["彼の親切には感謝のしようもない。","かれのしんせつにはかんしゃのしようもない。","Für seine Hilfe kann ich gar nicht genug danken."]],q:[{q:"道具がなければ、修理の＿＿がない。",o:["しよう","こと","つもり","はず"],c:0},{q:"〜ようがない bedeutet …",o:["es fehlt jede Methode / Möglichkeit","ich habe keine Lust","es ist verboten","es ist unnötig"],c:0},{q:"Vor ようがない steht …",o:["der ます-Stamm","die て-Form","die た-Form","die ない-Form"],c:0}]},{id:"n3-dakeate-dakenokotohaaru",level:3,title:'〜だけあって・〜だけのことはある — „wie nicht anders zu erwarten (bei …)"',intro:"Ein gutes Ergebnis passt genau zu einer Voraussetzung — meist anerkennend.",text:'Nomen / Plainform + だけあって + (positives Ergebnis). „長年練習しただけあって、演奏は見事だった." Nachgestellt: „さすがプロだけのことはある."',tip:'Fast immer lobend. Für ein negatives „gerade weil" nimmt man 〜だけに.',ex:[["人気店だけあって、いつも行列ができている。","にんきてんだけあって、いつもぎょうれつができている。","Als beliebtes Lokal hat es immer eine Schlange."],["彼は留学していただけあって、発音がきれいだ。","かれはりゅうがくしていただけあって、はつおんがきれいだ。","Man merkt seinem Akzent an, dass er im Ausland war."],["高かっただけのことはあって、長く使える。","たかかっただけのことはあって、ながくつかえる。","Der hohe Preis hat sich gelohnt — man kann es lange benutzen."]],q:[{q:"毎日走っている＿＿、体力がついた。",o:["だけあって","に反して","に比べて","かのように"],c:0},{q:"Das Ergebnis nach 〜だけあって ist meist …",o:["positiv / anerkennend","negativ / vorwurfsvoll","völlig unerwartet","egal"],c:0},{q:'Für „gerade weil (mit Nachteil)" nimmt man …',o:["〜だけに","〜だけあって","〜だけのことはある","〜だけましだ"],c:0}]},{id:"n3-dakeni",level:3,title:'〜だけに — „gerade weil …, umso mehr / umso …"',intro:"Eine Ursache verstärkt die Folge — die Folge ist stärker als üblich.",text:'Nomen / Plainform + だけに. „期待していただけに、負けたときの落胆は大きかった." Die Folge kann positiv oder negativ sein, ist aber immer verstärkt.',tip:"Oft mit einem Gefühl im Nachsatz (残念, うれしい, 悔しい). 〜だけあって ist rein lobend, 〜だけに betont die Verstärkung.",ex:[["初めての挑戦だっただけに、成功はうれしかった。","はじめてのちょうせんだっただけに、せいこうはうれしかった。","Weil es der erste Versuch war, war der Erfolg umso schöner."],["真面目な人だけに、今回のミスは意外だ。","まじめなひとだけに、こんかいのミスはいがいだ。","Gerade weil er so gewissenhaft ist, überrascht dieser Fehler."],["雨が続いていただけに、晴れた日曜がありがたい。","あめがつづいていただけに、はれたにちようがありがたい。","Nach dem Dauerregen ist der sonnige Sonntag umso willkommener."]],q:[{q:"準備を重ねてきた＿＿、中止の知らせはつらかった。",o:["だけに","に応じて","において","くらいなら"],c:0},{q:"〜だけに zeigt, dass die Folge …",o:["verstärkt / überdurchschnittlich ist","ausbleibt","egal ist","zufällig ist"],c:0},{q:"Im Nachsatz steht oft …",o:["ein Gefühl (残念/うれしい/悔しい)","ein Befehl","eine reine Zeitangabe","eine Frage"],c:0}]},{id:"n3-karashite",level:3,title:'〜からして — „schon allein an … / schon von … her"',intro:"Nennt ein Beispiel als schlagenden Beleg für eine allgemeine Aussage.",text:'Nomen + からして. „この店は入口からしておしゃれだ." Bedeutet: „nimm schon nur X — daran sieht man es". Meist mit negativem oder bewertendem Nachsatz.',tip:"Nicht mit 〜からすると (Standpunkt/Urteil) verwechseln. 〜からして greift ein Detail als Beweisstück heraus.",ex:[["彼の態度からして、反省していないのが分かる。","かれのたいどからして、はんせいしていないのがわかる。","Schon an seiner Haltung sieht man, dass er es nicht bereut."],["名前からして、外国の会社らしい。","なまえからして、がいこくのかいしゃらしい。","Schon am Namen erkennt man, dass es eine ausländische Firma ist."],["最初の一行からして、間違いだらけだ。","さいしょのいちぎょうからして、まちがいだらけだ。","Schon die erste Zeile steckt voller Fehler."]],q:[{q:"この計画は、予算＿＿無理がある。",o:["からして","に応じて","をこめて","において"],c:0},{q:"〜からして stellt … heraus.",o:["ein Detail als schlagenden Beleg","einen Zeitpunkt","einen Zweck","eine Bedingung"],c:0},{q:"〜からすると bedeutet dagegen …",o:["nach … zu urteilen / aus Sicht von","schon allein an","seitdem","trotz"],c:0}]},{id:"n3-karasuruto-karasureba",level:3,title:'〜からすると・〜からすれば — „nach … zu urteilen / aus der Sicht von"',intro:"Nennt den Blickwinkel oder die Grundlage einer Einschätzung.",text:'Nomen + からすると / からすれば / からいうと. „専門家からすると、この判断は危うい." „表情からすると、うまくいったようだ."',tip:"Ähnlich 〜にとって (für/aus Sicht von), aber 〜からすると betont das Schließen/Bewerten von diesem Standpunkt aus.",ex:[["あの言い方からすると、彼は怒っているようだ。","あのいいかたからすると、かれはおこっているようだ。","Nach seinem Tonfall zu urteilen, ist er verärgert."],["留学生からすれば、日本の敬語は難しい。","りゅうがくせいからすれば、にほんのけいごはむずかしい。","Aus Sicht von Austauschstudierenden ist japanische Höflichkeitssprache schwer."],["この売り上げからすると、来月は黒字になる。","このうりあげからすると、らいげつはくろじになる。","Bei diesem Umsatz dürfte nächster Monat schwarze Zahlen bringen."]],q:[{q:"足あとの大きさ＿＿、犯人は大柄な人物だ。",o:["からすると","からには","において","に比べて"],c:0},{q:"〜からすると betont …",o:["das Bewerten von einem Standpunkt aus","einen Gegensatz","einen Zweck","eine Reihenfolge"],c:0},{q:"Was steht vor からすると?",o:["ein Nomen","ein Verb in て-Form","ein い-Adjektiv","ein ganzer Satz mit と"],c:0}]},{id:"n3-de-no-ha",level:3,title:'〜上で・〜上の・〜上は — „nach dem …, bei …, was … betrifft"',intro:'Mehrere Bedeutungen rund um „auf der Grundlage / im Rahmen von".',text:'(1) Verb た-Form + 上で = „nachdem, auf Basis von": „よく考えた上で返事する." (2) Verb Wörterbuchform / Nomen + の + 上で = „bei / im Zuge von": „仕事の上での付き合い." (3) 〜上は = „da nun einmal" (wie 〜以上は).',tip:"Bedeutung (1) heißt: erst A abschließen, dann B. Nicht mit 〜あげく (negatives Endergebnis) verwechseln.",ex:[["資料を確認した上で、改めて連絡します。","しりょうをかくにんしたうえで、あらためてれんらくします。","Nachdem ich die Unterlagen geprüft habe, melde ich mich erneut."],["契約の上での注意点を説明します。","けいやくのうえでのちゅういてんをせつめいします。","Ich erläutere die zu beachtenden Punkte beim Vertrag."],["引き受けた上は、最後まで責任を持つ。","ひきうけたうえは、さいごまでせきにんをもつ。","Da ich es übernommen habe, trage ich bis zum Schluss die Verantwortung."]],q:[{q:"両親と相談した＿＿、進路を決めた。",o:["上で","あげく","かのように","に応じて"],c:0},{q:"〜た上で bedeutet …",o:["erst A abschließen, dann B","A und B gleichzeitig","A trotz B","weder A noch B"],c:0},{q:"〜上は entspricht etwa …",o:['〜以上は („da nun einmal")',"〜うちに","〜おそれがある","〜くらいなら"],c:0}]},{id:"n3-andererseits-auf-der-anderen-seite",level:3,title:'〜反面・〜半面 — „andererseits / auf der anderen Seite"',intro:"Nennt zu einer Eigenschaft die gegenteilige zweite Seite.",text:'Plainform (な-Adj + な・である / Nomen + である) + 反面. „便利な反面、値段が高い." Zwei entgegengesetzte Merkmale desselben Gegenstands.',tip:"Nah an 〜一方で, aber 〜反面 stellt immer einen echten Gegensatz gegenüber (Vorteil ↔ Nachteil).",ex:[["この仕事はやりがいがある反面、責任も重い。","このしごとはやりがいがあるはんめん、せきにんもおもい。","Diese Arbeit ist erfüllend, hat aber auch viel Verantwortung."],["都会は刺激が多い反面、疲れやすい。","とかいはしげきがおおいはんめん、つかれやすい。","Die Stadt bietet viele Reize, macht aber auch schnell müde."],["薬はよく効く反面、副作用もある。","くすりはよくきくはんめん、ふくさようもある。","Das Medikament wirkt gut, hat aber auch Nebenwirkungen."]],q:[{q:"新しい機種は軽い＿＿、電池のもちが悪い。",o:["反面","あまり","うえは","だけに"],c:0},{q:"〜反面 stellt gegenüber …",o:["zwei entgegengesetzte Merkmale","Ursache und Wirkung","zwei Zeitpunkte","zwei Personen"],c:0},{q:"な-Adjektiv vor 反面 steht mit …",o:["な / である","く","に","nichts"],c:0}]},{id:"n3-bakarini",level:3,title:'〜ばかりに — „nur weil (leider) …"',intro:"Ein einziger Grund führt zu einer unerwünschten Folge — mit Bedauern.",text:'Plainform (な-Adj + な / Nomen + である) + ばかりに. „一言多く言ったばかりに、けんかになった." Der Nachsatz ist immer negativ; oft schwingt Reue mit.',tip:'Nicht mit 〜ばかり („nur, ständig") verwechseln. 〜ばかりに sucht die Schuld bei genau einem Umstand.',ex:[["道を間違えたばかりに、飛行機に乗り遅れた。","みちをまちがえたばかりに、ひこうきにのりおくれた。","Nur weil ich mich verfahren habe, habe ich den Flug verpasst."],["保証書をなくしたばかりに、修理代を自分で払った。","ほしょうしょをなくしたばかりに、しゅうりだいをじぶんではらった。","Nur weil ich die Garantiekarte verloren hatte, musste ich die Reparatur selbst zahlen."],["正直に話したばかりに、かえって疑われた。","しょうじきにはなしたばかりに、かえってうたがわれた。","Nur weil ich ehrlich war, wurde ich erst recht verdächtigt."]],q:[{q:"ひとつ確認を忘れた＿＿、大きな問題になった。",o:["ばかりに","うえに","に応じて","かのように"],c:0},{q:"Die Folge nach 〜ばかりに ist …",o:["immer negativ, oft mit Bedauern","immer positiv","neutral","nicht genannt"],c:0},{q:"〜ばかりに unterscheidet sich von 〜ばかり dadurch, dass es …",o:["den einen Grund für ein Missgeschick nennt",'„nur/ständig" bedeutet',"eine Menge angibt","eine Reihenfolge angibt"],c:0}]},{id:"n3-toka",level:3,title:'〜とか — „so was wie / oder so" (vage Aufzählung, Hörensagen)',intro:"Nennt Beispiele unbestimmt oder gibt Gehörtes locker wieder.",text:'(1) Nomen/Plainform + とか … + とか = unbestimmte Aufzählung: „週末は掃除とか買い物とかで終わる." (2) am Satzende: „来月から値上げするとか." (etwas unsicher Gehörtes). Umgangssprachlich.',tip:"Lockerer und unbestimmter als 〜や / 〜たり. Für förmliche Texte ungeeignet.",ex:[["疲れたときは甘いものとかコーヒーとかがほしくなる。","つかれたときはあまいものとかコーヒーとかがほしくなる。","Wenn ich müde bin, will ich sowas wie Süßes oder Kaffee."],["田中さん、今日は休むとか言ってたよ。","たなかさん、きょうはやすむとかいってたよ。","Herr Tanaka meinte, er nimmt heute frei — oder so ähnlich."],["新しい店ができるとか、うわさで聞いた。","あたらしいみせができるとか、うわさできいた。","Es soll ein neuer Laden aufmachen — hab ich gerüchteweise gehört."]],q:[{q:"休みの日は映画＿＿散歩＿＿してのんびりする。",o:["とか / とか","こそ / こそ","さえ / さえ","きり / きり"],c:0},{q:"〜とか am Satzende drückt aus …",o:["etwas unsicher Gehörtes","einen festen Befehl","einen starken Wunsch","eine Bedingung"],c:0},{q:"〜とか ist im Ton …",o:["umgangssprachlich / unbestimmt","sehr förmlich","schriftsprachlich","poetisch"],c:0}]},{id:"n3-ke",level:3,title:'〜っけ — „war das nicht …? / wie war das nochmal?"',intro:"Fragt nach etwas, das man vergessen hat oder sich vergewissern will — meist zu sich selbst oder vertraut.",text:'Plainform (Verb た-Form / だ→だった) + っけ. „会議は3時からだったっけ？" „君、犬を飼ってたっけ？" Nur in vertrauter Rede.',tip:'Nicht gegenüber Höhergestellten. Oft mit った (auch bei eigentlich nicht-vergangenem Bezug: „明日は休みだったっけ").',ex:[["あれ、鍵、閉めたっけ？","あれ、かぎ、しめたっけ？","Hm, hab ich abgeschlossen?"],["この話、前にもしたっけ？","このはなし、まえにもしたっけ？","Hab ich das schon mal erzählt?"],["集合は駅前だったっけ、それとも店の前？","しゅうごうはえきまえだったっけ、それともみせのまえ？","War der Treffpunkt vorm Bahnhof oder vorm Laden?"]],q:[{q:"会議室、二階だ＿＿？三階だった気もする。",o:["っけ","とか","すら","きり"],c:0},{q:"〜っけ benutzt man …",o:["in vertrauter Rede, wenn man sich unsicher erinnert","gegenüber Vorgesetzten","in offiziellen Texten","bei einem Befehl"],c:0},{q:"Vor っけ steht oft …",o:["die た-Form (auch ohne echte Vergangenheit)","die て-Form","die ます-Form","die ば-Form"],c:0}]},{id:"n3-sura",level:3,title:'〜すら — „nicht einmal / sogar" (nachdrücklicher als 〜さえ)',intro:"Hebt ein extremes Beispiel hervor; oft mit Verneinung im Nachsatz.",text:'Nomen (+ Partikel) + すら. „忙しくて食事をする時間すらない." „専門家すら答えられなかった." Schriftsprachlicher und emphatischer als 〜さえ.',tip:"Fast immer mit einer Verneinung oder etwas Überraschendem im Nachsatz. In lockerer Rede eher 〜さえ / 〜も.",ex:[["疲れて、立ち上がる力すら残っていなかった。","つかれて、たちあがるちからすらのこっていなかった。","Ich war so erschöpft, dass mir nicht einmal die Kraft zum Aufstehen blieb."],["名前すら知らない人に道を聞かれた。","なまえすらしらないひとにみちをきかれた。","Ein Mensch, dessen Namen ich nicht mal kenne, fragte mich nach dem Weg."],["地元の人すら知らない小さな店だ。","じもとのひとすらしらないちいさなみせだ。","Ein kleiner Laden, den nicht mal die Einheimischen kennen."]],q:[{q:"緊張して、声＿＿出なかった。",o:["すら","きり","こそ","なり"],c:0},{q:"Nach 〜すら folgt meist …",o:["eine Verneinung / etwas Überraschendes","ein Befehl","eine Frage","ein Wunsch"],c:0},{q:"〜すら ist gegenüber 〜さえ …",o:["schriftsprachlicher / emphatischer","lockerer","gleichbedeutend und gleich im Ton","veraltet"],c:0}]},{id:"n3-buri",level:3,title:'〜ぶり（に）— „nach (Zeitspanne) zum ersten Mal wieder"',intro:"Nach einer langen Pause geschieht etwas erneut.",text:'Zeitangabe + ぶり（に）. „十年ぶりに故郷に帰った." „三日ぶりの晴れだ." Auch „〜ぶりの再会". Betont, dass so lange nichts davon geschah.',tip:'Nicht mit 〜ごとに („jedes Mal / alle …") verwechseln. Die Zeitangabe ist der Abstand seit dem letzten Mal.',ex:[["久しぶりに会ったら、彼はずいぶん大人になっていた。","ひさしぶりにあったら、かれはずいぶんおとなになっていた。","Als ich ihn nach langer Zeit wiedersah, war er sehr erwachsen geworden."],["一週間ぶりに雨がやんだ。","いっしゅうかんぶりにあめがやんだ。","Nach einer Woche hörte der Regen endlich auf."],["五年ぶりの帰国で、街の変化に驚いた。","ごねんぶりのきこくで、まちのへんかにおどろいた。","Bei der ersten Heimreise nach fünf Jahren überraschte mich, wie sehr sich die Stadt verändert hatte."]],q:[{q:"半年＿＿にプールで泳いだ。",o:["ぶり","おき","ごと","ずつ"],c:0},{q:"「十年ぶりに帰った」 heißt …",o:["zum ersten Mal seit zehn Jahren zurückgekehrt","alle zehn Jahre zurückkehren","vor zehn Jahren zurückgekehrt","zehn Jahre lang zurückkehren"],c:0},{q:"Vor ぶり steht …",o:["eine Zeitspanne","ein Verb in て-Form","ein Ort","ein Grund"],c:0}]},{id:"n3-mamire",level:3,title:'〜まみれ — „bedeckt / beschmiert mit"',intro:"Die ganze Oberfläche ist voll von etwas Unangenehmem (Schmutz, Flüssigkeit).",text:'Nomen (Schmutz/Staub/Schweiß/Öl/Blut …) + まみれ. „泥まみれの靴", „汗まみれになって働いた." Nur für negativ empfundene, klebrige/staubige Sachen.',tip:'Für „voller (Fehler, Schulden)" nimmt man 〜だらけ. 〜まみれ meint konkreten Belag auf einer Fläche.',ex:[["子どもは泥まみれで帰ってきた。","こどもはどろまみれでかえってきた。","Das Kind kam voller Schlamm nach Hause."],["作業のあと、手は油まみれだった。","さぎょうのあと、てはあぶらまみれだった。","Nach der Arbeit waren die Hände voller Öl."],["汗まみれになりながら荷物を運んだ。","あせまみれになりながらにもつをはこんだ。","Schweißgebadet trug ich das Gepäck."]],q:[{q:"ころんで、服がほこり＿＿になった。",o:["まみれ","だらけ","ぎみ","っぽい"],c:0},{q:"〜まみれ verwendet man für …",o:["einen klebrigen/staubigen Belag auf einer Fläche","viele Fehler in einem Text","eine leichte Tendenz","einen Vergleich"],c:0},{q:'Für „voller Fehler" nimmt man eher …',o:["〜だらけ","〜まみれ","〜ぎみ","〜がち"],c:0}]},{id:"n3-zujimai",level:3,title:'〜ずじまい — „am Ende gar nicht (getan), ohne dass es dazu kam"',intro:"Etwas Beabsichtigtes wurde letztlich nicht ausgeführt — meist mit Bedauern.",text:'Verb ない-Form (ohne い) + ずじまい（だ / で / の）. „忙しくて、結局連絡できずじまいだった." する→せずじまい. Rückblickend auf eine verpasste Absicht.',tip:"Immer rückblickend und meist bedauernd. Nicht für Handlungen, die man bewusst gelassen hat.",ex:[["雨で、せっかくの花火は見ずじまいだった。","あめで、せっかくのはなびはみずじまいだった。","Wegen des Regens habe ich das Feuerwerk am Ende gar nicht gesehen."],["お礼を言おうと思っていたのに、言えずじまいになった。","おれいをいおうとおもっていたのに、いえずじまいになった。","Ich wollte mich bedanken, kam aber nie dazu."],["買おうか迷っているうちに、売り切れて買わずじまいだった。","かおうかまよっているうちに、うりきれてかわずじまいだった。","Während ich noch überlegte, war es ausverkauft — gekauft habe ich es am Ende nicht."]],q:[{q:"結局、その本は読ま＿＿じまいで返した。",o:["ず","ない","なく","ぬ"],c:0},{q:"〜ずじまい bedeutet …",o:["die Absicht wurde am Ende nicht ausgeführt","man hat es bewusst gelassen","man tut es dauernd","man ist damit fertig"],c:0},{q:"「する」 wird zu …",o:["せずじまい","しずじまい","さずじまい","しないじまい"],c:0}]},{id:"n3-niwatate-niwatari-niwataru",level:3,title:'〜にわたって・〜にわたり・〜にわたる — „sich erstreckend über (Zeit/Raum/Bereich)"',intro:"Ein Vorgang deckt einen ganzen Zeitraum, ein Gebiet oder mehrere Bereiche ab.",text:'Nomen (Zeitraum / Gebiet / Zahl von Bereichen) + にわたって（にわたり）(adverbial) / にわたる + Nomen (attributiv). „三日間にわたって会議が続いた." „広い範囲にわたる調査".',tip:"Betont die volle Ausdehnung. Für einen einzelnen Zeitpunkt unpassend — dafür 〜において.",ex:[["工事は半年にわたって行われた。","こうじははんとしにわたっておこなわれた。","Die Bauarbeiten zogen sich über ein halbes Jahr hin."],["台風は関東の広い範囲にわたり被害を出した。","たいふうはかんとうのひろいはんいにわたりひがいをだした。","Der Taifun richtete in weiten Teilen der Kantō-Region Schäden an."],["三回にわたる話し合いの末、合意した。","さんかいにわたるはなしあいのすえ、ごういした。","Nach drei Gesprächsrunden kam es zur Einigung."]],q:[{q:"調査は五年間＿＿続けられた。",o:["にわたって","にかけて","において","に応じて"],c:0},{q:"〜にわたって betont …",o:["die volle Ausdehnung über Zeit/Raum/Bereiche","einen einzelnen Zeitpunkt","einen Gegensatz","einen Grund"],c:0},{q:"Die attributive Form ist …",o:["〜にわたる","〜にわたって","〜にわたっては","〜にわたりつつ"],c:0}]},{id:"n3-womegute-womeguru",level:3,title:'〜をめぐって・〜をめぐる — „um … (ein strittiges Thema) herum"',intro:"Rund um ein Thema gibt es Streit, Diskussion, Meinungen oder Ereignisse.",text:'Nomen + をめぐって（は）(adverbial) / をめぐる + Nomen (attributiv). „工場の建設をめぐって、住民の意見が分かれた." Typische Verben: 争う, 議論する, 対立する, 話し合う.',tip:'Nicht wörtlich „umkreisen". Es geht um ein Streit-/Diskussionsthema, das mehrere Parteien betrifft.',ex:[["遺産をめぐって、兄弟がもめている。","いさんをめぐって、きょうだいがもめている。","Um das Erbe streiten sich die Geschwister."],["新しい規則をめぐり、社内で議論が起きた。","あたらしいきそくをめぐり、しゃないでぎろんがおきた。","Um die neue Regel entstand in der Firma eine Debatte."],["その事件をめぐる報道が続いている。","そのじけんをめぐるほうどうがつづいている。","Die Berichterstattung rund um den Vorfall hält an."]],q:[{q:"土地の使い方＿＿、村で対立が続いている。",o:["をめぐって","にわたって","をこめて","において"],c:0},{q:"Nach 〜をめぐって stehen oft Verben wie …",o:["争う / 議論する / 対立する","食べる / 寝る / 歩く","始まる / 終わる","ある / いる"],c:0},{q:"Die attributive Form ist …",o:["〜をめぐる","〜をめぐって","〜をめぐっては","〜をめぐりつつ"],c:0}]},{id:"n3-wokikakeni",level:3,title:'〜をきっかけに（して）・〜がきっかけで — „zum Anlass nehmen / durch … ausgelöst"',intro:"Ein bestimmtes Ereignis ist der Auslöser für eine Veränderung.",text:'Nomen / Verb-の + をきっかけに（して）. „入院をきっかけに、たばこをやめた." Auch „〜がきっかけで、〜ようになった." Der Auslöser ist oft ein einmaliges Erlebnis.',tip:"Ähnlich 〜を契機に (förmlicher). Die Folge ist eine bewusste oder deutliche Änderung, nicht nur eine Kleinigkeit.",ex:[["引っ越しをきっかけに、家具を全部買い替えた。","ひっこしをきっかけに、かぐをぜんぶかいかえた。","Den Umzug habe ich zum Anlass genommen, alle Möbel zu erneuern."],["ある映画がきっかけで、日本語を学び始めた。","あるえいががきっかけで、にほんごをまなびはじめた。","Ein Film war der Auslöser, Japanisch zu lernen."],["小さなけんかをきっかけにして、二人は仲直りした。","ちいさなけんかをきっかけにして、ふたりはなかなおりした。","Ein kleiner Streit wurde zum Anlass, dass sich die beiden versöhnten."]],q:[{q:"健康診断＿＿、運動を始めた。",o:["をきっかけに","にかけては","をこめて","にしては"],c:0},{q:"Der Teil vor 〜をきっかけに ist …",o:["ein auslösendes Ereignis","die Folge","ein Gegensatz","eine Bedingung ohne Wirkung"],c:0},{q:"Etwas förmlicher als 〜をきっかけに ist …",o:["〜を契機に","〜がきっかけで","〜をもとに","〜にあたって"],c:0}]},{id:"n3-nomotode-nomotoni",level:3,title:'〜のもとで・〜のもとに — „unter (Leitung / Bedingung / Einfluss von)"',intro:"Etwas geschieht im Einfluss- oder Verantwortungsbereich einer Person oder Bedingung.",text:'Nomen + のもとで (Ort/Umfeld: „先生の指導のもとで研究する.") / のもとに (Bedingung/Prinzip: „一定の条件のもとに認められる."). Schriftsprachlich.',tip:"〜のもとで betont das Umfeld/die Aufsicht; 〜のもとに betont die zugrunde liegende Bedingung/Regel.",ex:[["彼は有名な監督のもとで演技を学んだ。","かれはゆうめいなかんとくのもとでえんぎをまなんだ。","Er lernte das Schauspiel unter einem berühmten Regisseur."],["「秘密を守る」という約束のもとに話してくれた。","「ひみつをまもる」というやくそくのもとにはなしてくれた。","Er erzählte es mir unter der Bedingung, dass ich es für mich behalte."],["厳しい管理のもとで薬が作られている。","きびしいかんりのもとでくすりがつくられている。","Die Medikamente werden unter strenger Kontrolle hergestellt."]],q:[{q:"専門家の助言＿＿、計画を進めた。",o:["のもとで","のうちに","のことだから","のわりに"],c:0},{q:"〜のもとに betont eher …",o:["die zugrunde liegende Bedingung/Regel","den Zeitpunkt","den Gegensatz","die Menge"],c:0},{q:"Der Stil von 〜のもとで/に ist …",o:["schriftsprachlich","salopp","kindlich","dialektal"],c:0}]},{id:"n3-dakemashida",level:3,title:'〜だけましだ — „wenigstens noch besser / erträglicher, dass …"',intro:"Die Lage ist schlecht, aber ein Umstand macht sie wenigstens weniger schlimm.",text:'Plainform / Nomen + な / い-Adj + だけましだ. „給料は安いが、残業がないだけましだ." Vergleich mit einem noch schlechteren gedachten Fall.',tip:'Immer positiv gemeint im Sinne von „hätte schlimmer kommen können". Vor だけ oft ein い-Adjektiv oder Verb in Plainform.',ex:[["負けたが、大けがをしなかっただけましだ。","まけたが、おおけがをしなかっただけましだ。","Wir haben verloren, aber immerhin gab es keine schweren Verletzungen."],["狭い部屋だが、駅に近いだけましだ。","せまいへやだが、えきにちかいだけましだ。","Das Zimmer ist klein, aber wenigstens nah am Bahnhof."],["雨だが、風がないだけましだ。","あめだが、かぜがないだけましだ。","Es regnet, aber immerhin ist es windstill."]],q:[{q:"仕事は大変だが、人間関係がいい＿＿。",o:["だけましだ","どころではない","に違いない","かのようだ"],c:0},{q:"〜だけましだ vergleicht mit …",o:["einem noch schlechteren gedachten Fall","einem idealen Zustand","der Vergangenheit","einer Vorschrift"],c:0},{q:"Der Grundton von 〜だけましだ ist …",o:['„hätte schlimmer kommen können"','„alles ist wunderbar"','„es ist hoffnungslos"','„es ist mir egal"'],c:0}]},{id:"n3-garu-gateiru",level:3,title:'〜がる・〜がっている — „(eine andere Person) zeigt das Gefühl / will …"',intro:"Von außen sichtbares Gefühl oder Wunsch einer dritten Person.",text:'い-Adj (ohne い) / な-Adj (Stamm) + がる. „子どもが犬を怖がる." „彼は新しい車を欲しがっている." Bei anhaltendem Zustand 〜がっている. 〜たい→〜たがる.',tip:"Nicht für die eigenen Gefühle (da direkt 怖い / 欲しい). 〜がる macht ein Adjektiv zum Verb (五段).",ex:[["妹は暗いところを怖がる。","いもうとはくらいところをこわがる。","Meine kleine Schwester fürchtet sich vor dunklen Orten."],["彼女はしきりに帰りたがっていた。","かのじょはしきりにかえりたがっていた。","Sie wollte unbedingt nach Hause."],["祖父は新しい機械を面白がって使っている。","そふはあたらしいきかいをおもしろがってつかっている。","Mein Großvater benutzt die neue Maschine mit sichtlichem Spaß."]],q:[{q:"子どもが外に出た＿＿ので、少し散歩した。",o:["がっていた","たかった","ほしかった","そうだった"],c:0},{q:"〜がる verwendet man für …",o:["sichtbare Gefühle/Wünsche anderer","die eigenen Gefühle","eine Vermutung über die Zukunft","einen Grund"],c:0},{q:"「〜たい」 wird zu …",o:["〜たがる","〜たいがる","〜たさがる","〜たくがる"],c:0}]},{id:"n3-tekure",level:3,title:'〜てくれ — „mach (schon) / gib her" (brüsker Imperativ)',intro:"Direkte, unhöfliche Aufforderung; nur unter Vertrauten oder von oben nach unten.",text:'Verb て-Form + くれ. „ちょっと待ってくれ." „これ、あとで片付けておいてくれ." Härter als 〜て / 〜てください; in Berichten oft indirekt: „待ってくれと言われた".',tip:'Nicht gegenüber Höhergestellten oder Fremden. In Schrift/Rede meist als zitierte Bitte („〜てくれと").',ex:[["悪いけど、この荷物、持ってくれ。","わるいけど、このにもつ、もってくれ。","Tut mir leid, aber trag mal dieses Gepäck."],["静かにしてくれと何度も言った。","しずかにしてくれとなんどもいった。","Ich habe mehrmals gesagt, sie sollen leise sein."],["分かったら、すぐ知らせてくれ。","わかったら、すぐしらせてくれ。","Sag sofort Bescheid, sobald du es weißt."]],q:[{q:"手が離せないんだ。ドアを開け＿＿。",o:["てくれ","てほしい","てくださる","ていただく"],c:0},{q:"〜てくれ benutzt man …",o:["unter Vertrauten oder von oben nach unten","gegenüber Vorgesetzten","zu Fremden auf der Straße","in offiziellen Briefen"],c:0},{q:"In einem Bericht steht die Bitte oft als …",o:["「〜てくれと」","「〜てくださいと」","「〜たいと」","「〜だろうと」"],c:0}]},{id:"n3-furiwosuru-furi",level:3,title:'〜ふりをする・〜ふり — „so tun, als ob"',intro:"Man verhält sich absichtlich so, als wäre etwas der Fall, obwohl es nicht stimmt.",text:'Plainform / な-Adj + な / Nomen + の + ふりをする. „知らないふりをした." „寝たふりをして話を聞いていた." Verneint: „見て見ぬふりをする" (wegsehen).',tip:"Immer bewusstes Verstellen. Nicht mit 〜かのようだ (bildhafter Vergleich) verwechseln — 〜ふりをする ist eine gespielte Handlung.",ex:[["彼は忙しいふりをして、仕事を手伝わなかった。","かれはいそがしいふりをして、しごとをてつだわなかった。","Er tat, als hätte er zu tun, und half nicht."],["気づいていたが、気づかないふりをした。","きづいていたが、きづかないふりをした。","Ich hatte es bemerkt, tat aber, als hätte ich nichts gemerkt."],["子どもは大人のふりをして注文した。","こどもはおとなのふりをしてちゅうもんした。","Das Kind gab sich als Erwachsener aus und bestellte."]],q:[{q:"眠くなかったが、眠い＿＿をして早く帰った。",o:["ふり","まま","うち","きり"],c:0},{q:"〜ふりをする bedeutet …",o:["absichtliches Verstellen","ein ehrlicher Vergleich","eine Vermutung","eine Gewohnheit"],c:0},{q:"「見て見ぬふりをする」 heißt …",o:["bewusst wegsehen","genau hinsehen","zum ersten Mal sehen","gemeinsam sehen"],c:0}]},{id:"n3-mokamawazu",level:3,title:'〜もかまわず — „ohne Rücksicht auf, ungeachtet"',intro:"Jemand tut etwas, ohne sich um einen Umstand zu kümmern, der andere normalerweise stören würde.",text:'Nomen + もかまわず. „人目もかまわず泣いた." „雨もかまわず外で遊んでいる." Oft leicht kritisch oder erstaunt.',tip:'Nah an 〜を問わず (neutral „egal welche"), aber 〜もかまわず betont, dass ein hinderlicher Umstand bewusst ignoriert wird.',ex:[["彼女は服が汚れるのもかまわず、地面に座った。","かのじょはふくがよごれるのもかまわず、じめんにすわった。","Ungeachtet dessen, dass ihre Kleidung schmutzig würde, setzte sie sich auf den Boden."],["まわりの目もかまわず、大声で話している。","まわりのめもかまわず、おおごえではなしている。","Ohne sich um die Blicke der anderen zu kümmern, redet er laut."],["時間もかまわず電話をかけてくる。","じかんもかまわずでんわをかけてくる。","Er ruft an, ohne auf die Uhrzeit zu achten."]],q:[{q:"危険＿＿、彼は川に飛び込んだ。",o:["もかまわず","をこめて","にわたって","のもとで"],c:0},{q:"〜もかまわず drückt aus, dass ein hinderlicher Umstand …",o:["bewusst ignoriert wird","genau beachtet wird","unbekannt ist","nicht existiert"],c:0},{q:"Der Ton ist oft …",o:["leicht kritisch oder erstaunt","begeistert","sachlich-neutral","höflich"],c:0}]},{id:"n5-to-partikel",level:5,title:"と — und / mit / Zitat",intro:'Die Partikel と hat drei häufige N5-Rollen: Dinge vollständig aufzählen, „zusammen mit jemandem", und Gesagtes/Gedachtes einleiten.',text:'1) Nomen + と + Nomen = „und" (erschöpfende Aufzählung, nur bei Nomen): 犬と猫 „Hund und Katze". 2) Person + と = „mit": 友だちと行きます „ich gehe mit einem Freund"; 一人で „allein" ist der Gegensatz. 3) Zitat-と vor 言う・思う: 「はい」と言いました / 高いと思います. Zum Vergleich: や zählt Beispiele auf (nicht vollständig), と zählt alles auf.',tip:"と verbindet nur Nomen. Sätze/Verben verbindet man mit der て-Form oder anderen Mitteln.",ex:[["パンと牛乳を買いました。","パンとぎゅうにゅうをかいました。","Ich habe Brot und Milch gekauft."],["日曜日は家族と出かけます。","にちようびはかぞくとでかけます。","Am Sonntag gehe ich mit der Familie aus."],["田中さんは「また来ます」と言いました。","たなかさんは「またきます」といいました。","Herr/Frau Tanaka sagte: „Ich komme wieder.“"],["この本はおもしろいと思います。","このほんはおもしろいとおもいます。","Ich finde, dieses Buch ist interessant."]],q:[{q:"„Hund und Katze“ (vollständige Aufzählung):",o:["犬と猫","犬や猫","犬も猫"],c:0},{q:"„Ich gehe mit einem Freund.“ — 友だち___行きます。",o:["と","に","で"],c:0},{q:"「行きます」___言いました。",o:["と","を","が"],c:0},{q:"と verbindet …",o:["nur Nomen","auch ganze Sätze","nur Verben"],c:0}]},{id:"n5-adjektiv-konjugation",level:5,title:"Adjektiv-Konjugation — Vergangenheit & Verneinung",intro:"い- und な-Adjektive werden unterschiedlich in Vergangenheit und Verneinung gesetzt. Das ist Grundstoff für jede Beschreibung in der Vergangenheit.",text:"い-Adjektiv: 〜い → verneint 〜くない, Vergangenheit 〜かった, verneinte Vergangenheit 〜くなかった (höflich + です): たかいです / たかくないです / たかかったです / たかくなかったです. Ausnahme いい: よくない・よかった・よくなかった. な-Adjektiv (wie ein Nomen mit です): しずかです / しずかじゃないです / しずかでした / しずかじゃなかったです.",tip:"Bei い-Adjektiven nie です in der Vergangenheit anhängen: ❌ たかいでした → ✅ たかかったです.",ex:[["きのうの映画はおもしろかったです。","きのうのえいがはおもしろかったです。","Der Film gestern war interessant."],["この部屋はあまり広くなかったです。","このへやはあまりひろくなかったです。","Dieses Zimmer war nicht besonders groß."],["先週は忙しかったですが、今週はひまです。","せんしゅうはいそがしかったですが、こんしゅうはひまです。","Letzte Woche war ich beschäftigt, aber diese Woche habe ich Zeit."],["テストは簡単じゃなかったです。","テストはかんたんじゃなかったです。","Der Test war nicht einfach."]],q:[{q:"„war teuer“ (höflich):",o:["たかかったです","たかいでした","たかくでした"],c:0},{q:"„war nicht groß“ (い-Adjektiv 広い):",o:["広くなかったです","広いじゃなかったです","広くないでした"],c:0},{q:"„war ruhig“ (な-Adjektiv 静か):",o:["静かでした","静かかったです","静くでした"],c:0},{q:"Vergangenheit von いい („gut“):",o:["よかった","いかった","いいかった"],c:0}]},{id:"n5-amari-zenzen",level:5,title:"あまり〜ない / ぜんぜん〜ない — nicht sehr / überhaupt nicht",intro:"Diese Adverbien stehen fest mit einer Verneinung und drücken „wenig / gar nicht“ aus.",text:"あまり + Verneinung = „nicht besonders / nicht sehr“: あまり食べません „ich esse nicht viel“; コーヒーはあまり好きじゃないです. ぜんぜん + Verneinung = „überhaupt nicht“: ぜんぜんわかりません. Ohne Verneinung sind beide falsch: ❌ あまり食べます. Umgangssprachlich hört man ぜんぜん auch positiv („total“), das ist aber kein Prüfungsstoff.",tip:"Merksatz: あまり und ぜんぜん „ziehen ein ない nach sich“ — der Satz muss verneint enden.",ex:[["朝はあまりコーヒーを飲みません。","あさはあまりコーヒーをのみません。","Morgens trinke ich nicht viel Kaffee."],["この映画はあまりおもしろくなかったです。","このえいがはあまりおもしろくなかったです。","Dieser Film war nicht besonders interessant."],["すみません、日本語がぜんぜんわかりません。","すみません、にほんごがぜんぜんわかりません。","Entschuldigung, ich verstehe überhaupt kein Japanisch."],["きのうはぜんぜん寝ませんでした。","きのうはぜんぜんねませんでした。","Gestern habe ich überhaupt nicht geschlafen."]],q:[{q:"„Ich esse nicht viel.“",o:["あまり食べません","あまり食べます","ぜんぜん食べます"],c:0},{q:"„Ich verstehe überhaupt nichts.“",o:["ぜんぜんわかりません","ぜんぜんわかります","あまりわかります"],c:0},{q:"Was ist an „あまり好きです“ falsch?",o:["あまり braucht eine Verneinung","あまり steht nur am Satzende","あまり passt nicht zu 好き"],c:0}]},{id:"n4-nara",level:4,title:"〜なら — »wenn (das Thema)« / »was … angeht«",intro:"なら greift ein gerade genanntes Thema auf und knüpft eine Aussage daran. Anders als と・ば・たら geht es nicht um zeitliche Abfolge, sondern um »unter der Annahme / zu diesem Thema«.",text:"Nomen + なら: 日本語なら、田中さんに聞いてください »was Japanisch angeht, frag Herrn Tanaka«. Verb/Adjektiv (Plainform) + なら: 行くなら、朝がいいです »wenn du (schon) gehst, ist der Morgen besser«. Typisch als Reaktion auf das Gesagte des Gegenübers. Kein »danach«-Sinn: dafür たら / てから.",tip:"Merksatz: なら = »falls das so ist / zu dem Thema«. Es setzt oft etwas voraus, was der andere gerade gesagt hat.",ex:[["A:辞書を買いたいです。 B:辞書なら、駅前の店が安いですよ。","A:じしょをかいたいです。 B:じしょなら、えきまえのみせがやすいですよ。","A: Ich möchte ein Wörterbuch kaufen. B: Wörterbuch — da ist der Laden am Bahnhof günstig."],["北海道へ行くなら、飛行機が便利です。","ほっかいどうへいくなら、ひこうきがべんりです。","Wenn du nach Hokkaido fährst, ist das Flugzeug praktisch."],["安いなら、買います。","やすいなら、かいます。","Wenn es günstig ist, kaufe ich es."],["あなたが行かないなら、私も行きません。","あなたがいかないなら、わたしもいきません。","Wenn du nicht gehst, gehe ich auch nicht."]],q:[{q:"»Was Reisen angeht, frag mich.« 旅行___、私に聞いて。",o:["なら","たら","から"],c:0},{q:"なら reagiert typischerweise auf …",o:["das, was der andere gerade gesagt hat","eine feste Uhrzeit","eine abgeschlossene Handlung"],c:0},{q:"»Wenn du gehst, geh früh.«",o:["行くなら、早く行って","行ってから、早く行って","行くと、早く行って"],c:0}]},{id:"n4-meireikei-kinshikei",level:4,title:"命令形・禁止形 — Befehl und Verbot (schroffe Form)",intro:"Der direkte Befehl (命令形) und das direkte Verbot (禁止形) sind sehr schroff. Man produziert sie selbst kaum, muss sie aber verstehen — auf Schildern, in Anleitungen, in zitierter Rede, unter Männern salopp.",text:"命令形: Godan う→え (行く→行け), Ichidan る→ろ (見る→見ろ), する→しろ, 来る→こい. 禁止形: Wörterbuchform + な (行くな, 見るな, するな). Gebrauch: Warnschilder (立入禁止 »Betreten verboten«, 止まれ »Halt«), Sport-Anfeuerung (がんばれ！), indirekt zitiert (「早く来い」と言われた). Höflich sagt man stattdessen 〜てください / 〜ないでください.",tip:"Im Alltag nie unüberlegt benutzen — es klingt wie anschreien. Erkennen reicht für N4.",ex:[["ここに入るな。","ここにはいるな。","Geh hier nicht rein."],["がんばれ！ 負けるな！","がんばれ！ まけるな！","Streng dich an! Gib nicht auf!"],["先生に「もっと勉強しろ」と言われた。","せんせいに「もっとべんきょうしろ」といわれた。","Der Lehrer sagte mir: »Lern mehr!«"],["危ない、止まれ！","あぶない、とまれ！","Vorsicht, halt!"]],q:[{q:"Befehlsform von 行く:",o:["行け","行ろ","行きろ"],c:0},{q:"Verbot »nicht ansehen«:",o:["見るな","見ろな","見ないな"],c:0},{q:"Befehlsform von する:",o:["しろ","すれ","せよろ"],c:0},{q:"Höfliche Entsprechung von 「食べるな」:",o:["食べないでください","食べてください","食べましょう"],c:0}]},{id:"n4-nasai",level:4,title:"〜なさい — milder Befehl (Eltern, Lehrer, Aufgaben)",intro:"〜なさい steht zwischen 〜てください und dem schroffen 命令形: bestimmt, aber nicht grob. Typisch von oben nach unten — Eltern zu Kindern, Lehrer zu Schülern — und auf Prüfungsblättern.",text:"Bildung: ます-Stamm + なさい. 食べます→食べなさい, 見ます→見なさい, します→しなさい, 来ます→きなさい. Nur positiv (für »tu nicht« gibt es kein なさい — dann 〜てはいけません / 〜ないで). Auf Aufgabenblättern: 「正しい答えを選びなさい」 »Wähle die richtige Antwort.«",tip:"Von Gleichrangigen oder zu Höhergestellten klingt なさい herablassend — nur »nach unten« verwenden.",ex:[["早く寝なさい。","はやくねなさい。","Geh früh ins Bett."],["野菜も食べなさい。","やさいもたべなさい。","Iss auch Gemüse."],["次の文を読んで、質問に答えなさい。","つぎのぶんをよんで、しつもんにこたえなさい。","Lies den folgenden Satz und beantworte die Frage."],["宿題をしてから遊びなさい。","しゅくだいをしてからあそびなさい。","Spiel erst, nachdem du die Hausaufgaben gemacht hast."]],q:[{q:"〜なさい bildet man aus …",o:["dem ます-Stamm + なさい","der Wörterbuchform + なさい","der て-Form + なさい"],c:0},{q:"»Steh auf!« (mild, Elternton):",o:["起きなさい","起きるなさい","起きてなさい"],c:0},{q:"Zu wem passt 〜なさい NICHT?",o:["zum eigenen Chef","zum eigenen Kind","zum Schüler"],c:0}]},{id:"n4-sasetekudasai",level:4,title:"〜させてください — »lass mich bitte …« (um Erlaubnis bitten)",intro:"Kausativ + てください: man bittet höflich darum, selbst etwas tun zu dürfen. Sehr häufig im Berufsleben und in Höflichkeitssituationen.",text:"Kausativform (させる-Form) + てください: 行く→行かせてください »lassen Sie mich (bitte) gehen«, 考える→考えさせてください »lassen Sie mich (kurz) überlegen«, する→させてください, 休む→休ませてください. Noch höflicher: 〜させていただけませんか / 〜させていただきます (謙譲). Nicht verwechseln mit 〜てください (jemand anderen bitten, etwas zu tun).",tip:"»Ich will X tun (und bitte um Erlaubnis)« → X in die させる-Form + てください.",ex:[["すみません、少し早く帰らせてください。","すみません、すこしはやくかえらせてください。","Entschuldigung, lassen Sie mich bitte etwas früher gehen."],["その仕事、私にやらせてください。","そのしごと、わたしにやらせてください。","Diese Aufgabe — lassen Sie mich das machen."],["少し考えさせてください。","すこしかんがえさせてください。","Lassen Sie mich kurz überlegen."],["写真を撮らせていただけませんか。","しゃしんをとらせていただけませんか。","Dürfte ich (bitte) ein Foto machen?"]],q:[{q:"»Lassen Sie mich das machen.« (やる)",o:["やらせてください","やってください","やられてください"],c:0},{q:"〜させてください heißt sinngemäß …",o:["Erlaubnis erbitten, selbst etwas zu tun","jemanden bitten, etwas zu tun","etwas verbieten"],c:0},{q:"Noch höflichere Form:",o:["〜させていただけませんか","〜させてはいけませんか","〜させないでください"],c:0}]},{id:"n4-kadouka-gimonshi-ka",level:4,title:"Eingebettete Fragen — 〜かどうか / 疑問詞 + 〜か",intro:"Eine Frage kann als Nebensatz in einen größeren Satz eingebaut werden — nach Verben wie 分かる, 知る, 聞く, 教える, 調べる, 覚える.",text:"Ja/Nein-Frage → 〜かどうか: 来るかどうか分かりません »ich weiß nicht, ob er kommt«. Mit Fragewort → 疑問詞 + 〜か: 何時に来るか分かりません »ich weiß nicht, um wie viel Uhr er kommt«; どこで買ったか教えてください. Der eingebettete Teil steht in der Plainform (だ fällt bei Nomen/な-Adj oft weg: 学生かどうか).",tip:"»ob« ohne Fragewort → かどうか. Mit Fragewort (何/だれ/いつ/どこ/どう …) → einfach + か.",ex:[["田中さんが会議に来るかどうか、知っていますか。","たなかさんがかいぎにくるかどうか、しっていますか。","Weißt du, ob Herr Tanaka zur Besprechung kommt?"],["この漢字を何と読むか教えてください。","このかんじをなんとよむかおしえてください。","Bitte sag mir, wie man dieses Kanji liest."],["パーティーに何人来るか、まだ分かりません。","パーティーになんにんくるか、まだわかりません。","Wie viele Leute zur Party kommen, weiß ich noch nicht."],["その店が今日開いているかどうか、調べます。","そのみせがきょうあいているかどうか、しらべます。","Ich schaue nach, ob der Laden heute geöffnet hat."]],q:[{q:"»Ich weiß nicht, ob er kommt.«",o:["来るかどうか分かりません","来るか分かりません","来るなら分かりません"],c:0},{q:"»Sag mir, wo du es gekauft hast.«",o:["どこで買ったか教えて","どこで買ったかどうか教えて","どこで買ってか教えて"],c:0},{q:"かどうか nimmt man, wenn die Frage …",o:["kein Fragewort hat (ja/nein)","ein Fragewort hat","höflich sein soll"],c:0}]},{id:"n4-yotei",level:4,title:"〜予定だ — geplant / vorgesehen",intro:"予定 (»Plan, Vorhaben«) drückt aus, dass etwas fest eingeplant ist — konkreter und weniger persönlich als 〜つもり (bloße Absicht).",text:"Verb (Wörterbuchform) + 予定です: 来月、京都へ行く予定です. Nomen + の + 予定: 会議は3時からの予定です. Verneint: 〜ない予定です oder 〜予定はありません. Unterschied zu つもり: 予定 = organisatorisch festgelegt (Termin, Fahrplan); つもり = ich habe es mir vorgenommen.",tip:"Terminkalender-Sprache: 出張の予定, 帰る予定. Für »ich hab vor …« aus Bauchgefühl eher つもり.",ex:[["来週、東京へ出張する予定です。","らいしゅう、とうきょうへしゅっちょうするよていです。","Nächste Woche bin ich planmäßig auf Dienstreise in Tokyo."],["飛行機は10時に出発する予定です。","ひこうきはじゅうじにしゅっぱつするよていです。","Das Flugzeug startet planmäßig um 10 Uhr."],["今日は残業する予定はありません。","きょうはざんぎょうするよていはありません。","Für heute sind keine Überstunden vorgesehen."],["パーティーは土曜日の予定です。","パーティーはどようびのよていです。","Die Party ist für Samstag geplant."]],q:[{q:"»Ich fahre planmäßig nach Kyoto.«",o:["京都へ行く予定です","京都へ行った予定です","京都へ行き予定です"],c:0},{q:"Unterschied 予定 vs. つもり:",o:["予定 = organisatorisch festgelegt, つもり = persönliche Absicht","kein Unterschied","つもり ist höflicher"],c:0},{q:"»Die Besprechung ist ab 3 Uhr geplant.« 会議は3時から___です。",o:["の予定","予定","を予定"],c:0}]},{id:"n4-hodo-nai",level:4,title:"〜ほど〜ない — »nicht so … wie«",intro:"Vergleich mit Verneinung: A ist nicht in dem Maße … wie B. Der Bezugspunkt steht vor ほど.",text:"A は B ほど 〜くない / 〜じゃない: 今日は昨日ほど暑くない »heute ist es nicht so heiß wie gestern«. Mit Verb: 私は姉ほど泳げない »ich kann nicht so gut schwimmen wie meine Schwester«. Verwandt, aber positiv: A より B のほうが … (N5). ほど…ない ist immer verneint.",tip:"Reihenfolge merken: »[weniger] は [Vergleich] ほど [Eigenschaft]ない«.",ex:[["今年の冬は去年ほど寒くないです。","ことしのふゆはきょねんほどさむくないです。","Dieser Winter ist nicht so kalt wie letztes Jahr."],["この問題は見た目ほど難しくない。","このもんだいはみためほどむずかしくない。","Diese Aufgabe ist nicht so schwer, wie sie aussieht."],["私は兄ほど背が高くない。","わたしはあにほどせがたかくない。","Ich bin nicht so groß wie mein großer Bruder."],["新しい店は前の店ほど混んでいない。","あたらしいみせはまえのみせほどこんでいない。","Der neue Laden ist nicht so voll wie der alte."]],q:[{q:"»Heute ist es nicht so heiß wie gestern.«",o:["今日は昨日ほど暑くない","今日は昨日より暑くない","今日は昨日ほど暑い"],c:0},{q:"〜ほど〜ない steht immer …",o:["verneint","in der Vergangenheit","mit einer Frage"],c:0},{q:"Positiver Vergleich stattdessen:",o:["〜より〜のほうが","〜ほど〜ない","〜くらい"],c:0}]},{id:"n4-noha-da",level:4,title:"〜のは〜だ — Hervorhebung (Cleft-Satz)",intro:"Mit 〜のは … だ hebt man genau einen Teil eines Satzes hervor: »Das, was …, ist X« / »Es war X, der/die/das …«.",text:"Aus 田中さんが窓を割りました wird je nach Fokus: 窓を割ったのは田中さんです »der, der das Fenster zerbrochen hat, ist Tanaka«; 田中さんが割ったのは窓です »was Tanaka zerbrochen hat, ist das Fenster«. Der Nebensatz endet in der Plainform + の, dann は … です. Häufig in Antworten auf »Wer/Was/Wo/Wann genau …?«.",tip:"Frag dich: welcher Teil ist die Antwort? Genau der kommt hinter のは … だ ans Ende.",ex:[["この写真を撮ったのは私です。","このしゃしんをとったのはわたしです。","Der, der dieses Foto gemacht hat, bin ich."],["私が生まれたのは北海道です。","わたしがうまれたのはほっかいどうです。","Wo ich geboren bin, ist Hokkaido."],["彼に初めて会ったのは去年の夏でした。","かれにはじめてあったのはきょねんのなつでした。","Ich habe ihn zum ersten Mal letzten Sommer getroffen."],["一番大切なのは健康です。","いちばんたいせつなのはけんこうです。","Das Wichtigste ist die Gesundheit."]],q:[{q:"Betone »ICH« in »Ich habe das Foto gemacht«:",o:["写真を撮ったのは私です","私は写真を撮ったのです","写真を私が撮ったです"],c:0},{q:"Der Nebensatz vor のは endet …",o:["in der Plainform + の","in der ます-Form","mit か"],c:0},{q:"〜のは〜だ beantwortet oft eine Frage mit …",o:["Wer / Was / Wo / Wann genau","Wie viele Male","Ob ja oder nein"],c:0}]},{id:"n4-o-ni-naru-o-suru",level:4,title:"お〜になる / お〜する — Keigo produktiv bilden",intro:"Neben den festen Sonderverben (いらっしゃる, なさる, 召し上がる …) gibt es zwei produktive Muster, mit denen man fast jedes Verb höflich macht.",text:"尊敬 (über andere, respektvoll): お + ます-Stamm + になる. 待つ→お待ちになる, 読む→お読みになる. — 謙譲 (über sich selbst, bescheiden): お + ます-Stamm + する / いたす. 持つ→お持ちします »ich trage es (für Sie)«, 送る→お送りします. Bei する-Verben chinesischen Ursprungs meist ご statt お: ご説明します, ご案内します. Sonderverben haben Vorrang, wo es sie gibt (見る→ご覧になる, nicht お見になる).",tip:"お〜になる = der andere handelt (Respekt). お〜する = ich handle für den anderen (Bescheidenheit).",ex:[["社長はもうお帰りになりました。","しゃちょうはもうおかえりになりました。","Der Chef ist bereits gegangen."],["お荷物、お持ちします。","おにもつ、おもちします。","Ich trage Ihr Gepäck."],["先生がお書きになった本を読みました。","せんせいがおかきになったほんをよみました。","Ich habe das Buch gelesen, das der Lehrer geschrieben hat."],["後で私からご説明します。","あとでわたしからごせつめいします。","Ich erkläre es Ihnen später."]],q:[{q:"»Der Kunde wartet.« (respektvoll)",o:["お客様がお待ちになっています","お客様がお待ちしています","お客様が待たれてします"],c:0},{q:"»Ich schicke es Ihnen.« (bescheiden, 送る)",o:["お送りします","お送りになります","送らせます"],c:0},{q:"お〜になる drückt aus, dass …",o:["der andere respektvoll handelt","ich bescheiden handle","etwas verboten ist"],c:0}]},{id:"n3-tsutsuaru",level:3,title:'〜つつある — „im Begriff sein, sich zu wandeln"',intro:"Eine Entwicklung läuft gerade und geht in eine Richtung — nicht der Zustand zählt, sondern die Bewegung.",text:"Verbstamm (ます-Form ohne ます) + つつある. 「経済は回復しつつある。」 Schriftlich und sachlich; gesprochen sagt man eher 〜てきている. Anders als 〜ている beschreibt es keinen Zustand, sondern eine Veränderung, die noch nicht abgeschlossen ist.",tip:"Merkhilfe: 〜ている zeigt ein Foto, 〜つつある einen Film. Deshalb steht es fast immer bei Verben der Veränderung (増える, 減る, 変わる, 進む).",ex:[["日本の人口は減りつつある。","にほんのじんこうはへりつつある。","Japans Bevölkerung ist im Schrumpfen begriffen."],["彼の病気は快方に向かいつつある。","かれのびょうきはかいほうにむかいつつある。","Seine Krankheit bessert sich zusehends."],["この習慣は消えつつある。","このしゅうかんはきえつつある。","Dieser Brauch ist im Verschwinden begriffen."]],q:[{q:"技術は日々進歩＿＿。",o:["しつつある","してつつある","するつつある","したつつある"],c:0},{q:"〜つつある betont …",o:["die laufende Veränderung","den fertigen Zustand","eine Absicht","eine Vermutung"],c:0},{q:"Welcher Stil passt zu 〜つつある?",o:["schriftlich und sachlich","salopp unter Freunden","Befehlston","Kindersprache"],c:0}]},{id:"n3-taraii-toii",level:3,title:'〜たらいい・〜といい — „es wäre gut, wenn"',intro:"Ein Wunsch oder ein Rat, je nachdem, um wessen Sache es geht.",text:"Verb たら/と + いい (höflich: いいです). Für sich selbst ein Wunsch: 「明日晴れるといいなあ。」 Für andere ein Rat: 「早く帰ったらいいですよ。」 Mit 〜ばいい klingt es sachlicher, mit 〜たらいい freundlicher. Der Wunsch für andere endet oft auf 〜といいですね.",tip:"Faustregel: といい für Dinge, die man nicht in der Hand hat (Wetter, Glück), たらいい für Handlungen, die jemand tun könnte.",ex:[["試験に受かるといいですね。","しけんにうかるといいですね。","Schön wäre es, wenn Sie die Prüfung bestehen."],["疲れたら、少し休んだらいいよ。","つかれたら、すこしやすんだらいいよ。","Wenn du müde bist, ruh dich ruhig etwas aus."],["何を買ったらいいか分かりません。","なにをかったらいいかわかりません。","Ich weiß nicht, was ich kaufen soll."]],q:[{q:"明日、雨が降らない＿＿いいですね。",o:["と","を","へ","から"],c:0},{q:"「どうしたらいいですか」 heißt …",o:["Was soll ich tun?","Was hast du getan?","Wer hat das getan?","Wann tust du es?"],c:0},{q:"〜といい passt am besten zu …",o:["etwas, das man nicht steuern kann","einem Befehl","einer Vergangenheit","einer Verneinung"],c:0}]},{id:"n3-aidani",level:3,title:'〜間に・〜間 — „während" (Zeitraum)',intro:"Zwei Aussagen über denselben Zeitraum — mit einem feinen, prüfungsrelevanten Unterschied.",text:"〜間 (ohne に): die Handlung dauert den ganzen Zeitraum an. 「夏休みの間、毎日泳いだ。」 〜間に (mit に): die Handlung passiert irgendwann *innerhalb* des Zeitraums. 「留守の間に、泥棒が入った。」 Vor 間 steht ein Nomen mit の, ein な-Adjektiv mit な oder ein Verb in der Plainform.",tip:"Das に ist der ganze Unterschied: 間 = die ganze Zeit über, 間に = einmal, irgendwann darin. Genau darauf zielen die Prüfungsfragen.",ex:[["母が寝ている間に、宿題を終わらせた。","ははがねているあいだに、しゅくだいをおわらせた。","Während meine Mutter schlief, machte ich die Hausaufgaben fertig."],["日本にいる間、ずっと日本語で話していた。","にほんにいるあいだ、ずっとにほんごではなしていた。","Solange ich in Japan war, habe ich durchgehend Japanisch gesprochen."],["若いうちに、いろいろな所へ行きたい。","わかいうちに、いろいろなところへいきたい。","Solange ich jung bin, möchte ich an viele Orte reisen."]],q:[{q:"会議の＿＿、電話が三回鳴った。",o:["間に","あいだ","うちで","ながら"],c:0},{q:"「留守の間、犬の世話をしてください」 bedeutet: bitte kümmere dich um den Hund …",o:["die ganze Zeit meiner Abwesenheit","einmal irgendwann","bevor ich gehe","nachdem ich zurück bin"],c:0},{q:"Vor 間 steht ein Nomen mit …",o:["の","が","を","に"],c:0}]},{id:"n3-hazuganai",level:3,title:'〜はずがない — „das kann unmöglich sein"',intro:"Die logische Verneinung: nach allem, was man weiß, ist es ausgeschlossen.",text:"Plainform + はずがない (auch 〜はずはない). 「彼がそんなことを言うはずがない。」 Gegenstück zu 〜はずだ. Es geht um Schlussfolgerung, nicht um Gefühl — deshalb braucht es immer einen Grund im Kontext. Neben 〜わけがない steht es fast gleichbedeutend; 〜わけがない klingt eine Spur emotionaler.",tip:'Nicht mit 〜ないはずだ verwechseln: 「来ないはずだ」 = „er wird (nach meinem Wissen) nicht kommen". 「来るはずがない」 = „er kann unmöglich kommen" (ausgeschlossen).',ex:[["あの正直な人が嘘をつくはずがない。","あのしょうじきなひとがうそをつくはずがない。","Ein so ehrlicher Mensch kann unmöglich lügen."],["こんな時間に店が開いているはずがない。","こんなじかんにみせがあいているはずがない。","Um diese Zeit kann der Laden unmöglich offen sein."],["一週間で終わるはずがありません。","いっしゅうかんでおわるはずがありません。","In einer Woche kann das unmöglich fertig werden."]],q:[{q:"彼は今アメリカにいる。ここにいる＿＿。",o:["はずがない","はずだ","ようだ","そうだ"],c:0},{q:"〜はずがない beruht auf …",o:["einer Schlussfolgerung","einem Gefühl","einem Befehl","einer Bitte"],c:0},{q:"「来ないはずだ」 heißt …",o:["er wird eigentlich nicht kommen","er kann unmöglich kommen","er kommt bestimmt","komm nicht!"],c:0}]},{id:"n3-souninai",level:3,title:'〜そうにない・〜そうもない — „es sieht nicht danach aus"',intro:"Die Verneinung des Anscheins: nach allem, was man sieht, wird es wohl nichts.",text:"Verbstamm + そうにない / そうもない / そうにありません. 「この雨は止みそうにない。」 Es ist die Verneinung von 〜そうだ (Anschein), nicht von 〜そうだ (Hörensagen). Bei い-Adjektiven: よさそう → よくなさそう.",tip:"Häufiger Prüfungsfehler: 〜なさそう (das Adjektiv ist verneint) gegen 〜そうにない (der Anschein ist verneint). Bei Verben gilt immer 〜そうにない.",ex:[["今日中に終わりそうにない。","きょうじゅうにおわりそうにない。","Es sieht nicht so aus, als würde es heute noch fertig."],["彼は約束を守りそうもない。","かれはやくそくをまもりそうもない。","Es sieht nicht danach aus, dass er sein Versprechen hält."],["この値段では売れそうにありません。","このねだんではうれそうにありません。","Zu diesem Preis wird sich das wohl nicht verkaufen."]],q:[{q:"電車はすぐには来＿＿。",o:["そうにない","そうだ","そうに","そうな"],c:0},{q:"〜そうにない ist die Verneinung von …",o:["〜そうだ (Anschein)","〜そうだ (Hörensagen)","〜ようだ","〜らしい"],c:0},{q:"Woran hängt 〜そうにない bei Verben?",o:["am Verbstamm","an der Plainform","an der て-Form","an der た-Form"],c:0}]},{id:"n3-temokamawanai",level:3,title:'〜ても構わない — „es macht nichts, wenn"',intro:"Erlaubnis mit einem Schulterzucken: von mir aus, mir ist es gleich.",text:'て-Form + もかまわない (höflich: もかまいません). 「窓を開けてもかまいませんか。」 Fast gleichbedeutend mit 〜てもいい, aber gleichgültiger: 〜てもいい gibt Erlaubnis, 〜てもかまわない sagt, dass es einen nicht stört. Verneint: 〜なくてもかまわない („es muss nicht sein").',tip:"Im Geschäftsleben wirkt 〜てもかまいません höflicher als 〜てもいいです, weil man die eigene Position zurücknimmt statt Erlaubnis zu erteilen.",ex:[["写真を撮ってもかまいませんか。","しゃしんをとってもかまいませんか。","Wäre es in Ordnung, wenn ich fotografiere?"],["明日は来なくてもかまいません。","あしたはこなくてもかまいません。","Sie müssen morgen nicht kommen."],["少し高くてもかまわない。","すこしたかくてもかまわない。","Es macht nichts, wenn es etwas teurer ist."]],q:[{q:"ここに座っ＿＿かまいませんか。",o:["ても","たら","ては","ずに"],c:0},{q:"〜なくてもかまいません heißt …",o:["es muss nicht sein","es ist verboten","es ist Pflicht","es ist unmöglich"],c:0},{q:"Gegenüber 〜てもいいです klingt 〜てもかまいません …",o:["zurückhaltender","strenger","kindlicher","gleich"],c:0}]},{id:"n3-kaneru-kanenai",level:3,title:"〜かねる・〜かねない — zwei Formen, entgegengesetzter Sinn",intro:"Dieselbe Silbe, zwei Bedeutungen, die man nicht verwechseln darf — ein Klassiker der Prüfung.",text:'〜かねる (Verbstamm + かねる) = „nicht können, nicht übers Herz bringen", höflich-ablehnend: 「その件については、お答えしかねます。」 〜かねない (Verbstamm + かねない) = „könnte durchaus (etwas Schlimmes) passieren": 「そんな運転では事故を起こしかねない。」 Beide gehören in die Schriftsprache und in höfliche Rede.',tip:"Eselsbrücke: 〜かねる sagt Nein zu etwas Gutem, 〜かねない sagt Ja zu etwas Schlechtem. 〜かねない steht deshalb fast nur bei unerfreulichen Verben.",ex:[["申し訳ありませんが、承知しかねます。","もうしわけありませんが、しょうちしかねます。","Es tut mir leid, aber dem kann ich nicht zustimmen."],["寝不足は病気につながりかねない。","ねぶそくはびょうきにつながりかねない。","Schlafmangel kann durchaus zu Krankheit führen."],["彼なら本当にやりかねない。","かれならほんとうにやりかねない。","Ihm ist das durchaus zuzutrauen."]],q:[{q:"この方法では失敗を招き＿＿。",o:["かねない","かねる","かねます","かねた"],c:0},{q:"「お答えしかねます」 heißt …",o:["darauf kann ich nicht antworten","ich antworte gleich","ich habe geantwortet","antworte bitte"],c:0},{q:"〜かねない steht meist bei …",o:["unerfreulichen Folgen","guten Nachrichten","Befehlen","Höflichkeitsfloskeln"],c:0}]},{id:"n3-niyoruto",level:3,title:'〜によると・〜によれば — „laut / wie … berichtet"',intro:"Die Quelle einer Information nennen — die Standardeinleitung jedes Nachrichtentexts.",text:"Nomen + によると / によれば, und am Satzende steht fast immer 〜そうだ, 〜ということだ oder 〜らしい. 「天気予報によると、明日は雨だそうです。」 Ohne diese Endung klingt der Satz unfertig; genau das wird in der Prüfung abgefragt.",tip:"Paarregel: によると … そうだ. Wer die Quelle nennt, muss auch kennzeichnen, dass es fremdes Wissen ist.",ex:[["新聞によると、来月から値上げされるそうだ。","しんぶんによると、らいげつからねあげされるそうだ。","Laut Zeitung wird es ab nächstem Monat teurer."],["彼の話によれば、会議は中止になったということだ。","かれのはなしによれば、かいぎはちゅうしになったということだ。","Seiner Erzählung nach wurde die Sitzung abgesagt."],["調査によると、若者の読書時間が減っている。","ちょうさによると、わかもののどくしょじかんがへっている。","Einer Untersuchung zufolge sinkt die Lesezeit junger Leute."]],q:[{q:"ニュース＿＿、地震があったそうだ。",o:["によると","について","にとって","に対して"],c:0},{q:"Womit endet ein Satz mit 〜によると typischerweise?",o:["〜そうだ","〜たい","〜ましょう","〜ください"],c:0},{q:"〜によれば ist gegenüber 〜によると …",o:["etwas schriftlicher","salopper","ein Befehl","eine Frage"],c:0}]},{id:"n3-sonkeigo-tokubetsu",level:3,title:"尊敬語 — die Sonderverben (いらっしゃる・おっしゃる・召し上がる)",intro:"Für die häufigsten Verben gibt es eigene Respektformen. Sie ersetzen お〜になる und müssen sitzen.",text:"いる・行く・来る → いらっしゃる. 言う → おっしゃる. 食べる・飲む → 召し上がる. 見る → ご覧になる. する → なさる. 知っている → ご存じだ. くれる → くださる. Die ます-Formen sind unregelmäßig: いらっしゃいます, おっしゃいます, なさいます, くださいます (kein 〜り!).",tip:"Die fünf Verben auf 〜る mit unregelmäßiger ます-Form (いらっしゃる, おっしゃる, なさる, くださる, ござる) sind der ganze Sonderfall. Wer sie kann, kann 尊敬語.",ex:[["先生はもうお帰りになりましたか。","せんせいはもうおかえりになりましたか。","Ist der Lehrer schon nach Hause gegangen?"],["社長は明日大阪へいらっしゃいます。","しゃちょうはあしたおおさかへいらっしゃいます。","Der Geschäftsführer fährt morgen nach Osaka."],["どうぞ召し上がってください。","どうぞめしあがってください。","Bitte greifen Sie zu."]],q:[{q:"先生が「明日来る」→ 尊敬語 では …",o:["いらっしゃいます","まいります","おります","いたします"],c:0},{q:"「言う」 の尊敬語 は …",o:["おっしゃる","申す","伺う","存じる"],c:0},{q:"なさる の ます形 は …",o:["なさいます","なさります","なされます","なしいます"],c:0}]},{id:"n3-kenjougo-tokubetsu",level:3,title:"謙譲語 — die Sonderverben (伺う・申す・いたす・拝見する)",intro:"Über sich selbst spricht man kleiner. Auch hier gibt es feste Sonderformen.",text:"行く・来る・聞く・尋ねる → 伺う. 言う → 申す / 申し上げる. する → いたす. 見る → 拝見する. いる → おる. 食べる・飲む・もらう → いただく. 知っている → 存じております. あげる → 差し上げる. 会う → お目にかかる.",tip:'Falle: 伺う deckt drei Verben ab (gehen, kommen, fragen) — welches gemeint ist, sagt nur der Kontext. 「明日伺います」 = „ich komme morgen vorbei".',ex:[["明日、三時に伺います。","あした、さんじにうかがいます。","Ich komme morgen um drei vorbei."],["田中と申します。","たなかともうします。","Mein Name ist Tanaka."],["お手紙、拝見しました。","おてがみ、はいけんしました。","Ich habe Ihren Brief gelesen."]],q:[{q:"自分が「見る」→ 謙譲語 では …",o:["拝見する","ご覧になる","召し上がる","なさる"],c:0},{q:"「伺う」 が表せないのは …",o:["食べる","行く","来る","聞く"],c:0},{q:"「する」 の謙譲語 は …",o:["いたす","なさる","おっしゃる","くださる"],c:0}]},{id:"n3-teineigo-gozaimasu",level:3,title:"丁寧語 — ございます und でございます",intro:"Die dritte Säule: nicht der Handelnde wird erhöht, sondern die Rede selbst wird gehoben.",text:"ある → ございます, です → でございます. 「二階に売り場がございます。」 「こちらが新商品でございます。」 Es erhöht niemanden — deshalb ist es auch für eigene Dinge richtig, wo 尊敬語 falsch wäre. Typisch für Läden, Hotels, Durchsagen und Telefonate.",tip:"Grenze beachten: でございます macht die Rede förmlich, nicht den Gesprächspartner respektvoll. Über den eigenen Chef sagt man gegenüber Kunden 「おりません」, nicht 「いらっしゃいません」.",ex:[["お手洗いは二階にございます。","おてあらいはにかいにございます。","Die Toilette befindet sich im ersten Stock."],["こちらがメニューでございます。","こちらがメニューでございます。","Hier ist die Speisekarte."],["ただいま担当者はおりません。","ただいまたんとうしゃはおりません。","Der zuständige Mitarbeiter ist derzeit nicht da."]],q:[{q:"「あります」 のより丁寧な形は …",o:["ございます","いらっしゃいます","おります","なさいます"],c:0},{q:"丁寧語 erhöht …",o:["die Rede selbst","den Gesprächspartner","den eigenen Chef","den Sprecher"],c:0},{q:"Wo hört man でございます am häufigsten?",o:["im Laden und am Telefon","unter Freunden","in Kinderbüchern","in Tagebüchern"],c:0}]},{id:"n3-uchi-soto",level:3,title:"Keigo im Betrieb: 内 und 外 — wen erhöht man wem gegenüber?",intro:"Die Regel, an der Keigo im Alltag scheitert: nicht der Rang entscheidet, sondern die Gruppe.",text:"Wer zur eigenen Gruppe gehört (内: eigene Firma, eigene Familie), wird gegenüber Außenstehenden (外: Kunden, fremde Firmen) NICHT erhöht — auch der eigene Chef nicht. Gegenüber dem Kunden: 「社長の田中はただいま外出しております。」 (謙譲語, ohne 〜さん). Innerhalb der Firma dagegen: 「社長は外出していらっしゃいます。」 Dieselbe Person, zwei Formen.",tip:"Fragen Sie sich vor jedem Keigo-Satz zuerst: Wer hört zu? Erst die Gruppengrenze, dann der Rang. Genau darauf zielen die N3-Hörverstehensaufgaben mit Telefonaten.",ex:[["（客に）部長の山田は席を外しております。","（きゃくに）ぶちょうのやまだはせきをはずしております。","(zum Kunden) Abteilungsleiter Yamada ist gerade nicht am Platz."],["（社内で）部長は会議にいらっしゃいます。","（しゃないで）ぶちょうはかいぎにいらっしゃいます。","(intern) Der Abteilungsleiter ist in einer Besprechung."],["母は今、出かけております。","はははいま、でかけております。","Meine Mutter ist gerade außer Haus."]],q:[{q:"客に自分の上司のことを話すとき、使うのは …",o:["謙譲語","尊敬語","命令形","普通形"],c:0},{q:"（客に）「田中部長はいらっしゃいません」 は …",o:["誤り","正しい","丁寧すぎる","古い言い方"],c:0},{q:"Was entscheidet zuerst über die Keigo-Wahl?",o:["die Gruppengrenze 内／外","das Alter","die Uhrzeit","das Geschlecht"],c:0}]},{id:"n3-njanai",level:3,title:'〜んじゃない？ — „ist das nicht …?" (Umgangssprache)',intro:"Eine vorsichtige Behauptung im Frageton — in gesprochenem Japanisch überall.",text:"Plainform + んじゃない？ (bzw. 〜んじゃないですか). 「もう遅いんじゃない？」 Der Sprecher glaubt etwas, will es aber nicht als Feststellung hinstellen. Mit steigender Intonation ist es eine Vermutung, mit fallender ein sanfter Einwand. Formeller: 〜のではないでしょうか.",tip:'Nicht mit der echten Verneinung verwechseln: 「行かないんじゃない？」 heißt „er geht wohl nicht, oder?" — nicht „geht er nicht?".',ex:[["この店、閉まってるんじゃない？","このみせ、しまってるんじゃない？","Der Laden hat doch bestimmt zu, oder?"],["それはちょっと高いんじゃないですか。","それはちょっとたかいんじゃないですか。","Ist das nicht ein bisschen teuer?"],["彼、もう帰ったんじゃないかな。","かれ、もうかえったんじゃないかな。","Er ist wohl schon nach Hause, denke ich."]],q:[{q:"雨が降る＿＿じゃない？",o:["ん","の","こと","もの"],c:0},{q:"〜んじゃない？ drückt aus …",o:["eine vorsichtige Vermutung","einen Befehl","eine Bitte","ein Verbot"],c:0},{q:"Die formelle Entsprechung ist …",o:["〜のではないでしょうか","〜てください","〜なさい","〜ましょう"],c:0}]},{id:"n3-chau-jau",level:3,title:"〜ちゃう・〜じゃう — die Kurzform von 〜てしまう",intro:"Gesprochenes Japanisch zieht zusammen. Wer das nicht kennt, versteht Hörtexte nicht.",text:"〜てしまう → 〜ちゃう, 〜でしまう → 〜じゃう. 「忘れちゃった。」 = 「忘れてしまった。」 Vergangenheit: 〜ちゃった / 〜じゃった. Die beiden Bedeutungen bleiben: etwas ganz zu Ende bringen oder etwas versehentlich tun. Regel: た-Form auf 〜て → ちゃう, auf 〜で → じゃう (飲んで → 飲んじゃう).",tip:"Dieselbe Zusammenziehung steckt in 〜なくちゃ (aus 〜なくてはいけない). Wer 〜ちゃう erkennt, erkennt auch das.",ex:[["ケーキ、全部食べちゃった。","ケーキ、ぜんぶたべちゃった。","Ich habe den ganzen Kuchen aufgegessen."],["財布をなくしちゃったんです。","さいふをなくしちゃったんです。","Ich habe leider mein Portemonnaie verloren."],["早く飲んじゃおう。","はやくのんじゃおう。","Trinken wir es schnell aus."]],q:[{q:"「読んでしまった」 のくだけた形は …",o:["読んじゃった","読んちゃった","読みちゃった","読んでちゃった"],c:0},{q:"〜ちゃう bedeutet nicht …",o:["einen Befehl geben","etwas versehentlich tun","etwas ganz zu Ende bringen","etwas bedauern"],c:0},{q:"Nach einer て-Form auf 〜で steht …",o:["じゃう","ちゃう","しゃう","ぢゃう"],c:0}]},{id:"n3-toku",level:3,title:"〜とく — die Kurzform von 〜ておく",intro:"Die zweite große Zusammenziehung des gesprochenen Japanisch.",text:'〜ておく → 〜とく, 〜でおく → 〜どく. 「買っとくね。」 = 「買っておくね。」 Vergangenheit: 〜といた / 〜どいた. Die Bedeutung bleibt: etwas im Voraus erledigen oder etwas so belassen. Häufig im Imperativ unter Freunden: 「言っといて。」 („Sag ihm Bescheid.")',tip:'Zusammen mit 〜ちゃう deckt 〜とく den größten Teil dessen ab, was Lernende in Hörtexten „nicht kennen". Beides ist keine neue Grammatik, nur schneller gesprochene alte.',ex:[["チケットを買っときます。","チケットをかっときます。","Ich kaufe die Karten schon mal."],["ここに置いといてください。","ここにおいといてください。","Lassen Sie es bitte hier liegen."],["先生に伝えといたよ。","せんせいにつたえといたよ。","Ich hab’s dem Lehrer schon ausgerichtet."]],q:[{q:"「予約しておく」 のくだけた形は …",o:["予約しとく","予約しちゃう","予約してく","予約しどく"],c:0},{q:"〜とく bedeutet …",o:["im Voraus erledigen","versehentlich tun","gerade dabei sein","nicht tun dürfen"],c:0},{q:"「読んでおく」 のくだけた形は …",o:["読んどく","読んとく","読みとく","読んでく"],c:0}]},{id:"n2-kanaikanouchini",level:2,title:'〜か〜ないかのうちに — „kaum … da schon"',intro:"Zwei Ereignisse fallen fast zusammen: das erste ist noch nicht ganz vorbei, da beginnt das zweite.",text:"Verb (Wörterbuchform) + か + dieselbe Verbform verneint + かのうちに. 「ベルが鳴るか鳴らないかのうちに、生徒たちは教室を出て行った。」 Der zweite Satzteil steht meist in der Vergangenheit und beschreibt etwas tatsächlich Geschehenes — keine Absicht, kein Befehl.",tip:"Nah an 〜とたんに, aber noch enger: bei 〜とたんに ist das erste Ereignis abgeschlossen, hier ist es das nicht einmal ganz.",ex:[["試合が終わるか終わらないかのうちに、雨が降り出した。","しあいがおわるかおわらないかのうちに、あめがふりだした。","Kaum war das Spiel zu Ende, da fing es an zu regnen."],["彼は座るか座らないかのうちに、話し始めた。","かれはすわるかすわらないかのうちに、はなしはじめた。","Kaum hatte er sich gesetzt, fing er schon an zu reden."],["ドアを開けるか開けないかのうちに、猫が飛び出した。","ドアをあけるかあけないかのうちに、ねこがとびだした。","Kaum hatte ich die Tür geöffnet, sprang die Katze heraus."]],q:[{q:"ベルが鳴る＿＿鳴らないかのうちに、彼は出て行った。",o:["か","と","も","は"],c:0},{q:"〜か〜ないかのうちに beschreibt …",o:["zwei fast gleichzeitige Ereignisse","eine Absicht","einen Befehl","eine Bedingung"],c:0},{q:"Der zweite Satzteil steht meist …",o:["in der Vergangenheit","im Imperativ","in der Verneinung","in der Höflichkeitsform"],c:0}]},{id:"n2-tekaratoiumono",level:2,title:'〜てからというもの — „seitdem … (und seither ist es anders)"',intro:"Ein Wendepunkt: seit diesem Ereignis hat sich etwas dauerhaft verändert.",text:"て-Form + からというもの. 「引っ越してからというもの、体調がよくなった。」 Anders als das schlichte 〜てから betont es die andauernde Folge und die persönliche Betroffenheit. Schriftlich und in Erzählungen zu Hause, nicht in einer Terminabsprache.",tip:'Merkhilfe: 〜てから nennt einen Zeitpunkt, 〜てからというもの eine Zeitrechnung — „seit damals ist alles anders".',ex:[["日本に来てからというもの、毎日が新しい発見だ。","にほんにきてからというもの、まいにちがあたらしいはっけんだ。","Seit ich nach Japan kam, ist jeder Tag eine neue Entdeckung."],["犬を飼ってからというもの、朝の散歩が習慣になった。","いぬをかってからというもの、あさのさんぽがしゅうかんになった。","Seit wir einen Hund haben, ist der Morgenspaziergang zur Gewohnheit geworden."],["あの事故があってからというもの、彼は運転しなくなった。","あのじこがあってからというもの、かれはうんてんしなくなった。","Seit jenem Unfall fährt er nicht mehr Auto."]],q:[{q:"手術をし＿＿というもの、体が軽くなった。",o:["てから","たから","るから","ないから"],c:0},{q:"〜てからというもの betont gegenüber 〜てから …",o:["die andauernde Folge","den genauen Zeitpunkt","eine Bedingung","einen Zweck"],c:0},{q:"Der Stil ist eher …",o:["erzählend und schriftlich","amtlich","befehlend","kindlich"],c:0}]},{id:"n2-nisakidatte",level:2,title:'〜に先立って — „im Vorfeld von, vor (einem Vorhaben)"',intro:"Etwas geschieht als Vorbereitung, bevor ein größeres Ereignis beginnt.",text:"Nomen + に先立って / に先立ち / に先立つ. 「開店に先立って、記者会見が行われた。」 Nur bei geplanten, bedeutsameren Ereignissen — nicht für alltägliche Reihenfolgen. Dafür steht 〜前に.",tip:'Faustregel: 〜前に kann alles, 〜に先立って nur Vorhaben mit Gewicht. „Vor dem Frühstück" ist nie 朝食に先立って.',ex:[["出発に先立って、注意事項をご説明します。","しゅっぱつにさきだって、ちゅういじこうをごせつめいします。","Vor der Abreise erläutern wir Ihnen die Hinweise."],["試合に先立ち、国歌が演奏された。","しあいにさきだち、こっかがえんそうされた。","Vor dem Spiel wurde die Nationalhymne gespielt."],["工事に先立つ調査が行われた。","こうじにさきだつちょうさがおこなわれた。","Es wurde eine dem Bau vorausgehende Untersuchung durchgeführt."]],q:[{q:"会議＿＿先立って、資料が配られた。",o:["に","を","が","で"],c:0},{q:"Welcher Satz passt NICHT?",o:["朝食に先立って歯を磨く","開会に先立って挨拶する","出発に先立って点検する","試験に先立って説明する"],c:0},{q:"〜に先立って steht bei …",o:["geplanten, bedeutsamen Ereignissen","alltäglichen Handlungen","Verboten","Wünschen"],c:0}]},{id:"n2-wokini",level:2,title:'〜を機に・〜を契機に — „zum Anlass nehmen"',intro:"Ein Ereignis ist der Auslöser für eine bewusste Veränderung.",text:"Nomen + を機に / を契機に(して) / を契機として. 「結婚を機に、田舎に引っ越した。」 Der zweite Satzteil ist meist eine Entscheidung des Sprechers. 〜を契機に klingt förmlicher als 〜を機に.",tip:"Unterschied zu 〜をきっかけに: dort kann der Auslöser zufällig sein, hier wird er bewusst ergriffen — man nimmt ihn zum Anlass.",ex:[["入院を機に、たばこをやめた。","にゅういんをきに、たばこをやめた。","Den Krankenhausaufenthalt nahm ich zum Anlass, mit dem Rauchen aufzuhören."],["転職を契機に、生活のリズムが変わった。","てんしょくをけいきに、せいかつのリズムがかわった。","Mit dem Stellenwechsel änderte sich mein Lebensrhythmus."],["この事件を契機として、法律が改正された。","このじけんをけいきとして、ほうりつがかいせいされた。","Dieser Vorfall war der Anlass für eine Gesetzesänderung."]],q:[{q:"就職＿＿機に、一人暮らしを始めた。",o:["を","に","が","で"],c:0},{q:"〜を機に unterscheidet sich von 〜をきっかけに durch …",o:["die bewusste Entscheidung danach","die Zeitform","die Höflichkeit","die Wortart"],c:0},{q:"〜を契機に ist gegenüber 〜を機に …",o:["förmlicher","salopper","älter","seltener falsch"],c:0}]},{id:"n2-sai",level:2,title:'〜際(に) — „bei Gelegenheit von, wenn" (förmlich)',intro:"Die förmliche Entsprechung von 〜とき: bei einer bestimmten Gelegenheit.",text:'Nomen + の際 / Verb (Wörterbuch- oder た-Form) + 際(に). 「お帰りの際は、電気をお消しください。」 Gehört in Durchsagen, Aushänge und Geschäftsbriefe. Für alltägliche Zeitangaben („als ich klein war") ist es zu steif.',tip:"Achtung: 〜際 beschreibt eine Gelegenheit, keinen Zeitpunkt in der Vergangenheit. 「子どもの際」 ist falsch — dort steht 子どものとき.",ex:[["ご利用の際は、こちらにご記入ください。","ごりようのさいは、こちらにごきにゅうください。","Bei der Nutzung tragen Sie sich bitte hier ein."],["地震の際には、まず身の安全を確保してください。","じしんのさいには、まずみのあんぜんをかくほしてください。","Sorgen Sie bei einem Erdbeben zuerst für Ihre Sicherheit."],["お申し込みの際に、身分証をご提示ください。","おもうしこみのさいに、みぶんしょうをごていじください。","Legen Sie bei der Anmeldung bitte einen Ausweis vor."]],q:[{q:"ご来店＿＿際は、会員証をお持ちください。",o:["の","を","が","に"],c:0},{q:"Wo hört man 〜際 am häufigsten?",o:["in Durchsagen und Aushängen","unter Freunden","in Kinderbüchern","in Tagebüchern"],c:0},{q:"「子どもの際」 ist …",o:["falsch — richtig ist 子どものとき","richtig und höflich","nur schriftlich richtig","veraltet, aber korrekt"],c:0}]},{id:"n2-saichuuni",level:2,title:'〜最中に — „mitten in, gerade während"',intro:"Etwas unterbricht eine Handlung, die gerade auf ihrem Höhepunkt ist.",text:"Nomen + の最中に / Verb ている + 最中に. 「食事の最中に電話が鳴った。」 Fast immer folgt etwas Störendes oder Unerwartetes — das ist der Kern dieser Wendung.",tip:'Unterschied zu 〜間に: das ist neutral („irgendwann während"). 〜最中に heißt „ausgerechnet mittendrin" und trägt Ärger mit.',ex:[["会議の最中に、携帯が鳴ってしまった。","かいぎのさいちゅうに、けいたいがなってしまった。","Mitten in der Sitzung klingelte mein Handy."],["話している最中に、口をはさまないでください。","はなしているさいちゅうに、くちをはさまないでください。","Fallen Sie mir bitte nicht mitten im Reden ins Wort."],["試験の最中に停電が起きた。","しけんのさいちゅうにていでんがおきた。","Mitten in der Prüfung fiel der Strom aus."]],q:[{q:"発表の＿＿にマイクが止まった。",o:["最中","以来","以上","以前"],c:0},{q:"Was folgt auf 〜最中に typischerweise?",o:["etwas Störendes","ein Wunsch","ein Befehl","eine Bitte"],c:0},{q:"Gegenüber 〜間に trägt 〜最中に …",o:["einen Beiklang von Ärger","mehr Höflichkeit","weniger Bedeutung","eine Zeitangabe"],c:0}]},{id:"n2-kotodashi",level:2,title:'〜ことだし — „zumal ja …, da nun einmal"',intro:"Ein Grund unter mehreren wird genannt, oft als sanfte Rechtfertigung.",text:"Plainform + ことだし. 「天気もいいことだし、散歩でもしようか。」 Der Sprecher deutet an, dass es noch weitere Gründe gäbe — deshalb steht oft も dabei. Gesprochene, freundliche Sprache.",tip:"Merkhilfe: 〜から nennt DEN Grund, 〜ことだし nennt EINEN Grund und lässt die anderen offen.",ex:[["もう遅いことだし、そろそろ失礼します。","もうおそいことだし、そろそろしつれいします。","Es ist ja auch schon spät, ich mache mich langsam auf den Weg."],["雨も止んだことだし、出かけようか。","あめもやんだことだし、でかけようか。","Der Regen hat ja auch aufgehört — wollen wir raus?"],["試験も終わったことだし、少し休みたい。","しけんもおわったことだし、すこしやすみたい。","Die Prüfungen sind ja auch vorbei, ich möchte etwas ausruhen."]],q:[{q:"時間もある＿＿、ゆっくり話そう。",o:["ことだし","ものだし","ところだし","わけだし"],c:0},{q:"Welches Partikel steht oft mit 〜ことだし?",o:["も","を","へ","と"],c:0},{q:"〜ことだし nennt …",o:["einen Grund unter mehreren","den einzigen Grund","eine Bedingung","einen Zweck"],c:0}]},{id:"n2-yueni",level:2,title:'〜ゆえに — „daher, aus diesem Grunde" (gehoben)',intro:"Die schriftsprachliche Form der Begründung — in Aufsätzen, Gutachten, Gesetzestexten.",text:"Nomen + (の)ゆえに / Plainform + ゆえに. 「経験不足ゆえに、判断を誤った。」 Sehr förmlich; im Gespräch wirkt es gestelzt. Auch als 〜ゆえの vor einem Nomen: 「若さゆえの過ち」.",tip:"Stilfrage, keine Bedeutungsfrage: 〜から (gesprochen) → 〜ので (neutral) → 〜ため (schriftlich) → 〜ゆえに (gehoben).",ex:[["準備不足ゆえに、計画は失敗に終わった。","じゅんびぶそくゆえに、けいかくはしっぱいにおわった。","Aus Mangel an Vorbereitung endete der Plan im Scheitern."],["若さゆえの過ちだったと思う。","わかさゆえのあやまちだったとおもう。","Ich denke, es war ein Fehler aus Jugend."],["貧しさゆえに学校へ行けない子どもがいる。","まずしさゆえにがっこうへいけないこどもがいる。","Es gibt Kinder, die aus Armut nicht zur Schule gehen können."]],q:[{q:"経験の浅さ＿＿に、失敗した。",o:["ゆえ","ため","ので","から"],c:0},{q:"Vor einem Nomen heißt es …",o:["〜ゆえの","〜ゆえに","〜ゆえで","〜ゆえと"],c:0},{q:"Der Stil von 〜ゆえに ist …",o:["gehoben und schriftlich","umgangssprachlich","kindlich","befehlend"],c:0}]},{id:"n2-tokoroga",level:2,title:'〜ところが — „doch dann, wider Erwarten"',intro:"Ein Satzverbinder für die Enttäuschung einer Erwartung.",text:"Steht am Satzanfang: 「早めに家を出た。ところが、電車が遅れて遅刻した。」 Anders als しかし (schlichter Gegensatz) drückt ところが aus, dass etwas anders kam, als man annehmen musste. Der Folgesatz steht fast immer in der Vergangenheit.",tip:'Nicht mit 〜たところ verwechseln: das ist „als ich es tat, stellte sich heraus". ところが verbindet zwei Sätze.',ex:[["薬を飲んだ。ところが、熱は下がらなかった。","くすりをのんだ。ところが、ねつはさがらなかった。","Ich nahm das Medikament. Doch das Fieber sank nicht."],["安いと思って買った。ところが、すぐ壊れてしまった。","やすいとおもってかった。ところが、すぐこわれてしまった。","Ich kaufte es, weil ich es günstig fand. Doch es ging sofort kaputt."],["雨は降らないと言われていた。ところが、大雨になった。","あめはふらないといわれていた。ところが、おおあめになった。","Es hieß, es würde nicht regnen. Doch es kam ein Wolkenbruch."]],q:[{q:"早く着いた。＿＿、店は閉まっていた。",o:["ところが","ところで","ところに","ところを"],c:0},{q:"ところが drückt aus …",o:["eine enttäuschte Erwartung","einen Zweck","eine Reihenfolge","einen Wunsch"],c:0},{q:"Der Folgesatz steht meist …",o:["in der Vergangenheit","im Imperativ","in der Verneinung","in der Zukunft"],c:0}]},{id:"n2-toittemo",level:2,title:'〜といっても — „auch wenn man sagt … (in Wahrheit)"',intro:"Ein Wort wird gebraucht, aber gleich relativiert: so groß ist die Sache nicht.",text:"Nomen / Plainform + といっても. 「料理といっても、卵を焼いただけです。」 Es korrigiert die Vorstellung, die der Hörer sich gerade macht — fast immer nach unten.",tip:"Häufig mit だけ, ただ oder ちょっと im Folgesatz: 「旅行といっても、一泊だけです。」",ex:[["日本語が話せるといっても、簡単な会話だけです。","にほんごがはなせるといっても、かんたんなかいわだけです。","Auch wenn ich sage, ich spreche Japanisch — nur einfache Gespräche."],["家といっても、小さなアパートです。","いえといっても、ちいさなアパートです。","Ein Haus — na ja, eine kleine Wohnung."],["忙しいといっても、休む時間はある。","いそがしいといっても、やすむじかんはある。","Auch wenn ich sage, ich sei beschäftigt: Zeit zum Ausruhen habe ich."]],q:[{q:"社長＿＿、社員は三人だけだ。",o:["といっても","といえば","というと","といって"],c:0},{q:"〜といっても korrigiert die Vorstellung meist …",o:["nach unten","nach oben","gar nicht","ins Gegenteil"],c:0},{q:"Was steht oft im Folgesatz?",o:["だけ","ばかり","こそ","さえ"],c:0}]},{id:"n2-taragosaigo",level:2,title:'〜たら最後・〜が最後 — „wenn erst einmal …, dann ist es vorbei"',intro:"Eine Warnung: ist der Schritt getan, gibt es kein Zurück.",text:"た-Form + ら最後 / が最後. 「あの人に話したら最後、翌日には全員が知っている。」 Der Folgesatz beschreibt eine unausweichliche, meist unerwünschte Folge — oft mit 必ず oder もう.",tip:'Merkhilfe: 最後 heißt hier nicht „zuletzt", sondern „damit ist Schluss". Die Wendung trägt immer eine Warnung.',ex:[["この本を読み始めたら最後、夜中まで止まらない。","このほんをよみはじめたらさいご、よなかまでとまらない。","Wenn ich dieses Buch erst einmal anfange, höre ich bis Mitternacht nicht auf."],["一度約束したが最後、断ることはできない。","いちどやくそくしたがさいご、ことわることはできない。","Hat man erst zugesagt, kann man nicht mehr absagen."],["彼に鍵を渡したら最後、返ってこないだろう。","かれにかぎをわたしたらさいご、かえってこないだろう。","Gibt man ihm erst den Schlüssel, kommt er wohl nie zurück."]],q:[{q:"始め＿＿最後、途中でやめられない。",o:["たら","ると","れば","ても"],c:0},{q:"Der Folgesatz ist meist …",o:["unausweichlich und unerwünscht","erfreulich","unsicher","höflich"],c:0},{q:"最後 bedeutet hier …",o:["damit ist es endgültig","als Letztes","am Ende der Reihe","zum Schluss"],c:0}]},{id:"n2-naikotoniwa",level:2,title:'〜ないことには — „ohne dass …, geht es nicht"',intro:"Eine notwendige Bedingung: erst muss dies geschehen, sonst ist alles Weitere sinnlos.",text:"Verb ない-Form + ことには + Verneinung. 「実際に見ないことには、判断できない。」 Der Folgesatz ist fast immer verneint — das gehört zur Struktur.",tip:'Merkhilfe: die doppelte Verneinung ist Absicht — „ohne X nicht Y". Vergisst man die Verneinung hinten, wird der Satz falsch.',ex:[["やってみないことには、分からない。","やってみないことには、わからない。","Ohne es zu versuchen, weiß man es nicht."],["資料がそろわないことには、始められません。","しりょうがそろわないことには、はじめられません。","Solange die Unterlagen nicht vollständig sind, können wir nicht anfangen."],["彼に会わないことには、話が進まない。","かれにあわないことには、はなしがすすまない。","Ohne ihn zu treffen, kommen wir nicht weiter."]],q:[{q:"食べてみ＿＿ことには、味は分からない。",o:["ない","た","る","て"],c:0},{q:"Der Folgesatz steht …",o:["verneint","im Imperativ","in der Vergangenheit","als Frage"],c:0},{q:"〜ないことには nennt …",o:["eine notwendige Bedingung","einen Zweck","eine Folge","einen Vergleich"],c:0}]},{id:"n2-nisotte",level:2,title:'〜に沿って — „entlang, gemäß"',intro:"Zwei Bilder in einem Ausdruck: räumlich am Rand entlang, übertragen einer Vorgabe folgend.",text:"Nomen + に沿って / に沿う / に沿った. 「川に沿って歩く」 (räumlich) — 「方針に沿って進める」 (übertragen). Im übertragenen Sinn steht es bei Richtlinien, Plänen, Wünschen.",tip:'Verwandt, aber verschieden: 〜に従って heißt „gehorchend", 〜に沿って „im Einklang mit". Einem Wunsch folgt man 沿って, einem Befehl 従って.',ex:[["道に沿って桜が植えられている。","みちにそってさくらがうえられている。","Entlang der Straße sind Kirschbäume gepflanzt."],["ご希望に沿えるよう努力いたします。","ごきぼうにそえるようどりょくいたします。","Wir bemühen uns, Ihrem Wunsch zu entsprechen."],["計画に沿った形で進めています。","けいかくにそったかたちですすめています。","Wir gehen in einer dem Plan entsprechenden Weise vor."]],q:[{q:"海岸＿＿沿って走る道。",o:["に","を","が","で"],c:0},{q:"〜に沿って im übertragenen Sinn steht bei …",o:["Richtlinien und Wünschen","Verboten","Zahlen","Personen"],c:0},{q:"Einem Befehl folgt man eher mit …",o:["〜に従って","〜に沿って","〜に基づいて","〜に応じて"],c:0}]},{id:"n2-nishitara",level:2,title:'〜にしたら・〜にすれば — „aus der Sicht von"',intro:"Der Standpunkt einer anderen Person — meist, um Verständnis für sie zu wecken.",text:"Nomen (Person) + にしたら / にすれば / にしても. 「親にしたら、心配なのは当然だ。」 Steht fast nur bei Personen und meist mit einem Gefühl oder Urteil im Folgesatz.",tip:'Unterschied zu 〜にとって: das ist neutral („für jemanden"). 〜にしたら nimmt den Standpunkt ein und verteidigt ihn oft.',ex:[["子どもにしたら、大人の話は退屈だろう。","こどもにしたら、おとなのはなしはたいくつだろう。","Aus Sicht eines Kindes sind Erwachsenengespräche wohl langweilig."],["彼にすれば、断るしかなかったのだ。","かれにすれば、ことわるしかなかったのだ。","Aus seiner Sicht blieb ihm nichts übrig, als abzulehnen."],["外国人にしたら、この習慣は不思議に見える。","がいこくじんにしたら、このしゅうかんはふしぎにみえる。","Für Ausländer wirkt dieser Brauch sonderbar."]],q:[{q:"先生＿＿すれば、当然の判断だった。",o:["に","を","が","で"],c:0},{q:"〜にしたら steht fast nur bei …",o:["Personen","Orten","Zeiten","Zahlen"],c:0},{q:"Gegenüber 〜にとって ist 〜にしたら …",o:["parteiischer","neutraler","förmlicher","kürzer"],c:0}]},{id:"n2-nitomonatte",level:2,title:'〜に伴って — „einhergehend mit, infolge"',intro:"Zwei Entwicklungen laufen gekoppelt: verändert sich die eine, verändert sich die andere mit.",text:"Nomen + に伴って / に伴い / に伴う. 「人口の増加に伴って、住宅が不足している。」 Schriftsprachlich, typisch für Berichte und Statistiken. Beide Seiten sind Veränderungen, keine einzelnen Handlungen.",tip:"Nah an 〜につれて, aber förmlicher und häufiger mit Nomen. 〜に伴って ist formeller und steht oft bei größeren Entwicklungen (Gesellschaft, Wirtschaft, Technik).",ex:[["気温の上昇に伴って、電力の需要が増えた。","きおんのじょうしょうにともなって、でんりょくのじゅようがふえた。","Mit dem Temperaturanstieg stieg der Strombedarf."],["技術の進歩に伴い、生活が便利になった。","ぎじゅつのしんぽにともない、せいかつがべんりになった。","Mit dem technischen Fortschritt wurde das Leben bequemer."],["都市化に伴う問題が指摘されている。","としかにともなうもんだいがしていされている。","Auf die mit der Verstädterung einhergehenden Probleme wird hingewiesen."]],q:[{q:"経済の発展＿＿伴って、環境問題も生じた。",o:["に","を","が","と"],c:0},{q:"Beide Seiten von 〜に伴って sind …",o:["Veränderungen","Personen","Orte","Befehle"],c:0},{q:"Der Stil ist …",o:["schriftsprachlich","salopp","kindlich","befehlend"],c:0}]},{id:"n2-wochuushinni",level:2,title:'〜を中心に — „mit … als Mittelpunkt, schwerpunktmäßig"',intro:"Etwas steht im Zentrum — räumlich, thematisch oder personell.",text:"Nomen + を中心に / を中心として / を中心とした. 「若者を中心に人気が広がっている。」 Bezeichnet den Schwerpunkt, nicht die Gesamtheit: andere sind nicht ausgeschlossen.",tip:'Wichtig für Prüfungstexte: 「学生を中心に」 heißt „vor allem unter Studierenden", nicht „nur unter Studierenden".',ex:[["この地域を中心に調査が行われた。","このちいきをちゅうしんにちょうさがおこなわれた。","Die Untersuchung wurde schwerpunktmäßig in dieser Gegend durchgeführt."],["駅前を中心として商店街が発展した。","えきまえをちゅうしんとしてしょうてんがいがはってんした。","Rund um den Bahnhofsvorplatz entwickelte sich eine Geschäftsstraße."],["若い世代を中心に支持を集めている。","わかいせだいをちゅうしんにしじをあつめている。","Vor allem in der jungen Generation findet es Zuspruch."]],q:[{q:"首都＿＿中心に人口が集まっている。",o:["を","に","が","で"],c:0},{q:"「学生を中心に」 heißt …",o:["vor allem unter Studierenden","nur unter Studierenden","außer Studierenden","gegen Studierende"],c:0},{q:"Vor einem Nomen steht …",o:["を中心とした","を中心に","を中心で","を中心が"],c:0}]},{id:"n2-nikagitte",level:2,title:'〜に限って・〜に限らず — „ausgerechnet" und „nicht nur"',intro:"Dieselbe Wurzel, zwei sehr verschiedene Bedeutungen — ein beliebter Prüfungsfall.",text:'〜に限って: „ausgerechnet dann/der", meist mit Ärger — 「急いでいる日に限って、電車が遅れる。」 Auch als Vertrauensbekundung: 「うちの子に限って、そんなことはしない。」 〜に限らず: „nicht nur … (sondern auch)" — 「若者に限らず、高齢者にも人気だ。」',tip:'Eselsbrücke: 限って grenzt EIN („genau der"), 限らず hebt die Grenze AUF („nicht nur der").',ex:[["約束のある日に限って、残業になる。","やくそくのあるひにかぎって、ざんぎょうになる。","Ausgerechnet an Tagen mit Verabredung gibt es Überstunden."],["彼に限って、うそをつくはずがない。","かれにかぎって、うそをつくはずがない。","Gerade er würde niemals lügen."],["日本に限らず、世界中で問題になっている。","にほんにかぎらず、せかいじゅうでもんだいになっている。","Nicht nur in Japan, weltweit ist es ein Problem."]],q:[{q:"忙しい日＿＿限って、来客が多い。",o:["に","を","が","で"],c:0},{q:"〜に限らず heißt …",o:["nicht nur","ausgerechnet","niemals","höchstens"],c:0},{q:"「うちの子に限って」 drückt aus …",o:["Vertrauen","Ärger","Zweifel","Gleichgültigkeit"],c:0}]},{id:"n2-nikimatteiru",level:2,title:'〜に決まっている — „das ist doch klar, ganz bestimmt"',intro:"Eine feste Überzeugung des Sprechers — ohne Beweis, aber ohne Zweifel.",text:"Plainform (な-Adj und Nomen ohne だ) + に決まっている. 「そんな話、うそに決まっている。」 Gesprochene Sprache und stärker als 〜に違いない: dort schließt man, hier weiß man es einfach.",tip:'Nicht mit 〜ことになっている verwechseln (Regel/Absprache). 決まっている allein heißt „ist festgelegt"; erst 〜に決まっている ist die Überzeugung.',ex:[["あんなに練習したのだから、勝つに決まっている。","あんなにれんしゅうしたのだから、かつにきまっている。","Nach so viel Training gewinnen wir doch bestimmt."],["この時間なら、道は混んでいるに決まっている。","このじかんなら、みちはこんでいるにきまっている。","Um diese Zeit ist die Straße doch bestimmt voll."],["彼が知らないはずがない。知っているに決まっている。","かれがしらないはずがない。しっているにきまっている。","Er kann es unmöglich nicht wissen. Er weiß es ganz sicher."]],q:[{q:"こんな安い店、まずい＿＿決まっている。",o:["に","と","が","を"],c:0},{q:"Gegenüber 〜に違いない ist 〜に決まっている …",o:["stärker und gesprochener","schwächer","förmlicher","unsicherer"],c:0},{q:"〜ことになっている bedeutet dagegen …",o:["es ist so festgelegt","es ist bestimmt so","es ist unmöglich","es ist erlaubt"],c:0}]},{id:"n2-nisouinai",level:2,title:'〜に相違ない — „zweifellos" (schriftlich)',intro:"Die schriftsprachliche Schwester von 〜に違いない.",text:"Plainform + に相違ない. 「犯人はこの部屋にいたに相違ない。」 Man findet es in Gutachten, Urteilen und älterer Literatur; im Gespräch klingt es theatralisch.",tip:"Reihe der Sicherheit, von schwach nach stark: 〜かもしれない → 〜だろう → 〜に違いない → 〜に相違ない (gleich stark, nur förmlicher).",ex:[["この筆跡は本人のものに相違ない。","このひっせきはほんにんのものにそういない。","Diese Handschrift stammt zweifellos von ihm selbst."],["彼が関与していたに相違ない。","かれがかんよしていたにそういない。","Er war zweifellos beteiligt."],["当時、状況は厳しかったに相違ない。","とうじ、じょうきょうはきびしかったにそういない。","Die Lage war damals zweifellos schwierig."]],q:[{q:"証拠から見て、事故だった＿＿相違ない。",o:["に","と","が","は"],c:0},{q:"〜に相違ない unterscheidet sich von 〜に違いない durch …",o:["den Stil","die Bedeutung","die Zeitform","die Wortart"],c:0},{q:"Wo findet man es?",o:["in Gutachten und Urteilen","im Gespräch","in Kinderbüchern","in Werbung"],c:0}]},{id:"n2-monoka",level:2,title:'〜ものか — „niemals! / von wegen"',intro:"Eine rhetorische Frage, die eine entschiedene Ablehnung ist.",text:"Plainform + ものか / もんか (salopp). 「あんな店、二度と行くものか。」 Es ist keine echte Frage: der Sprecher weist etwas empört zurück. Höflich: 〜ものですか.",tip:'Merkhilfe: die Frageform macht es stärker, nicht schwächer. 「行くものか」 heißt nicht „gehe ich?", sondern „ich gehe ganz sicher nicht".',ex:[["あんな人に負けるものか。","あんなひとにまけるものか。","Gegen so jemanden verliere ich doch nie!"],["こんな話、信じられるものですか。","こんなはなし、しんじられるものですか。","So etwas kann man doch unmöglich glauben."],["二度と遅刻するもんか。","にどとちこくするもんか。","Ich komme ganz sicher nie wieder zu spät."]],q:[{q:"あんな失礼な店、行く＿＿。",o:["ものか","ものだ","ものの","ものなら"],c:0},{q:"〜ものか ist …",o:["eine entschiedene Ablehnung","eine echte Frage","eine Bitte","ein Vorschlag"],c:0},{q:"Die höfliche Form lautet …",o:["〜ものですか","〜ものでした","〜ものです","〜ものでして"],c:0}]},{id:"n2-uru",level:2,title:'〜得る・〜得ない — „möglich" und „undenkbar"',intro:'Die schriftsprachliche Möglichkeitsform: nicht „ich kann", sondern „es ist möglich".',text:"Verbstamm + 得る (える oder うる) / 得ない (えない). 「そんなことは起こり得ない。」 Es geht um die grundsätzliche Möglichkeit, nicht um persönliches Können — dafür bleibt die Potentialform. Die Verneinung wird nur えない gelesen.",tip:"Lesefalle: 得る wird als Verb 「える」 gelesen, aber in der Verbindung oft 「うる」 — beides ist richtig. 得ない ist immer 「えない」.",ex:[["それは十分あり得る話だ。","それはじゅうぶんありうるはなしだ。","Das ist durchaus möglich."],["この方法では解決し得ない。","このほうほうではかいけつしえない。","Auf diesem Weg lässt es sich nicht lösen."],["考え得るかぎりの手段を試した。","かんがえうるかぎりのしゅだんをためした。","Wir haben alle denkbaren Mittel versucht."]],q:[{q:"そんな偶然は起こり＿＿。",o:["得ない","得らない","得れない","得ずない"],c:0},{q:"〜得る beschreibt …",o:["die grundsätzliche Möglichkeit","persönliches Können","eine Erlaubnis","eine Pflicht"],c:0},{q:"Die Verneinung wird gelesen als …",o:["えない","うない","とくない","えらない"],c:0}]},{id:"n2-wamochiron",level:2,title:'〜はもちろん・〜はもとより — „ganz zu schweigen von"',intro:"Das Selbstverständliche wird genannt, um das Erstaunlichere danach zu betonen.",text:"Nomen + はもちろん / はもとより + Nomen + も. 「この店は味はもちろん、値段も手ごろだ。」 はもとより ist die schriftsprachliche Fassung. Der zweite Teil trägt fast immer も.",tip:'Aufbau merken: „A ist ohnehin klar — und B kommt auch noch dazu." Fehlt das も im zweiten Teil, klingt der Satz unfertig.',ex:[["彼は英語はもちろん、中国語も話せる。","かれはえいごはもちろん、ちゅうごくごもはなせる。","Er spricht selbstverständlich Englisch, aber auch Chinesisch."],["子どもはもとより、大人も楽しめる映画だ。","こどもはもとより、おとなもたのしめるえいがだ。","Ein Film, den nicht nur Kinder, sondern auch Erwachsene genießen."],["土日はもちろん、平日も混んでいる。","どにちはもちろん、へいじつもこんでいる。","Am Wochenende sowieso, aber auch werktags ist es voll."]],q:[{q:"味はもちろん、見た目＿＿すばらしい。",o:["も","は","を","が"],c:0},{q:"〜はもとより ist gegenüber 〜はもちろん …",o:["schriftsprachlicher","saloppe","schwächer","älter und falsch"],c:0},{q:"Der erste Teil nennt …",o:["das Selbstverständliche","das Überraschende","eine Bedingung","einen Grund"],c:0}]},{id:"n2-nikagiru",level:2,title:'〜に限る — „nichts geht über"',intro:"Eine persönliche Empfehlung in Bestform: das ist das Beste.",text:"Nomen / Verb (Wörterbuchform oder ない-Form) + に限る. 「疲れたときは寝るに限る。」 Es ist eine subjektive Wertung, kein objektiver Vergleich — deshalb steht es meist ohne Begründung.",tip:'Nicht mit 〜に限って verwechseln („ausgerechnet"). 〜に限る empfiehlt, 〜に限って ärgert sich.',ex:[["夏はやっぱりビールに限る。","なつはやっぱりビールにかぎる。","Im Sommer geht doch nichts über ein Bier."],["風邪のときは早く寝るに限る。","かぜのときははやくねるにかぎる。","Bei einer Erkältung geht nichts über frühes Schlafengehen."],["危ないところには近づかないに限る。","あぶないところにはちかづかないにかぎる。","Gefährlichen Orten bleibt man am besten fern."]],q:[{q:"暑い日はかき氷＿＿限る。",o:["に","を","が","で"],c:0},{q:"〜に限る ist …",o:["eine persönliche Empfehlung","ein objektiver Vergleich","ein Verbot","eine Bedingung"],c:0},{q:"〜に限って heißt dagegen …",o:["ausgerechnet","am besten","niemals","nur wenn"],c:0}]},{id:"n2-toiuyori",level:2,title:'〜というより — „eher … als"',intro:"Zwei Beschreibungen werden gegeneinander abgewogen; die zweite trifft es besser.",text:"Plainform / Nomen + というより + (むしろ) + Alternative. 「彼は厳しいというより、細かい人だ。」 Oft mit むしろ verstärkt. Beide Beschreibungen sind denkbar — die zweite ist nur genauer.",tip:'Merkhilfe: nicht „falsch gegen richtig", sondern „ungenau gegen genau". Deshalb passt むしろ so gut dazu.',ex:[["あれは料理というより、芸術だ。","あれはりょうりというより、げいじゅつだ。","Das ist eher Kunst als Kochen."],["疲れたというより、眠いだけです。","つかれたというより、ねむいだけです。","Ich bin weniger müde als vielmehr schläfrig."],["寒いというより、むしろ痛いくらいだ。","さむいというより、むしろいたいくらいだ。","Es ist weniger kalt als vielmehr schon fast schmerzhaft."]],q:[{q:"彼は優しい＿＿、弱いのだと思う。",o:["というより","というと","といえば","といっても"],c:0},{q:"Welches Wort steht oft dabei?",o:["むしろ","まさか","せっかく","たとえ"],c:0},{q:"Die zweite Beschreibung ist …",o:["genauer","falsch","höflicher","älter"],c:0}]},{id:"n2-mademonai",level:2,title:'〜までもない — „nicht der Rede wert, erübrigt sich"',intro:"Etwas ist so selbstverständlich oder so gering, dass der Aufwand sich nicht lohnt.",text:'Verb (Wörterbuchform) + までもない. 「言うまでもなく、健康が一番だ。」 「病院へ行くまでもない、ただの擦り傷だ。」 Häufig als feste Wendung 言うまでもない („selbstverständlich").',tip:'Unterschied zu 〜ことはない („es besteht kein Anlass, sich zu sorgen"): 〜までもない sagt, der Aufwand wäre übertrieben.',ex:[["言うまでもなく、締め切りは守るべきだ。","いうまでもなく、しめきりはまもるべきだ。","Selbstverständlich sollte man Fristen einhalten."],["小さな傷だから、病院へ行くまでもない。","ちいさなきずだから、びょういんへいくまでもない。","Es ist nur eine kleine Wunde, ein Arztbesuch erübrigt sich."],["わざわざ確認するまでもないだろう。","わざわざかくにんするまでもないだろう。","Extra nachfragen muss man wohl nicht."]],q:[{q:"説明する＿＿もない、簡単な話だ。",o:["まで","こと","ため","もの"],c:0},{q:"「言うまでもない」 heißt …",o:["selbstverständlich","unaussprechlich","unerhört","unnötig zu fragen"],c:0},{q:"〜までもない sagt, der Aufwand wäre …",o:["übertrieben","zu gering","gefährlich","verboten"],c:0}]},{id:"n2-bakarida",level:2,title:'〜ばかりだ — „es wird nur immer noch …"',intro:"Eine Entwicklung läuft in eine Richtung weiter, und zwar meist in die schlechte.",text:"Verb (Wörterbuchform) + ばかりだ. 「病状は悪くなるばかりだ。」 Nur bei Verben der Veränderung, und fast immer bei unerwünschten. Nicht mit 〜たばかり (gerade eben getan) verwechseln.",tip:'Zwei Verwandte: 〜一方だ ist neutral („nimmt stetig zu"), 〜ばかりだ klagt.',ex:[["物価は上がるばかりだ。","ぶっかはあがるばかりだ。","Die Preise steigen nur immer weiter."],["待っていても、状況は悪くなるばかりだった。","まっていても、じょうきょうはわるくなるばかりだった。","Auch beim Warten wurde die Lage nur schlimmer."],["彼との距離は開くばかりだ。","かれとのきょりはひらくばかりだ。","Der Abstand zu ihm wird nur immer größer."]],q:[{q:"人口は減る＿＿だ。",o:["ばかり","たばかり","ばかりに","ばかりか"],c:0},{q:"〜ばかりだ steht meist bei …",o:["unerwünschten Entwicklungen","erfreulichen Nachrichten","Befehlen","Bitten"],c:0},{q:"〜一方だ ist dagegen …",o:["neutral","stärker klagend","höflicher","seltener"],c:0}]},{id:"n2-ippouda",level:2,title:'〜一方だ — „nimmt stetig zu / ab"',intro:"Eine einseitige, anhaltende Entwicklung — sachlich festgestellt.",text:'Verb (Wörterbuchform) + 一方だ. 「高齢化は進む一方だ。」 Typisch für Berichte und Statistiken. Nicht zu verwechseln mit 〜一方(で) („einerseits … andererseits").',tip:"Merkhilfe: dasselbe Wort, zwei Muster. Mit で davor ist es ein Gegensatz, ohne で eine Entwicklung.",ex:[["都市の人口は増える一方だ。","としのじんこうはふえるいっぽうだ。","Die Stadtbevölkerung nimmt stetig zu."],["彼の技術は上達する一方だ。","かれのぎじゅつはじょうたつするいっぽうだ。","Sein Können wird immer besser."],["森林は減る一方で、対策が急がれる。","しんりんはへるいっぽうで、たいさくがいそがれる。","Die Wälder schwinden stetig, Maßnahmen sind dringend."]],q:[{q:"生活費は上がる＿＿だ。",o:["一方","一度","一部","一般"],c:0},{q:"〜一方(で) mit で bedeutet …",o:["einerseits … andererseits","stetige Zunahme","einen Grund","eine Bedingung"],c:0},{q:"Der Ton von 〜一方だ ist …",o:["sachlich","klagend","freudig","ironisch"],c:0}]},{id:"n2-kake",level:2,title:'〜かけ・〜かける — „angefangen, aber nicht zu Ende"',intro:"Eine Handlung ist begonnen und steckengeblieben — oder sie setzt gerade ein.",text:'Verbstamm + かける / かけの / かけだ. 「読みかけの本」 „ein angefangenes Buch". Auch: 「言いかけてやめた」 „ich setzte an, etwas zu sagen, und ließ es". Bei 死ぬ heißt 死にかける „dem Tod nahe sein".',tip:"Vor einem Nomen steht immer かけの: 食べかけのパン, 書きかけの手紙.",ex:[["読みかけの本が机の上にある。","よみかけのほんがつくえのうえにある。","Auf dem Tisch liegt ein angefangenes Buch."],["何か言いかけて、彼は黙った。","なにかいいかけて、かれはだまった。","Er setzte an, etwas zu sagen, und verstummte."],["食べかけのまま置いてはいけません。","たべかけのままおいてはいけません。","Man darf es nicht angebissen liegen lassen."]],q:[{q:"書き＿＿の手紙が見つかった。",o:["かけ","かかり","かける","かかる"],c:0},{q:"「言いかけてやめた」 heißt …",o:["er setzte an und ließ es","er sagte es zu Ende","er rief laut","er sagte nichts"],c:0},{q:"Vor einem Nomen steht …",o:["かけの","かける","かけて","かけに"],c:0}]},{id:"n2-toiukotoda",level:2,title:'〜ということだ — „es heißt, dass" und „das bedeutet also"',intro:"Zwei Bedeutungen, die der Zusammenhang trennt: fremde Auskunft oder eigene Schlussfolgerung.",text:"Plainform + ということだ. Als Hörensagen: 「彼は来月帰国するということだ。」 (oft mit 〜によると). Als Schlussfolgerung: 「返事がないということは、断られたということだ。」",tip:"Erkennungshilfe: steht eine Quelle im Satz, ist es Hörensagen. Steht davor ein Sachverhalt, den man deutet, ist es die Schlussfolgerung.",ex:[["天気予報によると、明日は雪だということだ。","てんきよほうによると、あしたはゆきだということだ。","Laut Wettervorhersage soll es morgen schneien."],["つまり、時間がないということですね。","つまり、じかんがないということですね。","Das heißt also, Sie haben keine Zeit."],["彼が来ないということは、何かあったのだろう。","かれがこないということは、なにかあったのだろう。","Dass er nicht kommt, heißt wohl, dass etwas passiert ist."]],q:[{q:"新聞によると、値上げされる＿＿ことだ。",o:["という","といった","というの","というもの"],c:0},{q:"Woran erkennt man das Hörensagen?",o:["an einer genannten Quelle","an der Zeitform","an der Höflichkeit","an der Länge"],c:0},{q:"「つまり…ということだ」 ist …",o:["eine Schlussfolgerung","ein Zitat","eine Frage","eine Bitte"],c:0}]},{id:"n2-toiumonodewanai",level:2,title:'〜というものではない — „so einfach ist es nicht"',intro:"Eine verbreitete Annahme wird zurückgewiesen: so pauschal stimmt das nicht.",text:'Plainform + というものではない / というものでもない. 「高ければいいというものではない。」 Fast immer nach einer Bedingung — der Sprecher widerspricht der Gleichung „wenn A, dann automatisch gut".',tip:"Aufbau merken: 〜ば / 〜たら + いい + というものではない. Diese Kette ist die häufigste Form in Prüfungstexten.",ex:[["たくさん勉強すれば合格するというものではない。","たくさんべんきょうすればごうかくするというものではない。","Es ist nicht so, dass man mit viel Lernen automatisch besteht."],["安ければいいというものでもない。","やすければいいというものでもない。","Billig allein ist eben auch nicht gut."],["謝れば済むというものではない。","あやまればすむというものではない。","Mit einer Entschuldigung ist es nicht getan."]],q:[{q:"新しければいい＿＿ものではない。",o:["という","といった","というの","というと"],c:0},{q:"Was steht typischerweise davor?",o:["eine Bedingung mit 〜ば","ein Befehl","eine Frage","ein Zitat"],c:0},{q:"Der Sprecher …",o:["widerspricht einer Pauschalannahme","stimmt zu","fragt nach","befiehlt"],c:0}]},{id:"n2-monogaaru",level:2,title:'〜ものがある — „es hat etwas von, es ist schon …"',intro:"Ein Eindruck wird vorsichtig, aber nachdrücklich formuliert.",text:"い-Adjektiv / な-Adjektiv (な) / Verb (Wörterbuchform) + ものがある. 「彼の演奏には心を打つものがある。」 Es benennt eine Qualität, die man spürt, aber schwer belegen kann. Schriftlich und in Kritiken.",tip:"Nicht bei nüchternen Tatsachen: 「この部屋は広いものがある」 ist falsch. Es braucht einen Eindruck, kein Maß.",ex:[["彼女の文章には、人を引きつけるものがある。","かのじょのぶんしょうには、ひとをひきつけるものがある。","Ihre Texte haben etwas Fesselndes."],["この結果には、驚くべきものがある。","このけっかには、おどろくべきものがある。","Dieses Ergebnis hat etwas Erstaunliches."],["彼の成長には目を見張るものがある。","かれのせいちょうにはめをみはるものがある。","Seine Entwicklung ist bemerkenswert."]],q:[{q:"その絵には人を感動させる＿＿がある。",o:["もの","こと","ところ","わけ"],c:0},{q:"〜ものがある benennt …",o:["einen schwer belegbaren Eindruck","eine messbare Größe","eine Absicht","eine Pflicht"],c:0},{q:"Welcher Satz ist falsch?",o:["この部屋は広いものがある","心を打つものがある","驚くべきものがある","見張るものがある"],c:0}]},{id:"n2-kotoninatteiru",level:2,title:'〜ことになっている — „es ist so geregelt"',intro:"Eine Regel, ein Plan oder eine Absprache, die nicht vom Sprecher stammt.",text:'Plainform + ことになっている. 「会議は毎週月曜に行うことになっている。」 Anders als 〜ことになった (die Entscheidung fiel) beschreibt es den geltenden Zustand. Verneint: 〜ないことになっている („es ist nicht vorgesehen").',tip:"Unterschied zu 〜ことにしている: das ist die eigene Gewohnheit. 〜ことになっている ist von außen gesetzt.",ex:[["この部屋では飲食できないことになっている。","このへやではいんしょくできないことになっている。","In diesem Raum ist Essen und Trinken nicht vorgesehen."],["新入社員は研修を受けることになっている。","しんにゅうしゃいんはけんしゅうをうけることになっている。","Neue Mitarbeitende nehmen an einer Schulung teil — so ist es geregelt."],["明日、彼と会うことになっている。","あした、かれとあうことになっている。","Es ist abgemacht, dass ich ihn morgen treffe."]],q:[{q:"八時までに集合する＿＿なっている。",o:["ことに","ように","ものに","ところに"],c:0},{q:"〜ことにしている beschreibt dagegen …",o:["die eigene Gewohnheit","eine Vorschrift","einen Zufall","eine Bitte"],c:0},{q:"〜ことになっている ist …",o:["von außen gesetzt","selbst beschlossen","unsicher","verboten"],c:0}]},{id:"n2-dokorodewanai",level:2,title:'〜どころではない — „an … ist gar nicht zu denken"',intro:"Die Lage lässt etwas nicht zu, das sonst naheläge.",text:'Nomen / Verb (Wörterbuchform) + どころではない. 「仕事が忙しくて、旅行どころではない。」 Meist steht davor ein Grund. Nicht mit 〜どころか verwechseln („weit gefehlt, im Gegenteil").',tip:'Unterscheidung: 〜どころではない sagt „dafür ist jetzt keine Lage", 〜どころか korrigiert eine Annahme ins Gegenteil.',ex:[["締め切り前で、休むどころではない。","しめきりまえで、やすむどころではない。","Kurz vor der Abgabe ist an Ausruhen nicht zu denken."],["地震の直後で、花見どころではなかった。","じしんのちょくごで、はなみどころではなかった。","Direkt nach dem Beben war an Kirschblütenschau nicht zu denken."],["熱があって、勉強どころではありません。","ねつがあって、べんきょうどころではありません。","Ich habe Fieber, an Lernen ist nicht zu denken."]],q:[{q:"忙しくて、食事＿＿ではない。",o:["どころ","ところ","こそ","ばかり"],c:0},{q:"〜どころか bedeutet dagegen …",o:["weit gefehlt, im Gegenteil","keine Lage dafür","nur wenn","sobald"],c:0},{q:"Davor steht meist …",o:["ein Grund","ein Befehl","eine Frage","ein Zitat"],c:0}]},{id:"n2-sueni",level:2,title:'〜末(に) — „nach langem … schließlich"',intro:"Ein längerer Prozess führt am Ende zu einem Ergebnis.",text:"Nomen + の末(に) / Verb た-Form + 末(に). 「長時間の議論の末、結論が出た。」 Der Weg dorthin war mühsam oder lang — das gehört zur Bedeutung. Das Ergebnis kann gut oder schlecht sein.",tip:"Unterschied zu 〜あげく: dort ist das Ergebnis fast immer schlecht. 〜末に ist neutral und betont die Dauer.",ex:[["迷った末に、彼は留学を決めた。","まよったすえに、かれはりゅうがくをきめた。","Nach langem Zögern entschied er sich fürs Auslandsstudium."],["三年の努力の末、資格を取った。","さんねんのどりょくのすえ、しかくをとった。","Nach drei Jahren Mühe erwarb er die Qualifikation."],["話し合いの末、計画は中止となった。","はなしあいのすえ、けいかくはちゅうしとなった。","Nach langen Gesprächen wurde der Plan eingestellt."]],q:[{q:"長い議論の＿＿、結論が出た。",o:["末","間","中","前"],c:0},{q:"〜あげく unterscheidet sich durch …",o:["das meist schlechte Ergebnis","die Zeitform","die Höflichkeit","die Wortart"],c:0},{q:"〜末に betont …",o:["die Länge des Wegs","die Plötzlichkeit","die Absicht","die Bedingung"],c:0}]},{id:"n2-womotte",level:2,title:'〜をもって — „mit, zum Zeitpunkt von" (amtlich)',intro:"Amtssprache: ein Mittel oder ein Stichtag wird genannt.",text:"Nomen + をもって. Als Stichtag: 「本日をもって閉店いたします。」 Als Mittel: 「書面をもってお知らせします。」 Nur in Bekanntmachungen, Verträgen und Reden — im Gespräch klingt es fremd.",tip:'Merkhilfe: wo im Deutschen „mit Wirkung zum" oder „auf dem Wege der" stünde, steht japanisch をもって.',ex:[["三月三十一日をもって、営業を終了いたします。","さんがつさんじゅういちにちをもって、えいぎょうをしゅうりょういたします。","Mit Ablauf des 31. März stellen wir den Betrieb ein."],["結果は書面をもってお知らせいたします。","けっかはしょめんをもっておしらせいたします。","Das Ergebnis teilen wir Ihnen schriftlich mit."],["これをもちまして、閉会といたします。","これをもちまして、へいかいといたします。","Hiermit schließe ich die Versammlung."]],q:[{q:"本日＿＿もって受付を終了します。",o:["を","に","が","で"],c:0},{q:"Wo hört man 〜をもって?",o:["in Bekanntmachungen und Reden","unter Freunden","in Kinderbüchern","in Comics"],c:0},{q:"Es nennt …",o:["einen Stichtag oder ein Mittel","einen Grund","eine Bedingung","einen Wunsch"],c:0}]},{id:"n2-wotowazu",level:2,title:'〜を問わず — „unabhängig von, gleich welche"',intro:"Ein Merkmal spielt keine Rolle — typische Formel in Ausschreibungen.",text:"Nomen + を問わず. 「経験の有無を問わず、応募できます。」 Steht bei Gegensatzpaaren oder Kategorien: 男女, 年齢, 経験の有無, 昼夜. Nicht bei einzelnen Personen.",tip:"Nah an 〜にかかわらず, aber enger: 〜を問わず steht fast nur bei Kategorien, 〜にかかわらず auch bei Bedingungen und Umständen.",ex:[["年齢を問わず、どなたでも参加できます。","ねんれいをとわず、どなたでもさんかできます。","Unabhängig vom Alter kann jede und jeder teilnehmen."],["昼夜を問わず対応いたします。","ちゅうやをとわずたいおういたします。","Wir sind rund um die Uhr für Sie da."],["経験の有無を問わず歓迎します。","けいけんのうむをとわずかんげいします。","Mit oder ohne Erfahrung — Sie sind willkommen."]],q:[{q:"国籍＿＿問わず応募できる。",o:["を","に","が","は"],c:0},{q:"〜を問わず steht bei …",o:["Kategorien und Gegensatzpaaren","einzelnen Personen","Uhrzeiten","Orten"],c:0},{q:"Wo findet man es am häufigsten?",o:["in Ausschreibungen","in Tagebüchern","in Gesprächen","in Liedern"],c:0}]},{id:"n2-watomokaku",level:2,title:'〜はともかく — „ganz gleich, wie es damit steht"',intro:"Ein Punkt wird beiseitegeschoben, um zum Wichtigeren zu kommen.",text:"Nomen + はともかく(として). 「値段はともかく、デザインは気に入った。」 Das Beiseitegeschobene ist nicht unwichtig — es soll nur jetzt nicht diskutiert werden.",tip:"Unterschied zu 〜はもちろん: das nennt das Selbstverständliche, um mehr hinzuzufügen. 〜はともかく legt etwas zur Seite.",ex:[["結果はともかく、よく頑張ったと思う。","けっかはともかく、よくがんばったとおもう。","Vom Ergebnis einmal abgesehen, hast du dich gut geschlagen."],["味はともかくとして、量は多い。","あじはともかくとして、りょうはおおい。","Über den Geschmack lässt sich streiten, aber die Menge stimmt."],["理由はともかく、遅刻は遅刻だ。","りゆうはともかく、ちこくはちこくだ。","Der Grund sei dahingestellt — zu spät ist zu spät."]],q:[{q:"値段＿＿ともかく、品質はいい。",o:["は","を","が","に"],c:0},{q:"Das Beiseitegeschobene ist …",o:["jetzt nicht das Thema","völlig unwichtig","das Wichtigste","verboten"],c:0},{q:"〜はもちろん bedeutet dagegen …",o:["das ist ohnehin klar","das lassen wir beiseite","das ist falsch","das ist neu"],c:0}]},{id:"n1-gahayaika",level:1,title:"〜が早いか — kaum … da schon",intro:"Zwei Handlungen stoßen hart aneinander: die zweite beginnt im selben Augenblick, in dem die erste endet.",text:"Verb in der Wörterbuchform + が早いか. Der zweite Teil steht fast immer in der Vergangenheit und beschreibt etwas, das tatsächlich geschehen ist — keine Absicht, keine Aufforderung. Schriftsprachlich und leicht dramatisch; in der Alltagssprache sagt man eher 〜とたんに.",tip:"Nah an 〜や否や, aber 〜が早いか betont stärker die Schnelligkeit der handelnden Person. Nicht mit dem Adjektiv 早い verwechseln: hier ist が早いか eine feste Fügung.",ex:[["彼はベルが鳴るが早いか、教室を飛び出した。","かれはベルがなるがはやいか、きょうしつをとびだした。","Kaum hatte es geklingelt, stürmte er aus dem Klassenzimmer."],["席に着くが早いか、彼女は書類を広げた。","せきにつくがはやいか、かのじょはしょるいをひろげた。","Kaum saß sie, breitete sie schon die Unterlagen aus."],["店が開くが早いか、客がなだれ込んだ。","みせがひらくがはやいか、きゃくがなだれこんだ。","Kaum öffnete der Laden, strömten die Kunden herein."]],q:[{q:"彼はドアを開ける＿＿、外へ走り出した。",o:["が早いか","が早くて","を早いか","は早いか"],c:0},{q:"〜が早いか steht meist mit …",o:["einem Geschehen in der Vergangenheit","einer Bitte","einem Vorschlag","einer Verneinung"],c:0},{q:"Welcher Ausdruck liegt am nächsten?",o:["〜や否や","〜ばかりに","〜どころか","〜にすぎない"],c:0}]},{id:"n1-yainaya",level:1,title:"〜や否や — im selben Moment, als",intro:"Schriftsprachliche Fügung für zwei Ereignisse, zwischen denen keine Zeit liegt.",text:"Verb in der Wörterbuchform + や否や (auch verkürzt zu 〜や). Der Folgesatz nennt ein Geschehen, keine Absicht. や否や gehört in geschriebene Berichte und Erzählungen; gesprochen wirkt es gehoben bis literarisch.",tip:"Sehr nah an 〜が早いか. Faustregel: や否や berichtet nüchtern, が早いか malt die Eile aus.",ex:[["ニュースが流れるや否や、電話が鳴り始めた。","ニュースがながれるやいなや、でんわがなりはじめた。","Kaum lief die Nachricht, begann das Telefon zu klingeln."],["彼は結果を聞くや否や、顔色を変えた。","かれはけっかをきくやいなや、かおいろをかえた。","Als er das Ergebnis hörte, wechselte er sofort die Farbe."],["発表されるや否や、問い合わせが殺到した。","はっぴょうされるやいなや、といあわせがさっとうした。","Kaum war es bekanntgegeben, überschlugen sich die Anfragen."]],q:[{q:"到着する＿＿、雨が降り出した。",o:["や否や","ながらも","ものの","にしては"],c:0},{q:"や否や gehört vor allem in …",o:["geschriebene Sprache","lockere Gespräche","Befehle","Bitten"],c:0},{q:"Was folgt typischerweise auf や否や?",o:["ein tatsächlich eingetretenes Ereignis","eine Aufforderung","ein Wunsch","eine Frage"],c:0}]},{id:"n1-nari-sofort",level:1,title:"〜なり — und sogleich",intro:"Jemand tut etwas und schließt unmittelbar eine auffällige zweite Handlung an.",text:"Verb in der Wörterbuchform + なり. Anders als bei 〜や否や muss dieselbe Person beide Handlungen ausführen, und die zweite ist meist unerwartet. Der Satz steht in der Vergangenheit; über die eigene Person spricht man so nicht.",tip:"Nicht mit dem なり aus 〜なりに (auf eigene Weise) oder 〜なり〜なり (entweder … oder) verwechseln — gleiche Silbe, drei verschiedene Muster.",ex:[["彼は部屋に入るなり、窓を全部開けた。","かれはへやにはいるなり、まどをぜんぶあけた。","Kaum betrat er das Zimmer, riss er alle Fenster auf."],["母は手紙を読むなり、泣き出した。","ははははてがみをよむなり、なきだした。","Meine Mutter brach in Tränen aus, kaum dass sie den Brief gelesen hatte."],["彼女は席に座るなり、眠ってしまった。","かのじょはせきにすわるなり、ねむってしまった。","Kaum saß sie, war sie schon eingeschlafen."]],q:[{q:"彼は帰ってくる＿＿、ソファに倒れ込んだ。",o:["なり","なら","なりに","なると"],c:0},{q:"Was gilt für 〜なり?",o:["Beide Handlungen stammen von derselben Person","Die Personen müssen verschieden sein","Es beschreibt eine Absicht","Es steht im Präsens"],c:0},{q:"Über wen spricht man mit 〜なり NICHT?",o:["über sich selbst","über Dritte","über Gruppen","über Kinder"],c:0}]},{id:"n1-sobakara",level:1,title:"〜そばから — kaum getan, schon wieder",intro:"Etwas wiederholt sich: Sobald es getan ist, ist es auch schon wieder zunichte.",text:"Verb (Wörterbuchform oder 〜た) + そばから. Der Sprecher drückt Verdruss über die Wiederholung aus: Aufgeräumtes wird wieder unordentlich, Gelerntes wieder vergessen. Anders als 〜が早いか geht es nicht um ein einmaliges Ereignis, sondern um einen ärgerlichen Kreislauf.",tip:"Merkhilfe: そば heißt „daneben“ — kaum ist man fertig, steht das Gegenteil schon daneben.",ex:[["片付けるそばから、子どもが散らかす。","かたづけるそばから、こどもがちらかす。","Kaum habe ich aufgeräumt, macht das Kind wieder Unordnung."],["覚えたそばから忘れてしまう。","おぼえたそばからわすれてしまう。","Kaum gelernt, schon wieder vergessen."],["作るそばから売れていく。","つくるそばからうれていく。","Kaum hergestellt, ist es schon verkauft."]],q:[{q:"洗う＿＿、また汚れる。",o:["そばから","ついでに","うちに","とたんに"],c:0},{q:"〜そばから beschreibt …",o:["eine ärgerliche Wiederholung","ein einmaliges Ereignis","eine Absicht","eine Bedingung"],c:0},{q:"Welche Form steht vor そばから?",o:["Wörterbuchform oder 〜た","nur 〜て","nur 〜ば","nur die Verneinung"],c:0}]},{id:"n1-wokawakirini",level:1,title:"〜を皮切りに — den Auftakt bildend",intro:"Ein erstes Ereignis eröffnet eine Reihe weiterer.",text:"Nomen + を皮切りに(して) / を皮切りとして. Typisch für Tourneen, Ausstellungsreihen, Serien von Eröffnungen. Was folgt, muss sich ausweiten — für einen einzelnen Nachfolger taugt der Ausdruck nicht. Nur für Positives oder Neutrales, nicht für Ketten von Unglücken.",tip:"皮切り bezeichnet auch die erste Moxa-Behandlung (Moxibustion) einer Reihe — daher das Bild vom ersten Schritt, dem weitere folgen.",ex:[["東京公演を皮切りに、全国十都市を回る。","とうきょうこうえんをかわきりに、ぜんこくじっとしをまわる。","Beginnend mit der Aufführung in Tōkyō geht es durch zehn Städte im ganzen Land."],["この店を皮切りに、次々と支店が開いた。","このみせをかわきりに、つぎつぎとしてんがひらいた。","Mit diesem Laden als Auftakt eröffneten nacheinander weitere Filialen."],["彼の発言を皮切りに、議論が活発になった。","かれのはつげんをかわきりに、ぎろんがかっぱつになった。","Seine Wortmeldung gab den Auftakt zu einer lebhaften Diskussion."]],q:[{q:"大阪＿＿、全国で公演が行われる。",o:["を皮切りに","をはじめ","をもとに","をめぐって"],c:0},{q:"Was muss auf 〜を皮切りに folgen?",o:["eine Reihe weiterer Ereignisse","genau ein weiteres Ereignis","ein Gegensatz","eine Verneinung"],c:0},{q:"Wofür taugt der Ausdruck NICHT?",o:["für eine Kette von Unglücken","für eine Tournee","für Filialeröffnungen","für eine Diskussionsreihe"],c:0}]},{id:"n1-niitaru",level:1,title:"〜に至る / 〜に至るまで — bis hin zu",intro:"Eine Entwicklung läuft bis zu einem Endpunkt, oder eine Aufzählung reicht bis ins Kleinste.",text:"〜に至る beschreibt, dass eine Sache einen (oft ernsten) Zustand erreicht: 解散に至る, 離婚に至る. 〜に至るまで betont dagegen die Spannweite einer Aufzählung: vom Größten bis zum Kleinsten. Beides ist schriftsprachlich.",tip:"至る heißt schlicht „ankommen“. Bei 〜に至っては verschiebt sich die Bedeutung zu „was … angeht, da ist es besonders schlimm“.",ex:[["交渉は決裂し、ついに解散に至った。","こうしょうはけつれつし、ついにかいさんにいたった。","Die Verhandlungen scheiterten, und es kam schließlich zur Auflösung."],["机から鉛筆に至るまで、すべて点検された。","つくえからえんぴつにいたるまで、すべててんけんされた。","Vom Schreibtisch bis hin zum Bleistift wurde alles überprüft."],["調査はここに至ってようやく進み始めた。","ちょうさはここにいたってようやくすすみはじめた。","Erst an diesem Punkt kam die Untersuchung endlich voran."]],q:[{q:"議論は長引き、結論＿＿なかった。",o:["に至ら","に至って","に至る","に至り"],c:0},{q:"〜に至るまで betont …",o:["die Spannweite einer Aufzählung","eine Bedingung","einen Gegensatz","eine Absicht"],c:0},{q:"In welchem Register steht der Ausdruck?",o:["schriftsprachlich","umgangssprachlich","kindersprachlich","dialektal"],c:0}]},{id:"n1-katawara",level:1,title:"〜かたわら — und daneben zugleich",intro:"Jemand geht einer Haupttätigkeit nach und betreibt daneben dauerhaft noch etwas anderes.",text:"Nomen + の + かたわら oder Verb (Wörterbuchform) + かたわら. Beide Tätigkeiten laufen über längere Zeit nebeneinander — es geht nicht um zwei Handlungen an einem Nachmittag. Schriftsprachlich; im Gespräch sagt man 〜ながら.",tip:"Unterschied zu 〜ながら: ながら kann auch zwei gleichzeitige Handlungen im Augenblick meinen (essen und lesen). かたわら meint immer den Lebensabschnitt.",ex:[["彼は教師の傍ら、小説を書いている。","かれはきょうしのかたわら、しょうせつをかいている。","Neben seiner Lehrtätigkeit schreibt er Romane."],["会社に勤めるかたわら、夜は大学に通った。","かいしゃにつとめるかたわら、よるはだいがくにかよった。","Neben der Arbeit in der Firma besuchte er abends die Universität."],["農業のかたわら、民宿を営んでいる。","のうぎょうのかたわら、みんしゅくをいとなんでいる。","Neben der Landwirtschaft betreibt er eine Pension."]],q:[{q:"研究の＿＿、学生の指導も行っている。",o:["かたわら","うちに","とたん","ばかりに"],c:0},{q:"Worin liegt der Unterschied zu 〜ながら?",o:["かたわら meint einen längeren Zeitraum","かたわら ist umgangssprachlicher","かたわら braucht zwei Personen","es gibt keinen Unterschied"],c:0},{q:"Welche Form steht vor かたわら?",o:["Nomen + の oder Wörterbuchform","nur 〜て","nur 〜た","nur die Verneinung"],c:0}]},{id:"n1-gatera",level:1,title:"〜がてら — bei der Gelegenheit auch",intro:"Man tut etwas und erledigt bei derselben Gelegenheit noch etwas Zweites.",text:"Nomen (meist する-Nomen) oder Verb-Stamm + がてら. Beide Handlungen fallen in denselben Gang: spazieren gehen und dabei einkaufen. Die zweite Handlung ist der eigentliche Zweck oder zumindest gleichrangig.",tip:"Nah an 〜ついでに. Faustregel: ついでに betont, dass es nebenbei mitgeht; がてら stellt beide Zwecke gleichauf und klingt etwas gehobener.",ex:[["散歩がてら、郵便局に寄った。","さんぽがてら、ゆうびんきょくによった。","Beim Spaziergang bin ich auch noch zur Post gegangen."],["買い物がてら、友人の家を訪ねた。","かいものがてら、ゆうじんのいえをたずねた。","Beim Einkaufen habe ich auch einen Freund besucht."],["運動がてら、駅まで歩くことにしている。","うんどうがてら、えきまであるくことにしている。","Zur Bewegung gehe ich gewohnheitsmäßig zu Fuß zum Bahnhof."]],q:[{q:"散歩＿＿、本屋をのぞいた。",o:["がてら","ながらも","どころか","にしろ"],c:0},{q:"Was steht vor がてら?",o:["Nomen oder Verb-Stamm","nur 〜て-Form","nur 〜た-Form","nur ein Adjektiv"],c:0},{q:"Wie verhält sich がてら zu ついでに?",o:["がてら stellt beide Zwecke gleichauf","がてら ist salopper","がてら verneint","es gibt keinen Bezug"],c:0}]},{id:"n1-kotonashini",level:1,title:"〜ことなしに — ohne dass",intro:"Eine Sache ist nicht zu erreichen, wenn eine andere unterbleibt.",text:"Verb (Wörterbuchform) + ことなしに. Fast immer mit Verneinung im Hauptsatz: ohne A geht B nicht. Schriftsprachlich; im Alltag sagt man 〜ないで oder 〜なければ.",tip:"Merke die Doppelverneinung: ことなしに + 〜ない ergibt eine positive Notwendigkeit — „nur mit A geht B“.",ex:[["努力することなしに、成功は得られない。","どりょくすることなしに、せいこうはえられない。","Ohne Anstrengung ist kein Erfolg zu erlangen."],["彼は誰にも相談することなしに決めてしまった。","かれはだれにもそうだんすることなしにきめてしまった。","Er entschied, ohne irgendjemanden zu Rate zu ziehen."],["痛みを感じることなしに治療は終わった。","いたみをかんじることなしにちりょうはおわった。","Die Behandlung war zu Ende, ohne dass ich Schmerz spürte."]],q:[{q:"練習する＿＿、上達は望めない。",o:["ことなしに","ことだから","ことには","ことなく"],c:0},{q:"Womit steht ことなしに meist zusammen?",o:["mit einer Verneinung im Hauptsatz","mit einem Befehl","mit einer Frage","mit einer Bitte"],c:0},{q:"In welchem Register steht der Ausdruck?",o:["schriftsprachlich","umgangssprachlich","kindersprachlich","salopp"],c:0}]},{id:"n1-yueni",level:1,title:"〜ゆえ(に) — aus dem Grunde, dass",intro:"Schriftsprachlicher Grund — der schwerere Bruder von から und ので.",text:"Nomen (+ の) / な-Adjektiv (+ な) / Verb in der Grundform + ゆえ(に). Auch vorangestellt als 〜がゆえに. Gehört in Aufsätze, Urteile, Bekanntmachungen; in der Alltagssprache wirkt es steif oder ironisch.",tip:"〜ゆえの + Nomen ist häufig: 若さゆえの過ち — ein Fehler, der aus der Jugend kommt.",ex:[["経験が浅いゆえに、判断を誤った。","けいけんがあさいゆえに、はんだんをあやまった。","Aus mangelnder Erfahrung urteilte er falsch."],["天候不良ゆえ、公演は中止となりました。","てんこうふりょうゆえ、こうえんはちゅうしとなりました。","Wegen schlechten Wetters wurde die Aufführung abgesagt."],["若さゆえの失敗も、後に糧となる。","わかさゆえのしっぱいも、のちにかてとなる。","Auch Fehler, die aus der Jugend kommen, werden später zur Nahrung."]],q:[{q:"不注意＿＿、事故が起きた。",o:["ゆえに","ながら","どころか","にしては"],c:0},{q:"Wo begegnet man ゆえに typischerweise?",o:["in Aufsätzen und Bekanntmachungen","im Gespräch unter Freunden","in Kinderbüchern","in Werbesprüchen"],c:0},{q:"Was bedeutet 若さゆえの過ち?",o:["ein Fehler, der aus der Jugend kommt","ein Fehler trotz der Jugend","ein Fehler der Alten","ein absichtlicher Fehler"],c:0}]},{id:"n1-kototote",level:1,title:"〜こととて — da es sich ja um … handelt",intro:"Eine höfliche Entschuldigung: der genannte Umstand erklärt, warum etwas nachzusehen ist.",text:"Nomen + の + こととて oder Verb (Grundform/〜た) + こととて. Fast nur in förmlichen Entschuldigungen und Briefen; der Hauptsatz bittet um Nachsicht oder erklärt einen Mangel.",tip:"Klingt altertümlich und wird fast ausschließlich schriftlich benutzt. Wer es im Gespräch sagt, klingt wie eine Bekanntmachung.",ex:[["慣れぬこととて、失礼があったかもしれません。","なれぬこととて、しつれいがあったかもしれません。","Da ich ungeübt bin, mag ich mich unhöflich verhalten haben."],["急なこととて、十分な準備ができませんでした。","きゅうなこととて、じゅうぶんなじゅんびができませんでした。","Da es plötzlich kam, konnte ich mich nicht ausreichend vorbereiten."],["田舎のこととて、何のおもてなしもできません。","いなかのこととて、なんのおもてなしもできません。","Da wir auf dem Land sind, können wir nichts Rechtes auftischen."]],q:[{q:"初めての＿＿、不手際をお許しください。",o:["こととて","ことには","ことから","ことなく"],c:0},{q:"Was steht typischerweise im Hauptsatz?",o:["eine Bitte um Nachsicht","ein Befehl","eine Frage","ein Vorschlag"],c:0},{q:"Wie wirkt こととて heute?",o:["altertümlich und schriftlich","modern und locker","technisch","jugendsprachlich"],c:0}]},{id:"n1-toatte",level:1,title:"〜とあって — weil es sich um … handelt",intro:"Ein besonderer Anlass erklärt eine ungewöhnliche Folge.",text:"Nomen / Grundform + とあって. Der Sprecher berichtet über Dritte und begründet eine auffällige Lage: weil es dieser besondere Umstand ist, geschieht das Ungewöhnliche. Über eigene Angelegenheiten sagt man es nicht.",tip:"Typisch in Nachrichtensätzen: 連休とあって、道路は渋滞している。 Die Folge muss aus dem Anlass einleuchten.",ex:[["連休とあって、どの店も混んでいる。","れんきゅうとあって、どのみせもこんでいる。","Weil Feiertage sind, ist jedes Geschäft voll."],["人気作家の講演とあって、会場は満席だった。","にんきさっかのこうえんとあって、かいじょうはまんせきだった。","Da es der Vortrag eines beliebten Autors war, war der Saal ausverkauft."],["初優勝とあって、町は喜びに沸いた。","はつゆうしょうとあって、まちはよろこびにわいた。","Weil es der erste Sieg war, jubelte die ganze Stadt."]],q:[{q:"祭り＿＿、駅前は人であふれていた。",o:["とあって","にあって","とすると","にしても"],c:0},{q:"Worüber spricht man mit とあって?",o:["über Dritte oder allgemeine Lagen","über eigene Gefühle","über Wünsche","über Befehle"],c:0},{q:"Wie muss die Folge beschaffen sein?",o:["sie muss aus dem Anlass einleuchten","sie muss überraschen","sie muss verneint sein","sie muss zukünftig sein"],c:0}]},{id:"n1-dewaarumaishi",level:1,title:"〜ではあるまいし — es ist ja nicht so, dass",intro:"Ein Einwand mit leichtem Tadel: so etwas trifft hier doch gar nicht zu.",text:"Nomen + ではあるまいし (gesprochen oft じゃあるまいし). Der Sprecher weist eine Ausrede oder ein Verhalten zurück: du bist doch kein Kind. Im Hauptsatz steht ein Rat, ein Vorwurf oder eine Feststellung. Umgangssprachlich, aber nicht grob.",tip:"Nur mit Nomen oder Verb + んじゃあるまいし. Der Ton ist tadelnd — gegenüber Vorgesetzten besser meiden.",ex:[["子どもじゃあるまいし、自分で考えなさい。","こどもじゃあるまいし、じぶんでかんがえなさい。","Du bist doch kein Kind — denk selbst nach."],["神ではあるまいし、未来など分かるものか。","かみではあるまいし、みらいなどわかるものか。","Ich bin doch kein Gott — wie sollte ich die Zukunft kennen."],["初めてじゃあるまいし、そんなに緊張しなくていい。","はじめてじゃあるまいし、そんなにきんちょうしなくていい。","Es ist ja nicht das erste Mal — so nervös musst du nicht sein."]],q:[{q:"新人＿＿、これくらいはできるはずだ。",o:["じゃあるまいし","ではないが","にすぎず","どころか"],c:0},{q:"Welcher Ton schwingt mit?",o:["ein leichter Tadel","Bewunderung","Trauer","Gleichgültigkeit"],c:0},{q:"Wem gegenüber sollte man es meiden?",o:["Vorgesetzten","Freunden","Geschwistern","sich selbst"],c:0}]},{id:"n1-bakoso",level:1,title:"〜ばこそ — gerade weil",intro:"Nachdrückliche Begründung: genau dieser Grund und kein anderer.",text:"Verb in der ば-Form + こそ, danach oft 〜のだ / 〜んです. Der Sprecher hebt den wahren Grund hervor, oft gegen eine falsche Annahme: gerade weil ich dich schätze, sage ich das. Schriftsprachlich und feierlich.",tip:"Nicht mit 〜からこそ verwechseln, das dieselbe Rolle in der Alltagssprache übernimmt. ばこそ ist die gehobene Fassung.",ex:[["君のことを思えばこそ、厳しく言うのだ。","きみのことをおもえばこそ、きびしくいうのだ。","Gerade weil ich an dich denke, sage ich es so hart."],["健康であればこそ、仕事も楽しめる。","けんこうであればこそ、しごともたのしめる。","Gerade weil man gesund ist, macht auch die Arbeit Freude."],["支えがあればこそ、ここまで来られた。","ささえがあればこそ、ここまでこられた。","Nur weil ich Rückhalt hatte, bin ich so weit gekommen."]],q:[{q:"愛していれ＿＿、別れを選んだ。",o:["ばこそ","ばかり","ばこそも","ばなり"],c:0},{q:"Was folgt oft am Satzende?",o:["〜のだ / 〜んです","〜ましょう","〜てください","〜ませんか"],c:0},{q:"Was ist die alltagssprachliche Entsprechung?",o:["〜からこそ","〜ながら","〜どころか","〜にすぎない"],c:0}]},{id:"n1-temae",level:1,title:"〜手前 — da man vor anderen steht",intro:"Weil andere zusehen, bleibt einem nichts anderes übrig.",text:"Nomen + の + 手前 oder Grundform + 手前. Der Sprecher begründet sein Verhalten mit dem Blick der anderen: vor den Gästen kann ich nicht klagen. Es geht um Gesicht und Anstand, nicht um eine sachliche Ursache.",tip:"手前 heißt wörtlich „vor einem selbst“ — der Raum, in dem andere zusehen. Der Hauptsatz sagt meist, was man deshalb tun MUSS oder nicht tun KANN.",ex:[["約束した手前、今さらやめるとは言えない。","やくそくしたてまえ、いまさらやめるとはいえない。","Nachdem ich es zugesagt habe, kann ich jetzt schlecht absagen."],["後輩の手前、弱音は吐けなかった。","こうはいのてまえ、よわねははけなかった。","Vor den Jüngeren konnte ich nicht klagen."],["自分で言い出した手前、最後までやるしかない。","じぶんでいいだしたてまえ、さいごまでやるしかない。","Da ich es selbst vorgeschlagen habe, muss ich es zu Ende bringen."]],q:[{q:"引き受けた＿＿、途中でやめられない。",o:["手前","以来","うえは","ばかりに"],c:0},{q:"Worum geht es bei 〜手前?",o:["um das Gesicht vor anderen","um eine sachliche Ursache","um eine Zeitangabe","um einen Ort"],c:0},{q:"Was steht meist im Hauptsatz?",o:["was man deshalb tun muss oder nicht kann","eine Frage","ein Wunsch","eine Vermutung"],c:0}]},{id:"n1-kagirida",level:1,title:"〜限りだ — im höchsten Maße",intro:"Ein Gefühl wird auf seine äußerste Stufe gehoben.",text:"い-Adjektiv (Grundform) oder な-Adjektiv + な + 限りだ. Nur mit Gefühlswörtern: うれしい限りだ, 心細い限りだ, 羨ましい限りだ. Der Sprecher spricht über das eigene Empfinden, nicht über Dritte.",tip:"Nicht mit 〜に限る (am besten ist) oder 〜限り (solange) verwechseln. Hier steht 限りだ am Satzende und steigert ein Gefühl.",ex:[["お会いできて、うれしい限りです。","おあいできて、うれしいかぎりです。","Ich freue mich außerordentlich, Sie zu treffen."],["一人で山に残されるとは、心細い限りだった。","ひとりでやまにのこされるとは、こころぼそいかぎりだった。","Allein im Gebirge zurückzubleiben war überaus beklemmend."],["自由に旅ができるとは、羨ましい限りだ。","じゆうにたびができるとは、うらやましいかぎりだ。","Frei reisen zu können — ich beneide dich sehr."]],q:[{q:"再会できて、うれしい＿＿です。",o:["限り","ばかり","どころ","まで"],c:0},{q:"Welche Wörter stehen vor 限りだ?",o:["Gefühlswörter","Zahlwörter","Ortsangaben","Verben der Bewegung"],c:0},{q:"Über wen spricht man damit?",o:["über sich selbst","nur über Dritte","über Gruppen","über Gegenstände"],c:0}]},{id:"n1-noitari",level:1,title:"〜の至り — der Gipfel an",intro:"Förmliche Steigerung eines Gefühls, meist in Reden und Briefen.",text:"Nomen + の至り. Feste Wendungen: 光栄の至り (die höchste Ehre), 恐縮の至り (äußerst beschämt), 若気の至り (Jugendtorheit). Das Nomen ist fast immer eines aus dieser kleinen Gruppe; frei bilden lässt sich der Ausdruck nicht.",tip:"Unterschied zu 〜の極み: 至り steht bei Gefühlen der sprechenden Person, 極み eher bei Zuständen und Sachverhalten.",ex:[["このような賞をいただき、光栄の至りです。","このようなしょうをいただき、こうえいのいたりです。","Einen solchen Preis zu erhalten, ist mir die höchste Ehre."],["お手数をおかけし、恐縮の至りです。","おてすうをおかけし、きょうしゅくのいたりです。","Dass ich Ihnen Mühe mache, ist mir äußerst peinlich."],["あれは若気の至りでした。","あれはわかげのいたりでした。","Das war eine Jugendtorheit."]],q:[{q:"ご招待いただき、光栄の＿＿です。",o:["至り","極み","限り","ばかり"],c:0},{q:"Was gilt für die Wortwahl?",o:["nur wenige feste Nomen sind möglich","jedes Nomen passt","nur Verben passen","nur Adjektive passen"],c:0},{q:"Worin unterscheidet sich 〜の極み?",o:["極み steht eher bei Zuständen","極み ist umgangssprachlich","極み verneint","es gibt keinen Unterschied"],c:0}]},{id:"n1-nokiwami",level:1,title:"〜の極み — das Äußerste an",intro:"Ein Zustand wird als nicht mehr steigerbar bezeichnet.",text:"Nomen + の極み. Typisch: 贅沢の極み (der Gipfel des Luxus), 感激の極み, 疲労の極み. Anders als 〜の至り beschreibt es oft einen Sachverhalt oder Zustand, nicht nur das eigene Gefühl. Gehobene Schriftsprache.",tip:"Beide Wendungen sind formelhaft — sie neu zu erfinden klingt falsch. Lerne sie als Paare mit ihrem Nomen.",ex:[["連日の残業で、疲労の極みに達した。","れんじつのざんぎょうで、ひろうのきわみにたっした。","Durch die täglichen Überstunden erreichte die Erschöpfung ihren Gipfel."],["これほどの設備は贅沢の極みだ。","これほどのせつびはぜいたくのきわみだ。","Eine solche Ausstattung ist der Gipfel des Luxus."],["受賞の知らせは感激の極みだった。","じゅしょうのしらせはかんげきのきわみだった。","Die Nachricht vom Preis war überwältigend."]],q:[{q:"連日の作業で疲労の＿＿に達した。",o:["極み","至り","限り","末"],c:0},{q:"Was beschreibt 〜の極み häufig?",o:["einen Zustand oder Sachverhalt","eine Absicht","eine Bitte","eine Bedingung"],c:0},{q:"Wie lernt man solche Wendungen am besten?",o:["als feste Paare mit ihrem Nomen","durch freies Bilden","nur über die Lesung","gar nicht"],c:0}]},{id:"n1-woite",level:1,title:"〜をおいて(他に)ない — außer diesem gibt es keinen",intro:"Nachdrückliche Auszeichnung: es kommt nur diese eine Möglichkeit in Frage.",text:"Nomen + をおいて(他に)〜ない. Der Sprecher erklärt jemanden oder etwas für konkurrenzlos. Fast immer mit einer Verneinung im Hauptsatz und oft mit 他に verstärkt.",tip:"おいて kommt von 置く — „wenn man diesen beiseitelegt, bleibt keiner übrig“.",ex:[["この仕事を任せられるのは、彼をおいて他にいない。","このしごとをまかせられるのは、かれをおいてほかにいない。","Außer ihm gibt es niemanden, dem man diese Arbeit übertragen könnte."],["代表を務められる人は、あなたをおいていない。","だいひょうをつとめられるひとは、あなたをおいていない。","Außer Ihnen kann niemand die Vertretung übernehmen."],["この道をおいて、解決の方法はない。","このみちをおいて、かいけつのほうほうはない。","Außer diesem Weg gibt es keine Lösung."]],q:[{q:"適任者は彼女＿＿他にいない。",o:["をおいて","において","によって","をもって"],c:0},{q:"Was steht im Hauptsatz?",o:["eine Verneinung","ein Befehl","eine Frage","ein Wunsch"],c:0},{q:"Was drückt der Satz aus?",o:["dass die Sache konkurrenzlos ist","dass es viele Möglichkeiten gibt","dass etwas verboten ist","dass etwas unsicher ist"],c:0}]},{id:"n1-naraizashirazu",level:1,title:"〜ならいざしらず — bei … mag es angehen, aber",intro:"Ein Fall wäre verständlich, der vorliegende jedoch nicht.",text:"Nomen / Grundform + ならいざしらず. Der erste Teil nennt einen nachvollziehbaren Fall, der zweite den tatsächlichen, über den der Sprecher sich wundert oder ärgert. Schriftsprachlich und mit deutlichem Werturteil.",tip:"いざ知らず heißt wörtlich „das weiß ich nicht“ — über jenen Fall will ich nicht urteilen, über diesen sehr wohl.",ex:[["子どもならいざしらず、大人がそれでは困る。","こどもならいざしらず、おとながそれではこまる。","Bei einem Kind möge es angehen, aber bei einem Erwachsenen ist das ein Problem."],["昔ならいざしらず、今はそんな時代ではない。","むかしならいざしらず、いまはそんなじだいではない。","Früher mag das so gewesen sein, heute ist die Zeit nicht mehr danach."],["専門家ならいざしらず、素人には難しすぎる。","せんもんかならいざしらず、しろうとにはむずかしすぎる。","Für Fachleute mag es gehen, für Laien ist es zu schwer."]],q:[{q:"新人＿＿、経験者がこれではいけない。",o:["ならいざしらず","にもかかわらず","はもちろん","どころか"],c:0},{q:"Was steht im ersten Teil?",o:["ein nachvollziehbarer Fall","der tatsächliche Fall","eine Frage","ein Befehl"],c:0},{q:"Welchen Ton hat der Ausdruck?",o:["wertend","neutral","bittend","scherzhaft"],c:0}]},{id:"n1-hasateoki",level:1,title:"〜はさておき — beiseite gelassen",intro:"Ein Punkt wird bewusst zurückgestellt, um zum Wesentlichen zu kommen.",text:"Nomen + はさておき / はさておいて. Der Sprecher schiebt ein Thema vorerst weg, ohne es abzuwerten, und wendet sich dem Dringenderen zu. Häufig am Anfang eines Redebeitrags.",tip:"さておき kommt von さて置く — zur Seite stellen. Der zurückgestellte Punkt ist nicht erledigt, nur vertagt.",ex:[["費用はさておき、まず実現できるかを考えよう。","ひようはさておき、まずじつげんできるかをかんがえよう。","Die Kosten einmal beiseite — überlegen wir erst, ob es machbar ist."],["冗談はさておき、本題に入りましょう。","じょうだんはさておき、ほんだいにはいりましょう。","Spaß beiseite, kommen wir zur Sache."],["結果はさておき、過程は評価できる。","けっかはさておき、かていはひょうかできる。","Das Ergebnis einmal beiseite — der Weg dorthin verdient Anerkennung."]],q:[{q:"値段＿＿、品質は申し分ない。",o:["はさておき","をめぐって","に限って","どころか"],c:0},{q:"Was geschieht mit dem genannten Punkt?",o:["Er wird vorerst zurückgestellt","Er wird abgelehnt","Er wird bewiesen","Er wird wiederholt"],c:0},{q:"Wo steht der Ausdruck meist?",o:["am Anfang eines Beitrags","am Satzende","in Fragen","in Befehlen"],c:0}]},{id:"n1-mosarunagara",level:1,title:"〜もさることながら — nicht nur …, sondern erst recht",intro:"Das eine ist schon bemerkenswert, das andere aber noch mehr.",text:"Nomen + もさることながら. Der erste Punkt wird ausdrücklich anerkannt, der zweite als noch gewichtiger hervorgehoben. Beide sind positiv oder zumindest neutral; für Aufzählungen von Missständen taugt es nicht.",tip:"さる ist hier das alte 然る (ein solcher). Wörtlich: „auch das ist so, aber …“.",ex:[["味もさることながら、盛りつけが美しい。","あじもさることながら、もりつけがうつくしい。","Der Geschmack ist schon bemerkenswert, aber das Anrichten erst recht."],["技術もさることながら、彼の集中力には驚く。","ぎじゅつもさることながら、かれのしゅうちゅうりょくにはおどろく。","Das Können schon, aber seine Konzentration erstaunt noch mehr."],["景色もさることながら、地元の人の温かさが忘れられない。","けしきもさることながら、じもとのひとのあたたかさがわすれられない。","Die Landschaft schon, aber die Herzlichkeit der Menschen bleibt noch mehr."]],q:[{q:"内容＿＿、話し方も見事だった。",o:["もさることながら","にもかかわらず","はもとより","どころか"],c:0},{q:"Wie verhalten sich die beiden Teile?",o:["Der zweite wiegt schwerer","Der erste wiegt schwerer","Sie widersprechen sich","Sie sind gleich"],c:0},{q:"Wofür taugt der Ausdruck nicht?",o:["für Aufzählungen von Missständen","für Lob","für Beschreibungen","für Vergleiche"],c:0}]},{id:"n1-haoroka",level:1,title:"〜はおろか — geschweige denn",intro:"Schon das Geringere trifft nicht zu, das Größere erst recht nicht.",text:"Nomen + はおろか, danach meist 〜も〜ない. Der Sprecher steigert die Verneinung: nicht einmal das Einfache, vom Schwierigen ganz zu schweigen. Fast immer in negativem Zusammenhang.",tip:"Reihenfolge beachten: vor はおろか steht das Größere/Schwierigere, danach das Kleinere, das ebenfalls nicht geht.",ex:[["漢字はおろか、ひらがなも読めなかった。","かんじはおろか、ひらがなもよめなかった。","Von Kanji ganz zu schweigen — nicht einmal Hiragana konnte er lesen."],["旅行はおろか、外出する時間もない。","りょこうはおろか、がいしゅつするじかんもない。","An Reisen ist nicht zu denken — nicht einmal Zeit zum Ausgehen bleibt."],["返事はおろか、受け取ったという連絡すらない。","へんじはおろか、うけとったというれんらくすらない。","Von einer Antwort ganz zu schweigen — nicht einmal eine Eingangsbestätigung."]],q:[{q:"外国語＿＿、母語の作文も苦手だ。",o:["はおろか","をおいて","はさておき","にもまして"],c:0},{q:"Was folgt auf はおろか meist?",o:["〜も〜ない","〜てください","〜ましょう","〜たい"],c:0},{q:"In welchem Zusammenhang steht der Ausdruck?",o:["in einem negativen","in einem lobenden","in einem bittenden","in einem fragenden"],c:0}]},{id:"n1-naradeha",level:1,title:"〜ならでは — nur bei … zu finden",intro:"Etwas ist so gut oder so eigen, dass es nur von dieser Quelle kommen kann.",text:"Nomen + ならでは(の) + Nomen, oder 〜ならではだ am Satzende. Immer lobend: eine Leistung, ein Geschmack, eine Stimmung, die anderswo nicht zu haben ist.",tip:"Der Ausdruck lobt. Für Nachteile, die nur an einem Ort auftreten, benutzt man ihn nicht.",ex:[["この味は手作りならではだ。","このあじはてづくりならではだ。","Dieser Geschmack ist nur bei Handgemachtem zu finden."],["京都ならではの静けさがある。","きょうとならではのしずけさがある。","Es hat eine Stille, wie sie nur Kyōto hat."],["長年の経験ならではの判断だった。","ながねんのけいけんならではのはんだんだった。","Ein Urteil, wie es nur aus langer Erfahrung kommt."]],q:[{q:"この店＿＿の雰囲気が好きだ。",o:["ならでは","にしては","どころか","ながら"],c:0},{q:"Welchen Ton hat 〜ならでは?",o:["lobend","tadelnd","neutral-sachlich","bittend"],c:0},{q:"Wie schließt der Ausdruck vor einem Nomen an?",o:["ならではの","ならではで","ならではに","ならではと"],c:0}]},{id:"n1-nihikikae",level:1,title:"〜にひきかえ — ganz im Gegensatz zu",intro:"Zwei Seiten werden scharf gegeneinandergestellt.",text:"Nomen + にひきかえ, oder Grundform + の + にひきかえ. Anders als das nüchterne 〜に対して trägt にひきかえ eine Wertung: die eine Seite kommt gut weg, die andere schlecht. Der Sprecher urteilt.",tip:"に対して vergleicht neutral, にひきかえ vergleicht mit Sympathie und Missfallen. Wer sachlich bleiben will, nimmt に対して.",ex:[["兄にひきかえ、弟は落ち着いている。","あににひきかえ、おとうとはおちついている。","Ganz im Gegensatz zum älteren Bruder ist der jüngere ruhig."],["去年にひきかえ、今年は雨が少ない。","きょねんにひきかえ、ことしはあめがすくない。","Ganz anders als letztes Jahr regnet es dieses Jahr wenig."],["口先ばかりの彼にひきかえ、彼女は黙って動く。","くちさきばかりのかれにひきかえ、かのじょはだまってうごく。","Anders als er, der nur redet, handelt sie schweigend."]],q:[{q:"昨年＿＿、今年は売上が伸びている。",o:["にひきかえ","に加えて","に沿って","にわたって"],c:0},{q:"Worin unterscheidet es sich von 〜に対して?",o:["にひきかえ wertet","にひきかえ ist neutraler","にひきかえ verneint","es gibt keinen Unterschied"],c:0},{q:"Was steht vor にひきかえ?",o:["ein Nomen","nur ein Verb","nur ein Adjektiv","nur eine Zahl"],c:0}]},{id:"n1-nimomashite",level:1,title:"〜にもまして — noch mehr als",intro:"Etwas übertrifft einen schon hohen Vergleichspunkt.",text:"Nomen + にもまして. Oft mit Zeitangaben: 以前にもまして (mehr denn je), oder mit Fragewörtern: 何にもまして (vor allem anderen). Der Vergleichspunkt war bereits hoch — die Steigerung ist deshalb bemerkenswert.",tip:"まして gehört zu 勝る/増す (übertreffen, zunehmen). 何にもまして ist die häufigste feste Fügung: „mehr als alles andere“.",ex:[["以前にもまして忙しくなった。","いぜんにもましていそがしくなった。","Es ist noch geschäftiger geworden als vorher."],["何にもまして健康が大切だ。","なににもましてけんこうがたいせつだ。","Mehr als alles andere zählt die Gesundheit."],["昨年にもまして厳しい冬になりそうだ。","さくねんにもましてきびしいふゆになりそうだ。","Es wird wohl ein noch härterer Winter als letztes Jahr."]],q:[{q:"去年＿＿、今年は暑い。",o:["にもまして","にひきかえ","はおろか","どころか"],c:0},{q:"Wie war der Vergleichspunkt beschaffen?",o:["schon hoch","niedrig","unbekannt","gleichgültig"],c:0},{q:"Was bedeutet 何にもまして?",o:["mehr als alles andere","überhaupt nicht","ab und zu","genau so viel"],c:0}]},{id:"n1-tohaie",level:1,title:"〜とはいえ — wenngleich",intro:"Ein Zugeständnis, das sofort eingeschränkt wird.",text:"Nomen / Grundform + とはいえ. Der Sprecher räumt ein, was gilt, und stellt dann fest, dass die erwartete Folge ausbleibt. Schriftsprachlich; im Gespräch sagt man けど oder でも.",tip:"Steht auch am Satzanfang: とはいえ、… — „gleichwohl, …“. Nah an 〜ものの, aber とはいえ klingt eine Spur argumentativer.",ex:[["春とはいえ、まだ風は冷たい。","はるとはいえ、まだかぜはつめたい。","Es ist zwar Frühling, doch der Wind ist noch kalt."],["経験があるとはいえ、油断はできない。","けいけんがあるとはいえ、ゆだんはできない。","Zwar habe ich Erfahrung, nachlässig werden darf ich trotzdem nicht."],["安いとはいえ、質は悪くない。","やすいとはいえ、しつはわるくない。","Billig zwar, aber die Qualität ist nicht schlecht."]],q:[{q:"休日＿＿、やることは山ほどある。",o:["とはいえ","とあって","ゆえに","ばこそ"],c:0},{q:"Was tut der Sprecher zuerst?",o:["er räumt etwas ein","er widerspricht","er fragt","er befiehlt"],c:0},{q:"Was ist die alltagssprachliche Entsprechung?",o:["けど / でも","から","ので","なら"],c:0}]},{id:"n1-toiedomo",level:1,title:"〜といえども — selbst wenn; auch ein …",intro:"Sogar im stärksten denkbaren Fall gilt die Aussage.",text:"Nomen / Grundform + といえども. Der genannte Fall ist der am wenigsten erwartete: selbst ein Fachmann irrt; selbst ein Kind versteht das. Gehobene Schriftsprache, oft in Grundsatzsätzen.",tip:"Merke die Richtung: das Genannte ist der EXTREMFALL, nicht der Normalfall. Deshalb wirkt der Satz wie eine Regel ohne Ausnahme.",ex:[["専門家といえども、間違うことはある。","せんもんかといえども、まちがうことはある。","Selbst Fachleute können sich irren."],["どんな理由があるといえども、暴力は許されない。","どんなりゆうがあるといえども、ぼうりょくはゆるされない。","Welchen Grund es auch gebe — Gewalt ist nicht zu rechtfertigen."],["子どもといえども、約束は守るべきだ。","こどもといえども、やくそくはまもるべきだ。","Auch ein Kind sollte Versprechen halten."]],q:[{q:"名人＿＿、失敗することがある。",o:["といえども","とばかりに","とあって","ときたら"],c:0},{q:"Welchen Fall nennt der erste Teil?",o:["den Extremfall","den Normalfall","einen Zufall","einen Wunsch"],c:0},{q:"In welchem Register steht der Ausdruck?",o:["gehobene Schriftsprache","Jugendsprache","Kindersprache","Dialekt"],c:0}]},{id:"n1-nagaramo",level:1,title:"〜ながらも — obwohl zugleich",intro:"Zwei Seiten bestehen gleichzeitig, obwohl sie einander widersprechen.",text:"Verb-Stamm / い-Adjektiv / な-Adjektiv / Nomen + ながらも. Anders als das zeitliche 〜ながら (während) drückt ながらも einen Widerspruch aus: klein, aber fein; wusste es und tat es doch.",tip:"Das も macht den Unterschied. Ohne も ist ながら meist zeitlich, mit も fast immer adversativ.",ex:[["狭いながらも、居心地のよい部屋だ。","せまいながらも、いごこちのよいへやだ。","Ein zwar enges, aber behagliches Zimmer."],["知っていながらも、黙っていた。","しっていながらも、だまっていた。","Obwohl er es wusste, schwieg er."],["失敗しながらも、彼は歩みを止めなかった。","しっぱいしながらも、かれはあゆみをとめなかった。","Trotz Fehlschlägen hörte er nicht auf zu gehen."]],q:[{q:"小さい＿＿、力強い作品だ。",o:["ながらも","ながらに","ながらで","ながらと"],c:0},{q:"Was leistet das も?",o:["es macht den Ausdruck adversativ","es macht ihn zeitlich","es verneint","es fragt"],c:0},{q:"Welche Form steht vor ながらも bei Verben?",o:["der Verb-Stamm","die て-Form","die た-Form","die ば-Form"],c:0}]},{id:"n1-tsutsumo",level:1,title:"〜つつも — und dennoch",intro:"Man weiß es besser und handelt trotzdem anders.",text:"Verb-Stamm + つつも. Fast immer beim Eingeständnis eines Widerspruchs zwischen Einsicht und Verhalten: ich wusste, dass ich lernen sollte, und sah doch fern. Schriftsprachlich; das schlichte 〜つつ ohne も ist dagegen zeitlich (während).",tip:"Merksatz: つつ = während, つつも = obwohl. Ein einziges も dreht die Bedeutung.",ex:[["体に悪いと知りつつも、やめられない。","からだにわるいとしりつつも、やめられない。","Obwohl ich weiß, dass es ungesund ist, kann ich nicht aufhören."],["急がなければと思いつつも、足が動かなかった。","いそがなければとおもいつつも、あしがうごかなかった。","Obwohl ich dachte, ich müsse mich eilen, bewegten sich die Füße nicht."],["悪いと感じつつも、何も言えなかった。","わるいとかんじつつも、なにもいえなかった。","Obwohl es mir leidtat, konnte ich nichts sagen."]],q:[{q:"遅れると分かり＿＿、出発しなかった。",o:["つつも","ながらに","ばかりに","どころか"],c:0},{q:"Was drückt つつも aus?",o:["einen Widerspruch zwischen Einsicht und Handeln","Gleichzeitigkeit","eine Bedingung","eine Folge"],c:0},{q:"Was bedeutet 〜つつ ohne も?",o:["während","obwohl","weil","damit"],c:0}]},{id:"n1-kiwamarinai",level:1,title:"〜きわまりない — über alle Maßen",intro:"Ein negativ bewerteter Zustand wird als nicht mehr steigerbar bezeichnet.",text:"な-Adjektiv-Stamm + きわまりない (auch きわまる). Fast nur mit tadelnden Wörtern: 失礼きわまりない, 危険きわまりない, 不愉快きわまりない. Trotz der Verneinungsform ist die Bedeutung positiv-steigernd, nicht verneinend.",tip:"Achtung, Scheinverneinung: きわまりない heißt nicht „nicht äußerst“, sondern „äußerst“. Dasselbe gilt für 〜てやまない.",ex:[["彼の態度は失礼きわまりない。","かれのたいどはしつれいきわまりない。","Sein Verhalten ist über alle Maßen unhöflich."],["あの運転は危険きわまりない。","あのうんてんはきけんきわまりない。","Diese Fahrweise ist äußerst gefährlich."],["説明のない対応は不親切きわまりない。","せつめいのないたいおうはふしんせつきわまりない。","Eine Behandlung ohne Erklärung ist über alle Maßen unfreundlich."]],q:[{q:"その言い方は無礼＿＿。",o:["きわまりない","きわまらない","きわめない","きわまった"],c:0},{q:"Welche Wörter stehen davor?",o:["tadelnde な-Adjektive","Zahlwörter","Verben","Ortsangaben"],c:0},{q:"Was bedeutet die Verneinungsform hier?",o:["sie steigert, sie verneint nicht","sie verneint","sie fragt","sie bittet"],c:0}]},{id:"n1-tarumono",level:1,title:"〜たるもの — wer … ist, der",intro:"Aus einer Rolle folgt eine Pflicht.",text:"Nomen + たるもの(は). Der Sprecher leitet aus einem Amt oder Stand ab, was sich gehört: wer Lehrer ist, muss … Im Hauptsatz steht fast immer べきだ, なければならない oder ein Imperativ. Sehr förmlich, oft leicht pathetisch.",tip:"たる ist die alte attributive Form von である. 〜たるもの klingt nach Grundsatzrede — im Alltag unpassend.",ex:[["教師たるもの、言葉を選ばねばならない。","きょうしたるもの、ことばをえらばねばならない。","Wer Lehrer ist, muss seine Worte wählen."],["社会人たるもの、時間は守るべきだ。","しゃかいじんたるもの、じかんはまもるべきだ。","Wer im Berufsleben steht, sollte pünktlich sein."],["指導者たるもの、責任から逃げてはならない。","しどうしゃたるもの、せきにんからにげてはならない。","Wer führt, darf sich der Verantwortung nicht entziehen."]],q:[{q:"医師＿＿、患者の話をよく聞くべきだ。",o:["たるもの","なるもの","というもの","ともなると"],c:0},{q:"Was steht typischerweise im Hauptsatz?",o:["べきだ oder なければならない","かもしれない","たい","でしょう"],c:0},{q:"Wie wirkt der Ausdruck?",o:["förmlich und pathetisch","locker","kindlich","technisch"],c:0}]},{id:"n1-tomonaruto",level:1,title:"〜ともなると / 〜ともなれば — wenn es erst einmal … ist",intro:"Ab einer bestimmten Stufe gilt etwas anderes als vorher.",text:"Nomen (Alter, Rang, Zeitpunkt, Menge) + ともなると / ともなれば. Der Sprecher stellt fest, dass sich mit dem Erreichen dieser Schwelle die Lage ändert. Der Hauptsatz nennt die Folge, die dann selbstverständlich eintritt.",tip:"Faustregel: vor ともなると steht eine Schwelle (Alter, Position, Jahreszeit), nicht ein beliebiges Ereignis.",ex:[["大学生ともなると、親も口を出さなくなる。","だいがくせいともなると、おやもくちをださなくなる。","Ist man erst einmal Student, mischen sich auch die Eltern nicht mehr ein."],["師走ともなれば、どこも人でいっぱいだ。","しわすともなれば、どこもひとでいっぱいだ。","Ist erst einmal Dezember, ist überall voller Menschen."],["責任者ともなると、休みも自由に取れない。","せきにんしゃともなると、やすみもじゆうにとれない。","Ist man erst einmal verantwortlich, kann man auch Urlaub nicht frei nehmen."]],q:[{q:"三十歳＿＿、考え方も変わってくる。",o:["ともなると","にもまして","はおろか","ながらも"],c:0},{q:"Was steht vor ともなると?",o:["eine Schwelle wie Alter oder Rang","ein Gefühl","eine Farbe","ein Ort"],c:0},{q:"Was nennt der Hauptsatz?",o:["die dann selbstverständliche Folge","eine Bitte","eine Frage","einen Zweifel"],c:0}]},{id:"n1-nitaenai",level:1,title:"〜にたえない — nicht zu ertragen; von Herzen",intro:"Zwei Bedeutungen, die am Wort hängen: unerträglich — oder über die Maßen empfunden.",text:"Verb (Grundform) + にたえない heißt „nicht mit anzusehen/anzuhören“: 見るにたえない, 聞くにたえない. Nomen (Gefühl) + にたえない heißt dagegen „von ganzem Herzen“: 感謝にたえない, 遺憾にたえない. Welche Lesart gilt, entscheidet allein das Wort davor.",tip:"Zwei Muster, ein Ausdruck. Verb davor → unerträglich. Gefühlsnomen davor → im höchsten Maße.",ex:[["その映像は見るにたえない。","そのえいぞうはみるにたえない。","Diese Aufnahmen sind nicht mit anzusehen."],["皆様のご支援に、感謝にたえません。","みなさまのごしえんに、かんしゃにたえません。","Für Ihre Unterstützung bin ich von Herzen dankbar."],["彼の言い訳は聞くにたえなかった。","かれのいいわけはきくにたえなかった。","Seine Ausreden waren nicht mit anzuhören."]],q:[{q:"ご厚意に、感謝＿＿ません。",o:["にたえ","にかたく","にすぎ","にあたら"],c:0},{q:"Wann heißt es „unerträglich“?",o:["wenn ein Verb davorsteht","wenn ein Gefühlsnomen davorsteht","immer","nie"],c:0},{q:"Was bedeutet 感謝にたえない?",o:["von Herzen dankbar","undankbar","gleichgültig","unsicher"],c:0}]},{id:"n1-nikatakunai",level:1,title:"〜に難くない — leicht zu …",intro:"Etwas lässt sich ohne Mühe erschließen.",text:"Nomen (する-Nomen) + に難くない, fast nur mit 想像 und 察する: 想像に難くない, 察するに難くない. Der Sprecher sagt, dass man sich das Gemeinte gut vorstellen kann — meist bei Gefühlslagen anderer.",tip:"Wieder eine Scheinverneinung: 難くない heißt nicht „schwer“, sondern gerade „nicht schwer, also leicht“.",ex:[["彼の落胆は想像に難くない。","かれのらくたんはそうぞうにかたくない。","Seine Enttäuschung lässt sich leicht vorstellen."],["家族の心配は察するに難くない。","かぞくのしんぱいはさっするにかたくない。","Die Sorge der Familie ist leicht nachzufühlen."],["結果がどうなるかは想像に難くなかった。","けっかがどうなるかはそうぞうにかたくなかった。","Wie es ausgehen würde, war leicht vorauszusehen."]],q:[{q:"その苦労は想像＿＿。",o:["に難くない","にたえない","にすぎない","にほかならない"],c:0},{q:"Mit welchen Wörtern steht der Ausdruck fast nur?",o:["想像 und 察する","勉強 und 練習","旅行 und 移動","料理 und 掃除"],c:0},{q:"Was bedeutet 難くない?",o:["leicht","schwer","unmöglich","nötig"],c:0}]},{id:"n1-woyoginakusareru",level:1,title:"〜を余儀なくされる — gezwungen sein zu",intro:"Äußere Umstände lassen keine andere Wahl.",text:"Nomen + を余儀なくされる. Die betroffene Person ist passiv: der Umstand zwingt sie. Die aktive Gegenform 〜を余儀なくさせる bedeutet, dass ein Umstand jemanden zwingt. Schriftsprachlich, häufig in Nachrichten.",tip:"Der Zwang kommt immer von außen und ist unangenehm. Für eine freiwillige Entscheidung passt der Ausdruck nicht.",ex:[["大雨のため、登山は中止を余儀なくされた。","おおあめのため、とざんはちゅうしをよぎなくされた。","Wegen des starken Regens musste die Bergtour abgebrochen werden."],["経営難から、店は閉店を余儀なくされた。","けいえいなんから、みせはへいてんをよぎなくされた。","Wirtschaftliche Not zwang den Laden zur Schließung."],["けがのため、選手は引退を余儀なくされた。","けがのため、せんしゅはいんたいをよぎなくされた。","Die Verletzung zwang den Spieler zum Rücktritt."]],q:[{q:"台風で、大会は延期＿＿。",o:["を余儀なくされた","を禁じ得なかった","にたえなかった","に難くなかった"],c:0},{q:"Woher kommt der Zwang?",o:["von außen","von der Person selbst","aus einem Wunsch","aus einer Gewohnheit"],c:0},{q:"Wie ist die Lage zu bewerten?",o:["unangenehm","erfreulich","gleichgültig","unklar"],c:0}]},{id:"n1-wokinjienai",level:1,title:"〜を禁じ得ない — sich eines Gefühls nicht erwehren können",intro:"Ein Gefühl steigt auf, das sich nicht unterdrücken lässt.",text:"Gefühlsnomen + を禁じ得ない: 涙, 怒り, 同情, 驚き. Der Sprecher berichtet über das eigene Empfinden in gehobener Sprache; über die Gefühle Dritter sagt man es nicht. Sehr schriftsprachlich.",tip:"禁じる = untersagen, 得ない = nicht können. Wörtlich: „ich kann es mir nicht untersagen“.",ex:[["その知らせに、驚きを禁じ得なかった。","そのしらせに、おどろきをきんじえなかった。","Bei dieser Nachricht konnte ich mein Erstaunen nicht verbergen."],["被災地の様子に、涙を禁じ得ない。","ひさいちのようすに、なみだをきんじえない。","Beim Anblick des Katastrophengebiets kann ich die Tränen nicht zurückhalten."],["この対応には怒りを禁じ得ない。","このたいおうにはいかりをきんじえない。","Angesichts dieser Behandlung kann ich meinen Zorn nicht unterdrücken."]],q:[{q:"その光景に同情＿＿。",o:["を禁じ得ない","を余儀なくされる","にたえない","に難くない"],c:0},{q:"Über wessen Gefühle spricht man?",o:["über die eigenen","über fremde","über allgemeine","über gar keine"],c:0},{q:"Was steht vor を禁じ得ない?",o:["ein Gefühlsnomen","ein Verb","ein Ortsname","eine Zahl"],c:0}]},{id:"n1-teyamanai",level:1,title:"〜てやまない — von Herzen und unaufhörlich",intro:"Ein Wunsch oder Gefühl hört nicht auf.",text:"Verb in der て-Form + やまない. Nur mit Gefühlsverben: 願う, 祈る, 愛する, 期待する. Der Sprecher bekundet ein dauerndes, tiefes Empfinden. Feierlich, typisch für Grußworte und Reden.",tip:"やまない kommt von 止む (aufhören). Trotz Verneinungsform ist die Aussage positiv: es hört nicht auf.",ex:[["皆様のご健康を願ってやみません。","みなさまのごけんこうをねがってやみません。","Ich wünsche Ihnen allen von Herzen Gesundheit."],["ご活躍を期待してやまない。","ごかつやくをきたいしてやまない。","Ich erwarte Ihr Wirken mit größter Zuversicht."],["故郷を愛してやまない人だった。","ふるさとをあいしてやまないひとだった。","Er war ein Mensch, der seine Heimat unaufhörlich liebte."]],q:[{q:"ご成功を祈っ＿＿。",o:["てやみません","てたまりません","てなりません","ではいられません"],c:0},{q:"Welche Verben stehen davor?",o:["Gefühlsverben wie 願う oder 祈る","Bewegungsverben","Verben des Essens","Hilfsverben"],c:0},{q:"Wo begegnet man dem Ausdruck?",o:["in Grußworten und Reden","in Chatnachrichten","in Kochrezepten","in Fahrplänen"],c:0}]},{id:"n1-konouenai",level:1,title:"〜この上ない — höher geht es nicht",intro:"Eine Eigenschaft erreicht ihren höchsten Grad.",text:"Nomen (Gefühlswort, する-Nomen) + この上ない oder Adjektiv + こと + この上ない. Anders als 〜きわまりない steht es auch bei positiven Wörtern: 光栄この上ない, うれしいことこの上ない. Adverbial: この上なく静かだ. Schriftsprachlich.",tip:"Wörtlich: „darüber hinaus gibt es nichts“. Passt für Lob wie für Tadel, während きわまりない fast nur tadelt.",ex:[["お招きいただき、光栄この上ありません。","おまねきいただき、こうえいこのうえありません。","Ihre Einladung ist mir die größte Ehre."],["静かなことこの上ない環境だ。","しずかなことこのうえないかんきょうだ。","Eine Umgebung, wie sie stiller nicht sein könnte."],["手続きが煩雑なことこの上ない。","てつづきがはんざつなことこのうえない。","Das Verfahren ist umständlicher, als es nur sein kann."]],q:[{q:"ご配慮に感謝＿＿ありません。",o:["この上","これ以上","それ以上","この下"],c:0},{q:"Worin unterscheidet es sich von きわまりない?",o:["この上ない passt auch für Lob","この上ない tadelt nur","この上ない verneint","es gibt keinen Unterschied"],c:0},{q:"In welchem Register steht der Ausdruck?",o:["schriftsprachlich","salopp","kindlich","technisch"],c:0}]},{id:"n1-zunihaokanai",level:1,title:"〜ずにはおかない — es bleibt nicht aus, dass",intro:"Etwas löst zwangsläufig eine Wirkung aus — oder jemand wird es unweigerlich tun.",text:"Verb (ない-Form ohne ない) + ずにはおかない, bei する → せずにはおかない. Zwei Lesarten: eine Sache ruft eine Wirkung hervor (感動させずにはおかない), oder jemand ist fest entschlossen (真相を明らかにせずにはおかない).",tip:"Verwandt mit 〜ないではおかない, das etwas umgangssprachlicher ist. Die Wirkung tritt ohne Zutun ein — deshalb nicht für eigene Alltagsabsichten.",ex:[["この作品は読む者を感動させずにはおかない。","このさくひんはよむものをかんどうさせずにはおかない。","Dieses Werk rührt jeden, der es liest."],["真相を明らかにせずにはおかない。","しんそうをあきらかにせずにはおかない。","Wir werden die Wahrheit unweigerlich ans Licht bringen."],["彼の言葉は聞く人を考えさせずにはおかない。","かれのことばはきくひとをかんがえさせずにはおかない。","Seine Worte bringen jeden Zuhörer zum Nachdenken."]],q:[{q:"この映画は観る人を泣かせ＿＿。",o:["ずにはおかない","ないではいられない","かねない","っこない"],c:0},{q:"Was gilt für die Wirkung?",o:["sie tritt zwangsläufig ein","sie ist unwahrscheinlich","sie ist erwünscht","sie ist verboten"],c:0},{q:"Wie lautet die Form bei する?",o:["せずにはおかない","しずにはおかない","するずにはおかない","さずにはおかない"],c:0}]},{id:"n1-zunihasumanai",level:1,title:"〜ずにはすまない — es geht nicht ohne",intro:"Gesellschaftlicher Druck macht eine Handlung unausweichlich.",text:"Verb (ない-Form ohne ない) + ずにはすまない, bei する → せずにはすまない. Anders als 〜ずにはおかない geht es hier nicht um eine Wirkung, sondern um eine Pflicht, der man sich nicht entziehen kann: entschuldigen, bezahlen, erklären.",tip:"すむ heißt hier „damit ist es getan“. 〜ずにはすまない: damit allein ist es eben nicht getan.",ex:[["壊したのだから、弁償せずにはすまないだろう。","こわしたのだから、べんしょうせずにはすまないだろう。","Weil er es zerbrochen hat, wird er wohl Ersatz leisten müssen."],["これだけ迷惑をかけたら、謝らずにはすまない。","これだけめいわくをかけたら、あやまらずにはすまない。","Nach so viel Ärger komme ich ums Entschuldigen nicht herum."],["理由を説明せずにはすまない状況だ。","りゆうをせつめいせずにはすまないじょうきょうだ。","Eine Lage, in der eine Erklärung unvermeidlich ist."]],q:[{q:"約束を破ったのだから、謝ら＿＿。",o:["ずにはすまない","ずにはおかない","っこない","かねない"],c:0},{q:"Woher kommt der Zwang?",o:["aus gesellschaftlicher Erwartung","aus Naturgesetzen","aus einem Wunsch","aus Zufall"],c:0},{q:"Wie lautet die Form bei する?",o:["せずにはすまない","しずにはすまない","するずにはすまない","さずにはすまない"],c:0}]},{id:"n1-bekumonai",level:1,title:"〜べくもない — nicht im Entferntesten möglich",intro:"Etwas ist grundsätzlich ausgeschlossen, nicht nur schwierig.",text:"Verb (Wörterbuchform) + べくもない, bei する auch するべくもない / すべくもない. Häufig mit 知る, 望む, 比べる: 知るべくもない (davon konnte man unmöglich wissen). Sehr schriftsprachlich.",tip:"Stärker als 〜ない: nicht „ich weiß es nicht“, sondern „ich konnte es gar nicht wissen“.",ex:[["当時の事情は、今の我々には知るべくもない。","とうじのじじょうは、いまのわれわれにはしるべくもない。","Wie es damals war, können wir heute unmöglich wissen."],["両者の実力は比べるべくもない。","りょうしゃのじつりょくはくらべるべくもない。","Das Können beider lässt sich gar nicht vergleichen."],["独立など望むべくもなかった。","どくりつなどのぞむべくもなかった。","An Unabhängigkeit war nicht im Entferntesten zu denken."]],q:[{q:"結果は予想する＿＿なかった。",o:["べくも","ばかりも","どころも","ことも"],c:0},{q:"Wie stark ist die Aussage?",o:["grundsätzlich ausgeschlossen","nur schwierig","unsicher","wahrscheinlich"],c:0},{q:"Mit welchen Verben steht der Ausdruck oft?",o:["知る, 望む, 比べる","食べる, 飲む, 寝る","行く, 来る, 帰る","買う, 売る, 借りる"],c:0}]},{id:"n1-bekarazu",level:1,title:"〜べからず / 〜べからざる — es ist untersagt",intro:"Verbot in der Sprache von Schildern und Grundsätzen.",text:"Verb (Wörterbuchform) + べからず am Satzende (auf Schildern), oder + べからざる vor einem Nomen: 許すべからざる行為. Bei する gilt すべからず. Altertümlich; im Alltag sagt man 〜てはいけない.",tip:"べからざる + Nomen ist im Zeitungsdeutsch häufig: 欠くべからざる存在 — eine unentbehrliche Größe.",ex:[["芝生に入るべからず。","しばふにはいるべからず。","Betreten des Rasens verboten."],["それは許すべからざる行為だ。","それはゆるすべからざるこういだ。","Das ist eine nicht zu duldende Handlung."],["彼は欠くべからざる存在だ。","かれはかくべからざるそんざいだ。","Er ist eine unentbehrliche Größe."]],q:[{q:"ここにごみを捨てる＿＿。",o:["べからず","べきだ","ばかり","どころ"],c:0},{q:"Wie lautet die Form vor einem Nomen?",o:["べからざる","べからずの","べからずな","べからずと"],c:0},{q:"Wo begegnet man べからず?",o:["auf Schildern","in Chatnachrichten","in Kinderliedern","in Kochrezepten"],c:0}]},{id:"n1-naimademo",level:1,title:"〜ないまでも — wenn auch nicht …, so doch",intro:"Das Höchste wird nicht verlangt, aber ein Mindestmaß schon.",text:"Verb (ない-Form) + までも, auch Nomen + でないまでも. Der erste Teil nennt das anspruchsvollere Ziel, der zweite das noch zumutbare Minimum. Im Hauptsatz steht oft せめて oder 少なくとも.",tip:"Die Richtung ist wichtig: erst das Große (das ausbleiben darf), dann das Kleine (das sein muss).",ex:[["毎日とは言わないまでも、週に一度は連絡してほしい。","まいにちとはいわないまでも、しゅうにいちどはれんらくしてほしい。","Wenn schon nicht täglich, so möchte ich doch einmal die Woche hören."],["完璧でないまでも、及第点は取れた。","かんぺきでないまでも、きゅうだいてんはとれた。","Wenn auch nicht perfekt, so reichte es doch zum Bestehen."],["全員とは言わないまでも、多くが賛成した。","ぜんいんとはいわないまでも、おおくがさんせいした。","Wenn auch nicht alle, so stimmten doch viele zu."]],q:[{q:"優勝とは言わ＿＿、入賞はしたい。",o:["ないまでも","ないばかりに","ないどころか","ないうちに"],c:0},{q:"Was steht im ersten Teil?",o:["das anspruchsvollere Ziel","das Mindestmaß","eine Frage","ein Verbot"],c:0},{q:"Welches Wort steht oft im Hauptsatz?",o:["せめて","まったく","決して","二度と"],c:0}]},{id:"n1-naitomokagiranai",level:1,title:"〜ないとも限らない — es ist nicht ausgeschlossen, dass",intro:"Vorsichtige Warnung: man kann es nicht ganz ausschließen.",text:"Verb (ない-Form) + とも限らない. Doppelte Verneinung mit der Wirkung einer Warnung: es könnte doch passieren, also sei vorsichtig. Oft mit 念のため oder 万一.",tip:"Nicht mit 〜とは限らない verwechseln (nicht unbedingt). Hier steht ein ない davor, und die Aussage warnt.",ex:[["雨が降らないとも限らないから、傘を持って行こう。","あめがふらないともかぎらないから、かさをもっていこう。","Es könnte doch regnen — nehmen wir einen Schirm mit."],["事故が起きないとも限らない。","じこがおきないともかぎらない。","Ein Unfall ist nicht ausgeschlossen."],["誰かが見ていないとも限らない。","だれかがみていないともかぎらない。","Es kann gut sein, dass jemand zusieht."]],q:[{q:"必要になら＿＿ので、残しておこう。",o:["ないとも限らない","ないではいられない","ないにすぎない","ないどころではない"],c:0},{q:"Welche Wirkung hat der Ausdruck?",o:["eine Warnung","ein Lob","eine Bitte","eine Frage"],c:0},{q:"Worin unterscheidet er sich von 〜とは限らない?",o:["hier steht ein ない davor","er ist gleichbedeutend","er ist umgangssprachlich","er verneint nicht"],c:0}]},{id:"n1-nikoshitakotohanai",level:1,title:"〜に越したことはない — besser ist es allemal",intro:"Wenn es geht, ist es so am besten — aber nicht zwingend.",text:"Grundform / い-Adjektiv / な-Adjektiv (Stamm, ohne な) / Nomen + に越したことはない (bei な-Adjektiv und Nomen auch mit である). Ein milder Rat ohne Zwang: mehr Geld schadet nicht, früh sein ist besser. Oft mit もちろん oder 〜が.",tip:"Der Ratschlag ist unverbindlich. Wer eine Pflicht ausdrücken will, nimmt 〜なければならない.",ex:[["準備は早いに越したことはない。","じゅんびははやいにこしたことはない。","Mit der Vorbereitung ist früher allemal besser."],["部屋は静かに越したことはない。","へやはしずかにこしたことはない。","Ein ruhiges Zimmer ist allemal besser."],["確認しておくに越したことはない。","かくにんしておくにこしたことはない。","Nachzuprüfen schadet auf keinen Fall."]],q:[{q:"安全は確かめておく＿＿。",o:["に越したことはない","にほかならない","にすぎない","に違いない"],c:0},{q:"Wie verbindlich ist der Rat?",o:["unverbindlich","zwingend","verboten","gleichgültig"],c:0},{q:"Welche Form steht bei な-Adjektiven?",o:["nur der Stamm + に越したことはない (ohne な)","の + に越したことはない","で + に越したことはない","と + に越したことはない"],c:0}]},{id:"n1-beku",level:1,title:"〜べく — um zu",intro:"Schriftsprachliche Absicht: zu dem Zweck, dass.",text:"Verb (Wörterbuchform) + べく, bei する auch すべく. Der Hauptsatz nennt die Handlung, die dem Zweck dient. Kein Befehl, keine Bitte im Hauptsatz — nur ein Bericht über zielgerichtetes Handeln. Gehobene Schriftsprache.",tip:"Die Alltagsentsprechung ist 〜ために. べく findet man in Berichten, Chroniken und Firmenmitteilungen.",ex:[["真相を明らかにすべく、調査を始めた。","しんそうをあきらかにすべく、ちょうさをはじめた。","Um die Wahrheit ans Licht zu bringen, begann die Untersuchung."],["需要に応えるべく、生産を拡大した。","じゅようにこたえるべく、せいさんをかくだいした。","Um der Nachfrage gerecht zu werden, wurde die Produktion ausgeweitet."],["彼は夢をかなえるべく、故郷を離れた。","かれはゆめをかなえるべく、こきょうをはなれた。","Um seinen Traum zu erfüllen, verließ er die Heimat."]],q:[{q:"事故を防ぐ＿＿、規則を見直した。",o:["べく","べきで","ばかりに","ながら"],c:0},{q:"Was darf im Hauptsatz NICHT stehen?",o:["ein Befehl","eine Handlung","ein Bericht","eine Vergangenheitsform"],c:0},{q:"Was ist die Alltagsentsprechung?",o:["〜ために","〜ので","〜のに","〜たら"],c:0}]},{id:"n1-ngatameni",level:1,title:"〜んがため(に) — um willen",intro:"Nachdrückliche, altertümliche Zweckangabe.",text:"Verb (ない-Form ohne ない) + んがため(に), bei する → せんがため. Der Zweck ist stark, oft existenziell: um zu überleben, um zu gewinnen. Noch schriftsprachlicher als 〜べく und klingt fast literarisch.",tip:"Die Form täuscht: das ん kommt nicht von der Verneinung, sondern von der alten Endung む. せんがため heißt „um zu tun“, nicht „um nicht zu tun“.",ex:[["生きんがために、彼は働き続けた。","いきんがために、かれははたらきつづけた。","Um zu überleben, arbeitete er weiter."],["勝たんがための努力だった。","かたんがためのどりょくだった。","Es war eine Anstrengung um des Sieges willen."],["真実を伝えんがため、彼は筆を執った。","しんじつをつたえんがため、かれはふでをとった。","Um die Wahrheit zu verbreiten, griff er zur Feder."]],q:[{q:"目的を達せ＿＿、彼は全てを捨てた。",o:["んがために","ないために","んばかりに","ながらに"],c:0},{q:"Was bedeutet das ん in んがため?",o:["es kommt von der alten Endung む","es verneint","es fragt","es betont"],c:0},{q:"Wie wirkt der Ausdruck?",o:["literarisch","alltäglich","technisch","kindlich"],c:0}]},{id:"n1-youmononara",level:1,title:"〜ようものなら — wenn man auch nur",intro:"Schon der Versuch hätte schlimme Folgen.",text:"Verb (Willensform) + ものなら. Der erste Teil nennt eine riskante Handlung, der zweite die harte Folge. Der Sprecher warnt oder übertreibt bewusst.",tip:"Nicht mit 〜ものなら in 〜たいものなら oder 行けるものなら verwechseln: dort steht die Potentialform und es geht um einen Wunsch.",ex:[["遅刻しようものなら、大目玉を食らう。","ちこくしようものなら、おおめだまをくらう。","Käme ich auch nur zu spät, gäbe es eine gewaltige Standpauke."],["文句を言おうものなら、二度と呼ばれない。","もんくをいおうものなら、にどとよばれない。","Beschwerte man sich auch nur, würde man nie wieder eingeladen."],["触ろうものなら、すぐに警報が鳴る。","さわろうものなら、すぐにけいほうがなる。","Berührte man es auch nur, ginge sofort der Alarm los."]],q:[{q:"忘れ＿＿、信用を失う。",o:["ようものなら","たものなら","るものなら","ないものなら"],c:0},{q:"Welche Form steht vor ものなら?",o:["die Willensform","die た-Form","die ない-Form","die ば-Form"],c:0},{q:"Was tut der Sprecher?",o:["er warnt","er lobt","er fragt","er bittet"],c:0}]},{id:"n1-tomonaku",level:1,title:"〜ともなく / 〜ともなしに — ohne rechte Absicht",intro:"Eine Handlung geschieht nebenbei, ohne dass man sie beabsichtigt hätte.",text:"Verb (Wörterbuchform) + ともなく / ともなしに, meist mit Wahrnehmungsverben: 見るともなく見る, 聞くともなしに聞く. Auch mit Fragewörtern: どこからともなく (von irgendwoher).",tip:"Typisch ist die Wiederholung desselben Verbs: 見るともなく見ていた — ich sah hin, ohne hinzusehen.",ex:[["見るともなく窓の外を眺めていた。","みるともなくまどのそとをながめていた。","Ohne rechte Absicht sah ich aus dem Fenster."],["聞くともなしに、隣の会話が耳に入った。","きくともなしに、となりのかいわがみみにはいった。","Ohne hinzuhören bekam ich das Gespräch nebenan mit."],["どこからともなく花の香りが漂ってきた。","どこからともなくはなのかおりがただよってきた。","Von irgendwoher wehte Blütenduft heran."]],q:[{q:"聞く＿＿、その話が耳に入った。",o:["ともなしに","とばかりに","ながらも","つつも"],c:0},{q:"Mit welchen Verben steht der Ausdruck meist?",o:["Wahrnehmungsverben","Bewegungsverben","Hilfsverben","Verben des Sagens"],c:0},{q:"Was bedeutet どこからともなく?",o:["von irgendwoher","von nirgendwo","von überall","von hier"],c:0}]},{id:"n1-narini",level:1,title:"〜なりに / 〜なりの — auf die eigene Weise",intro:"Im Rahmen der eigenen Möglichkeiten — nicht mehr, aber auch nicht weniger.",text:"Nomen / Grundform + なりに (adverbial) oder + なりの + Nomen. Der Sprecher erkennt an, dass jemand mit seinen begrenzten Mitteln etwas geleistet hat. Anerkennend, nie herablassend gemeint — mit 私なりに spricht man am sichersten über sich selbst.",tip:"それなりに ist die häufigste feste Form: „auf seine Art durchaus“.",ex:[["子どもは子どもなりに考えている。","こどもはこどもなりにかんがえている。","Kinder denken auf ihre Weise durchaus mit."],["私なりに精一杯やりました。","わたしなりにせいいっぱいやりました。","Ich habe es auf meine Weise nach Kräften versucht."],["彼には彼なりの理由があるのだろう。","かれにはかれなりのりゆうがあるのだろう。","Er wird seine eigenen Gründe haben."]],q:[{q:"私＿＿工夫してみます。",o:["なりに","ながらに","ばかりに","どころに"],c:0},{q:"Welchen Ton hat der Ausdruck?",o:["anerkennend","herablassend","vorwurfsvoll","gleichgültig"],c:0},{q:"Wie lautet die Form vor einem Nomen?",o:["なりの","なりに","なりで","なりと"],c:0}]},{id:"n1-womonotomosezu",level:1,title:"〜をものともせず — ungeachtet aller",intro:"Ein Hindernis wird nicht beachtet und überwunden.",text:"Nomen (Hindernis) + をものともせず(に). Anerkennend über Dritte: trotz Verletzung, trotz Sturm, trotz Gegenwind. Über sich selbst sagt man es nicht, weil es Bewunderung ausdrückt.",tip:"Verwandt mit 〜をよそに, aber dort geht es um Gleichgültigkeit gegenüber anderen; hier um Tapferkeit gegenüber Widrigkeiten.",ex:[["彼は怪我をものともせず、試合に出た。","かれはけがをものともせず、しあいにでた。","Ungeachtet seiner Verletzung trat er im Spiel an."],["荒天をものともせず、船は出航した。","こうてんをものともせず、ふねはしゅっこうした。","Ungeachtet des Unwetters lief das Schiff aus."],["批判をものともせず、計画を進めた。","ひはんをものともせず、けいかくをすすめた。","Ungeachtet der Kritik trieb er den Plan voran."]],q:[{q:"彼女は困難＿＿、研究を続けた。",o:["をものともせず","をよそに","にもまして","はおろか"],c:0},{q:"Über wen spricht man damit?",o:["über Dritte","über sich selbst","über Gegenstände","über Tiere"],c:0},{q:"Was steht vor をものともせず?",o:["ein Hindernis","ein Wunsch","ein Ort","eine Zeit"],c:0}]},{id:"n1-woyosoni",level:1,title:"〜をよそに — unbekümmert um",intro:"Jemand kümmert sich nicht um das, was andere denken oder fühlen.",text:"Nomen + をよそに. Meist tadelnd: ungeachtet der Sorge der Eltern, ungeachtet der Proteste. Der erste Teil nennt fremde Gefühle oder Erwartungen, die missachtet werden.",tip:"Unterschied zu 〜をものともせず: dort Bewunderung für Tapferkeit, hier Missbilligung von Gleichgültigkeit.",ex:[["親の心配をよそに、彼は旅に出た。","おやのしんぱいをよそに、かれはたびにでた。","Unbekümmert um die Sorge seiner Eltern brach er zu einer Reise auf."],["住民の反対をよそに、工事は始まった。","じゅうみんのはんたいをよそに、こうじははじまった。","Ungeachtet der Proteste der Anwohner begannen die Bauarbeiten."],["周囲の期待をよそに、彼は引退を選んだ。","しゅういのきたいをよそに、かれはいんたいをえらんだ。","Unbekümmert um die Erwartungen ringsum wählte er den Rücktritt."]],q:[{q:"家族の反対＿＿、彼は決断した。",o:["をよそに","をものともせず","にもまして","をおいて"],c:0},{q:"Welchen Ton hat der Ausdruck?",o:["tadelnd","bewundernd","neutral","bittend"],c:0},{q:"Was steht vor をよそに?",o:["fremde Gefühle oder Erwartungen","ein Hindernis","ein Ort","eine Zahl"],c:0}]},{id:"n1-nikakotsukete",level:1,title:"〜にかこつけて — unter dem Vorwand",intro:"Ein vorgeschobener Grund dient dem eigentlichen Zweck.",text:"Nomen + にかこつけて. Der genannte Anlass ist nur die Ausrede; das wahre Ziel folgt im Hauptsatz. Immer mit leichtem Tadel, auch über sich selbst mit Selbstironie.",tip:"Nah an 〜を口実に. かこつける heißt „etwas vorschieben“ — der Grund ist nicht der echte.",ex:[["出張にかこつけて、観光を楽しんだ。","しゅっちょうにかこつけて、かんこうをたのしんだ。","Unter dem Vorwand der Dienstreise habe ich die Stadt besichtigt."],["病気にかこつけて、会合を欠席した。","びょうきにかこつけて、かいごうをけっせきした。","Unter dem Vorwand einer Krankheit blieb er der Versammlung fern."],["勉強にかこつけて、部屋にこもっていた。","べんきょうにかこつけて、へやにこもっていた。","Unter dem Vorwand des Lernens blieb ich im Zimmer."]],q:[{q:"仕事＿＿、遠出をした。",o:["にかこつけて","をものともせず","にもまして","はおろか"],c:0},{q:"Was ist der genannte Anlass?",o:["nur ein Vorwand","der echte Grund","ein Zufall","ein Verbot"],c:0},{q:"Welcher verwandte Ausdruck passt?",o:["〜を口実に","〜をもとに","〜を通じて","〜をこめて"],c:0}]},{id:"n1-niatte",level:1,title:"〜にあって — in der Lage, in der man sich befindet",intro:"Ein besonderer Ort oder Zeitpunkt bildet den Rahmen für das Folgende.",text:"Nomen (Zeit, Lage, Stellung) + にあって. Häufig bei außergewöhnlichen Umständen: in dieser Notlage, in solcher Stellung. Der Hauptsatz nennt, was unter diesen Umständen gilt. Schriftsprachlich.",tip:"Nicht mit 〜において (in, bei) verwechseln: において ist neutral örtlich, にあって betont die besondere Lage.",ex:[["非常時にあって、冷静さが求められる。","ひじょうじにあって、れいせいさがもとめられる。","In einer Notlage ist Besonnenheit gefragt."],["この立場にあって、私情は挟めない。","このたちばにあって、しじょうははさめない。","In dieser Stellung kann ich keine persönlichen Gefühle einbringen."],["困難な状況にあっても、彼は笑顔を絶やさなかった。","こんなんなじょうきょうにあっても、かれはえがおをたやさなかった。","Auch in schwieriger Lage verlor er das Lächeln nicht."]],q:[{q:"戦時＿＿、人々は助け合った。",o:["にあって","にあたって","において","にわたって"],c:0},{q:"Worin unterscheidet es sich von 〜において?",o:["にあって betont die besondere Lage","にあって ist neutraler","にあって verneint","es gibt keinen Unterschied"],c:0},{q:"Was steht vor にあって?",o:["Zeit, Lage oder Stellung","ein Gefühl","eine Farbe","eine Zahl"],c:0}]},{id:"n1-taritomo",level:1,title:"〜たりとも — nicht einmal ein einziges",intro:"Selbst die kleinste Menge ist ausgeschlossen.",text:"Zahlwort mit 一 + たりとも, danach eine Verneinung: 一日たりとも忘れない, 一円たりとも無駄にできない. Nachdrücklich und schriftsprachlich; die Zahl ist immer die kleinste denkbare.",tip:"Fast immer mit 一. Eine andere Zahl wirkt falsch — es geht um das absolute Minimum.",ex:[["一日たりとも忘れたことはない。","いちにちたりともわすれたことはない。","Ich habe es keinen einzigen Tag vergessen."],["一円たりとも無駄にはできない。","いちえんたりともむだにはできない。","Nicht ein einziger Yen darf verschwendet werden."],["一瞬たりとも気を抜けない。","いっしゅんたりともきをぬけない。","Nicht einen Augenblick darf man nachlassen."]],q:[{q:"一歩＿＿引くつもりはない。",o:["たりとも","ながらも","どころか","ばかりか"],c:0},{q:"Welche Zahl steht fast immer davor?",o:["一","十","百","千"],c:0},{q:"Was folgt im Satz?",o:["eine Verneinung","eine Bitte","eine Frage","ein Befehl"],c:0}]},{id:"n1-deare",level:1,title:"〜であれ / 〜であろうと — wer oder was es auch sei",intro:"Gleichgültig, welcher Fall vorliegt — die Aussage gilt.",text:"Nomen + であれ / であろうと, oft mit Fragewörtern: 誰であれ, どこであろうと. Auch verdoppelt: 雨であれ雪であれ. Der Hauptsatz nennt, was unabhängig davon gilt.",tip:"Nah an 〜にしても und 〜でも, aber であれ ist schriftsprachlicher und klingt nach Grundsatz.",ex:[["理由が何であれ、規則は守るべきだ。","りゆうがなんであれ、きそくはまもるべきだ。","Was auch immer der Grund sei — die Regel ist einzuhalten."],["雨であれ雪であれ、試合は行われる。","あめであれゆきであれ、しあいはおこなわれる。","Ob Regen oder Schnee — das Spiel findet statt."],["相手が誰であろうと、態度は変えない。","あいてがだれであろうと、たいどはかえない。","Wer auch immer mein Gegenüber ist — meine Haltung ändert sich nicht."]],q:[{q:"結果がどう＿＿、最後までやる。",o:["であれ","であって","でこそ","でさえ"],c:0},{q:"Womit steht der Ausdruck oft?",o:["mit Fragewörtern","mit Zahlen","mit Farben","mit Ortsnamen"],c:0},{q:"Wie wirkt であれ gegenüber でも?",o:["schriftsprachlicher","lockerer","verneinend","fragend"],c:0}]},{id:"n1-ikan",level:1,title:"〜いかん / 〜いかんによらず — je nach; unabhängig von",intro:"Der Ausgang hängt von etwas ab — oder gerade nicht.",text:"Nomen + の + いかんだ (es hängt davon ab), Nomen + いかんでは (je nachdem), Nomen + いかんによらず / いかんにかかわらず (unabhängig davon). Amtssprache: Bekanntmachungen, Verträge, Aushänge.",tip:"如何 (いかん) heißt „wie beschaffen“. Mit によらず kippt die Bedeutung ins Gegenteil — genau hinsehen, ob die Verneinung dabeisteht.",ex:[["合否は成績のいかんによる。","ごうひはせいせきのいかんによる。","Bestehen oder Nichtbestehen hängt von den Leistungen ab."],["理由のいかんによらず、返金はいたしません。","りゆうのいかんによらず、へんきんはいたしません。","Unabhängig vom Grund erfolgt keine Rückerstattung."],["天候いかんでは、中止となる場合がございます。","てんこういかんでは、ちゅうしとなるばあいがございます。","Je nach Witterung kann die Veranstaltung entfallen."]],q:[{q:"結果＿＿によらず、参加賞を差し上げます。",o:["いかん","ながら","ばかり","どころ"],c:0},{q:"Was bedeutet 〜いかんによらず?",o:["unabhängig davon","je nachdem","wegen","trotz"],c:0},{q:"In welchem Register steht der Ausdruck?",o:["Amtssprache","Jugendsprache","Kindersprache","Dialekt"],c:0}]},{id:"n1-wofumaete",level:1,title:"〜を踏まえ(て) — auf der Grundlage von",intro:"Eine Entscheidung berücksichtigt ausdrücklich das Vorangegangene.",text:"Nomen + を踏まえて / を踏まえた + Nomen. Typisch für Diskussionen und Berichte: die Ergebnisse berücksichtigend, die Kritik aufgreifend. Sachlich, ohne Wertung.",tip:"Nah an 〜をもとに, aber 踏まえる betont, dass man das Vorige geprüft und ernst genommen hat, nicht nur als Material benutzt.",ex:[["今回の反省を踏まえて、計画を練り直す。","こんかいのはんせいをふまえて、けいかくをねりなおす。","Die Lehren aus diesem Mal berücksichtigend, überarbeiten wir den Plan."],["調査結果を踏まえた提案です。","ちょうさけっかをふまえたていあんです。","Ein Vorschlag auf Grundlage der Untersuchungsergebnisse."],["前回の議論を踏まえ、方針を決めたい。","ぜんかいのぎろんをふまえ、ほうしんをきめたい。","Auf Grundlage der letzten Diskussion möchte ich die Richtung festlegen."]],q:[{q:"意見＿＿、修正案を出した。",o:["を踏まえて","をよそに","にかこつけて","はさておき"],c:0},{q:"Worin unterscheidet es sich von 〜をもとに?",o:["踏まえる betont das Prüfen und Ernstnehmen","踏まえる ist salopper","踏まえる verneint","es gibt keinen Unterschied"],c:0},{q:"Wie lautet die Form vor einem Nomen?",o:["を踏まえた","を踏まえで","を踏まえに","を踏まえと"],c:0}]},{id:"n1-nisokushite",level:1,title:"〜に即して — im Einklang mit",intro:"Etwas richtet sich genau nach einer Vorgabe oder den Tatsachen.",text:"Nomen + に即して / に即した + Nomen. Vor allem mit 事実, 実情, 規則, 法律: den Tatsachen entsprechend, dem Gesetz gemäß. Schriftsprachlich und sachlich.",tip:"Unterschied zu 〜に沿って: 沿う folgt einer Linie oder einem Wunsch, 即す hält sich eng an eine Vorgabe oder Tatsache.",ex:[["事実に即して報告してください。","じじつにそくしてほうこくしてください。","Berichten Sie bitte den Tatsachen entsprechend."],["法律に即した処理が必要だ。","ほうりつにそくしたしょりがひつようだ。","Eine dem Gesetz entsprechende Bearbeitung ist nötig."],["現場の実情に即した対策を取る。","げんばのじつじょうにそくしたたいさくをとる。","Wir ergreifen Maßnahmen, die der Lage vor Ort entsprechen."]],q:[{q:"規則＿＿判断します。",o:["に即して","にかけて","にわたって","にあたって"],c:0},{q:"Mit welchen Wörtern steht der Ausdruck oft?",o:["事実, 規則, 法律","天気, 季節, 色","名前, 住所, 電話","食事, 睡眠, 運動"],c:0},{q:"Worin unterscheidet es sich von 〜に沿って?",o:["即す hält sich enger an eine Vorgabe","即す ist lockerer","即す verneint","es gibt keinen Unterschied"],c:0}]},{id:"n1-niterashite",level:1,title:"〜に照らして — gemessen an",intro:"Ein Fall wird an einem Maßstab geprüft.",text:"Nomen + に照らして / に照らし合わせて. Der Maßstab ist ein Gesetz, eine Regel, eine Erfahrung: am Gesetz gemessen, an der bisherigen Praxis gemessen. Sachlich und schriftsprachlich.",tip:"照らす heißt „anleuchten“ — man hält den Fall gegen das Licht der Regel. Nah an 〜に即して, aber 照らす betont das Prüfen, 即す das Sich-Richten.",ex:[["規則に照らして、この行為は認められない。","きそくにてらして、このこういはみとめられない。","Am Regelwerk gemessen ist dieses Verhalten nicht zulässig."],["過去の例に照らせば、結論は明らかだ。","かこのれいにてらせば、けつろんはあきらかだ。","An früheren Fällen gemessen liegt der Schluss auf der Hand."],["法律に照らし合わせて判断した。","ほうりつにてらしあわせてはんだんした。","Ich habe im Abgleich mit dem Gesetz entschieden."]],q:[{q:"基準＿＿、この数値は高すぎる。",o:["に照らして","にかけて","につれて","において"],c:0},{q:"Was ist der Maßstab typischerweise?",o:["ein Gesetz oder eine Regel","ein Gefühl","ein Ort","eine Farbe"],c:0},{q:"Worin unterscheidet es sich von 〜に即して?",o:["照らす betont das Prüfen","照らす ist salopper","照らす verneint","es gibt keinen Unterschied"],c:0}]},{id:"n1-nikakawaru",level:1,title:"〜にかかわる — es geht um; es steht auf dem Spiel",intro:"Etwas Gewichtiges ist berührt — oft die Existenz selbst.",text:"Nomen + にかかわる + Nomen, oder am Satzende. Typisch mit 命, 信用, 名誉, 将来: da geht es ums Leben, da steht der Ruf auf dem Spiel. Das Berührte ist immer schwerwiegend.",tip:"Nicht mit 〜に関する (bezüglich) verwechseln: 関する ist neutral-thematisch, かかわる sagt, dass etwas Wichtiges betroffen ist.",ex:[["これは命にかかわる問題だ。","これはいのちにかかわるもんだいだ。","Das ist eine Frage auf Leben und Tod."],["会社の信用にかかわるので、慎重に対応したい。","かいしゃのしんようにかかわるので、しんちょうにたいおうしたい。","Weil der Ruf der Firma auf dem Spiel steht, will ich behutsam vorgehen."],["将来にかかわる大事な選択だ。","しょうらいにかかわるだいじなせんたくだ。","Eine wichtige Wahl, bei der es um die Zukunft geht."]],q:[{q:"名誉＿＿問題だから、譲れない。",o:["にかかわる","に関する","にわたる","における"],c:0},{q:"Wie ist das Berührte beschaffen?",o:["schwerwiegend","nebensächlich","erfreulich","gleichgültig"],c:0},{q:"Worin unterscheidet es sich von 〜に関する?",o:["関する ist neutral-thematisch","関する ist dringlicher","関する verneint","es gibt keinen Unterschied"],c:0}]},{id:"n1-womotoni",level:1,title:"〜をもとに — auf Grundlage von",intro:"Etwas Vorhandenes dient als Material für etwas Neues.",text:"Nomen + をもとに(して) / をもとにした + Nomen. Der Ausgangsstoff wird verarbeitet: nach einer wahren Begebenheit, auf Basis der Daten. Sachlich und häufig.",tip:"Unterschied zu 〜に基づいて: もとに nimmt etwas als Material und gestaltet frei, 基づいて hält sich streng an die Vorlage.",ex:[["実話をもとにした映画だ。","じつわをもとにしたえいがだ。","Ein Film nach einer wahren Begebenheit."],["調査データをもとに報告書を作成した。","ちょうさデータをもとにほうこくしょをさくせいした。","Auf Grundlage der Erhebungsdaten habe ich den Bericht erstellt."],["伝説をもとに、この祭りが生まれた。","でんせつをもとに、このまつりがうまれた。","Aus einer Sage heraus entstand dieses Fest."]],q:[{q:"アンケートの結果＿＿、改善案を出した。",o:["をもとに","をよそに","にかこつけて","はさておき"],c:0},{q:"Worin unterscheidet es sich von 〜に基づいて?",o:["もとに gestaltet freier","もとに ist strenger","もとに verneint","es gibt keinen Unterschied"],c:0},{q:"Wie lautet die Form vor einem Nomen?",o:["をもとにした","をもとにで","をもとにと","をもとにも"],c:0}]},{id:"n1-katagata",level:1,title:"〜かたがた — bei dieser Gelegenheit zugleich",intro:"Ein Besuch oder Schreiben erfüllt zwei Zwecke auf einmal.",text:"する-Nomen + かたがた. Fast nur in festen Höflichkeitswendungen: お礼かたがた, ご挨拶かたがた, お見舞いかたがた. Der Hauptsatz nennt die Handlung (besuchen, schreiben, vorbeikommen). Sehr förmlich und schriftlich.",tip:"Nah an 〜がてら und 〜ついでに, aber かたがた ist die förmlichste der drei und steht fast nur mit Höflichkeitsnomen.",ex:[["お礼かたがた、ご挨拶に伺いました。","おれいかたがた、ごあいさつにうかがいました。","Ich bin gekommen, um zu danken und mich zugleich vorzustellen."],["ご報告かたがた、お願いを申し上げます。","ごほうこくかたがた、おねがいをもうしあげます。","Ich berichte und trage zugleich eine Bitte vor."],["お見舞いかたがた、様子を見に行った。","おみまいかたがた、ようすをみにいった。","Ich bin zum Krankenbesuch gegangen und habe zugleich nach dem Rechten gesehen."]],q:[{q:"ご挨拶＿＿、お伺いいたします。",o:["かたがた","かたわら","がてら","ついでに"],c:0},{q:"Welche Wörter stehen davor?",o:["Höflichkeitsnomen wie お礼","Verben","Zahlen","Farben"],c:0},{q:"Wie förmlich ist der Ausdruck?",o:["sehr förmlich","locker","neutral","salopp"],c:0}]},{id:"n1-majiki",level:1,title:"〜まじき — was sich nicht gehört",intro:"Ein Verhalten passt nicht zu einer Rolle — schärfer als ein bloßes Verbot.",text:"Verb (Wörterbuchform) + まじき + Nomen, fast nur in der Fügung 〜にあるまじき: 教師にあるまじき行為. Der Sprecher verurteilt, weil das Verhalten der Rolle widerspricht. Altertümlich und sehr streng.",tip:"まじき ist die alte attributive Form von まじ (nicht sollen). Es steht immer vor einem Nomen, nie am Satzende.",ex:[["それは教師にあるまじき行為だ。","それはきょうしにあるまじきこういだ。","Das ist ein Verhalten, das einem Lehrer nicht ansteht."],["政治家にあるまじき発言だった。","せいじかにあるまじきはつげんだった。","Eine Äußerung, die einem Politiker nicht ansteht."],["医師として許すまじき過ちだ。","いしとしてゆるすまじきあやまちだ。","Ein Fehler, der einem Arzt nicht durchgehen darf."]],q:[{q:"警察官にある＿＿行いだ。",o:["まじき","べからず","ないまでも","ならでは"],c:0},{q:"Wo steht まじき im Satz?",o:["vor einem Nomen","am Satzende","am Satzanfang","nach einer Partikel"],c:0},{q:"Welchen Ton hat der Ausdruck?",o:["streng verurteilend","mild ratend","fragend","bittend"],c:0}]},{id:"n1-gotoki",level:1,title:"〜ごとき / 〜ごとく — gleichsam wie",intro:"Schriftsprachlicher Vergleich, der Bilder aufruft.",text:"Nomen + の + ごとき / ごとく, oder Verb (た-Form) + が + ごとし. Alte Entsprechung zu 〜ようだ: ごとく adverbial (wie …), ごとき vor einem Nomen (ein … gleiches). Nach einem Personalnomen kann es auch herabsetzend wirken: 私ごとき (unsereins).",tip:"Drei Formen, drei Stellen: ごとく vor einem Verb, ごとき vor einem Nomen, ごとし am Satzende.",ex:[["彼は矢のごとく走り去った。","かれはやのごとくはしりさった。","Er stürmte davon wie ein Pfeil."],["氷のごとき冷たさだった。","こおりのごときつめたさだった。","Eine Kälte wie Eis."],["私ごときが意見を述べるのは僭越ですが。","わたくしごときがいけんをのべるのはせんえつですが。","Dass unsereins eine Meinung äußert, ist vermessen, aber …"]],q:[{q:"時は流れる水の＿＿過ぎていく。",o:["ごとく","ごとき","ごとし","ごとの"],c:0},{q:"Welche Form steht vor einem Nomen?",o:["ごとき","ごとく","ごとし","ごとに"],c:0},{q:"Was bedeutet 私ごとき?",o:["unsereins (selbstherabsetzend)","ich allein","ich zuerst","ich auch"],c:0}]},{id:"n1-shimatsuda",level:1,title:"〜しまつだ — und am Ende kam es so weit",intro:"Eine Kette von Missgeschicken mündet in ein schlechtes Ende.",text:"Verb (Wörterbuchform) + 始末だ. Der Sprecher berichtet, wie schlimm es zuletzt kam — immer negativ und oft mit Vorwurf. Häufig mit あげく oder Aufzählungen davor.",tip:"始末 heißt „Ausgang, Zustand“. Die feste Wendung この始末だ (und nun das!) kommt oft am Ende einer Klage.",ex:[["準備もせず、遅刻するしまつだ。","じゅんびもせず、ちこくするしまつだ。","Ohne Vorbereitung — und am Ende kam er auch noch zu spät."],["何度も注意したのに、今度は壊すしまつだ。","なんどもちゅういしたのに、こんどはこわすしまつだ。","Oft ermahnt, und nun hat er es auch noch zerbrochen."],["言い争いの末、口もきかないこの始末だ。","いいあらそいのすえ、くちもきかないこのしまつだ。","Nach dem Streit reden sie nicht einmal mehr miteinander — so weit ist es gekommen."]],q:[{q:"文句ばかり言って、最後は帰る＿＿。",o:["しまつだ","ばかりだ","ものだ","ところだ"],c:0},{q:"Wie ist der Ausgang beschaffen?",o:["negativ","erfreulich","offen","gleichgültig"],c:0},{q:"Was steht oft davor?",o:["eine Aufzählung von Missgeschicken","ein Lob","eine Frage","ein Wunsch"],c:0}]},{id:"n1-naimonoka",level:1,title:"〜ないものか — ob sich nicht doch …",intro:"Ein dringlicher Wunsch in Frageform.",text:"Verb (ない-Form) + ものか / ものだろうか. Der Sprecher wünscht sich sehr, dass etwas ginge, und fragt gleichsam ins Leere. Kein echter Fragesatz — eine Antwort wird nicht erwartet.",tip:"Nicht mit dem trotzigen 〜ものか (bestimmt nicht!) verwechseln. Dort steht kein ない davor und der Ton ist ablehnend.",ex:[["もっと早く終わらせられないものか。","もっとはやくおわらせられないものか。","Ob sich das nicht doch schneller beenden ließe?"],["何とかならないものだろうか。","なんとかならないものだろうか。","Ob sich da nicht doch etwas machen ließe?"],["この問題を解決できないものかと考え続けた。","このもんだいをかいけつできないものかとかんがえつづけた。","Ich dachte immer weiter darüber nach, ob sich das Problem nicht doch lösen ließe."]],q:[{q:"もう少し安くなら＿＿。",o:["ないものか","ないことか","ないものだ","ないことだ"],c:0},{q:"Erwartet der Sprecher eine Antwort?",o:["nein","ja","nur schriftlich","nur von Fachleuten"],c:0},{q:"Worin unterscheidet es sich vom trotzigen 〜ものか?",o:["hier steht ein ない davor","es ist gleichbedeutend","es ist förmlicher","es fragt wirklich"],c:0}]},{id:"n1-tobakarini",level:1,title:"〜とばかりに — als wollte er sagen",intro:"Ohne Worte, aber unmissverständlich in Haltung und Geste.",text:"Zitat / Nomen + とばかりに. Der Sprecher beschreibt fremdes Verhalten so, als hätte die Person etwas gesagt — gesagt hat sie es aber nicht. Nur über Dritte.",tip:"Häufige feste Fügungen: ここぞとばかりに (die Gelegenheit beim Schopf packend), 待ってましたとばかりに (als hätte man nur darauf gewartet).",ex:[["彼は早く帰れとばかりに時計を見た。","かれははやくかえれとばかりにとけいをみた。","Er sah auf die Uhr, als wollte er sagen: Geh endlich."],["ここぞとばかりに質問が飛んだ。","ここぞとばかりにしつもんがとんだ。","Die Fragen prasselten, als wäre jetzt der Moment gekommen."],["待ってましたとばかりに立ち上がった。","まってましたとばかりにたちあがった。","Er stand auf, als hätte er nur darauf gewartet."]],q:[{q:"もう帰れ＿＿、彼はドアを開けた。",o:["とばかりに","んばかりに","とはいえ","ときたら"],c:0},{q:"Hat die Person es wirklich gesagt?",o:["nein","ja","nur leise","nur schriftlich"],c:0},{q:"Über wen spricht man damit?",o:["über Dritte","über sich selbst","über Gegenstände","über Zahlen"],c:0}]},{id:"n1-nbakarini",level:1,title:"〜んばかりに — beinahe so, als ob",intro:"Es fehlt nur noch ein Schritt, und es wäre tatsächlich geschehen.",text:"Verb (ない-Form ohne ない) + んばかりに / んばかりの + Nomen, bei する → せんばかり. Der Zustand ist so ausgeprägt, dass er fast in die genannte Handlung übergeht: fast weinend, zum Bersten voll.",tip:"Verwechslungsgefahr mit 〜とばかりに: dort ist eine Äußerung gemeint, hier eine fast vollzogene Handlung. Beide stehen nur bei Dritten.",ex:[["彼女は泣かんばかりの顔をしていた。","かのじょはなかんばかりのかおをしていた。","Sie machte ein Gesicht, als würde sie gleich weinen."],["会場は割れんばかりの拍手に包まれた。","かいじょうはわれんばかりのはくしゅにつつまれた。","Der Saal versank in tosendem Applaus."],["棚は落ちんばかりに本で埋まっていた。","たなはおちんばかりにほんでうまっていた。","Das Regal war so voller Bücher, dass es fast herunterbrach."]],q:[{q:"彼は飛び上がら＿＿喜んだ。",o:["んばかりに","とばかりに","ながらに","ばかりに"],c:0},{q:"Was beschreibt んばかりに?",o:["eine fast vollzogene Handlung","eine Äußerung","eine Bedingung","einen Zweck"],c:0},{q:"Wie lautet die Form bei する?",o:["せんばかり","しんばかり","するんばかり","さんばかり"],c:0}]},{id:"n1-tokitara",level:1,title:"〜ときたら — was … angeht (mit Ärger)",intro:"Ein Thema wird aufgegriffen, um sich darüber zu beklagen.",text:"Nomen + ときたら. Der Sprecher nennt eine Person oder Sache und äußert dann Unmut: mein Chef, also wirklich … Umgangssprachlich und immer wertend, meist negativ.",tip:"Neutrale Entsprechung ist 〜は oder 〜について. ときたら trägt den Ärger schon in sich — im Gespräch mit Vorgesetzten unpassend.",ex:[["うちの犬ときたら、靴ばかりかじる。","うちのいぬときたら、くつばかりかじる。","Unser Hund, also wirklich — er kaut nur an Schuhen."],["最近の天気ときたら、雨ばかりだ。","さいきんのてんきときたら、あめばかりだ。","Das Wetter in letzter Zeit — nichts als Regen."],["あの店ときたら、いつも待たされる。","あのみせときたら、いつもまたされる。","In diesem Laden, also wirklich — man muss immer warten."]],q:[{q:"弟＿＿、片付けを全くしない。",o:["ときたら","にかけては","にしては","といえども"],c:0},{q:"Welchen Ton hat der Ausdruck?",o:["ärgerlich wertend","neutral","bewundernd","bittend"],c:0},{q:"Wem gegenüber ist er unpassend?",o:["Vorgesetzten","Freunden","Geschwistern","Haustieren"],c:0}]},{id:"n1-tamonodehanai",level:1,title:"〜たものではない — das lässt sich nicht",intro:"Etwas ist so schlecht, dass es sich nicht tun lässt.",text:"Verb (Potentialform, た-Form) + ものではない: 食べられたものではない, 聞けたものではない. Der Sprecher weist etwas als untragbar zurück: nicht zu essen, nicht mit anzuhören. Umgangssprachlich bis mittelförmlich.",tip:"Nicht mit dem lobenden 〜ものだ verwechseln. Hier steht eine Verneinung, und das Urteil ist scharf.",ex:[["この料理は食べられたものではない。","このりょうりはたべられたものではない。","Dieses Essen ist schlicht nicht essbar."],["あんな音では、眠れたものではない。","あんなおとでは、ねむれたものではない。","Bei solchem Lärm ist an Schlaf nicht zu denken."],["彼の運転は、怖くて乗れたものではない。","かれのうんてんは、こわくてのれたものではない。","Bei seiner Fahrweise kann man aus Angst nicht mitfahren."]],q:[{q:"この暑さでは、外に出られた＿＿。",o:["ものではない","ものだ","ことだ","ところだ"],c:0},{q:"Wie fällt das Urteil aus?",o:["scharf ablehnend","lobend","neutral","unsicher"],c:0},{q:"Welche Form steht meist davor?",o:["die Potentialform","die Willensform","die Befehlsform","die Bedingungsform"],c:0}]},{id:"n1-denakutenandarou",level:1,title:"〜でなくてなんだろう — was denn sonst, wenn nicht",intro:"Eine rhetorische Frage, die eine Deutung mit Nachdruck festschreibt.",text:"Nomen + でなくてなんだろう(か). Der Sprecher erklärt eine Sache für den Inbegriff des genannten Begriffs: wenn das kein Glück ist, was dann. Literarisch, oft am Ende eines Absatzes.",tip:"Immer mit Gefühls- oder Wertbegriffen: 愛, 奇跡, 幸せ, 不幸. Für sachliche Aussagen taugt die Wendung nicht.",ex:[["これが愛でなくてなんだろう。","これがあいでなくてなんだろう。","Wenn das keine Liebe ist, was dann?"],["あの再会は奇跡でなくてなんだろうか。","あのさいかいはきせきでなくてなんだろうか。","Wenn jenes Wiedersehen kein Wunder war, was dann?"],["これが幸せでなくてなんだろう。","これがしあわせでなくてなんだろう。","Wenn das kein Glück ist, was dann?"]],q:[{q:"これが努力の成果＿＿。",o:["でなくてなんだろう","でなければならない","にほかならないか","にすぎないか"],c:0},{q:"Welche Wörter stehen davor?",o:["Gefühls- und Wertbegriffe","Zahlen","Ortsnamen","Farben"],c:0},{q:"Wo steht die Wendung meist?",o:["am Ende eines Absatzes","am Satzanfang","in Fragen an andere","in Befehlen"],c:0}]},{id:"n1-zukume",level:1,title:"〜ずくめ — lauter, durch und durch",intro:"Alles ist von einer Sorte — nichts anderes ist dabei.",text:"Nomen + ずくめ. Feste Verbindungen: 黒ずくめ (ganz in Schwarz), いいことずくめ (lauter gute Dinge), 規則ずくめ (nichts als Regeln). Nicht frei bildbar; die Menge der üblichen Nomen ist klein.",tip:"Nicht mit 〜だらけ verwechseln: だらけ ist immer negativ und meint Verschmutzung oder Überhäufung (泥だらけ), ずくめ kann auch positiv sein.",ex:[["黒ずくめの服装で現れた。","くろずくめのふくそうであらわれた。","Er erschien ganz in Schwarz gekleidet."],["今年はいいことずくめだった。","ことしはいいことずくめだった。","Dieses Jahr brachte lauter gute Dinge."],["規則ずくめで息が詰まる。","きそくずくめでいきがつまる。","Nichts als Vorschriften — da bleibt einem die Luft weg."]],q:[{q:"今月はいいこと＿＿だ。",o:["ずくめ","だらけ","まみれ","がち"],c:0},{q:"Worin unterscheidet es sich von 〜だらけ?",o:["ずくめ kann auch positiv sein","ずくめ ist immer negativ","ずくめ verneint","es gibt keinen Unterschied"],c:0},{q:"Wie frei ist die Wortwahl?",o:["nur wenige feste Nomen","jedes Nomen","nur Verben","nur Adjektive"],c:0}]},{id:"n1-saseteitadaku",level:1,title:"〜(さ)せていただく — ich erlaube mir zu",intro:"Die höflichste Art zu sagen, dass man selbst etwas tut.",text:"Verb in der Veranlassungsform + ていただく. Wörtlich: ich erhalte die Erlaubnis, zu tun. Angebracht, wenn die Handlung den anderen berührt oder seine Zustimmung voraussetzt. Ohne diesen Bezug wirkt sie geziert — 説明させていただきます bei einem Vortrag ist üblich, 帰らせていただきます gegenüber Fremden kann schroff klingen.",tip:"Häufiger Fehler: die Form auf alles anzuwenden. Wo keine Erlaubnis im Spiel ist, genügt die schlichte ます-Form.",ex:[["本日は私から説明させていただきます。","ほんじつはわたくしからせつめいさせていただきます。","Heute darf ich die Erläuterung übernehmen."],["写真を撮らせていただいてもよろしいでしょうか。","しゃしんをとらせていただいてもよろしいでしょうか。","Dürfte ich ein Foto machen?"],["早退させていただきたいのですが。","そうたいさせていただきたいのですが。","Ich würde mich gern früher verabschieden."]],q:[{q:"資料を配ら＿＿。",o:["せていただきます","せてくださいます","せてさしあげます","せておられます"],c:0},{q:"Wann ist die Form angebracht?",o:["wenn die Handlung den anderen berührt","immer","nur schriftlich","nur bei Fremden"],c:0},{q:"Was ist der häufigste Fehler?",o:["sie auf alles anzuwenden","sie zu selten zu nutzen","sie falsch zu lesen","sie zu verneinen"],c:0}]},{id:"n1-temairu",level:1,title:"〜てまいる / 〜ております — bescheidene Verlaufsform",intro:"Die demütige Entsprechung zu 〜ていく / 〜てくる und 〜ている.",text:"まいる ist das bescheidene 行く/来る, おる das bescheidene いる. In der Verbindung 〜てまいります (ich werde weiterhin …) und 〜ております (ich bin dabei, zu …) spricht man von eigenen Handlungen in förmlicher Lage: Ansprachen, Kundengespräche, Geschäftsbriefe.",tip:"Nur über die eigene Seite. Über den Gesprächspartner heißt es 〜ていらっしゃいます, nicht 〜ております.",ex:[["今後とも努力してまいります。","こんごともどりょくしてまいります。","Ich werde mich auch künftig bemühen."],["ただいま確認しております。","ただいまかくにんしております。","Ich prüfe es gerade."],["おかげさまで、順調に進んでまいりました。","おかげさまで、じゅんちょうにすすんでまいりました。","Dank Ihrer Hilfe ist es gut vorangegangen."]],q:[{q:"担当者が席を外して＿＿。",o:["おります","いらっしゃいます","おられます","ございます"],c:0},{q:"Über wen spricht man mit 〜ております?",o:["über die eigene Seite","über den Gesprächspartner","über Dritte","über alle"],c:0},{q:"Was ist die bescheidene Form von 行く/来る?",o:["まいる","いらっしゃる","おいでになる","うかがえる"],c:0}]},{id:"n1-tozonjimasu",level:1,title:"〜と存じます — ich bin der Ansicht (bescheiden)",intro:"Die demütige Entsprechung zu 思う und 知る in förmlicher Sprache.",text:"存じる ist das bescheidene 思う / 知る. 〜と存じます (ich denke), ご存じです (Sie wissen — das ist die ehrende Form für den anderen). Achtung auf die Richtung: 存じます über sich, ご存じ über den anderen.",tip:"Häufiger Fehler: 存じております für den Gesprächspartner zu verwenden. Für ihn gilt ご存じです.",ex:[["ご都合はいかがかと存じます。","ごつごうはいかがかとぞんじます。","Ich frage mich, wie es Ihnen zeitlich passt."],["その件は存じております。","そのけんはぞんじております。","Von dieser Sache weiß ich."],["ご存じのとおり、来月から変更になります。","ごぞんじのとおり、らいげつからへんこうになります。","Wie Sie wissen, ändert es sich ab nächstem Monat."]],q:[{q:"その件でしたら、私も＿＿おります。",o:["存じて","ご存じで","知られて","お知りに"],c:0},{q:"Welche Form gilt für den Gesprächspartner?",o:["ご存じです","存じます","存じております","存じ上げます"],c:0},{q:"Wofür steht 存じる?",o:["für 思う und 知る","für 行く und 来る","für 食べる","für 見る"],c:0}]},{id:"n1-itashimasu",level:1,title:"〜いたす / 〜いたします — bescheidenes する",intro:"Die demütige Entsprechung zu する in geschäftlicher und förmlicher Sprache.",text:"いたす ersetzt する, wenn man über eigene Handlungen spricht: ご案内いたします, 失礼いたします, お待ちいたします. Häufig im Muster お/ご + Nomen + いたします — das ist die bescheidene Form schlechthin.",tip:"Nicht über andere verwenden: für den Gesprächspartner heißt es なさる. 「先生がいたします」 ist ein grober Fehler.",ex:[["受付でご案内いたします。","うけつけでごあんないいたします。","Am Empfang begleite ich Sie gern."],["失礼いたします。","しつれいいたします。","Verzeihen Sie die Störung."],["こちらでお預かりいたします。","こちらでおあずかりいたします。","Wir nehmen es hier für Sie in Verwahrung."]],q:[{q:"お荷物をお持ち＿＿。",o:["いたします","なさいます","くださいます","いらっしゃいます"],c:0},{q:"Wie heißt die ehrende Form für den anderen?",o:["なさる","いたす","おる","まいる"],c:0},{q:"Welches Muster ist typisch?",o:["お/ご + Nomen + いたします","お + Verb + なさる","ご + Verb + られる","お + Nomen + ください"],c:0}]},{id:"n1-kudasaimasuyou",level:1,title:"〜くださいますよう — mit der höflichen Bitte, dass",intro:"Die förmlichste Bitte, typisch für Geschäftsbriefe und Aushänge.",text:"お/ご + Nomen + くださいますよう + お願い申し上げます. Die Bitte wird nicht direkt ausgesprochen, sondern als Wunsch formuliert. Fast nur schriftlich; in Briefen steht sie meist im Schlussabsatz.",tip:"Steigerung der Höflichkeit: 〜てください < 〜てくださいませんか < 〜くださいますようお願い申し上げます. Letzteres ist die Briefformel.",ex:[["ご出席くださいますようお願い申し上げます。","ごしゅっせきくださいますようおねがいもうしあげます。","Wir bitten Sie höflich um Ihre Teilnahme."],["ご了承くださいますようお願いいたします。","ごりょうしょうくださいますようおねがいいたします。","Wir bitten um Ihr Verständnis."],["期日までにご返送くださいますようお願い申し上げます。","きじつまでにごへんそうくださいますようおねがいもうしあげます。","Wir bitten Sie, es bis zum Termin zurückzusenden."]],q:[{q:"ご協力＿＿お願い申し上げます。",o:["くださいますよう","してくださって","いただきまして","なさいますと"],c:0},{q:"Wo steht die Formel meist?",o:["im Schlussabsatz eines Briefes","am Anfang","in der Mitte","in der Anrede"],c:0},{q:"Wie direkt ist die Bitte?",o:["indirekt, als Wunsch formuliert","sehr direkt","als Befehl","als Frage"],c:0}]}];export{e as GRAMMAR};
